// Arabic names and steps for the exercise library (library.js), keyed by exercise id: [name, [steps]].
window.LIBRARY_AR={"3_4_Sit-Up":["سيت أب ثلاثة أرباع",["استلقِ على الأرض وثبّت قدميك، والركبتان مثنيتان.","ضع يديك خلف رأسك أو بجانبه، وابدأ وظهرك على الأرض.","اثنِ حوضك وعمودك الفقري لترفع جذعك نحو ركبتيك حتى يصبح عموديًا على الأرض.","انزل ثلاثة أرباع المسافة فقط، دون أن تلمس الأرض، ثم كرّر."]],"90_90_Hamstring":["إطالة خلفي الفخذ 90/90",["استلقِ على ظهرك ورجل واحدة ممدودة على الأرض.","اثنِ ورك وركبة الرجل الأخرى بزاوية 90°، ويمكنك سندها بيديك. هذه وضعية البداية.","مدّ رجلك للأعلى مستقيمة، وتوقف لحظة، ثم أعدها.","كرّر 10–20 مرة ثم بدّل الرجل."]],"Ab_Crunch_Machine":["جهاز البطن (كرنش)",["اختر وزنًا خفيفًا واجلس على جهاز البطن، ضع قدميك تحت المساند وأمسك المقابض العلوية. ذراعاك مثنيتان بزاوية 90° والتراي مستند على المساند. هذه وضعية البداية.","ارفع رجليك وفي الوقت نفسه اثنِ جذعك العلوي (كرنش) وأنت تزفر. تحرّك ببطء وتحكّم، واعتمد على البطن لا على الرجلين.","توقف ثانية، ثم عد ببطء إلى البداية وأنت تشهق."]],"Ab_Roller":["عجلة البطن",["أمسك عجلة البطن بيديك واركع على الأرض.","ضع العجلة على الأرض أمامك بحيث تكون على يديك وركبتيك. هذه وضعية البداية.","دحرج العجلة ببطء للأمام حتى يستقيم جسمك. انزل لأبعد ما تستطيع دون أن يلمس جسمك الأرض، وأنت تشهق.","توقف، ثم اسحب نفسك إلى البداية وأنت تزفر. تحرّك ببطء والبطن مشدود دائمًا."]],"Adductor":["إطالة الفخذ الداخلي",["انبطح ورجل واحدة على الفوم رولر.","أدِر الرجل بحيث يلامس الرولر الفخذ الداخلي، وضع عليه ما تتحمّله من وزنك.","مع إرخاء عضلات الفخذ الداخلي، تدحرج بين الحوض والركبة، وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالرجل الأخرى."]],"Adductor_Groin":["إطالة الفخذ الداخلي والمنطقة الأربية",["استلقِ على ظهرك والقدمان مرفوعتان نحو السقف.","يمسك زميلك قدميك أو كاحليك. باعد رجليك لأبعد حد. هذه وضعية البداية.","حاول ضم رجليك 10 ثوانٍ أو أكثر بينما يمنعك زميلك.","أرخِ عضلات رجليك بينما يباعد زميلك قدميك بقدر ما يريحك. أخبره عندما تكفي الإطالة."]],"Advanced_Kettlebell_Windmill":["طاحونة الهواء بالكيتلبل (متقدم)",["ارفع الكيتلبل فوق رأسك بيد واحدة (كلين ثم ضغط).","والكيتلبل مثبت فوقك والذراع مقفلة دائمًا، ادفع مؤخرتك باتجاه الذراع الممسكة بالكيتلبل. اليد الأخرى خلف ظهرك، والقدمان بزاوية 45° بعيدًا عن جهة الكيتلبل.","انزل لأبعد ما تستطيع.","توقف ثانية، ثم اعكس الحركة إلى البداية."]],"Air_Bike":["دراجة الهواء",["استلقِ على الأرض وأسفل ظهرك ملتصق بها، ويداك بجانب رأسك دون شدّ الرقبة. ارفع كتفيك إلى وضعية الكرنش.","ارفع ركبتيك حتى تصبحا عموديتين على الأرض والساقان موازيتان لها. هذه وضعية البداية.","حرّك رجليك كأنك تبدّل دراجة: مدّ اليمنى وقرّب ركبة اليسرى، وقرّب مرفقك الأيمن من ركبتك اليسرى بكرنش جانبي، وأنت تزفر.","عد وأنت تشهق، ثم قرّب مرفقك الأيسر من ركبتك اليمنى. تابع بالتبادل."]],"All_Fours_Quad_Stretch":["إطالة أمامي الفخذ على أربع",["ابدأ على يديك وركبتيك، ثم ارفع رجلًا وأمسك قدمها بيدك.","أمسك القدم أو الكاحل والركبة مثنية بالكامل، لتشعر بإطالة في أمامي الفخذ وعضلات ثني الورك.","ادفع حوضك نحو الأرض. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Alternate_Hammer_Curl":["باي مطرقة بالتبادل",["قف باستقامة ودمبل في كل يد والذراعان ممدودتان، المرفقان قريبان من الجسم والكفّان متقابلتان نحو الجسم.","ثبّت العضد واثنِ الدمبل الأيمن للأعلى وأنت تزفر حتى يصل إلى مستوى الكتف. اثبت ثانية واعصر الباي. الساعد فقط يتحرك.","أنزل الدمبل ببطء وأنت تشهق.","كرّر باليد اليسرى، وهكذا بالتبادل."]],"Alternate_Heel_Touchers":["لمس الكعبين بالتبادل",["استلقِ على الأرض والركبتان مثنيتان والقدمان على الأرض متباعدتان 45–60 سم، والذراعان ممدودتان بجانبك.","ارفع جذعك قليلًا (8–10 سم) ومِل إلى اليمين حتى تلمس كعبك الأيمن، واثبت ثانية وأنت تزفر.","عد ببطء وأنت تشهق.","كرّر إلى اليسار حتى تلمس كعبك الأيسر. لمس الكعبين يساوي تكرارًا واحدًا. تابع بالتبادل."]],"Alternate_Incline_Dumbbell_Curl":["باي دمبل على بنش مائل بالتبادل",["اجلس على بنش مائل ودمبل في كل يد والذراعان ممدودتان للأسفل، والمرفقان قريبان من الجسم.","ثبّت العضد واثنِ الدمبل الأيمن للأعلى وأنت تزفر، مع لفّ الكف لتصبح للأعلى، حتى مستوى الكتف. اثبت ثانية واعصر الباي.","أنزله ببطء وأنت تشهق.","كرّر باليد اليسرى، وهكذا بالتبادل."]],"Alternate_Leg_Diagonal_Bound":["وثب قطري بالتبادل",["قف براحة وقدم أمام الأخرى قليلًا.","ادفع بالرجل الأمامية وارفع الركبة المعاكسة للأمام ولأعلى ما يمكن قبل الهبوط، محاولًا قطع أكبر مسافة جانبية مع كل وثبة.","يمكنك الاستعانة بخط على الأرض لقياس المسافة.","كرّر بالرجل الأخرى بالتبادل."]],"Alternating_Cable_Shoulder_Press":["ضغط أكتاف بالكيبل بالتبادل",["اضبط بكرتي الكيبل في الأسفل واختر الوزن المناسب.","أمسك المقبضين عند مستوى الكتفين والكفّان للأمام. هذه وضعية البداية.","ارفع رأسك وصدرك، ومدّ مرفق جهة واحدة لتضغط المقبض فوق رأسك مباشرة.","توقف في الأعلى، ثم عد وكرّر بالجهة الأخرى."]],"Alternating_Deltoid_Raise":["رفرفة الكتف بالتبادل",["قف ودمبل في كل يد بجانب جسمك.","مع ثني بسيط في المرفقين، ارفع الدمبلين أمامك حتى مستوى الكتفين بدون تأرجح.","أعدهما إلى جانبيك.","في التكرار التالي ارفعهما جانبيًا حتى مستوى الكتفين، ثم أعدهما. تابع بالتبادل بين الأمام والجانب."]],"Alternating_Floor_Press":["ضغط على الأرض بالتبادل",["استلقِ على الأرض وكيتلبلان بجانب كتفيك.","ضع واحدًا على صدرك ثم الآخر، وأمسكهما من المقبض والكفّان للأمام.","مدّ ذراعيك ليصبح الكيتلبلان فوق صدرك. أنزل واحدًا إلى صدرك مع لفّ الرسغ نحو الكيتلبل المرفوع.","ارفعه، ثم كرّر بالجهة الأخرى."]],"Alternating_Hang_Clean":["كلين من التعليق بالتبادل",["ضع كيتلبلين بين قدميك. ادفع مؤخرتك للخلف وانظر للأمام.","ارفع كيتلبلًا واحدًا إلى كتفك (كلين) بفرد الرجلين والحوض وأنت تسحبه نحو الكتف مع لفّ الرسغ، والآخر متدلٍّ.","أنزل الكيتلبل المرفوع إلى وضع التعليق، وارفع الآخر. تابع بالتبادل."]],"Alternating_Kettlebell_Press":["ضغط أكتاف بالكيتلبل بالتبادل",["ارفع كيتلبلين إلى كتفيك (كلين) بفرد الرجلين والحوض مع لفّ الرسغين.","اضغط واحدًا فوق رأسك مباشرة بفرد المرفق، مع لفّه لتصبح الكف للأمام، والآخر ثابت عند الكتف.","أنزله إلى البداية واضغط فورًا بالذراع الأخرى."]],"Alternating_Kettlebell_Row":["تجديف بالكيتلبل بالتبادل",["ضع كيتلبلين أمام قدميك. اثنِ ركبتيك قليلًا وادفع مؤخرتك للخلف قدر الإمكان، وانحنِ وأمسك الكيتلبلين من المقابض.","اسحب كيتلبلًا واحدًا عن الأرض والآخر ثابت، مع ضم لوح الكتف وثني المرفق نحو بطنك أو أضلاعك.","أنزله وكرّر بالذراع الأخرى."]],"Alternating_Renegade_Row":["تجديف رينيغيد بالتبادل",["ضع كيتلبلين على الأرض بعرض الكتفين. اتخذ وضعية الضغط ويداك على مقبضي الكيتلبلين، والجسم مستقيم. باعد قدميك للثبات.","اضغط كيتلبلًا على الأرض واسحب الآخر نحو جانبك بضم لوح الكتف وثني المرفق.","أنزله إلى الأرض وكرّر بالجهة الأخرى."]],"Ankle_Circles":["دوائر الكاحل",["أمسك شيئًا ثابتًا كقفص السكوات.","ارفع رجلك اليمنى عن الأرض نحو 5 سم وارسم دائرة كبيرة بإصبع القدم الكبير. كل دائرة تكرار. تنفّس بشكل طبيعي.","بعد الانتهاء كرّر بالرجل اليسرى."]],"Ankle_On_The_Knee":["إطالة الكاحل على الركبة",["استلقِ على ظهرك والركبتان مثنيتان والقدمان على الأرض.","ضع كاحل قدم على الركبة المعاكسة.","أمسك فخذ الرجل السفلية أو ركبتها واسحب الرجلين نحو صدرك. أرخِ الرقبة والكتفين. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Anterior_Tibialis-SMR":["تدليك عضلة الساق الأمامية بالفوم رولر",["اجلس على الأرض والرجلان مثنيتان والقدمان على الأرض.","باستخدام رولر العضلات أو شوبك العجين، اضغط على العضلات خارج عظمة الساق، من تحت الركبة حتى فوق الكاحل، وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالرجل الأخرى."]],"Anti-Gravity_Press":["ضغط مضاد للجاذبية",["ضع بارًا على الأرض خلف رأس بنش مائل.","انبطح على البنش ووجهك للأسفل، والتقط البار بقبضة علوية، ثم اثنِ مرفقيك لتقرّبه من صدرك. هذه وضعية البداية.","مدّ مرفقيك لتدفع البار أمام رأسك، مع إبقاء ذراعيك موازيتين للأرض.","عد إلى البداية وكرّر."]],"Arm_Circles":["دوائر الذراعين",["قف وافتح ذراعيك للجانبين موازيتين للأرض. هذه وضعية البداية.","ارسم ببطء دوائر قطرها نحو 30 سم بكل ذراع، وتنفّس بشكل طبيعي.","تابع نحو 10 ثوانٍ، ثم اعكس الاتجاه."]],"Arnold_Dumbbell_Press":["ضغط أرنولد بالدمبل",["اجلس على بنش بمسند للظهر وأمسك دمبلين أمام أعلى صدرك، الكفّان نحوك والمرفقان مثنيان، كأنك في أعلى حركة الباي.","ارفع الدمبلين وأنت تلفّ الكفّين لتصبحا للأمام.","تابع حتى تمتد ذراعاك فوق رأسك، وازفر أثناء الصعود.","توقف ثانية، ثم أنزلهما إلى البداية مع لفّ الكفّين نحوك وأنت تشهق."]],"Around_The_Worlds":["حول العالم (تفتيح دائري)",["استلقِ على بنش مستوٍ ودمبل في كل يد والكفّان للأعلى، والذراعان بجانب الفخذين موازيتان للأرض مع ثني بسيط في المرفقين.","حرّك الدمبلين في نصف دائرة من جانب الفخذين حتى فوق رأسك، والذراعان موازيتان للأرض طوال الوقت. اشهق أثناء ذلك.","اعكس الحركة لتعود إلى البداية وأنت تزفر."]],"Atlas_Stone_Trainer":["تدريب حجر أطلس",["أداة تدريب تقوّي رفع حجارة أطلس لمن لا يملك الحجارة، وتُصنع عادةً من أطراف بار أو أنبوب ثقيل.","حمّل الوزن المطلوب، وقف فوقه ولفّ ذراعيك حوله مع الانحناء من الحوض.","اسحب الوزن فوق الركبتين بفرد الحوض. بعد تجاوز الركبتين يمكنك إسناده على فخذيك والجلوس للخلف مع ضمّه إلى صدرك بقوة.","أكمل بفرد الحوض والركبتين لترفعه لأعلى ما يمكن. أعده إلى الفخذين أو الأرض للتكرار التالي."]],"Atlas_Stones":["حجارة أطلس",["ابدأ والحجر بين قدميك. انحنِ من الحوض ولفّ ذراعيك عموديًا حوله محاولًا إدخال أصابعك تحته. كثير من الحجارة لها جزء مسطح صغير في الأسفل يسهّل الإمساك.","اسحب الحجر نحو جذعك وادفع بالنصف الخلفي من قدميك لترفعه عن الأرض.","عندما يتجاوز الركبتين، اجلس للخلف لتسنده على فخذيك.","اجلس منخفضًا وارفع الحجر إلى صدرك مع تغيير قبضتك لتلتف فوقه، ثم قف بدفع الحوض. اقترب من المنصة ومِل للخلف مع فرد الحوض لرفعه لأعلى ما يمكن ووضعه."]],"Axle_Deadlift":["ديدلفت بالبار السميك (أكسل)",["اقترب من البار السميك بحيث يكون فوق منتصف قدميك، والقدمان بعرض الحوض. انحنِ وأمسكه بعرض الكتفين، عادةً بقبضة مختلطة.","خذ نفسًا عميقًا، أنزل حوضك واثنِ ركبتيك حتى تلامس ساقاك البار. انظر للأمام وارفع صدرك وقوّس ظهرك، وادفع بكعبيك لترفع الوزن.","بعد تجاوز الركبتين اسحب البار للخلف بقوة وادفع حوضك نحوه واضغط لوحي الكتف معًا.","أنزل البار بثني الحوض وتوجيهه إلى الأرض."]],"Back_Flyes_-_With_Bands":["كتف خلفي بالمطاط",["لفّ مطاطًا حول عمود ثابت كقفص السكوات.","أمسك المطاط من مقبضيه وارجع للخلف حتى يشتد.","ارفع ذراعيك مستقيمتين أمامك موازيتين للأرض، والقدمان بعرض الكتفين. هذه وضعية البداية.","ازفر وافتح ذراعيك للجانبين وللخلف، مستقيمتين وموازيتين للأرض، حتى تصبحا بجانبيك.","توقف، ثم عد وأنت تشهق."]],"Backward_Drag":["سحب للخلف بالزلاجة",["حمّل الزلاجة بالوزن المطلوب واربط بها حبلًا أو أحزمة تمسكها.","امشِ للخلف مسافة محددة، مائلًا للخلف ومادًّا رجليك بخطوات قصيرة وسريعة."]],"Backward_Medicine_Ball_Throw":["رمي الكرة الطبية للخلف",["الأفضل مع زميل، أو ارمِ الكرة واجلبها، أو ارمها على حائط.","قف على بعد أمتار أمام زميلك وكلاكما بالاتجاه نفسه، والكرة بين رجليك.","انزل في سكوات ثم اعكس بقوة حتى تمتد بالكامل وارمِ الكرة فوق رأسك إلى زميلك.","يدحرج زميلك الكرة إليك، وكرّر."]],"Balance_Board":["لوح التوازن",["ضع لوح التوازن أمامك.","قف عليه وحاول الحفاظ على توازنك.","اثبت أطول وقت تريده."]],"Ball_Leg_Curl":["خلفي على كرة التمارين",["استلقِ على ظهرك وقدماك فوق كرة التمارين.","ضع الكرة بحيث يكون كاحلاك فوقها والرجلان ممدودتان. هذه وضعية البداية.","ارفع حوضك عن الأرض والوزن على لوحي الكتف والقدمين.","اثنِ ركبتيك واسحب الكرة نحوك قدر الإمكان بعصر خلفي الفخذ.","توقف لحظة، ثم عد إلى البداية."]],"Band_Assisted_Pull-Up":["عقلة بمساعدة المطاط",["اربط المطاط حول منتصف بار العقلة. المطاطات المختلفة تعطي مساعدة مختلفة.","اسحب طرف المطاط للأسفل وضع فيه ركبة مثنية بشكل آمن. أمسك البار بقبضة متوسطة إلى واسعة. هذه وضعية البداية.","اسحب نفسك للأعلى بعضلات الظهر وثني المرفقين نحو جانبيك، محاولًا رفع ذقنك فوق البار، دون تأرجح.","توقف لحظة، ثم انزل إلى البداية."]],"Band_Good_Morning":["غود مورنينغ بالمطاط",["قف على أحد طرفي مطاط طويل والقدمان متباعدتان قليلًا. انحنِ ولفّ الطرف الآخر خلف رقبتك. هذه وضعية البداية.","والرجلان مستقيمتان، افرد حوضك حتى تقف شبه مستقيم.","انزل إلى البداية دون أن يتقوّس ظهرك للأسفل."]],"Band_Good_Morning_Pull_Through":["غود مورنينغ بالمطاط (سحب بين الرجلين)",["لفّ المطاط حول عمود، وقف على مسافة منه ولفّ الطرف الآخر حول رقبتك، ويمكن أن تساعدك يداك في تثبيته.","انحنِ من الحوض بدفع مؤخرتك للخلف لأقصى حد، والظهر مستقيم، حتى يصبح جذعك بزاوية 90° تقريبًا. الركبتان مثنيتان قليلًا.","عد إلى الوقوف بدفع حوضك للأمام."]],"Band_Hip_Adductions":["ضم الفخذ بالمطاط",["ثبّت المطاط حول عمود أو شيء ثابت.","قف وجانبك الأيسر للعمود، وأدخل قدمك اليمنى في المطاط حول الكاحل.","قف باستقامة وأمسك العمود إن احتجت. هذه وضعية البداية.","والركبة مستقيمة، ارفع رجلك اليمنى إلى الجانب لأقصى حد.","عد إلى البداية. أكمل التكرارات ثم بدّل الجهة."]],"Band_Pull_Apart":["فتح المطاط (باند بول أبارت)",["ابدأ والذراعان ممدودتان أمامك تمسكان المطاط بيديك.","باعد يديك للجانبين في حركة تفتيح عكسي.","المرفقان ممدودان، حتى يصل المطاط إلى صدرك. أبقِ كتفيك للخلف.","توقف في النهاية، ثم عد بتحكّم إلى البداية."]],"Band_Skull_Crusher":["تراي جبهة بالمطاط (سكل كراشر)",["ثبّت المطاط في قاعدة القفص أو البنش، واستلقِ على البنش بحيث يكون المطاط على خط رأسك.","أمسك المطاط وارفع مرفقيك بحيث يكون العضدان عموديين على الأرض، والمرفقان مثنيان والمطاط فوق رأسك. هذه وضعية البداية.","افرد مرفقيك لتستقيم ذراعاك مع ثبات العضدين. توقف في الأعلى، ثم عد."]],"Barbell_Ab_Rollout":["عجلة البطن بالبار",["اتخذ وضعية الضغط (بوش أب) لكن يداك على بار أولمبي محمّل بوزن خفيف على كل جهة. هذه وضعية البداية.","شدّ بطنك وحافظ على استقامة ظهرك، ثم ارفع حوضك ودحرج البار نحو قدميك وأنت تزفر. ذراعاك تبقيان عموديتين على الأرض، وإلا اشتغل الكتف والظهر أكثر من البطن.","اثبت ثانية في الأعلى، ثم دحرج البار ببطء إلى البداية وأنت تشهق."]],"Barbell_Ab_Rollout_-_On_Knees":["عجلة البطن بالبار على الركبتين",["أمسك بارًا أولمبيًا محمّلًا بوزن خفيف واركع على الأرض.","ضع البار على الأرض أمامك بحيث تكون على يديك وركبتيك. هذه وضعية البداية.","دحرج البار ببطء للأمام حتى يستقيم جسمك. انزل لأبعد ما تستطيع دون أن يلمس جسمك الأرض، وأنت تشهق.","توقف ثانية، ثم اسحب نفسك إلى البداية وأنت تزفر. تحرّك ببطء والبطن مشدود دائمًا."]],"Barbell_Bench_Press_-_Medium_Grip":["ضغط صدر بالبار على بنش مستوٍ (قبضة متوسطة)",["استلقِ على بنش مستوٍ، وأمسك البار بقبضة متوسطة (يتكوّن بين الساعد والعضد زاوية 90° في منتصف الحركة). ارفع البار من الحامل وثبّته فوقك والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى يلمس منتصف صدرك.","توقف لحظة، ثم ادفع البار للأعلى بعضلات الصدر وأنت تزفر، واعصر صدرك في الأعلى ثانية. الأفضل أن يأخذ النزول ضعف وقت الصعود.","عند الانتهاء أعد البار إلى الحامل."]],"Barbell_Curl":["باي بالبار",["قف باستقامة وأمسك البار بقبضة بعرض الكتفين، الكفّان للأمام والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ البار للأعلى وأنت تزفر. الساعدان فقط يتحركان.","تابع حتى يصل البار إلى مستوى الكتفين، واثبت ثانية واعصر الباي بقوة.","أنزل البار ببطء إلى البداية وأنت تشهق."]],"Barbell_Curls_Lying_Against_An_Incline":["باي بالبار مستلقيًا على بنش مائل",["استند بصدرك على بنش مائل، وأمسك البار والذراعان متدليتان للأسفل.","ثبّت العضدين واثنِ البار لأعلى ما يمكن وأنت تعصر الباي وتزفر. لا تؤرجح ذراعيك.","اثبت ثانية، ثم انزل ببطء حتى النهاية وأنت تشهق."]],"Barbell_Deadlift":["ديدلفت بالبار",["قف أمام بار محمّل.","حافظ على ظهرك مستقيمًا قدر الإمكان، اثنِ ركبتيك وانحنِ وأمسك البار بقبضة علوية بعرض الكتفين. إذا صعب الإمساك استخدم قبضة مختلطة أو أحزمة الرسغ.","ادفع بالرجلين وارفع جذعك في الوقت نفسه حتى تقف باستقامة وأنت تزفر. في الأعلى افتح صدرك واسحب لوحي الكتف للخلف.","عد إلى البداية بثني الركبتين وإمالة الجذع للأمام مع إبقاء الظهر مستقيمًا، حتى تلمس الأقراص الأرض."]],"Barbell_Full_Squat":["سكوات كامل بالبار",["يُفضّل أداء التمرين داخل قفص السكوات للأمان. اضبط البار أعلى مستوى الكتفين بقليل، ثم ادخل تحته وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسك البار بيديك وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة عن الحامل، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم.","انزل ببطء بثني الركبتين والجلوس بالحوض للخلف حتى يلامس خلفي الفخذ السمانة، وأنت تشهق.","ادفع الأرض بالكعب أو منتصف القدم لتصعد إلى البداية وأنت تزفر."]],"Barbell_Glute_Bridge":["جسر الأرداف بالبار",["اجلس على الأرض والبار المحمّل فوق رجليك. وضع وسادة على البار يخفف الإزعاج. دحرج البار حتى يصبح فوق حوضك تمامًا، ثم استلقِ على ظهرك.","ادفع بكعبيك وارفع حوضك للأعلى مع البار. وزنك على أعلى ظهرك وكعبيك.","ارتفع لأقصى حد، ثم انزل إلى البداية."]],"Barbell_Guillotine_Bench_Press":["ضغط صدر بالبار للرقبة (غيوتين)",["أمسك البار بقبضة متوسطة، ارفعه من الحامل وثبّته فوق رقبتك والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى يصبح على بُعد 2–3 سم من رقبتك.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود. استخدم وزنًا خفيفًا ومُساعدًا، فالتمرين خطِر.","عند الانتهاء أعد البار إلى الحامل."]],"Barbell_Hack_Squat":["هاك سكوات بالبار",["قف باستقامة والبار خلفك والذراعان ممدودتان، القدمان بعرض الكتفين والكفّان للخلف.","ارفع رأسك وحافظ على ظهرك مستقيمًا، وانزل في سكوات حتى يصبح الفخذان موازيين للأرض وأنت تشهق.","ادفع بالكعبين واعصر الفخذين لتصعد وأنت تزفر."]],"Barbell_Hip_Thrust":["دفع الورك بالبار (هيب ثرست)",["اجلس على الأرض وخلفك بنش مباشرة، والبار المحمّل فوق رجليك. وضع وسادة على البار يخفف الإزعاج.","دحرج البار حتى يصبح فوق حوضك، واستند بظهرك على البنش بحيث يكون لوحا الكتف قرب حافته.","ادفع بقدميك وارفع حوضك للأعلى مع البار. وزنك على لوحي الكتف والقدمين. ارتفع لأقصى حد ثم انزل."]],"Barbell_Incline_Bench_Press_-_Medium_Grip":["ضغط صدر بالبار على بنش مائل (قبضة متوسطة)",["استلقِ على بنش مائل، وأمسك البار بقبضة متوسطة، ارفعه من الحامل وثبّته فوقك والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى يلمس أعلى صدرك.","توقف ثانية، ثم ادفع البار بعضلات الصدر إلى البداية وأنت تزفر، واعصر صدرك في الأعلى. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد البار إلى الحامل."]],"Barbell_Incline_Shoulder_Raise":["رفع الكتفين بالبار على بنش مائل",["استلقِ على بنش مائل وأمسك البار بقبضة أعرض قليلًا من الكتفين، ارفعه من الحامل والذراعان مستقيمتان.","مع إبقاء الذراعين مستقيمتين، ارفع البار بدفع لوحي الكتف للأمام حتى يرتفع كتفاك عن البنش، وأنت تزفر.","أعد البار إلى البداية وأنت تشهق."]],"Barbell_Lunge":["لانج بالبار",["يُفضّل أداء التمرين داخل قفص السكوات للأمان. اضبط البار تحت مستوى الكتفين بقليل، وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسك البار وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد عن الحامل واخطُ برجلك اليمنى للأمام، وانزل بالحوض مع إبقاء الجذع مستقيمًا والتوازن ثابتًا، وأنت تشهق. لا تدع الركبة تتجاوز أصابع القدم كثيرًا.","ادفع بكعب القدم الأمامية لتعود إلى البداية وأنت تزفر.","أكمل التكرارات ثم بدّل إلى الرجل اليسرى."]],"Barbell_Rear_Delt_Row":["تجديف كتف خلفي بالبار",["قف باستقامة وأمسك البار بقبضة علوية واسعة (أعرض من الكتفين).","اثنِ ركبتيك قليلًا وانحنِ مع الحفاظ على تقوّس الظهر الطبيعي حتى يصبح جذعك موازيًا للأرض، والذراعان متدليتان. افتح المرفقين للخارج بحيث يشبه جسمك حرف T.","مع إبقاء العضدين عموديين على الجذع، اسحب البار نحو أعلى صدرك وأنت تعصر الكتف الخلفي وتزفر. لا تسحب بالباي، الذراعان مجرد خطّافين.","عد ببطء إلى البداية وأنت تشهق."]],"Barbell_Rollout_from_Bench":["عجلة البطن بالبار من البنش",["ضع بارًا محمّلًا على الأرض قرب طرف البنش. اركع بركبتيك على البنش وأمسك البار بقبضة متوسطة أو ضيقة.","افرد حوضك ودحرج البار ببطء للأمام، ومع التقدّم ارفع ذراعيك حتى يصل البار أمام رأسك. ذراعاك تبقيان ممدودتين.","عندما تصل لأبعد نقطة ممكنة، عد إلى البداية."]],"Barbell_Seated_Calf_Raise":["سمانة جلوس بالبار",["ضع مكعبًا على بُعد 30 سم تقريبًا أمام بنش مستوٍ.","اجلس على البنش وضع مقدمة قدميك على المكعب.","ضع البار (أو اطلب من أحد وضعه) على فخذيك فوق الركبتين بنحو 8 سم.","ارتفع على أصابع قدميك لأقصى حد وأنت تعصر السمانة وتزفر.","اثبت ثانية، ثم انزل ببطء مع أكبر إطالة ممكنة للسمانة."]],"Barbell_Shoulder_Press":["ضغط أكتاف بالبار",["اجلس على بنش بمسند للظهر داخل قفص السكوات، واضبط البار فوق رأسك بقليل. أمسكه بقبضة علوية (الكفّان للأمام).","ارفع البار فوق رأسك حتى تمتد ذراعاك، أمام رأسك بقليل. هذه وضعية البداية.","أنزل البار ببطء إلى مستوى الكتفين وأنت تشهق.","ادفعه للأعلى إلى البداية وأنت تزفر."]],"Barbell_Shrug":["ترابيس بالبار (شراغ)",["قف باستقامة والقدمان بعرض الكتفين، وأمسك البار أمامك بقبضة علوية أعرض قليلًا من الكتفين. يمكنك استخدام أحزمة الرسغ.","ارفع كتفيك لأعلى ما يمكن وأنت تزفر، واثبت ثانية. لا ترفع البار بالباي.","انزل ببطء إلى البداية وأنت تشهق."]],"Barbell_Shrug_Behind_The_Back":["ترابيس بالبار خلف الظهر",["قف باستقامة والقدمان بعرض الكتفين، وأمسك البار خلف ظهرك بقبضة علوية (الكفّان للخلف) أعرض قليلًا من الكتفين.","ارفع كتفيك لأعلى ما يمكن وأنت تزفر، واثبت ثانية. الذراعان تبقيان ممدودتين، ولا تسحب بالباي.","انزل ببطء إلى البداية وأنت تشهق."]],"Barbell_Side_Bend":["ميلان جانبي بالبار",["قف باستقامة والبار على أعلى ظهرك تحت الرقبة بقليل، والقدمان بعرض الكتفين.","مع إبقاء الظهر مستقيمًا والرأس مرفوعًا، مِل من الخصر فقط إلى اليمين لأقصى حد وأنت تشهق. اثبت ثانية ثم عد وأنت تزفر. باقي الجسم ثابت.","كرّر الميلان إلى اليسار، واثبت ثانية ثم عد."]],"Barbell_Side_Split_Squat":["سكوات جانبي مفتوح بالبار",["قف باستقامة والبار على أعلى ظهرك، والقدمان متباعدتان كثيرًا، وقدم الرجل القائدة موجهة للجانب.","انزل بجسمك نحو جهة القدم الموجهة بثني ركبتها وحوضها، مع إبقاء الرجل الأخرى شبه مستقيمة، وأنت تشهق.","افرد ركبة الرجل القائدة وحوضها لتعود إلى البداية وأنت تزفر.","بعد إكمال التكرارات بدّل الرجل."]],"Barbell_Squat":["سكوات بالبار",["يُفضّل أداء التمرين داخل قفص السكوات للأمان. اضبط البار تحت مستوى الكتفين بقليل، ثم ادخل تحته وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسك البار بيديك وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، الرأس مرفوع والظهر مستقيم.","انزل ببطء بثني الركبتين والحوض حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق. حافظ على ظهر مستقيم ورأس مرفوع.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Barbell_Squat_To_A_Bench":["سكوات بالبار حتى البنش",["يُفضّل أداؤه داخل قفص السكوات. ضع بنشًا أو صندوقًا خلفك، فهو يعلّمك دفع الحوض للخلف والوصول إلى العمق المطلوب.","اضبط البار على ارتفاعك وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسكه وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل ببطء بثني الركبتين ودفع الحوض للخلف حتى تلامس البنش برفق، وأنت تشهق.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Barbell_Step_Ups":["صعود على الصندوق بالبار",["قف باستقامة والبار على أعلى ظهرك، وأمامك منصة مرتفعة أو صندوق.","ضع قدمك اليمنى على المنصة واصعد بفرد الورك والركبة، معتمدًا على الكعب، ثم ضع القدم اليسرى بجانبها. ازفر أثناء الصعود.","انزل بالرجل اليسرى أولًا وأنت تشهق، ثم أعد القدم اليمنى بجانبها على الأرض.","أكمل التكرارات بالرجل اليمنى ثم بدّل إلى اليسرى."]],"Barbell_Walking_Lunge":["لانج مشي بالبار",["قف والقدمان بعرض الكتفين والبار على أعلى ظهرك.","اخطُ برجل للأمام واثنِ الركبتين لتنزل بحوضك حتى تكاد الركبة الخلفية تلمس الأرض. الجذع مستقيم والركبة الأمامية فوق القدم.","ادفع بكعب القدم الأمامية وافرد الركبتين لتصعد.","اخطُ بالقدم الخلفية للأمام وكرّر بالرجل الأخرى، وهكذا تمشي."]],"Battling_Ropes":["حبال المعركة",["تحتاج حبلًا ثقيلًا مثبتًا من منتصفه على بعد 5–6 أمتار. قف أمامه وأمسك طرفًا بكل يد والذراعان ممدودتان بجانبك. هذه وضعية البداية.","ارفع ذراعًا واحدة بسرعة حتى مستوى الكتف.","أثناء إنزالها ارفع الذراع الأخرى.","تابع بالتبادل وأنت تضرب الحبلين للأعلى وللأسفل بأسرع ما يمكن."]],"Bear_Crawl_Sled_Drags":["زحف الدب بالزلاجة",["البس حزامًا أو حزام وزن واربط السلسلة خلفك بحيث يكون ظهرك للزلاجة. انحنِ ويداك على الأرض، والظهر مستقيم والركبتان مثنيتان. هذه وضعية البداية.","ادفع برجليك بالتبادل، واستخدم يديك للتوازن والمساعدة في السحب. حافظ على ظهر مستقيم لمسافة محددة."]],"Behind_Head_Chest_Stretch":["إطالة الصدر خلف الرأس",["اجلس باستقامة على الأرض وزميلك خلفك.","ضع يديك خلف رأسك وادفع مرفقيك للخلف لأبعد حد، ويمسك زميلك مرفقيك. هذه وضعية البداية.","حاول سحب مرفقيك للأمام برفق 10 ثوانٍ أو أكثر، ويداك خلف رأسك، بينما يمنعك زميلك.","أرخِ عضلاتك ودع زميلك يسحب مرفقيك للخلف برفق بقدر ما يريحك. أخبره عندما تكفي الإطالة."]],"Bench_Dips":["متوازي على البنش (تراي)",["ضع بنشًا خلفك بالعرض. أمسك حافته بيديك بعرض الكتفين والذراعان ممدودتان، والرجلان ممدودتان أمامك. هذه وضعية البداية.","انزل ببطء بثني المرفقين حتى تصبح الزاوية بين العضد والساعد أقل قليلًا من 90°، وأنت تشهق. المرفقان قريبان من الجسم والساعدان للأسفل دائمًا.","اصعد بالتراي إلى البداية."]],"Bench_Jump":["قفز فوق البنش",["ضع صندوقًا أو بنشًا على بعد 30–60 سم أمامك، والقدمان بعرض الكتفين. هذه وضعية البداية.","انزل في سكوات قصير استعدادًا للقفز، وأرجح ذراعيك للخلف.","انطلق بفرد الحوض والركبتين والكاحلين لتقفز لأعلى ما يمكن، مع أرجحة الذراعين للأمام وللأعلى.","اقفز فوق البنش واهبط والركبتان مثنيتان لامتصاص الصدمة.","استدر واقفز فوق البنش عائدًا."]],"Bench_Press_-_Powerlifting":["ضغط صدر (أسلوب الباورلفتنغ)",["استلقِ على البنش ورأسك خلف البار إن أمكن. اسحب قدميك للخلف وقوّس ظهرك، ثم اسحب لوحي الكتف للخلف واضغطهما معًا. حافظ على هذا الشد طوال الحركة.","مهما كان عرض قبضتك فلتغطِّ الحلقة المرسومة على البار. أخرج البار من الحامل دون أن تدفع كتفيك للأمام، واعصر البار كأنك تحاول شدّه من طرفيه.","أنزل البار إلى أسفل صدرك أو أعلى بطنك. البار والرسغ والمرفق على خط واحد دائمًا.","توقف عندما يلمس البار جسمك، ثم ادفعه للأعلى بأقصى قوة، والمرفقان قريبان من الجسم حتى نهاية الحركة."]],"Bench_Press_-_With_Bands":["ضغط صدر بالمطاط",["ثبّت المطاط تحت رجل البنش المستوي القريبة من رأسك.","أمسك المطاط من المقبضين واستلقِ على البنش.","مدّ ذراعيك أمامك بعرض الكتفين، ولفّ رسغيك لتصبح الكفّان للأمام. هذه وضعية البداية.","أنزل المقبضين ببطء حتى يصبح المرفق بزاوية 90°، بتحكّم كامل.","ازفر وادفع المقبضين للأعلى بعضلات الصدر، واعصر ثانية. النزول يأخذ ضعف وقت الصعود."]],"Bench_Press_with_Chains":["ضغط صدر بالسلاسل",["اضبط طول السلسلة الخفيفة وعلّق السلاسل على طرفي البار.","استلقِ ورأسك خلف البار إن أمكن. اسحب قدميك للخلف وقوّس ظهرك، واضغط لوحي الكتف معًا، وحافظ على هذا الشد. القبضة تغطي الحلقة المرسومة على البار.","أخرج البار دون دفع الكتفين للأمام واعصره. أنزله إلى أسفل صدرك أو أعلى بطنك، والبار والرسغ والمرفق على خط واحد.","توقف عند ملامسة جسمك، ثم ادفع البار بأقصى قوة والمرفقان قريبان من الجسم حتى القفل."]],"Bench_Sprint":["عدو على البنش",["قف على الأرض وقدم واحدة على بنش أو صندوق والكعب قرب الحافة.","ادفع بالقدم التي على البنش بفرد الورك والركبة.","اهبط بالقدم الأخرى على الصندوق وأعد الأولى إلى الأرض.","تابع بالتبادل بسرعة."]],"Bent-Arm_Barbell_Pullover":["بول أوفر بالبار بذراعين مثنيتين",["استلقِ على بنش مستوٍ وأمسك البار بقبضة بعرض الكتفين فوق صدرك، مع ثني بسيط في الذراعين.","ثبّت ثني الذراعين وأنزل البار ببطء في قوس خلف رأسك وأنت تشهق، حتى تشعر بإطالة في الصدر.","أعد البار في القوس نفسه إلى فوق صدرك وأنت تزفر، واثبت ثانية."]],"Bent-Arm_Dumbbell_Pullover":["بول أوفر بالدمبل بذراعين مثنيتين",["ضع دمبلًا واقفًا على بنش مستوٍ.","استلقِ بالعرض على البنش بحيث يستند كتفاك فقط عليه، والحوض أسفل مستوى البنش والقدمان ثابتتان على الأرض.","أمسك الدمبل بيديك من أحد طرفيه فوق صدرك مع ثني بسيط في الذراعين. تأكد أن أقراص الدمبل مثبتة جيدًا.","ثبّت ثني الذراعين وأنزل الدمبل ببطء في قوس خلف رأسك وأنت تشهق، حتى تشعر بإطالة في الصدر.","أعده في القوس نفسه إلى فوق صدرك وأنت تزفر، واثبت ثانية."]],"Bent-Knee_Hip_Raise":["رفع الحوض بركبتين مثنيتين",["استلقِ على الأرض والذراعان بجانبك.","اثنِ ركبتيك بزاوية نحو 75° وارفع قدميك عن الأرض بنحو 5 سم.","بأسفل البطن، قرّب ركبتيك نحوك مع ثبات زاوية الرجلين، حتى يرتفع حوضك عن الأرض بلفّه للخلف، وأنت تزفر. في النهاية تكون ركبتاك فوق صدرك.","اعصر البطن ثانية، ثم عد ببطء وأنت تشهق."]],"Bent_Over_Barbell_Row":["تجديف بالبار منحنيًا",["أمسك البار بقبضة علوية، اثنِ ركبتيك قليلًا وانحنِ من الخصر مع ظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. ارفع رأسك، والبار متدلٍّ أمامك.","ثبّت جذعك، ازفر واسحب البار نحوك. المرفقان قريبان من الجسم والساعدان يمسكان فقط. في الأعلى اعصر عضلات الظهر لحظة.","اشهق وأنزل البار ببطء إلى البداية."]],"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench":["كتف خلفي بالدمبل منحنيًا والرأس على البنش",["قف باستقامة ودمبل في كل يد، وأمامك بنش مائل.","مع ظهر مستقيم، انحنِ للأمام حتى تلمس جبهتك البنش، والذراعان متدليتان والكفّان متقابلتان، والجذع موازٍ للأرض.","ثبّت جذعك، ومع ثني بسيط في المرفقين ارفع الدمبلين جانبيًا حتى تصبح ذراعاك موازيتين للأرض، وأنت تزفر. لا تؤرجح جسمك ولا ترجع ذراعيك للخلف.","اثبت ثانية في الأعلى، ثم أنزلهما ببطء."]],"Bent_Over_Low-Pulley_Side_Lateral":["كتف خلفي بالكيبل السفلي منحنيًا",["اختر الوزن وأمسك مقبض الكيبل السفلي بيدك اليمنى.","انحنِ من الخصر حتى يصبح جذعك شبه موازٍ للأرض، الركبتان مثنيتان قليلًا ويدك اليسرى على فخذك. الذراع اليمنى متدلية أمامك مع ثني بسيط في المرفق.","ارفع ذراعك اليمنى جانبيًا حتى تصبح موازية للأرض وعلى خط أذنك، وأنت تزفر.","أنزلها ببطء وأنت تشهق.","أكمل التكرارات ثم بدّل الذراع."]],"Bent_Over_One-Arm_Long_Bar_Row":["تجديف بطرف البار بيد واحدة (تي بار)",["ضع أقراصًا على أحد طرفي بار أولمبي، وثبّت الطرف الآخر في زاوية حائط أو بجسم ثقيل حتى لا ينزلق.","انحنِ حتى يقترب جذعك من الموازاة مع الأرض، والركبتان مثنيتان قليلًا.","أمسك البار بيد واحدة خلف الأقراص مباشرة، وضع اليد الأخرى على ركبتك.","اسحب البار للأعلى والمرفق قريب من جسمك حتى تلمس الأقراص أسفل صدرك. اعصر الظهر ثانية في الأعلى وأنت تزفر. لا تؤرجح جذعك.","أنزل البار ببطء لتشعر بإطالة الظهر، دون أن تلمس الأقراص الأرض. استخدام أقراص صغيرة يعطي مدى حركة أفضل.","أكمل التكرارات ثم بدّل اليد."]],"Bent_Over_Two-Arm_Long_Bar_Row":["تجديف بطرف البار بيدين (تي بار)",["ضع أقراصًا على أحد طرفي بار أولمبي، وثبّت الطرف الآخر في زاوية حائط أو بجسم ثقيل حتى لا ينزلق.","انحنِ حتى يقترب جذعك من الموازاة مع الأرض، والركبتان مثنيتان قليلًا.","أمسك البار بيديك خلف الأقراص مباشرة، أو استخدم مقبض الكيبل المزدوج تحت طرف البار.","اسحب البار للأعلى والمرفقان قريبان من جسمك حتى تلمس الأقراص أسفل صدرك. اعصر الظهر ثانية في الأعلى وأنت تزفر.","أنزل البار ببطء لتشعر بإطالة الظهر، دون أن تلمس الأقراص الأرض."]],"Bent_Over_Two-Dumbbell_Row":["تجديف بدمبلين منحنيًا",["دمبل في كل يد والكفّان نحو جسمك، اثنِ ركبتيك قليلًا وانحنِ من الخصر مع ظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. ارفع رأسك، والدمبلان متدليان أمامك.","ثبّت جذعك واسحب الدمبلين إلى جانبيك وأنت تزفر، والمرفقان قريبان من الجسم. في الأعلى اعصر عضلات الظهر ثانية.","أنزلهما ببطء إلى البداية وأنت تشهق."]],"Bent_Over_Two-Dumbbell_Row_With_Palms_In":["تجديف بدمبلين منحنيًا بقبضة محايدة",["دمبل في كل يد والكفّان متقابلتان، اثنِ ركبتيك قليلًا وانحنِ من الخصر مع ظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. ارفع رأسك.","ثبّت جذعك واسحب الدمبلين إلى جانبيك وأنت تزفر، واضغط لوحي الكتف معًا. اثبت ثانية في الأعلى.","أنزلهما ببطء إلى البداية وأنت تشهق."]],"Bent_Press":["الضغط المائل (بنت برس)",["ارفع الكيتلبل إلى كتفك (كلين) بفرد الرجلين والحوض مع لفّ الرسغ. هذه وضعية البداية.","مِل إلى الجهة المعاكسة للكيتلبل حتى تلمس الأرض باليد الحرة، وعيناك على الكيتلبل، وفي الوقت نفسه افرد المرفق لتضغط الوزن عموديًا والذراع عمودية على الأرض.","عد إلى الوقوف والكيتلبل فوق رأسك، ثم أعده إلى الكتف وكرّر."]],"Bicycling":["دراجة هوائية",["اجلس على الدراجة واضبط المقعد على طولك، ثم ابدّل بالسرعة والشدة المطلوبة."]],"Bicycling_Stationary":["دراجة ثابتة",["اجلس على الدراجة واضبط المقعد على طولك.","اختر البرنامج من القائمة (قد تحتاج للبدء بالتبديل لتشغيلها)، يدويًا أو برنامجًا جاهزًا. يمكنك إدخال عمرك ووزنك لتقدير السعرات، وتغيير المقاومة أثناء التمرين، واستخدام المقابض لقياس النبض."]],"Board_Press":["ضغط صدر على لوح (بورد برس)",["استلقِ على البنش، وضع على صدرك لوحًا أو أكثر من الخشب (يمسكه زميل أو يُثبَّت تحت قميصك).","اسحب قدميك للخلف وقوّس ظهرك، واسحب لوحي الكتف للخلف واضغطهما معًا، وحافظ على هذا الشد طوال الحركة.","أمسك البار بقبضتك المعتادة، أو بعرض الكتفين للتركيز على التراي. أخرجه من الحامل، والبار والرسغ والمرفق على خط واحد.","أنزل البار حتى يلمس الألواح، ثم ادفعه للأعلى بأقصى قوة والمرفقان قريبان من الجسم."]],"Body-Up":["رفع الجسم من البلانك (بودي أب)",["اتخذ وضعية البلانك على الساعدين وأطراف القدمين، والجذع مستقيم والساعدان بعرض الكتفين. هذه وضعية البداية.","اضغط كفّيك على الأرض وافرد مرفقيك لترفع جسمك، والجذع مشدود.","أنزل ساعديك ببطء إلى الأرض بثني المرفقين، وكرّر."]],"Body_Tricep_Press":["تراي بوزن الجسم",["اضبط بارًا على الحامل بمستوى الصدر.","أمسكه بقبضة بعرض الكتفين وارجع خطوة أو اثنتين، والقدمان معًا والذراعان ممدودتان بحيث تتكئ على البار. هذه وضعية البداية.","اثنِ مرفقيك لتنزل نحو البار.","توقف لحظة، ثم افرد مرفقيك لتعود. لزيادة الصعوبة أضف سلاسل على كتفيك أو أنزل البار."]],"Bodyweight_Flyes":["تفتيح بوزن الجسم",["ضع بارين EZ متساويين في الوزن على الأرض بجانب بعضهما، بحيث يمكن دحرجتهما.","اتخذ وضعية الضغط فوق البارين، ويداك عليهما والجسم مستقيم.","ببطء وتحكّم، باعد يديك عن منتصف جسمك ودحرج البارين للخارج وأنت تشهق.","بعد أبعد مسافة ممكنة، اسحبهما معًا لتعود إلى البداية وأنت تزفر."]],"Bodyweight_Mid_Row":["تجديف بوزن الجسم",["أمسك جهاز العقلة بقبضة متوسطة إلى واسعة والكفّان للأمام. من وضع التعلّق، قرّب ركبتيك من صدرك ومِل للخلف لتضع رجليك فوق البار من جهتك. هذه وضعية البداية.","والذراعان ممدودتان، اثنِ المرفقين واضمم لوحي الكتف لترفع جسمك حتى تلامس رجلاك البار.","توقف لحظة، ثم عد إلى البداية."]],"Bodyweight_Squat":["سكوات بوزن الجسم",["قف والقدمان بعرض الكتفين، ويمكنك وضع يديك خلف رأسك. هذه وضعية البداية.","اثنِ ركبتيك وحوضك واجلس بحوضك للخلف.","انزل لأقصى عمق تستطيعه، ثم اعكس الحركة بسرعة إلى البداية. الرأس والصدر مرفوعان والركبتان للخارج."]],"Bodyweight_Walking_Lunge":["لانج مشي بوزن الجسم",["قف والقدمان بعرض الكتفين ويداك على خصرك.","اخطُ برجل للأمام واثنِ الركبتين لتنزل بحوضك حتى تكاد الركبة الخلفية تلمس الأرض. الجذع مستقيم والركبة الأمامية فوق القدم.","ادفع بكعب القدم الأمامية وافرد الركبتين لتصعد.","اخطُ بالقدم الخلفية للأمام وكرّر بالرجل الأخرى."]],"Bosu_Ball_Cable_Crunch_With_Side_Bends":["كرنش بالكيبل على كرة بوسو مع ميلان جانبي",["ركّب مقبضًا على كل كيبل واضبطهما في أدنى وضع، وضع كرة بوسو أمام الجهاز في المنتصف.","استلقِ على الكرة بحيث يلتف أسفل ظهرك حولها، والمؤخرة قريبة من الأرض دون لمسها.","أمسك المقبضين خلفك، ثم مدّ ذراعيك أمامك بين ركبتيك على مستوى الركبتين، والقدمان متباعدتان.","ارفع جذعك في حركة كرنش دون أن تثني ذراعيك أو تنزلهما، ثم انزل ببطء حتى يمتد البطن حول الكرة. كرّر حتى التعب.","في النهاية شدّ بطنك وارفع جذعك إلى وضعية البلانك، وأنزل ذراعيك بجانبك وقم بميلان جانبي بالتبادل نحو الكعبين لتشغيل الخواصر."]],"Bottoms-Up_Clean_From_The_Hang_Position":["كلين بالكيتلبل مقلوبًا من التعليق",["قف باستقامة وكيتلبل في يد واحدة.","أرجح الكيتلبل للخلف بقوة ثم اعكس الحركة بقوة. اعصر المقبض بقوة وارفع الكيتلبل مقلوبًا (القاعدة للأعلى) إلى كتفك."]],"Bottoms_Up":["رفع الحوض للأعلى (باتمز أب)",["استلقِ على ظهرك والرجلان ممدودتان والذراعان بجانبك. هذه وضعية البداية.","اثنِ حوضك وركبتيك لتقرّب ركبتيك من صدرك، ثم مدّ رجليك للأعلى عموديتين على الأرض، وارفع حوضك عن الأرض بلفّه.","توقف لحظة، ثم عد إلى البداية."]],"Box_Jump_Multiple_Response":["قفز على الصندوق (متكرر)",["قف براحة مقابل الصندوق على بعد طول ذراع تقريبًا، والذراعان بجانبك والرجلان مثنيتان قليلًا.","بمساعدة الذراعين، اقفز للأعلى وللأمام واهبط بالقدمين معًا على الصندوق.","انزل أو اقفز فورًا إلى مكانك الأول، وكرّر."]],"Box_Skip":["نطّ على الصندوق",["تحتاج عدة صناديق في صف على بعد 2.5 متر تقريبًا بين كل صندوقين.","قف مقابل الصندوق الأول ورجل خلف الأخرى قليلًا.","ادفع بالرجل الخلفية محاولًا رفع حوضك لأعلى ما يمكن.","فور الهبوط على الصندوق، ادفع بالرجل الأخرى للأمام وللأعلى لتثب منه، واهبط بين الصندوقين بالرجل نفسها التي هبطت على الأول.","اخطُ إلى الصندوق التالي وكرّر."]],"Box_Squat":["سكوات على الصندوق (بوكس سكوات)",["يسمح لك هذا السكوات بالنزول لعمق محدد وبناء قوة انفجارية. ضع صندوقًا خلفك داخل القفص، ارتفاعه يوصلك عادةً إلى موازاة الفخذ للأرض.","ضع البار على أعلى ظهرك، اضغط لوحي الكتف معًا، وأخرجه من الحامل مع تقويس أسفل الظهر. باعد القدمين للتركيز على الظهر والأرداف وخلفي الفخذ، أو قرّبهما للتركيز على أمامي الفخذ.","مع شدّ الظهر والبطن، ادفع ركبتيك ومؤخرتك للخارج واجلس بحوضك للخلف حتى تجلس على الصندوق. الساقان عموديتان قدر الإمكان. توقف على الصندوق، ولا ترتد عنه أبدًا.","والوزن على الكعبين، ادفع قدميك وركبتيك للخارج واصعد بقوة عن الصندوق، والرأس يقود الحركة، مع الحفاظ على شدّ الجسم كله."]],"Box_Squat_with_Bands":["بوكس سكوات بالمطاط",["ضع صندوقًا خلفك داخل القفص. ثبّت المطاط على طرفي البار وعلى أوتاد القفص أو دمبلات ثقيلة بشد مناسب. ارتفاع الصندوق عادةً يوصلك إلى موازاة الفخذ للأرض.","ضع البار على أعلى ظهرك، اضغط لوحي الكتف معًا، وأخرجه مع تقويس أسفل الظهر. باعد القدمين للتركيز على الأرداف وخلفي الفخذ، أو قرّبهما لأمامي الفخذ.","مع شدّ الظهر والبطن، ادفع ركبتيك ومؤخرتك للخارج واجلس للخلف حتى تجلس على الصندوق. توقف ولا ترتد أبدًا.","والوزن على الكعبين، اصعد بقوة عن الصندوق والرأس يقود الحركة، ثم أعد البار إلى الحامل بحذر."]],"Box_Squat_with_Chains":["بوكس سكوات بالسلاسل",["ضع صندوقًا خلفك داخل القفص، ارتفاعه يوصلك عادةً إلى موازاة الفخذ للأرض.","علّق السلسلة الخفيفة على طرفي البار واربط بها الثقيلة، بحيث تبقى بضع حلقات على الأرض في الأعلى.","ضع البار على أعلى ظهرك، اضغط لوحي الكتف معًا، وأخرجه مع تقويس أسفل الظهر. باعد القدمين أو قرّبهما حسب التركيز المطلوب.","مع شدّ الظهر والبطن، اجلس للخلف حتى تجلس على الصندوق. توقف ولا ترتد أبدًا.","والوزن على الكعبين، اصعد بقوة عن الصندوق والرأس يقود الحركة."]],"Brachialis-SMR":["تدليك العضدية بالفوم رولر",["استلقِ على جنبك والعضد على الفوم رولر، على خط جسمك تقريبًا، والجهة الخارجية للباي على الرولر.","ارفع حوضك عن الأرض والوزن على ذراعك وقدميك. اثبت 10–30 ثانية ثم بدّل الجهة."]],"Bradford_Rocky_Presses":["ضغط برادفورد (روكي)",["اجلس على بنش الضغط العسكري والبار على مستوى الكتفين بقبضة علوية أعرض من الكتفين.","ارفع البار فوق رأسك حتى تمتد ذراعاك.","أنزله ببطء خلف رأسك وأنت تشهق، ثم ارفعه وأنت تزفر.","أنزله أمام رأسك إلى البداية وأنت تشهق. هذا تكرار واحد. تابع بالتبادل بين الأمام والخلف. استخدم وزنًا خفيفًا إذا كان كتفك حساسًا."]],"Butt-Ups":["رفع المؤخرة من البلانك",["اتخذ وضعية الضغط لكن على ساعديك، والمرفقان مثنيان 90°.","قوّس ظهرك قليلًا للأعلى بدل إبقائه مستقيمًا تمامًا.","ارفع مؤخرتك نحو السقف وأنت تعصر البطن بقوة لتقريب القفص الصدري من الحوض، وأنت تزفر.","انزل ببطء إلى البداية وأنت تشهق، دون أن يتهدّل ظهرك."]],"Butt_Lift_Bridge":["رفع الحوض (جسر)",["استلقِ على ظهرك واليدان بجانبك والركبتان مثنيتان، والقدمان بعرض الكتفين. هذه وضعية البداية.","ادفع بكعبيك وارفع حوضك عن الأرض مع ظهر مستقيم، وأنت تزفر. اثبت ثانية في الأعلى.","انزل ببطء وأنت تشهق."]],"Butterfly":["فراشة صدر (بيك ديك)",["اجلس على الجهاز وظهرك ملتصق بالمسند.","أمسك المقابض، واضبط المقعد بحيث يكون العضدان موازيين للأرض. هذه وضعية البداية.","اضغط المقبضين نحو بعضهما ببطء وأنت تعصر صدرك في المنتصف وتزفر، واثبت ثانية.","عد ببطء إلى البداية وأنت تشهق حتى تشعر بإطالة كاملة في الصدر."]],"Cable_Chest_Press":["ضغط صدر بالكيبل",["اختر الوزن واجلس وأمسك المقابض. العضدان بزاوية 45° تقريبًا عن الجسم، والمرفقان مثنيان نحو 90°، والرأس والصدر مرفوعان.","مدّ مرفقيك واضغط المقبضين أمامك مباشرة، مع إبقاء لوحي الكتف مسحوبين للخلف.","توقف عند امتداد الذراعين، ثم عد إلى البداية مع إبقاء الشد على الكيبل.","يمكنك أداؤه أيضًا دون الاستناد إلى المسند، أو بزاوية مائلة، أو بيد واحدة بالتبادل."]],"Cable_Crossover":["تقاطع الكيبل (كيبل كروس أوفر)",["اضبط البكرتين في الأعلى (فوق رأسك)، اختر الوزن وأمسك مقبضًا بكل يد.","تقدّم خطوة أمام الخط بين البكرتين، واجمع يديك أمامك مع ميلان بسيط بالجذع للأمام. هذه وضعية البداية.","مع ثني بسيط في المرفقين، افتح ذراعيك للجانبين في قوس واسع حتى تشعر بإطالة في الصدر، وأنت تشهق. الحركة من مفصل الكتف فقط.","أعد ذراعيك في القوس نفسه إلى الأمام وأنت تزفر، واثبت ثانية."]],"Cable_Crunch":["كرنش بالكيبل",["اركع تحت الكيبل العلوي المركّب عليه حبل.","أمسك الحبل وأنزله حتى تصبح يداك بجانب وجهك.","اثنِ حوضك قليلًا ودع الوزن يمدّ أسفل ظهرك. هذه وضعية البداية.","ثبّت الحوض واثنِ جذعك بعصر البطن حتى يتجه المرفقان نحو منتصف الفخذين، وأنت تزفر. اثبت ثانية.","عد ببطء وأنت تشهق، مع إبقاء الشد على البطن. لا تختر وزنًا ثقيلًا يجعل أسفل الظهر يقوم بالعمل."]],"Cable_Deadlifts":["ديدلفت بالكيبل",["اضبط البكرتين في الأسفل واختر الوزن، وقف في المنتصف بينهما.","انزل بثني الحوض والركبتين حتى تصل إلى المقبضين.","أمسكهما وادفع بكعبيك لتفرد حوضك وركبتيك وتقف، واليدان متدليتان بجانبك. الرأس والصدر مرفوعان.","بعد الوقوف الكامل، عد إلى البداية وكرّر."]],"Cable_Hammer_Curls_-_Rope_Attachment":["باي مطرقة بالكيبل بالحبل",["ركّب حبلًا على الكيبل السفلي وقف مقابل الجهاز على بعد 30 سم تقريبًا.","أمسك الحبل بقبضة محايدة (الكفّان متقابلتان) وقف باستقامة مع ثبات الجذع.","ألصق مرفقيك بجانبيك وثبّتهما طوال الحركة. الساعدان فقط يتحركان.","ارفع الحبل بالباي وأنت تزفر حتى يلامس الباي الساعدين.","اعصر الباي ثانية، ثم أنزل الوزن ببطء."]],"Cable_Hip_Adduction":["ضم الفخذ بالكيبل",["قف أمام الكيبل السفلي، ورجل بجانب الجهاز والأخرى بعيدة عنه.","اربط حزام الكاحل بالكيبل وبكاحل الرجل القريبة من الجهاز.","ابتعد عن الجهاز بوقفة واسعة وأمسك إطار الجهاز للتوازن.","قف على القدم البعيدة، ودع الرجل المربوطة تنسحب نحو الجهاز. هذه وضعية البداية.","اسحب الرجل المربوطة إلى أمام الرجل الأخرى باستخدام الفخذ الداخلي، وأنت تزفر.","عد ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الرجل."]],"Cable_Incline_Pushdown":["تراي للأسفل بالكيبل على بنش مائل",["استلقِ على بنش مائل وظهرك للكيبل العلوي المركّب عليه بار مستقيم.","أمسك البار فوق رأسك بقبضة علوية بعرض الكتفين، ومدّ ذراعيك أمامك حتى يقترب البار من فخذيك.","مع إبقاء الذراعين مستقيمتين، حرّكهما للخلف في نصف دائرة حتى يصبح البار فوق رأسك، وأنت تشهق.","عد ببطء إلى البداية بعضلات الظهر (لاتس) واعصرها، وأنت تزفر."]],"Cable_Incline_Triceps_Extension":["تراي بالكيبل على بنش مائل",["استلقِ على بنش مائل وظهرك للكيبل العلوي المركّب عليه بار مستقيم.","أمسك البار فوق رأسك بقبضة علوية ضيقة، والمرفقان قريبان من جسمك.","ثبّت العضدين ومدّ ذراعيك بعصر التراي وأنت تزفر، واثبت ثانية.","عد ببطء إلى البداية."]],"Cable_Internal_Rotation":["تدوير الكتف للداخل بالكيبل",["اجلس بجانب الكيبل السفلي وأمسك المقبض باليد القريبة منه. يمكنك الجلوس على بنش إذا أمكن رفع البكرة.","ألصق المرفق بجانبك مثنيًا 90° والساعد يشير نحو الجهاز. هذه وضعية البداية.","اسحب المقبض نحو جسمك بتدوير الكتف للداخل حتى يصبح الساعد أمام بطنك، في نصف دائرة. الساعد عمودي على الجذع دائمًا.","عد ببطء إلى البداية. أكمل التكرارات ثم بدّل الذراع."]],"Cable_Iron_Cross":["الصليب الحديدي بالكيبل",["اضبط البكرتين في الأعلى، اختر الوزن وأمسك مقبضًا بكل يد.","قف في المنتصف والذراعان ممدودتان للجانبين على شكل حرف T، والرأس والصدر مرفوعان.","مع إبقاء المرفقين ممدودين، اسحب ذراعيك للأسفل إلى جانبيك.","توقف عند أقصى انقباض، ثم أعد ذراعيك إلى البداية."]],"Cable_Judo_Flip":["قلبة الجودو بالكيبل",["ركّب حبلًا على الكيبل في أدنى وضع، وقف وجانبك للجهاز بوقفة واسعة وأمسك الحبل بيديك.","لفّ جسمك بعيدًا عن الجهاز وأنت تجرّ الحبل فوق كتفك، كأنك تقلب خصمًا في الجودو.","انقل وزنك بين قدميك وأنت تلتف وتنحني للأمام ساحبًا الكيبل للأسفل.","عد إلى البداية وكرّر، ثم بدّل الجهة."]],"Cable_Lying_Triceps_Extension":["تراي بالكيبل مستلقيًا",["استلقِ على بنش مستوٍ وأمسك البار المستقيم للكيبل السفلي بقبضة علوية ضيقة (الأسهل أن يناولك أحدهم البار).","مدّ ذراعيك فوق جذعك بحيث تكونان عموديتين عليه. هذه وضعية البداية.","ثبّت العضدين والمرفقين للداخل، وأنزل البار بثني المرفقين حتى يلامس جبهتك برفق، وأنت تشهق.","ارفعه إلى البداية بعصر التراي وأنت تزفر، واثبت ثانية."]],"Cable_One_Arm_Tricep_Extension":["تراي بالكيبل بيد واحدة",["أمسك مقبضًا واحدًا على الكيبل العلوي بيدك اليمنى بقبضة سفلية (الكف للأعلى)، وقف أمام الجهاز مباشرة.","اسحب المقبض حتى يلتصق العضد والمرفق بجانبك، والزاوية بين العضد والساعد أقل من 90°. يمكنك وضع رجل أمام الأخرى للتوازن.","مدّ ذراعك للأسفل بعصر التراي حتى تستقيم، وأنت تزفر. العضد ثابت والساعد فقط يتحرك.","اعصر التراي ثانية، ثم عد ببطء. أكمل التكرارات ثم بدّل الذراع."]],"Cable_Preacher_Curl":["باي على المسند بالكيبل (بريتشر)",["ضع بنش المسند (بريتشر) على بعد 60 سم تقريبًا أمام الكيبل، وركّب بارًا مستقيمًا على الكيبل السفلي.","اجلس على البنش والعضدان على المسند، وأمسك البار والذراعان ممدودتان. هذه وضعية البداية.","اثنِ البار نحو كتفيك وأنت تزفر، واعصر الباي بقوة واثبت ثانية في الأعلى.","أنزل الوزن ببطء إلى البداية."]],"Cable_Rear_Delt_Fly":["كتف خلفي بالكيبل (تفتيح عكسي)",["اضبط البكرتين فوق مستوى رأسك واختر الوزن.","أمسك البكرة اليسرى بيدك اليمنى واليمنى باليسرى، بحيث يتقاطع الكيبلان أمامك. هذه وضعية البداية.","حرّك ذراعيك للخلف وللخارج مع إبقائهما مستقيمتين.","توقف في نهاية الحركة، ثم أعد المقبضين إلى البداية."]],"Cable_Reverse_Crunch":["كرنش عكسي بالكيبل",["ركّب حزام الكاحل على الكيبل السفلي وضع حصيرة أمامه.","اجلس وقدماك نحو الجهاز واربط الكيبل بكاحليك.","استلقِ وارفع رجليك مع ثني الركبتين 90°، بحيث تكون الرجلان على خط الكيبل (عدّل ارتفاع البكرة إن لزم).","ويداك خلف رأسك، اسحب ركبتيك نحو جذعك وارفع حوضك عن الأرض.","توقف لحظة، ثم أنزل حوضك ببطء وأعد رجليك إلى زاوية 90° مع إبقاء الشد على البطن."]],"Cable_Rope_Overhead_Triceps_Extension":["تراي خلف الرأس بالكيبل بالحبل",["ركّب حبلًا على الكيبل السفلي.","أمسك الحبل بيديك بقبضة محايدة ومدّ ذراعيك فوق رأسك، والمرفقان قريبان من الرأس والذراعان عموديتان على الأرض. هذه وضعية البداية.","ثبّت العضدين وأنزل الحبل ببطء خلف رأسك وأنت تشهق، حتى تشعر بإطالة كاملة في التراي.","عد إلى البداية بعصر التراي وأنت تزفر."]],"Cable_Rope_Rear-Delt_Rows":["تجديف كتف خلفي بالكيبل بالحبل",["اجلس على جهاز التجديف بالكيبل السفلي كما في التجديف العادي للظهر.","ركّب حبلًا وأمسكه بقبضة علوية، والذراعان ممدودتان موازيتان للأرض والمرفقان للخارج.","أسفل ظهرك مستقيم والركبتان مثنيتان قليلًا. هذه وضعية البداية.","اسحب الحبل نحو أعلى صدرك تحت الرقبة، والمرفقان مرفوعان للخارج، حتى يصلا خلف ظهرك قليلًا، وأنت تزفر. العضدان موازيان للأرض طوال الحركة.","عد إلى البداية مع مدّ الذراعين وإطالة الكتفين للأمام، وأنت تشهق."]],"Cable_Russian_Twists":["الالتفاف الروسي بالكيبل",["ركّب مقبضًا على الكيبل واضبطه في المنتصف.","استلقِ على كرة التمارين بالعرض بالنسبة للكيبل، على بعد طول ذراع تقريبًا، والكيبل مشدود.","أمسك المقبض بيديك ومدّ ذراعيك فوق صدرك على خط البكرة.","ارفع حوضك وشدّ بطنك، ولفّ جذعك بعيدًا عن الجهاز ربع دورة. جسمك مستقيم من الرأس إلى الركبتين.","توقف لحظة ثم عد ببطء مع إبقاء الشد. أكمل التكرارات ثم بدّل الجهة."]],"Cable_Seated_Crunch":["كرنش بالكيبل جلوسًا",["اجلس على بنش مستوٍ وظهرك للكيبل العلوي.","أمسك الحبل بيديك (الكفّان متقابلتان) وثبّت يديك فوق كتفيك. دع الوزن يمدّ أسفل ظهرك قليلًا.","ثبّت الحوض واثنِ جذعك حتى يتجه المرفقان نحو الحوض، وأنت تزفر.","عد ببطء إلى البداية وأنت تشهق."]],"Cable_Seated_Lateral_Raise":["رفرفة جانبية بالكيبل جلوسًا",["قف بين بكرتين سفليتين متقابلتين، وضع بنشًا مستويًا خلفك بالعرض، واختر الوزن على كل بكرة.","اجلس على طرف البنش وقدماك أمام ركبتيك، وانحنِ للأمام بظهر مستقيم حتى يستند جذعك على فخذيك.","أمسك البكرة اليسرى باليد اليمنى واليمنى باليسرى، بحيث يمرّ الكيبلان تحت ركبتيك، والذراعان ممدودتان مع ثني بسيط في المرفقين.","ارفع ذراعيك جانبيًا حتى تصبحا موازيتين للأرض على مستوى الكتفين، وأنت تزفر، واثبت ثانية.","أنزلهما ببطء وأنت تشهق، مع ثبات زاوية المرفق طوال الحركة."]],"Cable_Shoulder_Press":["ضغط أكتاف بالكيبل",["اضبط البكرتين في الأسفل واختر الوزن.","قف في المنتصف وأمسك المقبضين على مستوى الكتفين والكفّان للأمام. هذه وضعية البداية.","ارفع رأسك وصدرك، ومدّ مرفقيك لتضغط المقبضين فوق رأسك مباشرة.","توقف في الأعلى، ثم عد إلى البداية."]],"Cable_Shrugs":["ترابيس بالكيبل (شراغ)",["أمسك بارًا مركّبًا على الكيبل السفلي بقبضة علوية بعرض الكتفين أو أعرض قليلًا.","قف باستقامة قريبًا من الجهاز والذراعان ممدودتان أمامك.","ارفع كتفيك لأعلى ما يمكن وأنت تزفر، واثبت ثانية. الذراعان ممدودتان دائمًا، ولا تسحب بالباي.","أنزل البار إلى البداية."]],"Cable_Wrist_Curl":["باي الرسغ بالكيبل",["ضع بنشًا مستويًا أمام الكيبل السفلي المركّب عليه بار مستقيم.","أمسك البار بقبضة سفلية (الكفّان للأعلى) واسند ساعديك على فخذيك، والرسغان خارج الركبتين.","اثنِ رسغيك للأعلى وأنت تزفر، واثبت ثانية.","أنزل رسغيك ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك."]],"Calf-Machine_Shoulder_Shrug":["ترابيس على جهاز السمانة",["ضع نفسك على جهاز السمانة بحيث تكون المساند فوق كتفيك، والجذع مستقيم والذراعان بجانبك.","ارفع كتفيك نحو أذنيك وأنت تزفر، واثبت ثانية كاملة.","انزل ببطء إلى البداية وأنت تشهق."]],"Calf_Press":["ضغط السمانة",["اضبط المقعد بحيث تكون رجلاك مثنيتين قليلًا في البداية، ومقدمة قدميك ثابتة على المنصة.","اختر الوزن وأمسك المقابض.","افرد ركبتيك لترفع الوزن قليلًا عن المكدّس، ثم ادفع بمقدمة قدميك لأقصى حد.","توقف لحظة، ثم عد بإطالة كاملة وكرّر."]],"Calf_Press_On_The_Leg_Press_Machine":["سمانة على مكبس الأرجل",["اجلس على مكبس الأرجل وضع قدميك على المنصة بعرض الكتفين.","حرّر أذرع الأمان وادفع المنصة حتى تمتد رجلاك دون قفل الركبتين (إن سمح الجهاز بإبقاء الأمان فهو أفضل). ثم ضع مقدمة قدميك على الطرف السفلي للمنصة والكعبان خارجها.","ادفع المنصة برفع كعبيك لأقصى حد وأنت تزفر، واعصر السمانة ثانية. الركبتان ثابتتان دون ثني.","انزل ببطء بإنزال الكعبين حتى تشعر بإطالة السمانة، وأنت تشهق."]],"Calf_Raise_On_A_Dumbbell":["سمانة على دمبل",["أمسك شيئًا ثابتًا للتوازن وقف على مقبض دمبل (الأقراص الدائرية تجعل التوازن أصعب وأفيد).","دحرج قدمك قليلًا للأمام لتحصل على إطالة جيدة في السمانة.","ارفع كعبك وأنت تدحرج قدمك فوق المقبض لتمتد بالكامل، وأنت تزفر. اعصر السمانة ثانية في الأعلى.","انزل وأنت تشهق مع دحرجة الدمبل قليلًا للأمام لإطالة أكبر."]],"Calf_Raises_-_With_Bands":["سمانة بالمطاط",["قف بمقدمة قدميك على مطاط التمارين، مع طول متساوٍ من الجهتين.","أمسك المقبضين وارفع يديك بجانب رأسك كأنك ستضغط أكتاف، الكفّان للأمام والمرفقان مثنيان للجانبين، ليشتد المطاط. هذه وضعية البداية.","ويداك عند كتفيك، ارتفع على أصابع قدميك وأنت تزفر، واعصر السمانة بقوة.","اثبت ثانية، ثم انزل ببطء."]],"Calf_Stretch_Elbows_Against_Wall":["إطالة السمانة والمرفقان على الحائط",["قف مقابل حائط على بعد نحو 60 سم.","مِل نحو الحائط واستند على ساعديك.","حاول إبقاء كعبيك على الأرض. اثبت 10–20 ثانية. الابتعاد عن الحائط يزيد الإطالة والاقتراب يخففها."]],"Calf_Stretch_Hands_Against_Wall":["إطالة السمانة واليدان على الحائط",["قف مقابل حائط على بعد خطوات، وقدم أمام الأخرى.","مِل للأمام وضع يديك على الحائط، والكعب الخلفي والحوض والرأس على خط مستقيم.","حاول إبقاء الكعب على الأرض. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Calves-SMR":["تدليك السمانة بالفوم رولر",["اجلس على الأرض والفوم رولر تحت ساقك. الرجل الأخرى فوقها أو على الأرض تحمل جزءًا من الوزن. هذه وضعية البداية.","ضع يديك بجانبك أو خلفك واضغط لترفع حوضك، فيقع معظم وزنك على السمانة. تدحرج من تحت الركبة حتى فوق الكاحل، وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالرجل الأخرى."]],"Car_Deadlift":["ديدلفت السيارة",["جهاز ديدلفت السيارة له عادةً مقابض محايدة، ويُحمّل بسيارة أو أوزان ثقيلة كالإطارات.","قف في منتصف المقابض (أو أخّر قليلًا إن كنت قويًا في الديدلفت)، والقدمان بعرض الحوض. انحنِ وأمسك المقابض، خذ نفسًا عميقًا وأنزل حوضك واثنِ ركبتيك.","انظر للأمام وارفع صدرك وقوّس ظهرك، وادفع بكعبيك لترفع الوزن، مع ضم لوحي الكتف ودفع الحوض للأمام.","أنزل الوزن بثني الحوض وتوجيهه إلى الأرض."]],"Car_Drivers":["مقود السيارة (بالقرص)",["قف باستقامة وأمسك قرصًا بيديك عند الساعة 3 والساعة 9، والذراعان ممدودتان أمامك.","لفّ القرص لأقصى حد إلى جهة واحدة، كأنك تدير مقود سيارة.","اعكس الحركة إلى الجهة الأخرى بالكامل."]],"Carioca_Quick_Step":["خطوات كاريوكا السريعة",["قف والقدمان متقاربتان والذراع اليسرى مرفوعة بوضعية رياضية مرتاحة.","بقدمك اليمنى اخطُ بسرعة خلف اليسرى وارفع الركبة.","حرّك ذراعيك للأعلى مع رفع الركبة، والركبة تتحرك للأعلى وللأسفل مستقيمة. لا تدِر قدميك، وانظر للأمام وأنت تتحرك جانبيًا."]],"Cat_Stretch":["إطالة القطة",["ابدأ على يديك وركبتيك.","اسحب بطنك للداخل وقوّس ظهرك وكتفيك ورقبتك للأعلى، ودع رأسك ينخفض.","اثبت 15 ثانية."]],"Catch_and_Overhead_Throw":["التقاط ورمي من فوق الرأس",["قف مقابل حائط أو زميل.","أمسك الكرة بيديك خلف رأسك مع أقصى إطالة، وارمها للأمام بقوة.","أكمل حركة الرمي واستعد لاستقبال الكرة المرتدة. مع الحائط قف قريبًا بما يكفي وصوّب أعلى قليلًا."]],"Chain_Handle_Extension":["تراي بمقبض السلسلة",["تحتاج مقبضي كيبل وبنشًا مستويًا وسلاسل. علّق منتصف السلاسل بالمقبضين واستلقِ على البنش، والمرفقان يشيران للأعلى.","افرد المرفقين مع ثبات العضدين والرسغان بقبضة علوية.","توقف عند امتداد الذراعين، ثم عد إلى البداية."]],"Chain_Press":["ضغط بالسلاسل",["علّق السلاسل بمقبضي الكيبل. استلقِ على بنش مستوٍ كما في ضغط الدمبل، والرسغان بقبضة علوية والذراعان عموديتان على الأرض. هذه وضعية البداية.","أنزل السلاسل بثني المرفقين، فيستقر جزء منها على الأرض.","تابع حتى يصبح المرفق بزاوية 90°، ثم ادفع للأعلى حتى امتداد الذراعين."]],"Chair_Leg_Extended_Stretch":["إطالة الرجل الممدودة على الكرسي",["اجلس باستقامة على كرسي وأمسك جانبي المقعد.","ارفع رجلًا مع فرد الركبة وثني الكاحل نحوك.","حرّك الرجل ببطء للخارج لأبعد حد، ثم أعدها إلى المنتصف وأنزلها.","كرّر بالرجل الأخرى."]],"Chair_Lower_Back_Stretch":["إطالة أسفل الظهر على الكرسي",["اجلس باستقامة على كرسي.","مِل إلى جانب والذراع فوق رأسك، ويمكنك الإمساك بالكرسي باليد الأخرى.","اثبت 10 ثوانٍ، ثم كرّر بالجهة الأخرى."]],"Chair_Squat":["سكوات الكرسي",["اضبط البار على ارتفاع يناسب طولك، ثم ضعه على أعلى ظهرك.","أمسك البار وارفعه عن الحامل بفرد رجليك.","قدّم قدميك نحو 45 سم أمام البار، بعرض الكتفين وأصابعهما للخارج قليلًا. انظر للأمام وحافظ على ظهر مستقيم.","انزل ببطء بثني الركبتين كأنك تجلس على كرسي، حتى تصبح الزاوية أقل من 90°.","ادفع بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Chair_Upper_Body_Stretch":["إطالة الجزء العلوي على الكرسي",["اجلس على طرف كرسي وأمسك ظهره.","افرد ذراعيك مع ظهر مستقيم واسحب الجزء العلوي للأمام حتى تشعر بإطالة. اثبت 20–30 ثانية."]],"Chest_And_Front_Of_Shoulder_Stretch":["إطالة الصدر ومقدمة الكتف",["قف والرجلان معًا وأمسك عصا أو بارًا خفيفًا.","أمسكه بقبضة أعرض قليلًا من الكتفين أمامك والكفّان للأسفل.","ارفعه بحذر فوق رأسك وخلفه حتى تشعر بإطالة في الصدر ومقدمة الكتفين."]],"Chest_Push_from_3_point_stance":["دفع الصدر من وضعية الثلاث نقاط",["ابدأ بوضعية الثلاث نقاط: منخفضًا والظهر مستقيم ويد على الأرض، والكرة الطبية أمامك.","مع الخطوة الأولى اسحب الكرة إلى صدرك وجهّز يديك للرمي.","مع الخطوة الثانية ادفع الكرة للأمام بقوة انفجارية."]],"Chest_Push_multiple_response":["دفع الصدر بالكرة الطبية (متكرر)",["اركع مقابل حائط أو زميل، وأمسك الكرة بيديك ملاصقة لصدرك.","اندفع بحوضك للأمام وللخارج وادفع الكرة بأقصى قوة.","أكمل الحركة بالسقوط للأمام واستقبل نفسك بيديك.","عد فورًا إلى الوضع المستقيم وكرّر."]],"Chest_Push_single_response":["دفع الصدر بالكرة الطبية (مرة واحدة)",["اركع وأمسك الكرة الطبية بيديك ملاصقة لصدرك.","اندفع بحوضك للأمام وللخارج وادفع الكرة لأبعد مسافة.","أكمل الحركة بالسقوط للأمام واستقبل نفسك بيديك."]],"Chest_Push_with_Run_Release":["دفع الصدر مع الانطلاق جريًا",["قف بوضعية رياضية: الركبتان مثنيتان والحوض للخلف والظهر مستقيم، والكرة قرب رجليك. هذه وضعية البداية.","مع الخطوة الأولى اسحب الكرة إلى صدرك.","مع الخطوة الثانية ادفعها للأمام بقوة، ثم اركض فورًا نحو 10 أمتار."]],"Chest_Stretch_on_Stability_Ball":["إطالة الصدر على كرة التمارين",["انزل على يديك وركبتيك بجانب كرة التمارين.","ضع مرفقك فوق الكرة والذراع للجانب. هذه وضعية البداية.","أنزل جذعك نحو الأرض والمرفق على الكرة. اثبت 20–30 ثانية ثم بدّل الذراع."]],"Childs_Pose":["وضعية الطفل",["ابدأ على يديك وركبتيك، ثم امشِ بيديك للأمام.","أنزل مؤخرتك لتجلس على كعبيك، ودع ذراعيك تنسحبان على الأرض لتطيل ظهرك كله.","بعد الجلوس على الكعبين، ضع يديك بجانب قدميك واسترخِ وجبهتك على الأرض، وتنفّس بعمق. تجنّب هذه الوضعية إن كانت عندك مشاكل في الركبة."]],"Chin-Up":["عقلة بقبضة سفلية (تشن أب)",["أمسك بار العقلة بقبضة سفلية (الكفّان نحوك) أضيق من الكتفين.","والذراعان ممدودتان، أبقِ جذعك مستقيمًا قدر الإمكان مع تقويس بسيط في أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","ازفر واسحب جسمك للأعلى حتى يصل رأسك إلى مستوى البار تقريبًا، معتمدًا على الباي والمرفقان قريبان من الجسم.","اعصر ثانية، ثم انزل ببطء حتى تمتد ذراعاك بالكامل، وأنت تشهق."]],"Chin_To_Chest_Stretch":["إطالة الذقن نحو الصدر",["اجلس على الأرض.","شبّك يديك خلف رأسك والإبهامان للأسفل والمرفقان للأمام، واسحب رأسك ببطء نحو صدرك. اثبت 20–30 ثانية."]],"Circus_Bell":["جرس السيرك",["جرس السيرك دمبل ضخم بمقبض سميك. ابدأ والدمبل بين قدميك وأمسك المقبض بيديك.","ارفعه إلى كتفك (كلين) بفرد الحوض والركبتين، ثم اترك اليد الإضافية.","اجعل أحد رأسي الدمبل خلف كتفك حتى لا يختل توازنك. لرفعه فوق رأسك انزل قليلًا بالركبتين ثم ادفع للأعلى وأنت تمدّه فوق رأسك، مائلًا قليلًا بعيدًا عنه.","أعده إلى الأرض بحذر وتحكّم، ويُفضّل على حصيرة مطاطية سميكة."]],"Clean":["كلين",["البار على الأرض قريب من ساقيك، أمسكه بقبضة علوية (أو قبضة الخطّاف) خارج الرجلين مباشرة. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع، والكتفان أمام البار قليلًا.","السحبة الأولى: ادفع بالكعبين وافرد الركبتين، مع ثبات زاوية الظهر والذراعان مستقيمتان، حتى يتجاوز البار الركبتين بتحكّم.","السحبة الثانية: عندما يقترب البار من منتصف الفخذ، افرد الحوض والركبتين والكاحلين بقوة كأنك تقفز، والذراعان ما زالتا مستقيمتين، والجسم في النهاية ممدود ومائل قليلًا للخلف.","السحبة الثالثة: ارفع كتفيك بقوة واثنِ ذراعيك والمرفقان للأعلى وللخارج، ثم اسحب نفسك تحت البار مع لفّ المرفقين تحته. استقبله في وضعية سكوات أمامي على مقدمة الكتفين ملامسًا الرقبة برفق.","اصعد فورًا بالدفع بالكعبين، والجذع مستقيم والمرفقان مرفوعان، حتى تقف."]],"Clean_Deadlift":["ديدلفت الكلين",["قف والبار قريب من ساقيك، والقدمان تحت الحوض وأصابعهما للخارج قليلًا. أمسك البار بقبضة علوية أو قبضة الخطّاف بعرض الكتفين، وانزل إليه. الظهر مستقيم تمامًا والكتفان أمام البار، والظهر أقرب للعمودي قدر الإمكان.","ادفع الأرض بمقدمة الكعبين. أثناء صعود البار حافظ على زاوية الظهر ثابتة، وادفع ركبتيك للخارج لتبتعد عن مسار البار.","بعد تجاوز البار الركبتين، ادفع حوضك نحو البار حتى يمتد الحوض والركبتان بالكامل."]],"Clean_Pull":["سحب الكلين",["البار على الأرض قريب من ساقيك، أمسكه بقبضة علوية أو قبضة الخطّاف خارج الرجلين. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع.","السحبة الأولى: ادفع بالكعبين وافرد الركبتين، مع ثبات زاوية الظهر والذراعان مستقيمتان، حتى يتجاوز البار الركبتين.","السحبة الثانية: عند منتصف الفخذ افرد الحوض والركبتين والكاحلين بقوة كأنك تقفز، دون السحب بالذراعين. في النهاية يكون الجسم ممدودًا ومائلًا قليلًا للخلف، بامتداد سريع وحاد."]],"Clean_Shrug":["ترابيس الكلين",["أمسك البار بقبضة علوية أو قبضة الخطّاف بعرض الكتفين، والبار متدلٍّ عند منتصف الفخذ، والظهر مستقيم ومائل للأمام قليلًا.","ارفع كتفيك نحو أذنيك. يمكن استخدام وزن أثقل من الكلين، لكن لا تثقل لدرجة تبطئ الحركة."]],"Clean_and_Jerk":["كلين وجيرك",["البار على الأرض قريب من ساقيك، أمسكه بقبضة علوية أو قبضة الخطّاف خارج الرجلين. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع.","السحبة الأولى: ادفع بالكعبين وافرد الركبتين، مع ثبات زاوية الظهر والذراعان مستقيمتان، حتى يتجاوز البار الركبتين.","السحبة الثانية: عند منتصف الفخذ افرد الحوض والركبتين والكاحلين بقوة كأنك تقفز، دون السحب بالذراعين.","السحبة الثالثة: ارفع كتفيك واثنِ ذراعيك، واسحب نفسك تحت البار مع لفّ المرفقين، واستقبله في سكوات أمامي على مقدمة الكتفين.","قف فورًا بالدفع بالكعبين والجذع مستقيم والمرفقان مرفوعان.","الجيرك: والبار على كتفيك والقدمان تحت الحوض، انزل قليلًا بالركبتين ثم اعكس بأقصى قوة، وأبعد رأسك عن مسار البار.","افتح قدميك (واحدة للأمام وأخرى للخلف) واستقبل البار والذراعان مقفلتان فوق رأسك، ثم قف واجمع قدميك."]],"Clean_and_Press":["كلين وضغط",["قف بعرض الكتفين والركبتان بين الذراعين. بظهر مستقيم، اثنِ ركبتيك وحوضك وأمسك البار بقبضة علوية أعرض قليلًا من الكتفين، والبار قريب من الساقين والكتفان فوقه أو أمامه قليلًا.","اسحب البار بفرد الركبتين، مع رفع الحوض والكتفين معًا وثبات زاوية الظهر، والبار قريب من جسمك.","عندما يتجاوز البار الركبتين، افرد الكاحلين والركبتين والحوض بقوة كأنك تقفز، وارفع كتفيك لتسحب البار لأعلى ما يمكن والمرفقان للخارج.","في أعلى نقطة اسحب نفسك تحت البار ونزولًا في سكوات.","لفّ مرفقيك تحت البار واستقبله على مقدمة كتفيك، مع ثني الحوض والركبتين لامتصاص الوزن، ثم قف باستقامة.","دون تحريك قدميك، اضغط البار فوق رأسك وأنت تزفر، ثم أنزله بتحكّم."]],"Clean_from_Blocks":["كلين من المكعبات",["البار على صناديق بالارتفاع المطلوب. أمسكه بقبضة علوية أو قبضة الخطّاف خارج الرجلين. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع.","ادفع بالكعبين وافرد الركبتين والحوض بقوة، مع ثبات زاوية الظهر والذراعان مستقيمتان.","عند الامتداد الكامل، ارفع كتفيك بقوة واثنِ ذراعيك والمرفقان للأعلى وللخارج، ثم اسحب نفسك تحت البار مع لفّ المرفقين تحته، واستقبله في سكوات أمامي.","اصعد فورًا بالدفع بالكعبين حتى تقف. أعد البار إلى الصناديق للتكرار التالي."]],"Clock_Push-Up":["ضغط الساعة (بوش أب دائري)",["اتخذ وضعية الضغط على يديك وأطراف قدميك، واليدان بعرض الكتفين والجسم مستقيم. هذه وضعية البداية.","انزل بثني المرفقين بصدرك نحو الأرض.","في الأسفل ادفع للأعلى بأسرع ما يمكن حتى ترتفع عن الأرض، وانتقل بجسمك 30–45 سم إلى جانب واحد.","انقل القدم الخارجية مع الحركة، ودُر بجسمك نحو 30° مع كل تكرار.","تابع حتى تكمل دائرة كاملة وتعود إلى مكانك."]],"Close-Grip_Barbell_Bench_Press":["ضغط صدر بالبار بقبضة ضيقة",["استلقِ على بنش مستوٍ وأمسك البار بقبضة ضيقة (بعرض الكتفين تقريبًا)، ارفعه من الحامل والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى يلمس منتصف صدرك. أبقِ المرفقين قريبين من جسمك دائمًا لتشغيل التراي أكثر.","توقف ثانية، ثم ادفع البار بالتراي إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد البار إلى الحامل."]],"Close-Grip_Dumbbell_Press":["ضغط دمبل بقبضة ضيقة",["ضع دمبلًا واقفًا على بنش مستوٍ.","استلقِ بالعرض على البنش بحيث يستند كتفاك فقط، والحوض أسفل مستوى البنش والقدمان ثابتتان على الأرض.","أمسك الدمبل بيديك من جانبيه فوق صدرك والذراعان ممدودتان.","أنزل الدمبل إلى صدرك.","افرد مرفقيك لتعود إلى البداية."]],"Close-Grip_EZ-Bar_Curl_with_Band":["باي بار EZ بقبضة ضيقة مع مطاط",["اربط مطاطًا بكل طرف من البار، وقف على منتصف المطاط. أمسك بار EZ بقبضة سفلية ضيقة والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ المرفقين لترفع البار وأنت تزفر.","تابع حتى يصل البار إلى مستوى الكتفين، واثبت ثانية واعصر الباي بقوة.","أنزل البار ببطء وأنت تشهق."]],"Close-Grip_EZ-Bar_Press":["ضغط بار EZ بقبضة ضيقة",["استلقِ على بنش مستوٍ مع بار EZ محمّل بالوزن المناسب.","أمسك البار بقبضة ضيقة وارفعه فوق جذعك والمرفقان للداخل، والذراعان عموديتان على الأرض.","أنزل البار إلى أسفل صدرك وأنت تشهق، والمرفقان قريبان من الجسم.","ادفعه بالتراي إلى البداية بفرد المرفقين وأنت تزفر."]],"Close-Grip_EZ_Bar_Curl":["باي بار EZ بقبضة ضيقة",["قف باستقامة وأمسك بار EZ من المقبض الداخلي الضيق، الكفّان للأمام ومائلتان للداخل قليلًا، والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ البار للأعلى وأنت تزفر. الساعدان فقط يتحركان.","تابع حتى يصل البار إلى مستوى الكتفين، واثبت ثانية واعصر الباي بقوة.","أنزل البار ببطء وأنت تشهق."]],"Close-Grip_Front_Lat_Pulldown":["سحب أمامي بقبضة ضيقة (لات بول داون)",["اجلس على جهاز السحب الأمامي واضبط مسند الركبتين ليثبّتك.","أمسك البار بقبضة ضيقة (أقل من عرض الكتفين) والكفّان للأمام.","والذراعان ممدودتان، مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","اسحب البار وأنت تزفر حتى يلمس أعلى صدرك، بسحب الكتفين والعضدين للأسفل وللخلف. اعصر الظهر في الأسفل. الجذع ثابت والساعدان يمسكان فقط.","بعد ثانية، ارفع البار ببطء حتى تمتد ذراعاك وتشعر بإطالة الظهر، وأنت تشهق."]],"Close-Grip_Push-Up_off_of_a_Dumbbell":["ضغط بقبضة ضيقة على دمبل (بوش أب)",["استلقِ على الأرض وضع يديك على دمبل واقف. والوزن على أطراف القدمين واليدين، الجذع مشدود والمرفقان للداخل والذراعان مستقيمتان. هذه وضعية البداية.","انزل بثني المرفقين وأنت تشهق، والجسم مستقيم دون ارتفاع أو هبوط الحوض.","ادفع لتعود إلى البداية بفرد المرفقين وأنت تزفر.","توقف لحظة في الأعلى، ثم كرّر."]],"Close-Grip_Standing_Barbell_Curl":["باي بالبار وقوفًا بقبضة ضيقة",["أمسك البار بيديك بقبضة سفلية (الكفّان للأعلى) والمسافة بين اليدين بضعة سنتيمترات.","قف باستقامة والرأس مرفوع، القدمان بعرض الكتفين والمرفقان قريبان من الجسم. العضدان ثابتان طوال الحركة.","اثنِ البار للأعلى في نصف دائرة حتى يلامس الساعدان الباي، وأنت تزفر، واعصر الباي ثانية. لا تؤرجح ظهرك.","انزل ببطء إلى البداية وأنت تشهق."]],"Cocoons":["الشرنقة (كرنش كامل)",["استلقِ على ظهرك والرجلان ممدودتان والذراعان ممدودتان خلف رأسك. هذه وضعية البداية.","قرّب ركبتيك من صدرك وارفع حوضك عن الأرض بلفّه، وفي الوقت نفسه ارفع جذعك وذراعيك للأمام في حركة كرنش.","توقف لحظة، ثم عد إلى البداية."]],"Conans_Wheel":["عجلة كونان",["حمّل الوزن وأمسك طرف الأداة بوضعية زيرشر: البار في ثنية المرفق ويدك تمسك رسغك الآخر، والوزن بعيد عن الساعدين.","ارفع الوزن عن الأرض، وبوضعية مستقيمة ومشدودة امشِ بخطوات قصيرة وسريعة في دائرة، والنظر للأعلى وللأمام. لا تحبس نفسك. تابع حتى تكمل دورة أو أكثر."]],"Concentration_Curls":["باي تركيز",["اجلس على بنش مستوٍ والدمبل أمامك بين رجليك المتباعدتين، والقدمان على الأرض.","أمسك الدمبل بيدك اليمنى واسند خلف العضد على الجزء الداخلي من فخذك الأيمن، والكف للأمام والذراع ممدودة.","ثبّت العضد واثنِ الدمبل للأعلى وأنت تزفر حتى مستوى الكتف. في الأعلى اجعل الإصبع الصغير أعلى من الإبهام لانقباض أفضل، واعصر ثانية.","أنزله ببطء وأنت تشهق، دون أي تأرجح.","أكمل التكرارات ثم بدّل إلى اليد اليسرى."]],"Cross-Body_Crunch":["كرنش متقاطع",["استلقِ على ظهرك واثنِ ركبتيك نحو 60°.","القدمان على الأرض ويداك خلف رأسك برفق. هذه وضعية البداية.","ارفع جذعك وقرّب مرفقك الأيمن وكتفك عبر جسمك، وفي الوقت نفسه قرّب ركبتك اليسرى، محاولًا أن يلمس المرفق الركبة، وأنت تزفر. ارفع الكتف لا المرفق فقط، والمهم عصر البطن.","عد وأنت تشهق، ثم كرّر بالمرفق الأيسر والركبة اليمنى. تابع بالتبادل."]],"Cross_Body_Hammer_Curl":["باي مطرقة عبر الجسم",["قف باستقامة ودمبل في كل يد بجانبك، والكفّان نحو جسمك.","مع إبقاء الكف نحو الداخل ودون لفّ الذراع، ارفع الدمبل الأيمن عبر جسمك نحو كتفك الأيسر وأنت تزفر، واثبت ثانية.","أنزله ببطء في المسار نفسه وأنت تشهق، ثم كرّر باليد اليسرى. تابع بالتبادل."]],"Cross_Over_-_With_Bands":["تقاطع بالمطاط",["ثبّت مطاط التمارين حول عمود.","وظهرك للعمود، أمسك المقبضين وتقدّم حتى يشتد المطاط.","افتح ذراعيك للجانبين موازيتين للأرض على شكل حرف T، والكفّان للأمام مع ثني بسيط في المرفقين. هذه وضعية البداية.","والذراعان مستقيمتان، اجمعهما أمام صدرك في نصف دائرة وأنت تزفر وتعصر الصدر. اثبت ثانية.","عد ببطء وأنت تشهق."]],"Crossover_Reverse_Lunge":["لانج خلفي متقاطع",["قف والقدمان بعرض الكتفين. هذه وضعية البداية.","اخطُ للخلف بقدم واحدة في لانج خلفي بثني الحوض والركبة الأمامية، ولفّ جذعك نحو الرجل الأمامية.","توقف لحظة، ثم عد وكرّر بالجهة الأخرى بالتبادل."]],"Crucifix":["الصليب (رفع جانبي ثابت)",["في هذا التمرين تحمل وزنين ممدودين للجانبين لأطول وقت. يمكن التدريب بالدمبل، لكن الأفضل بالأدوات المستخدمة في المنافسة كالفؤوس والمطارق.","قف وارفع ذراعيك للجانبين موازيتين للأرض. اثبت أطول وقت ممكن، والوزن عادةً يجعلك تفشل خلال 30–60 ثانية."]],"Crunch_-_Hands_Overhead":["كرنش واليدان فوق الرأس",["استلقِ على الأرض وظهرك مستقيم والركبتان مثنيتان نحو 60°.","القدمان على الأرض، ومدّ ذراعيك فوق رأسك متقاطعتين. هذه وضعية البداية.","ارفع جذعك للأمام حتى يرتفع لوحا الكتف عن الأرض، والذراعان على خط الرأس والرقبة دائمًا. ازفر واثبت ثانية.","انزل ببطء وأنت تشهق."]],"Crunch_-_Legs_On_Exercise_Ball":["كرنش والرجلان على كرة التمارين",["استلقِ على ظهرك وقدماك على كرة التمارين والركبتان مثنيتان 90°.","القدمان متباعدتان 8–10 سم وأصابعهما للداخل تتلامس.","ضع يديك برفق بجانب رأسك والمرفقان للداخل، دون تشبيك الأصابع خلف الرأس.","اضغط أسفل ظهرك على الأرض لعزل البطن. هذه وضعية البداية.","ارفع كتفيك عن الأرض نحو 10 سم مع إبقاء أسفل الظهر على الأرض، وأنت تزفر. اعصر البطن بقوة ثانية، ببطء ودون اندفاع.","انزل ببطء وأنت تشهق."]],"Crunches":["كرنش",["استلقِ على ظهرك والقدمان على الأرض، أو على بنش والركبتان مثنيتان 90°.","ضع يديك برفق بجانب رأسك والمرفقان للداخل، دون تشبيك الأصابع خلف الرأس.","اضغط أسفل ظهرك على الأرض، وابدأ برفع كتفيك.","ارفع كتفيك نحو 10 سم مع إبقاء أسفل الظهر على الأرض، وأنت تعصر البطن وتزفر. اثبت ثانية. تحرّك ببطء دون اندفاع.","انزل ببطء وأنت تشهق."]],"Cuban_Press":["الضغط الكوبي",["قف ودمبل في كل يد بقبضة علوية. ارفع العضدين حتى يصبحا موازيين للأرض والساعدان متدليان للأسفل (وضعية الفزّاعة).","دوّر كتفيك للخارج مع ثبات العضدين، حتى يصبح الرسغان فوق المرفقين والساعدان عموديين على الأرض.","اضغط الدمبلين فوق رأسك بفرد المرفقين.","عد إلى البداية بعكس الخطوات وأنت تشهق. استخدم وزنًا خفيفًا."]],"Dancers_Stretch":["إطالة الراقص",["اجلس على الأرض.","ضع رجلك اليمنى فوق اليسرى والركبة مثنية، واليسرى ممدودة على الأرض.","ضع ذراعك اليسرى على رجلك اليمنى ويدك اليمنى على الأرض.","لفّ جذعك نحو اليمين واثبت 10–20 ثانية. بدّل الجهة."]],"Dead_Bug":["الحشرة الميتة (ديد بَغ)",["استلقِ على ظهرك والذراعان ممدودتان نحو السقف.","ارفع قدميك وركبتيك وحوضك بزاوية 90°.","ازفر بقوة لتنزل قفصك الصدري وتلصق ظهرك بالأرض، مع لفّ الحوض للأعلى وعصر الأرداف. حافظ على هذا طوال التمرين. هذه وضعية البداية.","مدّ رجلًا واحدة حتى تصبح فوق الأرض بقليل.","حافظ على أسفل ظهرك ملتصقًا بالأرض، فهو سيحاول التقوّس.","أعد الرجل إلى البداية وكرّر بالرجل الأخرى، وتابع بالتبادل."]],"Deadlift_with_Bands":["ديدلفت بالمطاط",["لفّ المطاط القصير على البار وادخل قدميك فيه، أو ثبّت المطاط الطويل بقاعدة ثابتة كالدمبلات الثقيلة أو القفص.","مع ضبط القدمين والقبضة، خذ نفسًا عميقًا وأنزل حوضك واثنِ ركبتيك حتى تلامس ساقاك البار. انظر للأمام وارفع صدرك وقوّس ظهرك، وادفع بكعبيك لترفع الوزن. بعد تجاوز الركبتين اسحب البار للخلف وادفع حوضك نحو البار واضغط لوحي الكتف معًا.","أنزل البار بثني الحوض وتوجيهه إلى الأرض."]],"Deadlift_with_Chains":["ديدلفت بالسلاسل",["علّق السلاسل على طرفي البار أو ضع منتصفها فوقه.","قف والبار فوق منتصف قدميك، والقدمان بعرض الحوض. انحنِ وأمسك البار بعرض الكتفين بقبضة علوية أو مختلطة. خذ نفسًا عميقًا وأنزل حوضك حتى تلامس ساقاك البار.","انظر للأمام وارفع صدرك وقوّس ظهرك، وادفع بكعبيك لترفع الوزن. بعد تجاوز الركبتين اسحب البار للخلف وادفع حوضك نحوه واضغط لوحي الكتف معًا.","أنزل البار بثني الحوض وتوجيهه إلى الأرض."]],"Decline_Barbell_Bench_Press":["ضغط صدر بالبار على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ ببطء.","أمسك البار بقبضة متوسطة، ارفعه من الحامل وثبّته فوقك والذراعان ممدودتان. يُفضّل أن يساعدك أحد في إخراج البار لحماية الكتف.","اشهق وأنزل البار ببطء حتى يلمس أسفل صدرك.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر، واعصر صدرك. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد البار إلى الحامل."]],"Decline_Close-Grip_Bench_To_Skull_Crusher":["ضغط صدر ضيق على بنش مقلوب ثم تراي جبهة",["ثبّت رجليك في طرف البنش المقلوب واستلقِ ببطء.","أمسك البار بقبضة ضيقة (أقل قليلًا من عرض الكتفين)، ارفعه من الحامل والذراعان ممدودتان والمرفقان للداخل.","أنزل البار إلى أسفل صدرك وأنت تشهق، والمرفقان قريبان من الجسم، ثم ادفعه بالتراي إلى الأعلى وأنت تزفر.","ثبّت العضدين وأنزل البار ببطء بثني المرفقين في نصف دائرة حتى يلامس جبهتك برفق، وأنت تشهق.","ارفعه إلى البداية بعصر التراي وأنت تزفر. هذا تكرار واحد."]],"Decline_Crunch":["كرنش على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ.","ضع يديك برفق بجانب رأسك والمرفقان للداخل، دون تشبيك الأصابع.","اضغط أسفل ظهرك على البنش وابدأ برفع كتفيك.","ارفع كتفيك نحو 10 سم مع إبقاء أسفل الظهر على البنش، وأنت تعصر البطن وتزفر. اثبت ثانية. تحرّك ببطء دون اندفاع.","انزل ببطء وأنت تشهق."]],"Decline_Dumbbell_Bench_Press":["ضغط صدر بالدمبل على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ، والدمبلان على فخذيك والكفّان متقابلتان.","ارفع الدمبلين أمامك بعرض الكتفين، ثم لفّ رسغيك لتصبح الكفّان للأمام. هذه وضعية البداية.","أنزل الدمبلين ببطء إلى جانبي صدرك، والساعدان عموديان على الأرض دائمًا.","ادفعهما للأعلى بعضلات الصدر وأنت تزفر، واعصر صدرك ثانية. النزول يأخذ ضعف وقت الصعود."]],"Decline_Dumbbell_Flyes":["تفتيح دمبل على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ، والدمبلان على فخذيك والكفّان متقابلتان.","ارفع الدمبلين أمامك بعرض الكتفين، الكفّان متقابلتان والذراعان ممدودتان. هذه وضعية البداية.","مع ثني بسيط في المرفقين، أنزل ذراعيك للجانبين في قوس واسع حتى تشعر بإطالة في الصدر، وأنت تشهق. الحركة من الكتف فقط.","أعد ذراعيك في القوس نفسه وأنت تعصر صدرك وتزفر، واثبت ثانية."]],"Decline_Dumbbell_Triceps_Extension":["تراي بالدمبل على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ، والدمبلان على فخذيك والكفّان متقابلتان.","ارفع الدمبلين فوقك بعرض الكتفين، والذراعان ممدودتان عموديتان على الأرض. هذه وضعية البداية.","ثبّت العضدين والمرفقين للداخل، وأنزل الدمبلين ببطء بثني المرفقين حتى يصبح الإبهامان بجانب أذنيك، وأنت تشهق.","ارفعهما إلى البداية بعصر التراي وأنت تزفر."]],"Decline_EZ_Bar_Triceps_Extension":["تراي بار EZ على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ ببطء.","أمسك بار EZ بقبضة ضيقة، ارفعه من الحامل والذراعان ممدودتان والمرفقان للداخل.","ثبّت العضدين وأنزل البار ببطء بثني المرفقين حتى يلامس جبهتك برفق، وأنت تشهق.","ارفعه إلى البداية بعصر التراي وأنت تزفر."]],"Decline_Oblique_Crunch":["كرنش الخواصر على بنش مقلوب",["ثبّت رجليك في طرف البنش المقلوب واستلقِ ببطء.","ارفع جذعك حتى يصبح بزاوية 35–45° عن الأرض.","ضع يدًا بجانب رأسك والأخرى على فخذك. هذه وضعية البداية.","ارفع جذعك ببطء مع لفّه نحو اليسار حتى يلمس مرفقك الأيمن ركبتك اليسرى، وأنت تزفر. اثبت ثانية والبطن مشدود.","انزل ببطء وأنت تشهق.","أكمل التكرارات ثم بدّل الجهة."]],"Decline_Push-Up":["ضغط والرجلان مرفوعتان (بوش أب مقلوب)",["انبطح على الأرض واليدان أعرض قليلًا من الكتفين، وارفع جسمك والذراعان ممدودتان. ضع قدميك على صندوق أو بنش. هذه وضعية البداية.","اشهق وانزل حتى يكاد صدرك يلمس الأرض.","ازفر وادفع للأعلى مع عصر الصدر.","توقف لحظة، ثم كرّر."]],"Decline_Reverse_Crunch":["كرنش عكسي على بنش مقلوب",["استلقِ على ظهرك على بنش مقلوب وأمسك أعلى البنش بيديك حتى لا تنزلق.","ارفع رجليك موازيتين للأرض بالبطن، والركبتان والقدمان معًا مع ثني بسيط في الركبتين. هذه وضعية البداية.","ازفر وحرّك رجليك نحو جذعك مع لفّ الحوض للخلف ورفعه عن البنش، حتى تلمس ركبتاك صدرك.","اثبت ثانية، ثم أعد رجليك إلى البداية وأنت تشهق."]],"Decline_Smith_Press":["ضغط صدر على السميث على بنش مقلوب",["ضع بنشًا مقلوبًا تحت جهاز السميث، واضبط البار على ارتفاع تصله وذراعاك شبه ممدودتين. أمسكه بقبضة علوية أعرض من الكتفين وحرّره من الحامل.","اشهق وأنزل البار بتحكّم حتى يلامس صدرك برفق.","توقف لحظة، ثم ادفعه إلى البداية بفرد المرفقين وأنت تزفر.","عند انتهاء المجموعة، أعد قفل البار في الحامل."]],"Deficit_Deadlift":["ديدلفت من منصة مرتفعة (ديفيسيت)",["قف على منصة أو أقراص بارتفاع 3–8 سم، والبار فوق منتصف قدميك والقدمان بعرض الحوض. انحنِ وأمسك البار بعرض الكتفين بقبضة علوية أو مختلطة.","خذ نفسًا عميقًا، أنزل حوضك واثنِ ركبتيك حتى تلامس ساقاك البار. انظر للأمام، ارفع صدرك وقوّس ظهرك، ثم ادفع بكعبيك لترفع البار. بعد تجاوز الركبتين، اسحب البار للخلف واضغط لوحي الكتف معًا وادفع حوضك للأمام.","أنزل البار بثني الحوض وتوجيهه إلى الأرض."]],"Depth_Jump_Leap":["قفز عميق ثم وثب",["تحتاج صندوقين: واحد بارتفاع 30–40 سم والآخر 55–65 سم.","قف على الصندوق الأول والذراعان بجانبك والقدمان معًا عند الحافة، والصندوق الآخر أمامك على بعد 60–90 سم.","انزل عن الصندوق الأول، واهبط وانطلق فورًا بالقدمين معًا.","ارتد للأعلى وللأمام بأقصى قوة مستعينًا بذراعيك وفرد جسمك لتقفز على الصندوق الأعلى، وامتص الصدمة برجليك."]],"Dip_Machine":["جهاز المتوازي",["اجلس جيدًا على جهاز المتوازي، اختر الوزن وأمسك المقابض بقوة.","أبقِ مرفقيك قريبين من جانبيك للتركيز على التراي، مثنيين بزاوية 90°.","مدّ ذراعيك للأسفل بعصر التراي وأنت تزفر. أبقِ ثنيًا بسيطًا في الأسفل للحفاظ على الشد.","عد ببطء إلى البداية وأنت تشهق."]],"Dips_-_Chest_Version":["متوازي (للصدر)",["ارفع جسمك على بارات المتوازي والذراعان مقفلتان.","اشهق وانزل ببطء مع ميلان الجذع للأمام نحو 30° والمرفقان للخارج قليلًا، حتى تشعر بإطالة خفيفة في الصدر.","اصعد بعضلات الصدر وأنت تزفر، واعصر الصدر ثانية في الأعلى."]],"Dips_-_Triceps_Version":["متوازي (للتراي)",["ارفع جسمك على بارات المتوازي والذراعان شبه ممدودتين.","اشهق وانزل ببطء، والجذع مستقيم والمرفقان قريبان من الجسم للتركيز على التراي، حتى تصبح الزاوية بين العضد والساعد 90°.","ازفر واصعد بالتراي إلى البداية."]],"Donkey_Calf_Raises":["سمانة الحمار",["تحتاج جهاز سمانة الحمار. ضع أسفل ظهرك وحوضك تحت المسند، بحيث يلمس المسند منطقة العصعص.","أمسك المقابض الجانبية وضع مقدمة قدميك على المكعب والكعبان خارجه، وافرد ركبتيك دون قفلهما. هذه وضعية البداية.","ارفع كعبيك لأعلى ما يمكن وأنت تزفر وتعصر السمانة، والركبتان ثابتتان. اثبت ثانية.","انزل ببطء حتى تتمدد السمانة وأنت تشهق."]],"Double_Kettlebell_Alternating_Hang_Clean":["كلين بكيتلبلين من التعليق بالتبادل",["ضع كيتلبلين بين قدميك. ادفع مؤخرتك للخلف وانظر للأمام.","ارفع كيتلبلًا إلى كتفك (كلين) وأمسك الآخر متدليًا.","بحركة انسيابية، أنزل العلوي وارفع السفلي في الوقت نفسه."]],"Double_Kettlebell_Jerk":["جيرك بكيتلبلين",["أمسك كيتلبلًا في كل يد من المقبض.","ارفعهما إلى كتفيك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغين لتصبح الكفّان للأمام. هذه وضعية البداية.","انزل قليلًا بثني الركبتين والجذع مستقيم.","اعكس الاتجاه فورًا بالدفع بالكعبين كأنك تقفز.","في الوقت نفسه اضغط الكيتلبلين فوق رأسك مستفيدًا من اندفاع الجسم.","اهبط بقدمين مفتوحتين (واحدة للأمام وأخرى للخلف)، ثم اجمعهما وقف والوزن فوق رأسك. أنزل الكيتلبلين للتكرار التالي."]],"Double_Kettlebell_Push_Press":["ضغط دفعي بكيتلبلين",["ارفع كيتلبلين إلى كتفيك (كلين).","انزل بضعة سنتيمترات في سكوات ثم اعكس الحركة بسرعة، واستخدم اندفاع الرجلين لدفع الكيتلبلين فوق رأسك.","بعد قفل الذراعين، أنزلهما إلى كتفيك وكرّر."]],"Double_Kettlebell_Snatch":["خطف بكيتلبلين (سناتش)",["ضع كيتلبلين خلف قدميك. اثنِ ركبتيك واجلس للخلف لتلتقطهما.","أرجح الكيتلبلين بين رجليك بقوة ثم اعكس الاتجاه.","ادفع بحوضك واقفل الكيتلبلين فوق رأسك بحركة واحدة متصلة."]],"Double_Kettlebell_Windmill":["طاحونة الهواء بكيتلبلين",["ضع كيتلبلًا أمام قدمك الأمامية، وارفع كيتلبلًا آخر فوق رأسك باليد المعاكسة (كلين ثم ضغط).","والكيتلبل العلوي مقفل دائمًا، ادفع مؤخرتك باتجاهه، والقدمان بزاوية 45° بعيدًا عن جهته.","انحنِ من الحوض إلى الجانب ببطء حتى تلتقط الكيتلبل من الأرض، وعيناك على الكيتلبل العلوي دائمًا.","توقف ثانية بعد التقاطه، ثم عد إلى البداية."]],"Double_Leg_Butt_Kick":["ركل المؤخرة بالرجلين معًا",["قف والركبتان مثنيتان قليلًا.","انزل بسرعة قليلًا بثني الحوض والركبتين، ثم اقفز فورًا لأعلى ارتفاع.","أثناء الصعود اثنِ ركبتيك محاولًا لمس مؤخرتك بكعبيك.","اهبط والركبتان مثنيتان جزئيًا لامتصاص الصدمة."]],"Downward_Facing_Balance":["التوازن ووجهك للأسفل",["انبطح على كرة التمارين.","وبطنك على الكرة، امشِ بيديك للأمام على الأرض وارفع رجليك، مع فرد المرفقين والركبتين، وحافظ على التوازن."]],"Drag_Curl":["باي سحب (دراغ كيرل)",["أمسك البار بقبضة سفلية (الكفّان للأمام)، والمرفقان قريبان من الجسم وللخلف قليلًا.","ازفر واسحب البار للأعلى ملاصقًا لجسمك، مع إرجاع المرفقين للخلف بدل تثبيتهما بجانبك. لا ترفع كتفيك.","انزل ببطء إلى البداية والبار ملاصق لجسمك دائمًا."]],"Drop_Push":["ضغط بالإسقاط (دروب بوش)",["ضع منصتين منخفضتين على بعد 60–90 سم.","اتخذ وضعية الضغط بينهما ويداك على المنصتين.","بوضعية جيدة، ادفع لترتفع ثم انزل بيديك إلى الأرض بعرض الكتفين، وامتص الصدمة بذراعيك."]],"Dumbbell_Alternate_Bicep_Curl":["باي دمبل بالتبادل",["قف باستقامة ودمبل في كل يد والذراعان ممدودتان، المرفقان قريبان من الجسم والكفّان نحو فخذيك.","ثبّت العضد واثنِ الدمبل الأيمن مع لفّ الكف للأمام، وتابع حتى مستوى الكتف وأنت تزفر. اعصر الباي ثانية. الساعد فقط يتحرك.","أنزله ببطء مع إعادة الكف نحو الفخذ، وأنت تشهق.","كرّر باليد اليسرى، وهكذا بالتبادل."]],"Dumbbell_Bench_Press":["ضغط صدر بالدمبل",["استلقِ على بنش مستوٍ ودمبل في كل يد مسنود على فخذيك، والكفّان متقابلتان.","بمساعدة فخذيك، ارفع الدمبلين واحدًا تلو الآخر وأمسكهما أمامك بعرض الكتفين.","لفّ رسغيك لتصبح الكفّان للأمام، والدمبلان بجانب صدرك والزاوية بين العضد والساعد 90°. هذه وضعية البداية.","ازفر وادفع الدمبلين للأعلى بعضلات الصدر، واعصر صدرك ثانية في الأعلى، ثم انزل ببطء. الأفضل أن يأخذ النزول ضعف وقت الصعود."]],"Dumbbell_Bench_Press_with_Neutral_Grip":["ضغط صدر بالدمبل بقبضة محايدة",["خذ دمبلًا في كل يد واستلقِ على بنش مستوٍ، القدمان على الأرض ولوحا الكتف مسحوبان للخلف.","بقبضة محايدة (الكفّان متقابلتان)، ابدأ والذراعان ممدودتان فوقك.","اثنِ المرفقين وأنزل الدمبلين حتى يصلا إلى جانبي جذعك.","توقف لحظة، ثم افرد مرفقيك لتعود إلى البداية."]],"Dumbbell_Bicep_Curl":["باي دمبل",["قف باستقامة ودمبل في كل يد والذراعان ممدودتان، المرفقان قريبان من الجسم والكفّان للأمام.","ثبّت العضدين، ازفر واثنِ الدمبلين بعصر الباي حتى مستوى الكتفين، واعصر لحظة في الأعلى.","اشهق وأنزلهما ببطء إلى البداية."]],"Dumbbell_Clean":["كلين بالدمبل",["قف ودمبل في كل يد والقدمان بعرض الكتفين.","أنزل الدمبلين إلى الأرض بثني الحوض والركبتين ودفع الحوض للخلف. هذه وضعية البداية.","اقفز للأعلى بقوة بفرد الحوض والركبتين والكاحلين لتسريع الدمبلين، والذراعان مستقيمتان بقبضة محايدة.","بعد الامتداد الكامل، اثنِ الحوض والركبتين لتستقبل الوزن في وضعية سكوات، ودع ذراعيك تنثنيان لتوجيه الدمبلين إلى كتفيك.","افرد حوضك وركبتيك لتقف والدمبلان على كتفيك."]],"Dumbbell_Floor_Press":["ضغط دمبل على الأرض",["استلقِ على الأرض ودمبل في كل يد، ويمكنك ثني ركبتيك. ابدأ والذراعان ممدودتان فوقك.","أنزل الدمبلين حتى يلمس العضدان الأرض. قرّب المرفقين من جسمك للتركيز على التراي، أو باعدهما للتركيز على الصدر.","توقف في الأسفل، ثم افرد المرفقين واجمع الدمبلين في الأعلى."]],"Dumbbell_Flyes":["تفتيح دمبل",["استلقِ على بنش مستوٍ ودمبل في كل يد مسنود على فخذيك، والكفّان متقابلتان.","بمساعدة فخذيك، ارفع الدمبلين أمامك بعرض الكتفين والكفّان متقابلتان، وتوقف قبل قفل المرفقين. هذه وضعية البداية.","مع ثني بسيط في المرفقين، أنزل ذراعيك للجانبين في قوس واسع حتى تشعر بإطالة في الصدر، وأنت تشهق. الحركة من الكتف فقط.","أعد ذراعيك في القوس نفسه وأنت تعصر صدرك وتزفر، واثبت ثانية."]],"Dumbbell_Incline_Row":["تجديف دمبل على بنش مائل",["انبطح بصدرك على بنش مائل.","أمسك دمبلًا في كل يد بقبضة محايدة، والذراعان ممدودتان للأسفل. هذه وضعية البداية.","اسحب لوحي الكتف للخلف واثنِ المرفقين لتسحب الدمبلين إلى جانبيك.","توقف في الأعلى، ثم عد إلى البداية."]],"Dumbbell_Incline_Shoulder_Raise":["رفع الكتفين بالدمبل على بنش مائل",["اجلس على بنش مائل والدمبلان على فخذيك.","ارفع رجليك قليلًا لتدفع الدمبلين إلى كتفيك واستلقِ. ارفع الدمبلين فوق كتفيك والذراعان ممدودتان عموديتان على الأرض.","مع إبقاء الذراعين مستقيمتين، ارفع الدمبلين برفع كتفيك عن البنش وأنت تزفر.","عد إلى البداية وأنت تشهق."]],"Dumbbell_Lunges":["لانج بالدمبل",["قف باستقامة ودمبل في كل يد بجانبك.","اخطُ برجلك اليمنى للأمام نحو 60 سم وانزل بجسمك مع إبقاء الجذع مستقيمًا والتوازن ثابتًا، وأنت تشهق. الساق الأمامية عمودية على الأرض، ولا تدع الركبة تتجاوز أصابع القدم كثيرًا.","ادفع بكعب القدم الأمامية لتعود إلى البداية وأنت تزفر.","أكمل التكرارات ثم بدّل إلى الرجل اليسرى."]],"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise":["كتف خلفي بالدمبل مستلقيًا بيد واحدة",["أمسك دمبلًا بيد واحدة وانبطح بصدرك على بنش بميل خفيف (نحو 15°). يمكنك الإمساك بالبنش باليد الأخرى للثبات.","الكف نحو جسمك والذراع ممدودة مع ثني بسيط في المرفق. هذه وضعية البداية.","ارفع الذراع جانبيًا حتى يصبح المرفق على مستوى الكتف والذراع موازية للأرض، وأنت تزفر. اثبت ثانية.","أنزل الدمبل ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الذراع."]],"Dumbbell_Lying_Pronation":["كبّ الساعد بالدمبل مستلقيًا",["انبطح على بنش مستوٍ، دمبل في يد واليد الأخرى مطوية تحت رأسك.","اثنِ مرفق الذراع الممسكة بالدمبل 90°، وارفع العضد ليصبح موازيًا للأرض وعموديًا على جذعك، والساعد متدلٍّ للأسفل. هذه وضعية البداية.","ازفر ودوّر ساعدك للأمام حتى يصبح موازيًا للأرض، مع ثبات زاوية 90°. اثبت ثانية.","اشهق وعد ببطء إلى البداية."]],"Dumbbell_Lying_Rear_Lateral_Raise":["كتف خلفي بالدمبل مستلقيًا",["أمسك دمبلًا في كل يد وانبطح بصدرك على بنش بميل خفيف (نحو 15°).","الكفّان نحو جسمك والذراعان ممدودتان مع ثني بسيط في المرفقين. هذه وضعية البداية.","ارفع ذراعيك جانبيًا حتى يصبح المرفقان على مستوى الكتفين والذراعان موازيتان للأرض، وأنت تزفر. اثبت ثانية.","أنزل الدمبلين ببطء وأنت تشهق."]],"Dumbbell_Lying_Supination":["بسط الساعد بالدمبل مستلقيًا",["استلقِ على جنبك على بنش مستوٍ، دمبل في اليد العليا واليد الأخرى تحت رأسك.","اثنِ مرفق الذراع الممسكة بالدمبل 90°، والعضد ملتصق بجانبك والساعد أمامك موازٍ للأرض. هذه وضعية البداية.","ازفر ودوّر ساعدك للخارج في نصف دائرة حتى يصبح عموديًا على الأرض ويشير نحو السقف، مع ثبات زاوية 90°. اثبت ثانية.","اشهق وعد ببطء. أكمل التكرارات ثم بدّل الذراع."]],"Dumbbell_One-Arm_Shoulder_Press":["ضغط أكتاف بالدمبل بيد واحدة",["خذ دمبلًا واجلس على بنش بمسند للظهر، أو قف باستقامة.","ارفع الدمبل إلى مستوى الكتف. يمكن أن تبقى اليد الأخرى على خصرك أو ممسكة بشيء ثابت.","لفّ رسغك لتصبح الكف للأمام. هذه وضعية البداية.","ازفر وادفع الدمبل للأعلى حتى تمتد ذراعك.","توقف ثانية، ثم انزل ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الذراع."]],"Dumbbell_One-Arm_Triceps_Extension":["تراي بالدمبل بيد واحدة",["خذ دمبلًا واجلس على بنش بمسند للظهر، أو قف باستقامة.","ارفع الدمبل إلى الكتف ثم مدّ ذراعك فوق رأسك بحيث تكون الذراع كلها عمودية بجانب رأسك. يمكنك سند العضد باليد الأخرى.","لفّ رسغك بحيث تكون الكف للأمام والإصبع الصغير نحو السقف. هذه وضعية البداية.","ثبّت العضد وأنزل الدمبل ببطء خلف رأسك وأنت تشهق، حتى تشعر بإطالة كاملة في التراي.","عد إلى البداية بعصر التراي وأنت تزفر. الساعد فقط يتحرك. أكمل التكرارات ثم بدّل الذراع."]],"Dumbbell_One-Arm_Upright_Row":["سحب عمودي بالدمبل بيد واحدة (أبرايت رو)",["أمسك دمبلًا وقف باستقامة والذراع ممدودة أمامك مع ثني بسيط، والدمبل على فخذك والكف نحوه.","اليد الأخرى على خصرك أو ممسكة بشيء ثابت.","ارفع الدمبل بالكتف الجانبي وأنت تزفر، قريبًا من جسمك، حتى يقارب مستوى ذقنك. المرفق يقود الحركة ويبقى أعلى من الساعد. الجذع ثابت، واثبت ثانية في الأعلى.","أنزله ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الذراع."]],"Dumbbell_Prone_Incline_Curl":["باي دمبل منبطحًا على بنش مائل",["أمسك دمبلًا في كل يد وانبطح على بنش مائل، والكتفان قرب أعلى البنش. يمكنك إسناد ركبتيك على المقعد أو فتح رجليك للجانبين.","دع ذراعيك تتدليان أمامك عموديتين على الأرض.","ثبّت المرفقين بجانبك والكفّان للأمام. هذه وضعية البداية.","ارفع الدمبلين بعصر الباي حتى ينثني الذراعان بالكامل، وأنت تزفر. العضدان ثابتان والساعدان فقط يتحركان.","أنزل الدمبلين حتى تمتد ذراعاك بالكامل."]],"Dumbbell_Raise":["رفع الدمبل",["أمسك دمبلًا في كل يد وقف باستقامة والذراعان بجانبك مع ثني بسيط، والكفّان للخلف.","ارفع الدمبلين بالكتف الجانبي وأنت تزفر، بجانب جسمك، حتى يقاربا مستوى الذقن. المرفقان يقودان الحركة ويبقيان أعلى من الساعدين. الجذع ثابت، واثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Dumbbell_Rear_Lunge":["لانج خلفي بالدمبل",["قف باستقامة ودمبل في كل يد بجانبك.","اخطُ برجلك اليمنى للخلف نحو 60 سم وانزل بجسمك مع إبقاء الجذع مستقيمًا، وأنت تشهق. الساق الأمامية عمودية على الأرض. الخطوة الطويلة تركّز على الأرداف، والقصيرة على أمامي الفخذ.","ادفع للأعلى لتعود إلى البداية وأنت تزفر. الدفع بمقدمة القدم يركّز على أمامي الفخذ، وبالكعب على الأرداف.","كرّر بالرجل الأخرى."]],"Dumbbell_Scaption":["رفع الدمبل بزاوية (سكابشن)",["تمرين تصحيحي يقوّي عضلات تثبيت لوح الكتف. أمسك وزنًا خفيفًا في كل يد بجانبك، والإبهامان للأعلى.","ارفع ذراعيك أمامك بزاوية نحو 30° عن الخط الأمامي، والذراعان ممدودتان بالكامل.","تابع حتى تصبح ذراعاك موازيتين للأرض، ثم عد إلى البداية."]],"Dumbbell_Seated_Box_Jump":["قفز على الصندوق من الجلوس بالدمبل",["ضع صندوقًا على بعد خطوة بجانب بنش. أمسك دمبلًا بيديك على صدرك واجلس على البنش مقابل الصندوق. هذه وضعية البداية.","ثبّت قدميك على الأرض ومِل للأمام، ثم افرد الحوض والركبتين لتقفز للأعلى وللأمام.","اهبط على الصندوق بالقدمين معًا، وامتص الصدمة بثني الحوض والركبتين.","انزل عن الصندوق وعد إلى البداية."]],"Dumbbell_Seated_One-Leg_Calf_Raise":["سمانة جلوس برجل واحدة بالدمبل",["ضع مكعبًا على الأرض على بعد 30 سم تقريبًا من بنش مستوٍ.","اجلس على البنش وضع دمبلًا على فخذك الأيسر فوق الركبة بنحو 8 سم.","ضع مقدمة قدمك اليسرى على المكعب. هذه وضعية البداية.","ارتفع على أصابعك لأعلى ما يمكن وأنت تزفر وتعصر السمانة، واثبت ثانية.","انزل ببطء لأقصى إطالة. أكمل التكرارات ثم بدّل الرجل."]],"Dumbbell_Shoulder_Press":["ضغط أكتاف بالدمبل",["أمسك دمبلًا في كل يد واجلس على بنش بمسند للظهر، والدمبلان واقفان على فخذيك.","ارفع الدمبلين إلى مستوى الكتفين واحدًا تلو الآخر بمساعدة فخذيك.","لفّ رسغيك لتصبح الكفّان للأمام. هذه وضعية البداية.","ازفر وادفع الدمبلين للأعلى حتى يتلامسا فوق رأسك.","توقف لحظة، ثم أنزلهما ببطء إلى البداية وأنت تشهق."]],"Dumbbell_Shrug":["ترابيس بالدمبل (شراغ)",["قف باستقامة ودمبل في كل يد بجانبك، والكفّان نحو جسمك.","ارفع كتفيك لأعلى ما يمكن وأنت تزفر، واثبت ثانية. الذراعان ممدودتان دائمًا، ولا تسحب بالباي. الكتفان فقط يتحركان.","أنزل الدمبلين إلى البداية."]],"Dumbbell_Side_Bend":["ميلان جانبي بالدمبل",["قف باستقامة ودمبل في يدك اليسرى (الكف نحو الجسم) واليد اليمنى على خصرك، والقدمان بعرض الكتفين.","بظهر مستقيم ورأس مرفوع، مِل من الخصر إلى اليمين لأقصى حد وأنت تشهق، ثم اثبت ثانية وعد وأنت تزفر. باقي الجسم ثابت.","كرّر الميلان إلى اليسار.","أكمل التكرارات ثم بدّل اليد."]],"Dumbbell_Squat":["سكوات بالدمبل",["قف باستقامة ودمبل في كل يد بجانب فخذيك.","القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع (النظر للأسفل يفقدك التوازن) والظهر مستقيم.","انزل ببطء بثني الركبتين مع ظهر مستقيم حتى يصبح الفخذان موازيين للأرض، وأنت تشهق.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Dumbbell_Squat_To_A_Bench":["سكوات بالدمبل حتى البنش",["قف باستقامة وخلفك بنش مستوٍ، ودمبل في كل يد بجانب فخذيك.","القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم.","انزل ببطء بثني الركبتين مع ظهر مستقيم حتى تلامس البنش برفق، وأنت تشهق.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Dumbbell_Step_Ups":["صعود على الصندوق بالدمبل",["قف باستقامة ودمبل في كل يد بجانب فخذيك، وأمامك منصة مرتفعة.","ضع قدمك اليمنى على المنصة واصعد بفرد الورك والركبة، معتمدًا على الكعب، ثم ضع القدم اليسرى بجانبها. ازفر أثناء الصعود.","انزل بالرجل اليسرى أولًا وأنت تشهق، ثم أعد القدم اليمنى بجانبها.","أكمل التكرارات بالرجل اليمنى ثم بدّل إلى اليسرى."]],"Dumbbell_Tricep_Extension_-Pronated_Grip":["تراي بالدمبل بقبضة علوية",["استلقِ على بنش مستوٍ ودمبلان فوق كتفيك، والذراعان ممدودتان عموديتان على الأرض.","الكفّان للأمام (نحو قدميك) والمرفقان للداخل. هذه وضعية البداية.","اشهق وأنزل الدمبلين ببطء حتى يقتربا من أذنيك، مع ثبات العضدين.","ازفر وأعدهما إلى البداية بالتراي."]],"Dynamic_Back_Stretch":["إطالة الظهر الحركية",["قف والقدمان بعرض الكتفين. هذه وضعية البداية.","والذراعان مستقيمتان، أرجحهما للأعلى أمامك 5–10 مرات مع زيادة المدى كل مرة حتى تصبحا فوق رأسك."]],"Dynamic_Chest_Stretch":["إطالة الصدر الحركية",["قف والذراعان ممدودتان أمامك واليدان معًا. هذه وضعية البداية.","والذراعان مستقيمتان، حرّكهما بسرعة للخلف لأبعد حد ثم للأمام، كحركة تصفيق مبالغ فيها. كرّر 5–10 مرات مع زيادة السرعة."]],"EZ-Bar_Curl":["باي بار EZ",["قف باستقامة وأمسك بار EZ من المقبض الخارجي الواسع، الكفّان للأمام ومائلتان للداخل قليلًا، والمرفقان قريبان من الجسم.","ثبّت العضدين، ازفر واثنِ البار للأعلى بعصر الباي. الساعدان فقط يتحركان.","تابع حتى مستوى الكتفين واعصر الباي لحظة.","اشهق وأنزل البار ببطء إلى البداية."]],"EZ-Bar_Skullcrusher":["تراي جبهة بار EZ (سكل كراشر)",["أمسك بار EZ بقبضة ضيقة واستلقِ على البنش، والذراعان ممدودتان عموديتان على الأرض والمرفقان للداخل.","ثبّت العضدين وأنزل البار بثني المرفقين وأنت تشهق، وتوقف عندما يصبح البار فوق جبهتك.","ارفعه إلى البداية بفرد المرفقين وأنت تزفر."]],"Elbow_Circles":["دوائر المرفقين",["اجلس أو قف والقدمان متباعدتان قليلًا.","ضع يديك على كتفيك والمرفقان بمستوى الكتفين للخارج.","ارسم دائرة بمرفقيك ببطء. ازفر في بداية الدائرة واشهق في نهايتها."]],"Elbow_to_Knee":["المرفق إلى الركبة",["استلقِ على الأرض وضع رجلك اليمنى فوق ركبتك اليسرى المثنية، وشبّك يديك خلف رأسك ولوحا الكتف على الأرض. هذه وضعية البداية.","اثنِ جذعك ولفّه لتقرّب مرفقك الأيسر من ركبتك اليمنى.","عد إلى البداية. أكمل التكرارات ثم بدّل الجهة."]],"Elbows_Back":["المرفقان للخلف",["قف باستقامة.","ضع يديك على أسفل ظهرك والأصابع للأسفل والمرفقان للخارج.","اسحب مرفقيك للخلف برفق محاولًا تقريبهما من بعض."]],"Elevated_Back_Lunge":["لانج خلفي من منصة مرتفعة",["ضع البار على الحامل بمستوى الكتفين بالوزن المناسب، وضع منصة منخفضة خلفك.","ضع البار على أعلى ظهرك مع ظهر مقوّس ومشدود، واصعد على المنصة بقدميك. هذه وضعية البداية.","اخطُ برجل للخلف وانزل بثني الحوض والركبتين حتى تلمس ركبتك الخلفية الأرض.","توقف لحظة، ثم افرد الحوض والركبتين لتصعد إلى البداية، وبدّل الرجل."]],"Elevated_Cable_Rows":["تجديف بالكيبل من مقعد مرتفع",["ضع منصة بارتفاع 10–15 سم على مقعد جهاز التجديف بالكيبل، واجلس عليها.","ضع قدميك على المسند الأمامي مع ثني بسيط في الركبتين.","مِل للأمام مع ظهر مستقيم وأمسك مقبض V.","اسحب للخلف والذراعان ممدودتان حتى يصبح جذعك عموديًا على رجليك، الظهر مقوّس قليلًا والصدر للأمام. هذه وضعية البداية.","ثبّت جذعك واسحب المقبض نحو بطنك والذراعان قريبتان من الجسم، وأنت تزفر. اعصر الظهر بقوة ثانية، ثم عد ببطء وأنت تشهق."]],"Elliptical_Trainer":["جهاز الإليبتكال",["اصعد على جهاز الإليبتكال واختر البرنامج من القائمة، يدويًا أو برنامجًا جاهزًا. يمكنك إدخال عمرك ووزنك لتقدير السعرات، وتغيير الميل لتغيير الشدة.","يمكنك استخدام المقابض لقياس النبض والحفاظ على شدة مناسبة."]],"Exercise_Ball_Crunch":["كرنش على كرة التمارين",["استلقِ على كرة التمارين وتقوّس أسفل ظهرك ملاصق للكرة، والركبتان مثنيتان والقدمان ثابتتان على الأرض. الجزء العلوي متدلٍّ خلف الكرة، والذراعان بجانبك أو متقاطعتان على صدرك لتجنّب شد الرقبة.","أنزل جذعك للخلف في إطالة مع ثبات الرقبة. هذه وضعية البداية.","ثبّت الحوض واعصر البطن لترفع كتفيك وجذعك حتى تشعر بانقباض جيد، وأسفل الظهر ملاصق للكرة دائمًا. ازفر واثبت ثانية.","عد إلى البداية وأنت تشهق."]],"Exercise_Ball_Pull-In":["سحب الركبتين على كرة التمارين",["ضع كرة تمارين قريبة واتخذ وضعية الضغط أمامها، واليدان على الأرض بعرض الكتفين.","ضع أسفل ساقيك على الكرة والرجلان ممدودتان. هذه وضعية البداية.","والظهر مستقيم والجزء العلوي ثابت، اسحب ركبتيك نحو صدرك وأنت تزفر، فتتدحرج الكرة تحت كاحليك. اعصر البطن ثانية.","افرد رجليك ببطء لتعيد الكرة إلى البداية، وأنت تشهق."]],"Extended_Range_One-Arm_Kettlebell_Floor_Press":["ضغط بالكيتلبل على الأرض بيد واحدة (مدى أوسع)",["استلقِ على الأرض وأمسك كيتلبلًا من مقبضه بيد واحدة. الرجل في جهة الضغط مثنية والركبة تعبر خط منتصف الجسم.","اضغط الكيتلبل للأعلى بفرد المرفق وتقريب الذراع نحو منتصف الجسم، ثم عد إلى البداية. أكمل التكرارات ثم بدّل الجهة."]],"External_Rotation":["تدوير الكتف للخارج",["استلقِ على جنبك على بنش مستوٍ، دمبل في اليد العليا واليد الأخرى تحت رأسك.","اثنِ المرفق 90° والعضد ملتصق بجانبك، والساعد أمامك موازٍ للأرض. هذه وضعية البداية.","ازفر ودوّر ساعدك للخارج في نصف دائرة حتى يصبح عموديًا على الأرض ويشير نحو السقف، مع ثبات زاوية 90°. اثبت ثانية.","اشهق وعد ببطء. أكمل التكرارات ثم بدّل الذراع."]],"External_Rotation_with_Band":["تدوير الكتف للخارج بالمطاط",["اربط المطاط حول عمود بمستوى مرفقك، وقف وجانبك الأيسر له على بعد خطوة.","أمسك طرف المطاط بيدك اليمنى وألصق مرفقك بجانبك (يمكنك وضع منشفة ملفوفة تحته).","المرفق مثني 90° واليد أمام بطنك. هذه وضعية البداية.","دوّر ذراعك للخارج مع ثبات المرفق.","تابع لأبعد ما تستطيع، توقف، ثم عد. أكمل التكرارات ثم بدّل الجهة."]],"External_Rotation_with_Cable":["تدوير الكتف للخارج بالكيبل",["اضبط الكيبل بمستوى مرفقك، وقف وجانبك الأيسر للجهاز على بعد خطوة تقريبًا.","أمسك المقبض بيدك اليمنى وألصق مرفقك بجانبك (يمكنك وضع منشفة ملفوفة تحت المرفق).","المرفق مثني 90° واليد أمام بطنك. هذه وضعية البداية.","دوّر ذراعك للخارج مع ثبات المرفق في مكانه، ثم عد ببطء. أكمل التكرارات ثم بدّل الجهة."]],"Face_Pull":["سحب للوجه (فيس بول)",["قف مقابل الكيبل العلوي المركّب عليه حبل أو مقبضان، واسحب الوزن نحو وجهك مباشرة مع مباعدة يديك. أبقِ العضدين موازيين للأرض، واعصر الكتف الخلفي ولوحي الكتف في نهاية الحركة، ثم عد ببطء."]],"Farmers_Walk":["مشي المزارع",["يمكن استخدام أدوات مخصصة أو دمبلات ثقيلة أو بارات قصيرة. قف بين الأداتين.","أمسك المقابض وارفعهما بالدفع بكعبيك، والظهر مستقيم والرأس مرفوع.","امشِ بخطوات قصيرة وسريعة ولا تحبس نفسك، لمسافة محددة (عادة 15–30 مترًا) بأسرع ما يمكن."]],"Fast_Skipping":["نطّ سريع",["قف بوضعية مرتاحة ورجل للأمام قليلًا. هذه وضعية البداية.","نطّ بنمط خطوة ثم قفزة: يمين-يمين، ثم يسار-يسار، وهكذا بالتبادل.","نطّ بسرعة مع البقاء قريبًا من الأرض وتقليل وقت الطيران."]],"Finger_Curls":["ثني الأصابع",["أمسك البار بيديك والكفّان للأعلى بعرض الكتفين.","ضع قدميك على الأرض بعرض أوسع قليلًا من الكتفين. هذه وضعية البداية.","أنزل البار لأقصى حد بفتح أصابعك، ودعه يتدحرج حتى تمسكه بأطراف الأصابع.","أغلق يديك لترفع البار لأعلى ما يمكن وأنت تزفر، واثبت في الأعلى."]],"Flat_Bench_Cable_Flyes":["تفتيح بالكيبل على بنش مستوٍ",["ضع بنشًا مستويًا بين بكرتين سفليتين بحيث يكون صدرك على خط البكرتين عند الاستلقاء.","استلقِ على البنش والقدمان على الأرض.","أمسك مقبضًا بكل يد بقبضة سفلية (يمكن أن يناولك أحد المقبضين).","افتح ذراعيك للجانبين موازيتين للأرض مع ثني بسيط ثابت في المرفقين. هذه وضعية البداية.","ارفع ذراعيك في نصف دائرة أمامك حتى تلتقي يداك فوق صدرك، وأنت تعصر الصدر وتزفر. اثبت ثانية.","عد ببطء إلى البداية."]],"Flat_Bench_Leg_Pull-In":["سحب الركبتين على بنش مستوٍ",["استلقِ على حصيرة أو بنش مستوٍ ورجلاك خارج طرفه.","ضع يديك تحت مؤخرتك والكفّان للأسفل، أو أمسك جانبي البنش. مدّ رجليك. هذه وضعية البداية.","اثنِ ركبتيك واسحب فخذيك نحو بطنك وأنت تزفر حتى تقترب ركبتاك من صدرك. اثبت ثانية.","عد ببطء إلى البداية وأنت تشهق."]],"Flat_Bench_Lying_Leg_Raise":["رفع الرجلين مستلقيًا على بنش مستوٍ",["استلقِ على ظهرك على بنش ورجلاك ممدودتان خارج طرفه.","ضع يديك تحت مؤخرتك أو أمسك جانبي البنش. هذه وضعية البداية.","والرجلان ممدودتان مع ثني بسيط ثابت في الركبتين، ارفعهما حتى تصبحا عموديتين على الأرض، وأنت تزفر. اثبت ثانية.","اشهق وأنزلهما ببطء إلى البداية."]],"Flexor_Incline_Dumbbell_Curls":["باي دمبل على بنش مائل مع ثني الرسغ",["أمسك الدمبل بحيث يكون ثقله أكثر نحو الجهة القريبة من إبهامك، وأبقِ رسغيك للخلف قدر الإمكان لتخفيف الضغط عليهما.","اجلس على بنش مائل بزاوية 45° ودمبل في كل يد.","دع ذراعيك تتدليان بجانبك والمرفقان للداخل، والكفّان للأمام. لا تلفّ يديك أثناء الحركة.","اثنِ الدمبلين معًا حتى ينقبض الباي بالكامل وأنت تزفر، دون تأرجح. اثبت ثانية.","اشهق وعد ببطء إلى البداية."]],"Floor_Glute-Ham_Raise":["رفع خلفي الفخذ على الأرض (غلوت هام)",["استعن بزميل يمسك قدميك أو ثبّتهما تحت شيء ثابت.","ابدأ على ركبتيك والفخذان والجذع مستقيمة. هذه وضعية البداية.","انزل للأمام بفرد الركبتين، دون ثني الحوض.","ضع يديك أمامك عند وصولك للأرض. التمرين صعب جدًا، فادفع بيديك قليلًا عن الأرض لتساعد نفسك على العودة."]],"Floor_Press":["ضغط على الأرض بالبار",["اضبط خطافات القفص على الارتفاع المناسب، واستلقِ على الأرض ورأسك قرب طرف القفص. اضغط لوحي الكتف معًا وأخرج البار.","أنزل البار نحو أسفل صدرك أو أعلى بطنك وأنت تعصره كأنك تشدّه من طرفيه، والمرفقان قريبان من الجسم. انزل حتى يلمس العضدان الأرض وتوقف دون ارتداد.","ادفع البار للأعلى بأسرع ما يمكن، والبار والرسغان والمرفقان على خط واحد."]],"Floor_Press_with_Chains":["ضغط على الأرض بالسلاسل",["اضبط خطافات القفص على الارتفاع المناسب، وعلّق السلاسل على طرفي البار بعيدًا عن الأقراص.","استلقِ على الأرض ورأسك قرب طرف القفص، اضغط لوحي الكتف معًا وأخرج البار.","أنزل البار نحو أسفل صدرك أو أعلى بطنك وأنت تعصره، والمرفقان قريبان من الجسم، حتى يلمس العضدان الأرض. توقف دون ارتداد.","ادفع البار للأعلى بأسرع ما يمكن، والبار والرسغان والمرفقان على خط واحد."]],"Flutter_Kicks":["ركل الرفرفة",["انبطح على بنش مستوٍ والحوض عند طرفه، والرجلان ممدودتان خارجه، وأمسك الحافة الأمامية للبنش.","اعصر الأرداف وخلفي الفخذ وارفع رجليك حتى تصبحا بمستوى الحوض. هذه وضعية البداية.","ارفع الرجل اليسرى أعلى من اليمنى.","أنزل اليسرى وارفع اليمنى في الوقت نفسه، كأنك تسبح بركل الرفرفة. تنفّس بشكل طبيعي وحافظ على التحكّم."]],"Foot-SMR":["تدليك القدم بالكرة",["يطيل هذا التمرين أنسجة باطن القدم. اجلس واخلع حذاءك، وضع قدمك على رولر صغير أو أنبوب تحت قوس القدم. هذه وضعية البداية.","اضغط بقوة ودحرج قوس القدم فوقه. اثبت 10–30 ثانية ثم بدّل القدم."]],"Forward_Drag_with_Press":["سحب للأمام مع ضغط",["اربط حبلًا بمقبضين بالزلاجة، وقف وظهرك لها ومقبض في كل يد.","تقدّم خطوة مائلًا للأمام بفرد الرجلين والحوض، ومع كل خطوة توقف وافرد مرفقيك لتدفع يديك للأمام. تقدّم حتى تعود إلى وضعية الاستعداد للدفع."]],"Frankenstein_Squat":["سكوات فرانكنشتاين",["هذا التمرين يعلّمك وضعية البار والجسم الصحيحة في الكلين والسكوات الأمامي.","ضع البار على مقدمة كتفيك، ثم اترك قبضتك ومدّ ذراعيك أمامك. ادفع كتفيك للأمام لتصنع رفًا للبار، والبار ملامس للرقبة، دون تقويس أعلى الظهر.","انزل في سكوات بين رجليك، والجذع مستقيم والذراعان مرفوعتان والكتفان للأمام، والبار ثابت في مكانه، حتى يلامس خلفي الفخذ السمانة.","اصعد بالدفع بمقدمة الكعبين وفرد الركبتين والحوض."]],"Freehand_Jump_Squat":["سكوات بالقفز",["اعقد ذراعيك على صدرك.","الرأس مرفوع والظهر مستقيم، والقدمان بعرض الكتفين.","انزل في سكوات وأنت تشهق حتى يصبح الفخذان موازيين للأرض أو أدنى.","ادفع بمقدمة قدميك واقفز للأعلى بأقصى ما يمكن، مستخدمًا فخذيك كالنابض، وأنت تزفر.","عند الهبوط، انزل فورًا في سكوات واقفز مجددًا."]],"Frog_Hops":["قفز الضفدع",["قف ويداك خلف رأسك، وانزل في سكوات والجذع مستقيم والرأس مرفوع. هذه وضعية البداية.","اقفز للأمام لمسافة جيدة دون ارتفاع زائد. عند الهبوط امتص الصدمة برجليك واقفز مجددًا. كرّر 5–10 مرات."]],"Frog_Sit-Ups":["سيت أب الضفدع",["استلقِ على ظهرك والرجلان ممدودتان.","اثنِ ركبتيك وأنزل فخذيك للخارج نحو الأرض حتى يتلامس باطنا القدمين.","قرّب القدمين منك قدر الإمكان مع إبقاء الفخذين قريبين من الأرض، بحيث تشكّل الرجلان شكل معيّن.","اعقد ذراعيك أمام صدرك بلمس الكتفين المعاكسين. هذه وضعية البداية.","ازفر والصق أسفل ظهرك بالأرض وأنت ترفع جذعك (كربع حركة سيت أب)، واثبت ثانية.","انزل ببطء وأنت تشهق."]],"Front_Barbell_Squat":["سكوات أمامي بالبار",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار على ارتفاعك، وضعه على مقدمة كتفيك والمرفقان مرفوعان والعضدان أعلى من الموازاة قليلًا. يمكنك تقاطع ذراعيك فوق البار للتحكّم.","ارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق. المرفقان مرفوعان دائمًا.","ادفع الأرض بمنتصف قدميك لتصعد إلى البداية وأنت تزفر."]],"Front_Barbell_Squat_To_A_Bench":["سكوات أمامي بالبار حتى البنش",["يُفضّل أداؤه داخل قفص السكوات. ضع بنشًا مستويًا خلفك واضبط البار على ارتفاعك، وضعه على مقدمة كتفيك والمرفقان مرفوعان، مع تقاطع الذراعين فوقه للتحكّم.","ارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى تلامس البنش بمؤخرتك، وأنت تشهق.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Front_Box_Jump":["قفز أمامي على الصندوق",["ضع صندوقًا بارتفاع مناسب على بعد 30–60 سم أمامك، والقدمان بعرض الكتفين. هذه وضعية البداية.","انزل في سكوات قصير استعدادًا للقفز وأرجح ذراعيك للخلف.","انطلق بفرد الحوض والركبتين والكاحلين لأعلى ما يمكن، مع أرجحة الذراعين للأمام وللأعلى.","اهبط على الصندوق والركبتان مثنيتان لامتصاص الصدمة. انزل بخطوة رجلًا رجلًا (أفضل من القفز للأسفل)."]],"Front_Cable_Raise":["رفرفة أمامية بالكيبل",["اختر الوزن على الكيبل السفلي وأمسك المقبض بيدك اليسرى.","قف وظهرك للجهاز، والذراع ممدودة للأسفل أمام فخذك والكف نحو الفخذ. هذه وضعية البداية.","مع ثبات الجذع ودون تأرجح، ارفع ذراعك للأمام مع ثني بسيط في المرفق والكف للأسفل، حتى أعلى من مستوى الكتف قليلًا. ازفر واثبت ثانية.","اشهق وأنزل الذراع ببطء. أكمل التكرارات ثم بدّل الذراع."]],"Front_Cone_Hops_or_hurdle_hops":["نطّ أمامي فوق الأقماع (أو الحواجز)",["ضع صفًّا من الأقماع أو الحواجز الصغيرة على مسافات قصيرة.","قف أمام القمع الأول والقدمان بعرض الكتفين. هذه وضعية البداية.","اقفز بالقدمين معًا فوق القمع الأول مع أرجحة الذراعين.","امتص الصدمة بثني الركبتين وارتد فورًا فوق القمع التالي.","تابع حتى تتجاوز كل الأقماع."]],"Front_Dumbbell_Raise":["رفرفة أمامية بالدمبل",["قف باستقامة والدمبلان أمام فخذيك والكفّان نحوهما.","مع ثبات الجذع ودون تأرجح، ارفع الدمبل الأيسر للأمام مع ثني بسيط في المرفق والكف للأسفل، حتى أعلى من مستوى الكتف قليلًا. ازفر واثبت ثانية.","أنزله ببطء وفي الوقت نفسه ارفع الدمبل الأيمن.","تابع بالتبادل."]],"Front_Incline_Dumbbell_Raise":["رفرفة أمامية بالدمبل على بنش مائل",["اجلس على بنش مائل بزاوية بين 30° و60° ودمبل في كل يد. تغيير الزاوية يشغّل العضلة بشكل مختلف قليلًا.","مدّ ذراعيك أمامك والكفّان للأسفل، والدمبلان فوق فخذيك بقليل. هذه وضعية البداية.","ارفع الدمبلين ببطء والمرفقان ممدودان حتى أعلى من الكتفين قليلًا، واعصر ثانية وأنت تزفر. الرأس على البنش والقدمان على الأرض.","أنزل ذراعيك إلى البداية وأنت تشهق."]],"Front_Leg_Raises":["رفع الرجل للأمام",["قف بجانب كرسي أو مسند وأمسكه بيد واحدة.","أرجح رجلك للأمام وهي مستقيمة، ثم للخلف بقدر ما تسمح مرونتك. كرّر 5–10 مرات ثم بدّل الرجل."]],"Front_Plate_Raise":["رفرفة أمامية بالقرص",["قف باستقامة وأمسك قرصًا بيديك عند الساعة 3 والساعة 9، والكفّان متقابلتان، والذراعان ممدودتان مع ثني بسيط ثابت، والقرص أمام خصرك. هذه وضعية البداية.","ارفع القرص ببطء وأنت تزفر حتى أعلى من مستوى الكتفين قليلًا، واثبت ثانية. لا تؤرجح الوزن ولا تثنِ المرفقين، والجذع ثابت.","اشهق وأنزله ببطء إلى البداية."]],"Front_Raise_And_Pullover":["رفرفة أمامية مع بول أوفر",["استلقِ على بنش مستوٍ وأمسك البار بقبضة علوية والمسافة بين اليدين نحو 40 سم.","ضع البار على أعلى فخذيك والذراعان ممدودتان مع ثني بسيط في المرفقين. هذه وضعية البداية.","ارفع البار في نصف دائرة والذراعان مستقيمتان وأنت تشهق، حتى يصل خلف رأسك (نحو 180°) والذراعان موازيتان للأرض.","أعد البار بعكس الحركة إلى البداية وأنت تزفر."]],"Front_Squat_Clean_Grip":["سكوات أمامي (قبضة الكلين)",["اضبط البار تحت مستوى الكتفين بقليل. ضع البار على مقدمة الكتفين ملاصقًا للترقوة، وأمسكه بقبضة الكلين بأطراف أصابعك.","ارفعه عن الحامل بالدفع برجليك، وابتعد خطوة. القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس والمرفقان مرفوعان دائمًا.","اثنِ ركبتيك وانزل بين رجليك حتى يلامس خلفي الفخذ السمانة، مع دفع الركبتين للخارج على خط القدمين.","ادفع الأرض بالكعب أو منتصف القدم لتصعد إلى البداية وأنت تزفر."]],"Front_Squats_With_Two_Kettlebells":["سكوات أمامي بكيتلبلين",["ارفع كيتلبلين إلى كتفيك (كلين) بفرد الرجلين والحوض مع لفّ الرسغين.","والنظر للأمام دائمًا، انزل في سكوات لأعمق ما تستطيع بين رجليك وتوقف. ادفع ركبتيك للخارج، والجذع مستقيم والرأس والصدر مرفوعان.","اصعد بالدفع بكعبيك وكرّر."]],"Front_Two-Dumbbell_Raise":["رفرفة أمامية بدمبلين",["قف باستقامة والدمبلان أمام فخذيك والكفّان نحوهما.","مع ثبات الجذع ودون تأرجح، ارفع الدمبلين معًا للأمام مع ثني بسيط في المرفقين والكفّان للأسفل، حتى أعلى من مستوى الكتفين قليلًا. ازفر واثبت ثانية.","اشهق وأنزلهما ببطء إلى البداية."]],"Full_Range-Of-Motion_Lat_Pulldown":["سحب أمامي بمدى حركة كامل (لات بول داون)",["قف أو اجلس على بنش عالٍ بين بكرتين علويتين، وأمسك كل مقبض باليد المعاكسة بحيث تتقاطع ذراعاك فوقك والكفّان للأمام.","ارفع صدرك مع تقويس بسيط في أسفل الظهر، واسحب المقبضين للأسفل كما في السحب الأمامي العادي، لكن في مسار قوسي. أثناء السحب لفّ يديك بحيث تتقابل الكفّان في الأسفل. عد ببطء وكرّر."]],"Gironda_Sternum_Chins":["عقلة جيروندا إلى عظمة الصدر",["أمسك بار العقلة بقبضة سفلية بعرض الكتفين.","تعلّق والذراعان ممدودتان، أخرج صدرك ومِل للخلف، وابقَ مائلًا طوال الحركة. هذه وضعية البداية.","اسحب نفسك نحو البار مع تقويس الظهر وإمالة الرأس للخلف بعيدًا عن البار، وأنت تزفر. في الأعلى يكون الحوض والرجلان بزاوية 45° تقريبًا.","تابع حتى تتجاوز الترقوة البار ويلمس أسفل صدرك (عظمة الصدر) البار. اثبت ثانية.","انزل ببطء وأنت تشهق."]],"Glute_Ham_Raise":["رفع خلفي الفخذ على جهاز غلوت هام",["اضبط الجهاز على مقاس جسمك. انبطح وقدماك على اللوح بين البكرات، وركبتاك خلف المسند مباشرة.","ابدأ من أسفل الحركة. مع ظهر مقوّس، اثنِ ركبتيك واضغط بأصابع قدميك على اللوح لترفع جذعك. الجذع مستقيم، وتابع حتى يصبح جسمك عموديًا.","عد إلى البداية بنزول متحكّم به."]],"Glute_Kickback":["ركلة الأرداف للخلف (كيك باك)",["اركع على الأرض وانحنِ واستند على يديك بعرض الكتفين، والذراعان عموديتان، والركبتان مثنيتان 90°، والنظر للأمام. هذه وضعية البداية.","ازفر وارفع رجلك اليمنى حتى يصبح الفخذ على خط الظهر مع إبقاء ثني الركبة 90°. اعصر الأرداف واثبت ثانية.","عد وأنت تشهق، ثم كرّر بالرجل اليسرى. تابع بالتبادل."]],"Goblet_Squat":["سكوات الكأس (غوبلت)",["قف وأمسك كيتلبلًا خفيفًا (أو دمبلًا) من قرنيه قريبًا من صدرك. هذه وضعية البداية.","انزل في سكوات بين رجليك حتى يلامس خلفي الفخذ السمانة، والصدر والرأس مرفوعان والظهر مستقيم.","في الأسفل توقف وادفع ركبتيك للخارج بمرفقيك. ثم اصعد إلى البداية."]],"Good_Morning":["غود مورنينغ",["ضع البار على الحامل بمستوى الكتفين، ثم ضعه على أعلى ظهرك خلف الكتفين كما في السكوات. شدّ ظهرك واضغط لوحي الكتف معًا، والركبتان مثنيتان قليلًا، وابتعد عن الحامل.","انحنِ من الحوض بدفعه للخلف حتى يقارب جذعك الموازاة مع الأرض، مع ظهر مقوّس ورقبة على خط الظهر.","عد بفرد الحوض باستخدام الأرداف وخلفي الفخذ حتى تقف. استخدم وزنًا خفيفًا، والتمرين يضغط أسفل الظهر."]],"Good_Morning_off_Pins":["غود مورنينغ من المساند",["اضبط البار على مساند القفص بمستوى بطنك تقريبًا. انحنِ تحته وضعه على أعلى ظهرك خلف الكتفين، بحيث يكون جذعك شبه موازٍ للأرض. شدّ ظهرك واضغط لوحي الكتف، والركبتان مثنيتان قليلًا.","افرد حوضك باستخدام الأرداف وخلفي الفخذ حتى تقف بالوزن، ثم أنزله ببطء إلى المساند."]],"Gorilla_Chin_Crunch":["عقلة الغوريلا مع كرنش",["تعلّق على بار العقلة بقبضة سفلية أعرض قليلًا من الكتفين.","اثنِ ركبتيك 90° بحيث تكون الساقان موازيتين للأرض والفخذان عموديين. هذه وضعية البداية.","ازفر واسحب نفسك للأعلى وفي الوقت نفسه ارفع ركبتيك حتى مستوى الصدر، وتوقف عندما يصل أنفك إلى مستوى البار.","انزل ببطء وأنت تشهق."]],"Groin_and_Back_Stretch":["إطالة الفخذ الداخلي والظهر",["اجلس على الأرض والركبتان مثنيتان وباطنا القدمين متلاصقان.","شبّك أصابعك خلف رأسك. هذه وضعية البداية.","انحنِ للأسفل مقرّبًا مرفقيك إلى داخل فخذيك. توقف لحظة ثم عد والرأس مرفوع والظهر مستقيم. كرّر 10–20 مرة."]],"Groiners":["ركبة إلى اليد من البلانك",["ابدأ بوضعية الضغط على الأرض. هذه وضعية البداية.","اقفز بالرجلين معًا للأمام لتهبط بقدميك بجانب يديك، والرأس مرفوع.","عد إلى البداية وكرّر فورًا 10–20 مرة."]],"Hack_Squat":["هاك سكوات",["أسند ظهرك على مسند الجهاز وضع كتفيك تحت مساند الكتف.","ضع قدميك على المنصة بعرض الكتفين وأصابعهما للخارج قليلًا. الرأس مرفوع والظهر ملتصق بالمسند دائمًا.","أمسك المقابض الجانبية وحرّر أذرع الأمان.","افرد رجليك دون قفل الركبتين. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق.","ادفع المنصة بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Hammer_Curls":["باي مطرقة (هامر)",["قف باستقامة ودمبل في كل يد والذراعان ممدودتان، والمرفقان قريبان من الجسم.","الكفّان متقابلتان نحو جسمك. هذه وضعية البداية.","ثبّت العضد، ازفر واثنِ الدمبل بعصر الباي حتى مستوى الكتف، واعصر لحظة. المرفق ثابت والساعد فقط يتحرك.","اشهق وأنزل الدمبلين ببطء إلى البداية."]],"Hammer_Grip_Incline_DB_Bench_Press":["ضغط دمبل على بنش مائل بقبضة محايدة",["استلقِ على بنش مائل والدمبلان على فخذيك والكفّان متقابلتان.","بمساعدة فخذيك، ارفع الدمبلين واحدًا تلو الآخر إلى عرض الكتفين.","أبقِ القبضة محايدة (الكفّان متقابلتان)، والمرفقان مثنيان 90°. هذه وضعية البداية.","أنزل الدمبلين ببطء إلى جانبيك وأنت تشهق، مع تحكّم كامل.","ادفعهما للأعلى بعضلات الصدر وأنت تزفر، واثبت ثانية. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أنزل الدمبلين على فخذيك ثم على الأرض، فهذه أكثر طريقة آمنة."]],"Hamstring-SMR":["تدليك خلفي الفخذ بالفوم رولر",["اجلس ومدّ رجليك فوق الفوم رولر بحيث يكون تحت خلف الفخذين، ويداك بجانبك أو خلفك للسند. هذه وضعية البداية.","ارفع حوضك بيديك وانقل وزنك على الرولر إلى رجل واحدة، وأرخِ خلفي الفخذ.","تدحرج من تحت الورك حتى فوق خلف الركبة، وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالرجل الأخرى."]],"Hamstring_Stretch":["إطالة خلفي الفخذ",["استلقِ على ظهرك ورجل مرفوعة فوقك بزاوية 90° عند الورك، والأخرى ممدودة على الأرض.","لفّ حزامًا أو مطاطًا أو حبلًا حول مقدمة قدمك المرفوعة. هذه وضعية البداية.","اسحب الحزام لتشعر بإطالة في السمانة وخلفي الفخذ. اثبت 10–30 ثانية ثم بدّل الرجل."]],"Handstand_Push-Ups":["ضغط بالوقوف على اليدين",["وظهرك للحائط، انحنِ وضع يديك على الأرض بعرض الكتفين.","اركل رجليك للأعلى على الحائط والذراعان مستقيمتان، حتى تصبح مقلوبًا والجسم مستقيم. في المرة الأولى اطلب من أحد مساعدتك، وانظر نحو الحائط لا للأسفل.","انزل ببطء وأنت تشهق حتى يكاد رأسك يلمس الأرض. النزول البطيء ضروري لتجنّب إصابة الرأس.","ادفع ببطء للأعلى وأنت تزفر حتى تقارب ذراعاك الامتداد الكامل."]],"Hang_Clean":["كلين من التعليق",["أمسك البار بقبضة علوية أو قبضة الخطّاف بعرض الكتفين، والبار متدلٍّ عند منتصف الفخذ، والظهر مستقيم ومائل للأمام قليلًا.","افرد الحوض والركبتين والكاحلين بقوة لتدفع الوزن للأعلى، وارفع كتفيك نحو أذنيك. ثم اسحب نفسك تحت البار مع لفّ المرفقين، واستقبله على مقدمة الكتفين في سكوات أمامي.","اصعد فورًا بالدفع بالكعبين، والجذع مستقيم والمرفقان مرفوعان، حتى تقف."]],"Hang_Clean_-_Below_the_Knees":["كلين من التعليق تحت الركبتين",["أمسك البار بقبضة علوية أو قبضة الخطّاف بعرض الكتفين، والبار متدلٍّ تحت الركبتين بقليل، والظهر مستقيم ومائل للأمام قليلًا.","افرد الحوض والركبتين والكاحلين بقوة لتدفع الوزن للأعلى، وارفع كتفيك. عند الامتداد الكامل اثنِ ذراعيك بقوة والمرفقان للأعلى وللخارج.","اسحب نفسك تحت البار مع لفّ المرفقين، واستقبله على مقدمة الكتفين في سكوات أمامي.","اصعد فورًا بالدفع بالكعبين حتى تقف."]],"Hang_Snatch":["خطف من التعليق (سناتش)",["أمسك البار بقبضة واسعة (علوية أو خطّاف)، والقدمان تحت الحوض وأصابعهما للخارج، والركبتان مثنيتان قليلًا والجذع مائل للأمام، والظهر مستقيم والبار عند الحوض. هذه وضعية البداية.","افرد رجليك وحوضك بقوة. في أقصى امتداد ارفع كتفيك ودع المرفقين ينثنيان للجانبين.","انقل قدميك إلى وضعية الاستقبال واسحب نفسك بقوة تحت البار وأنت ترفعه فوق رأسك. استقبله بأدنى وضعية ممكنة والذراعان ممدودتان.","قف والوزن فوق رأسك، ثم أنزله إلى الأرض بتحكّم."]],"Hang_Snatch_-_Below_Knees":["خطف من التعليق تحت الركبتين",["أمسك البار بقبضة واسعة (علوية أو خطّاف)، والقدمان تحت الحوض وأصابعهما للخارج، والركبتان مثنيتان قليلًا والجذع مائل للأمام، والبار تحت الركبتين بقليل. هذه وضعية البداية.","افرد رجليك وحوضك بقوة. في أقصى امتداد ارفع كتفيك ودع المرفقين ينثنيان للجانبين.","انقل قدميك إلى وضعية الاستقبال واسحب نفسك بقوة تحت البار وأنت ترفعه فوق رأسك. استقبله بأدنى وضعية ممكنة والذراعان ممدودتان.","قف والوزن فوق رأسك، ثم أنزله إلى الأرض بتحكّم."]],"Hanging_Bar_Good_Morning":["غود مورنينغ والبار معلّق",["علّق البار بالسلاسل أو الأحزمة على ارتفاع بطنك تقريبًا.","انحنِ تحته وضعه على أعلى ظهرك خلف الكتفين، بحيث يكون جذعك شبه موازٍ للأرض. شدّ ظهرك واضغط لوحي الكتف، والركبتان مثنيتان قليلًا.","افرد حوضك باستخدام الأرداف وخلفي الفخذ حتى تقف بالوزن.","أنزل الوزن ببطء حتى تحمله السلاسل من جديد."]],"Hanging_Leg_Raise":["رفع الرجلين معلّقًا",["تعلّق على بار العقلة بقبضة واسعة أو متوسطة والذراعان ممدودتان، والرجلان مستقيمتان للأسفل والحوض ملفوف للخلف قليلًا. هذه وضعية البداية.","ارفع رجليك حتى تصبح الزاوية بين الجذع والرجلين 90°، وأنت تزفر. اثبت ثانية.","انزل ببطء وأنت تشهق، دون تأرجح."]],"Hanging_Pike":["رفع الرجلين مستقيمتين معلّقًا (بايك)",["تعلّق على بار العقلة بقبضة علوية أعرض قليلًا من الكتفين والرجلان معًا. يمكنك استخدام أحزمة الرسغ.","اثنِ ركبتيك 90° وارفع فخذيك للأمام حتى يصبحا موازيين للأرض. هذه وضعية البداية.","اسحب رجليك للأعلى وأنت تزفر حتى تقترب ساقاك من البار، مع محاولة فرد رجليك في الأعلى.","أنزل رجليك ببطء قدر الإمكان إلى البداية، دون تأرجح."]],"Heaving_Snatch_Balance":["توازن الخطف بالدفع",["تمرين لتعلّم الخطف. أمسك وزنًا خفيفًا على أعلى ظهرك، والقدمان أعرض قليلًا من الحوض وأصابعهما للخارج كوضعية السكوات.","انزل قليلًا بالركبتين ثم ادفع للأعلى لتخفّف الوزن عن كتفيك لحظة، واندفع تحت البار وأنت ترفعه فوق رأسك نازلًا إلى سكوات كامل.","قف باستقامة."]],"Heavy_Bag_Thrust":["دفع كيس الملاكمة",["قف بجانب كيس ملاكمة ثقيل، والقدمان متباعدتان للأمام والخلف بوقفة واسعة، ويدك على الكيس بمستوى الصدر. هذه وضعية البداية.","لفّ خصرك وادفع الكيس للأمام بأقوى وأسرع ما يمكن.","استقبل الكيس عند عودته بعكس الحركة."]],"High_Cable_Curls":["باي بالكيبل العلوي",["قف بين بكرتين علويتين وأمسك مقبضًا بكل يد، والعضدان موازيان للأرض والكفّان نحوك. هذه وضعية البداية.","اثنِ المقبضين نحوك حتى يصلا بجانب أذنيك، وأنت تعصر الباي وتزفر. العضدان ثابتان. اثبت ثانية.","أعد ذراعيك ببطء إلى البداية."]],"Hip_Circles_prone":["دوائر الورك منبطحًا",["ابدأ على يديك وركبتيك، وارفع ركبة مثنية عن الأرض بوضعية جيدة. هذه وضعية البداية.","والركبة مثنية، دوّر الفخذ لترسم بركبتك دائرة كبيرة.","أدِّها ببطء عدة مرات ثم بدّل الجهة."]],"Hip_Extension_with_Bands":["مدّ الورك بالمطاط",["ثبّت أحد طرفي المطاط أسفل عمود والآخر بكاحلك.","قف مقابل العمود وأمسكه للثبات.","والرأس والصدر مرفوعان، حرّك الرجل المربوطة للخلف لأقصى حد والركبة مستقيمة.","أعد الرجل إلى البداية. أكمل التكرارات ثم بدّل الرجل."]],"Hip_Flexion_with_Band":["ثني الورك بالمطاط",["ثبّت أحد طرفي المطاط أسفل عمود والآخر بكاحلك.","قف وظهرك للعمود.","والرأس والصدر مرفوعان، ارفع ركبتك حتى 90° وتوقف.","أعد الرجل إلى البداية. أكمل التكرارات ثم بدّل الرجل."]],"Hip_Lift_with_Band":["رفع الحوض بالمطاط",["اختر مطاطًا مناسبًا وثبّته على جانبي القفص (أو بدمبلات ثقيلة ثابتة)، واستلقِ في المنتصف.","اضبط وضعك بحيث يكون المطاط فوق حوضك مباشرة، والركبتان مثنيتان والقدمان على الأرض.","والكتفان على الأرض، ادفع بكعبيك لترفع حوضك ضد المطاط لأعلى ما تستطيع.","توقف في الأعلى، ثم عد إلى البداية."]],"Hug_A_Ball":["احتضان الكرة",["اجلس على الأرض.","ضع كرة التمارين بين رجليك وأنزل حوضك نحو الأرض.","احتضن الكرة بذراعيك للسند، والقدمان على الأرض والركبتان فوق الكاحلين. أمسك الكرة جيدًا حتى لا تتدحرج."]],"Hug_Knees_To_Chest":["ضم الركبتين إلى الصدر",["استلقِ على ظهرك واسحب ركبتيك إلى صدرك.","ضع ذراعيك تحت الركبتين لا فوقهما، حتى لا تضغط على مفصل الركبة.","اسحب الركبتين ببطء نحو كتفيك. هذا يطيل الأرداف أيضًا."]],"Hurdle_Hops":["نطّ فوق الحواجز",["ضع صفًّا من الحواجز الصغيرة على مسافات قصيرة.","قف أمام الحاجز الأول والقدمان بعرض الكتفين. هذه وضعية البداية.","اقفز بالقدمين معًا فوق الحاجز الأول مع أرجحة الذراعين.","امتص الصدمة بثني الركبتين وارتد فورًا فوق الحاجز التالي، حتى تتجاوز كل الحواجز."]],"Hyperextensions_Back_Extensions":["تمديد الظهر (هايبر إكستنشن)",["انبطح على جهاز تمديد الظهر وثبّت كاحليك تحت المساند.","اضبط المسند العلوي بحيث يستقر أعلى فخذيك عليه، ويبقى مجال لتنحني من الخصر بحرية.","والجسم مستقيم، اعقد ذراعيك أمام صدرك أو خلف رأسك (يمكنك حمل قرص للصعوبة). هذه وضعية البداية.","انحنِ ببطء من الخصر مع ظهر مستقيم، وأنت تشهق، حتى تشعر بإطالة في خلفي الفخذ أو قبل أن يتقوّس ظهرك. لا تقوّس ظهرك للأسفل أبدًا.","ارفع جذعك ببطء إلى البداية، دون أن تتجاوز الخط المستقيم ودون تأرجح."]],"Hyperextensions_With_No_Hyperextension_Bench":["تمديد الظهر بدون جهاز",["بمساعدة شخص يمسك رجليك، انزلق إلى طرف بنش مستوٍ حتى يتدلى حوضك وجذعك خارجه نحو الأرض.","والجسم مستقيم، اعقد ذراعيك أمام صدرك أو خلف رأسك (يمكنك حمل قرص للصعوبة). هذه وضعية البداية.","انحنِ ببطء من الخصر لأبعد ما تستطيع مع ظهر مستقيم، وأنت تشهق، حتى تقارب الأرض أو تشعر بإطالة في خلفي الفخذ. لا تقوّس ظهرك للأسفل أبدًا.","ارفع جذعك ببطء إلى البداية وأنت تزفر، دون أن تتجاوز الخط المستقيم ودون تأرجح."]],"IT_Band_and_Glute_Stretch":["إطالة الحزام الحرقفي والأرداف",["استلقِ على ظهرك ولفّ حزامًا أو حبلًا حول قدم واحدة، وحرّك تلك الرجل عبر جسمك إلى الجهة المعاكسة وهي ممدودة. هذه وضعية البداية.","والقدم مرفوعة عن الأرض، اسحب الحزام لتسحب أصابع القدم نحوك. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Iliotibial_Tract-SMR":["تدليك الحزام الحرقفي بالفوم رولر",["استلقِ على جنبك والرجل السفلية على الفوم رولر بين الورك والركبة، والرجل الأخرى أمامك.","ضع على الرجل السفلية ما تتحمّله من وزنك، وأرخِ عضلاتها.","تدحرج من الورك حتى الركبة، وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالرجل الأخرى."]],"Inchworm":["مشية الدودة",["قف والقدمان متقاربتان. والرجلان مستقيمتان، انحنِ وضع يديك على الأرض أمامك. هذه وضعية البداية.","امشِ بيديك ببطء للأمام بالتبادل، مع الانحناء من الحوض فقط والرجلان مستقيمتان.","تابع حتى يصبح جسمك موازيًا للأرض بوضعية الضغط.","ثبّت يديك وامشِ بقدميك بخطوات قصيرة جدًا.","تابع حتى تصل قدماك قرب يديك، والرجلان مستقيمتان."]],"Incline_Barbell_Triceps_Extension":["تراي بالبار على بنش مائل",["أمسك البار بقبضة علوية أضيق قليلًا من الكتفين.","استلقِ على بنش مائل بزاوية بين 45° و75°.","ارفع البار فوق رأسك والذراعان ممدودتان والمرفقان للداخل. هذه وضعية البداية.","أنزل البار في نصف دائرة خلف رأسك حتى يلمس الساعدان الباي، وأنت تشهق. العضدان ثابتان وقريبان من الرأس.","عد إلى البداية بعصر التراي وأنت تزفر، واثبت ثانية."]],"Incline_Bench_Pull":["تجديف منبطحًا على بنش مائل",["أمسك دمبلًا في كل يد وانبطح على بنش مائل بنحو 30°.","دع ذراعيك تتدليان نحو الأرض ممدودتين.","لفّ رسغيك لتصبح القبضة علوية (الكفّان للخلف).","افتح المرفقين للخارج. هذه وضعية البداية.","ازفر واسحب الدمبلين للأعلى كأنه ضغط صدر معكوس، بثني المرفقين ورفع العضدين حتى يصلا إلى مستوى ظهرك. يشبه جسمك حرف T في الأعلى. اثبت ثانية.","انزل ببطء وأنت تشهق."]],"Incline_Cable_Chest_Press":["ضغط صدر بالكيبل على بنش مائل",["اختر الوزن واجلس وأمسك المقابض. العضدان بزاوية 45° تقريبًا عن الجسم، والمرفقان مثنيان نحو 90°، والرأس والصدر مرفوعان.","مدّ مرفقيك واضغط المقبضين أمامك وللأعلى قليلًا، مع إبقاء لوحي الكتف مسحوبين للخلف.","توقف عند امتداد الذراعين، ثم عد إلى البداية مع إبقاء الشد على الكيبل."]],"Incline_Cable_Flye":["تفتيح بالكيبل على بنش مائل",["اضبط البكرتين في أدنى وضع.","ضع بنشًا مائلًا بزاوية 45° بين البكرتين، اختر الوزن وأمسك مقبضًا بكل يد.","استلقِ على البنش واجمع يديك أمام وجهك والذراعان ممدودتان. هذه وضعية البداية.","مع ثني بسيط في المرفقين، أنزل ذراعيك للجانبين في قوس واسع حتى تشعر بإطالة في الصدر، وأنت تشهق. الحركة من الكتف فقط.","أعد ذراعيك في القوس نفسه وأنت تعصر صدرك وتزفر، واثبت ثانية."]],"Incline_Dumbbell_Bench_With_Palms_Facing_In":["ضغط دمبل على بنش مائل بقبضة محايدة",["استلقِ على بنش مائل والدمبلان على فخذيك والكفّان متقابلتان.","بمساعدة فخذيك، ارفع الدمبلين واحدًا تلو الآخر إلى عرض الكتفين.","أبقِ القبضة محايدة (الكفّان متقابلتان)، والمرفقان مثنيان 90°. هذه وضعية البداية.","أنزل الدمبلين ببطء إلى جانبيك وأنت تشهق، مع تحكّم كامل.","ادفعهما للأعلى بعضلات الصدر وأنت تزفر، واثبت ثانية. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أنزل الدمبلين على فخذيك ثم على الأرض."]],"Incline_Dumbbell_Curl":["باي دمبل على بنش مائل",["اجلس على بنش مائل ودمبل في كل يد والذراعان ممدودتان للأسفل. المرفقان قريبان من الجسم والكفّان للأمام.","ثبّت العضدين واثنِ الدمبلين بعصر الباي وأنت تزفر حتى مستوى الكتفين. الساعدان فقط يتحركان. اثبت ثانية.","أنزلهما ببطء إلى البداية وأنت تشهق."]],"Incline_Dumbbell_Flyes":["تفتيح دمبل على بنش مائل",["أمسك دمبلًا في كل يد واستلقِ على بنش مائل بزاوية لا تزيد عن 30°.","مدّ ذراعيك فوقك مع ثني بسيط في المرفقين.","لفّ رسغيك بحيث تكون الكفّان نحوك والإصبعان الصغيران متجاوران. هذه وضعية البداية.","اشهق وأنزل ذراعيك ببطء للجانبين وأنت تلفّ الرسغين، حتى تصبح ذراعاك بجانبك والكفّان للأعلى.","ازفر وأعد الدمبلين إلى البداية بعكس الحركة. الحركة من الكتف والرسغ فقط، لا من المرفق."]],"Incline_Dumbbell_Flyes_-_With_A_Twist":["تفتيح دمبل على بنش مائل مع لفّ الرسغ",["أمسك دمبلًا في كل يد واستلقِ على بنش مائل بزاوية لا تزيد عن 30°.","مدّ ذراعيك فوقك مع ثني بسيط في المرفقين.","لفّ رسغيك بحيث تكون الكفّان نحوك والإصبعان الصغيران متجاوران. هذه وضعية البداية.","اشهق وأنزل ذراعيك ببطء للجانبين وأنت تلفّ الرسغين، حتى تصبح ذراعاك بجانبك والكفّان للأعلى.","ازفر وأعد الدمبلين إلى البداية بعكس الحركة. الحركة من الكتف والرسغ فقط، لا من المرفق."]],"Incline_Dumbbell_Press":["ضغط دمبل على بنش مائل",["استلقِ على بنش مائل والدمبلان على فخذيك والكفّان متقابلتان.","بمساعدة فخذيك، ارفع الدمبلين واحدًا تلو الآخر إلى عرض الكتفين.","لفّ رسغيك لتصبح الكفّان للأمام. هذه وضعية البداية.","حافظ على تحكّم كامل بالدمبلين، ثم ازفر وادفعهما للأعلى بالصدر.","اثبت ثانية في الأعلى، ثم أنزل الوزن ببطء. الأفضل أن يأخذ النزول ضعف وقت الصعود.","عند الانتهاء أنزل الدمبلين على فخذيك ثم على الأرض."]],"Incline_Hammer_Curls":["باي مطرقة على بنش مائل",["اجلس على بنش مائل ودمبل في كل يد، وظهرك ملتصق بالمسند. دع الدمبلين يتدليان بجانبك بقبضة محايدة.","اثنِ المرفقين مع محاولة إبقاء العضدين ثابتين.","تابع إلى أعلى الحركة وتوقف لحظة، ثم عد ببطء إلى البداية."]],"Incline_Inner_Biceps_Curl":["باي داخلي على بنش مائل",["أمسك دمبلًا في كل يد واستلقِ على بنش مائل.","الدمبلان متدليان بجانبك والكفّان للخارج. هذه وضعية البداية.","ازفر واثنِ الدمبلين للخارج وللأعلى، والساعدان على خط الكتفين الجانبيين، حتى يصلا إلى مستوى الكتفين بجانبهما. تشبه النهاية وضعية استعراض الباي المزدوج.","اعصر ثانية، ثم اشهق وأنزلهما ببطء في المسار نفسه."]],"Incline_Push-Up":["ضغط مائل واليدان مرتفعتان",["قف مقابل بنش أو منصة ثابتة، وضع يديك على حافته أعرض قليلًا من الكتفين.","ارجع بقدميك والذراعان والجسم مستقيمة. والجسم مستقيم، انزل بصدرك نحو الحافة بثني الذراعين.","ادفع حتى تمتد ذراعاك، وكرّر."]],"Incline_Push-Up_Close-Grip":["ضغط مائل بقبضة ضيقة",["قف مقابل بار السميث أو منصة ثابتة بارتفاع مناسب.","ضع يديك متجاورتين على البار.","ارجع بقدميك والذراعان والجسم مستقيمة. هذه وضعية البداية.","والجسم مستقيم، انزل بصدرك نحو البار بثني الذراعين.","ادفع لتعود إلى البداية بفرد المرفقين."]],"Incline_Push-Up_Depth_Jump":["ضغط مائل مع قفز عميق",["تحتاج صندوقًا بارتفاع نحو 30 سم ودرجتي أيروبيك أو حصيرتين سميكتين.","ضع الدرجتين خارج كتفيك مباشرة، وقدميك على الصندوق بوضعية ضغط مائل، ويداك بين الدرجتين. هذه وضعية البداية.","انزل بثني المرفقين ثم ادفع بسرعة لترتفع عن الأرض، وانقل يديك إلى الدرجتين مع ثني المرفقين لامتصاص الصدمة.","كرّر الحركة لتعود إلى البداية."]],"Incline_Push-Up_Medium":["ضغط مائل بقبضة متوسطة",["قف مقابل بار السميث أو منصة ثابتة بارتفاع مناسب.","ضع يديك على البار بعرض الكتفين.","ارجع بقدميك والذراعان والجسم مستقيمة. هذه وضعية البداية.","والجسم مستقيم، انزل بصدرك نحو البار بثني الذراعين.","ادفع لتعود إلى البداية بفرد المرفقين."]],"Incline_Push-Up_Reverse_Grip":["ضغط مائل بقبضة معكوسة",["قف مقابل بار السميث أو منصة ثابتة بارتفاع مناسب.","ضع يديك على البار والكفّان للأعلى بعرض الكتفين.","ارجع بقدميك والذراعان والجسم مستقيمة. هذه وضعية البداية.","والجسم مستقيم، انزل بصدرك نحو البار بثني الذراعين.","ادفع لتعود إلى البداية بفرد المرفقين."]],"Incline_Push-Up_Wide":["ضغط مائل بقبضة واسعة",["قف مقابل بار السميث أو منصة ثابتة بارتفاع مناسب.","ضع يديك على البار أعرض من الكتفين.","ارجع بقدميك والذراعان والجسم مستقيمة، والذراعان عموديتان على الجسم. هذه وضعية البداية.","والجسم مستقيم، انزل بصدرك نحو البار بثني الذراعين.","ادفع لتعود إلى البداية بفرد المرفقين."]],"Intermediate_Groin_Stretch":["إطالة الفخذ الداخلي (متوسط)",["استلقِ على ظهرك والرجلان ممدودتان. لفّ حزامًا أو حبلًا حول قدم واحدة، وحرّك تلك الرجل إلى الجانب لأبعد حد. هذه وضعية البداية.","اسحب الحزام برفق لتشعر بشد في الفخذ الداخلي وخلفي الفخذ. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Intermediate_Hip_Flexor_and_Quad_Stretch":["إطالة ثانيات الورك وأمامي الفخذ (متوسط)",["انبطح على الأرض وحبل أو حزام ملفوف حول قدم واحدة.","اثنِ الركبة وافرد الورك، واسحب الحزام بيديك حتى ترتفع الركبة والورك عن الأرض لتشعر بإطالة في ثانيات الورك وأمامي الفخذ. اثبت 10–20 ثانية ثم بدّل الرجل."]],"Internal_Rotation_with_Band":["تدوير الكتف للداخل بالمطاط",["اربط المطاط حول عمود بمستوى مرفقك، وقف وجانبك الأيمن له على بعد خطوة.","أمسك طرف المطاط بيدك اليمنى وألصق مرفقك بجانبك (يمكنك وضع منشفة ملفوفة تحته).","المرفق مثني 90° واليد بعيدة عن الجسم للخارج. هذه وضعية البداية.","دوّر ذراعك للداخل نحو بطنك مع ثبات المرفق.","تابع لأبعد ما تستطيع، توقف، ثم عد. أكمل التكرارات ثم بدّل الجهة."]],"Inverted_Row":["تجديف مقلوب (بوزن الجسم)",["اضبط بارًا في القفص أو على السميث بمستوى الخصر تقريبًا.","أمسكه بقبضة أعرض من الكتفين وتعلّق تحته، والجسم مستقيم والكعبان على الأرض والذراعان ممدودتان. هذه وضعية البداية.","اثنِ المرفقين واسحب صدرك نحو البار مع ضم لوحي الكتف.","توقف في الأعلى، ثم انزل إلى البداية. كلما اقتربت قدماك من تحت البار سهل التمرين."]],"Inverted_Row_with_Straps":["تجديف مقلوب بالأحزمة",["علّق حبلًا أو أحزمة معلّقة على القفص أو شيء ثابت. أمسك الطرفين وتعلّق على ظهرك، والجسم مستقيم والكعبان على الأرض والذراعان ممدودتان. هذه وضعية البداية.","اثنِ المرفقين واسحب صدرك نحو يديك مع ضم لوحي الكتف.","توقف في الأعلى، ثم عد إلى البداية."]],"Iron_Cross":["الصليب الحديدي"],"Iron_Crosses_stretch":["الصليب الحديدي (إطالة)",["انبطح على الأرض والذراعان ممدودتان للجانبين والكفّان على الأرض. هذه وضعية البداية.","اثنِ ركبة واحدة واعبر بتلك الرجل خلف جسمك محاولًا لمس الأرض قرب اليد المعاكسة.","أعدها فورًا وكرّر بالرجل الأخرى. تابع بالتبادل 10–20 مرة."]],"Isometric_Chest_Squeezes":["ضغط الصدر الثابت (تقلص ثابت)",["جالسًا أو واقفًا، اثنِ ذراعيك 90° وضع كفّيك معًا أمام صدرك، والأصابع للأمام.","اضغط اليدين على بعضهما وأنت تعصر الصدر. ابدأ بشد خفيف وزِده تدريجيًا، وتنفّس بشكل طبيعي.","اثبت عدد الثواني المطلوب، ثم أرخِ الشد ببطء.","استرح ثم كرّر."]],"Isometric_Neck_Exercise_-_Front_And_Back":["تمرين الرقبة الثابت أمامًا وخلفًا",["والرأس والرقبة في الوضع الطبيعي، ضع يديك على جبهتك.","ادفع برأسك للأمام برفق مع مقاومة أي حركة بيديك، وابدأ بشد خفيف ثم زِده تدريجيًا. تنفّس بشكل طبيعي.","اثبت عدد الثواني المطلوب، ثم أرخِ الشد ببطء.","استرح ثم كرّر ويداك على خلف رأسك."]],"Isometric_Neck_Exercise_-_Sides":["تمرين الرقبة الثابت جانبيًا",["والرأس والرقبة في الوضع الطبيعي، ضع يدك اليسرى على الجانب الأيسر من رأسك.","ادفع برأسك نحو اليسار برفق مع مقاومة أي حركة، وابدأ بشد خفيف ثم زِده تدريجيًا. تنفّس بشكل طبيعي.","اثبت عدد الثواني المطلوب، ثم أرخِ الشد ببطء.","استرح ثم كرّر باليد اليمنى على الجانب الأيمن."]],"Isometric_Wipers":["مسّاحات ثابتة",["اتخذ وضعية الضغط، واليدان أعرض قليلًا من الكتفين والجسم مستقيم. هذه وضعية البداية.","انقل وزنك لأبعد حد إلى جانب واحد، ودع مرفق ذلك الجانب ينثني وأنت تنزل.","افرد الذراع المثنية لتصعد، ثم انزل إلى الجانب الآخر. تابع بالتبادل."]],"JM_Press":["ضغط JM",["استلقِ على بنش مستوٍ وأمسك البار بقبضة ضيقة والذراعان ممدودتان والمرفقان للداخل، والبار فوق أعلى صدرك مباشرة.","أنزل البار كأنه تراي مستلقٍ وأنت تشهق. عند منتصف الطريق، حرّك العضدين نحو رجليك حتى يصبحا عموديين على الجذع، مع ثبات ثني المرفقين.","ازفر وادفع البار للأعلى بالتراي كأنه ضغط صدر ضيق.","عد إلى البداية وكرّر."]],"Jackknife_Sit-Up":["سيت أب السكين (جاك نايف)",["استلقِ على ظهرك والذراعان ممدودتان خلف رأسك والرجلان ممدودتان. هذه وضعية البداية.","ازفر وانثنِ من الخصر وارفع رجليك وذراعيك معًا لتلتقي فوقك كالسكين المطوية. الرجلان بزاوية 35–45° عن الأرض والذراعان موازيتان لهما، والجزء العلوي مرفوع عن الأرض.","اشهق وأنزل ذراعيك ورجليك إلى البداية."]],"Janda_Sit-Up":["سيت أب جاندا",["استلقِ في وضعية السيت أب: الركبتان 90° والقدمان على الأرض، والذراعان على الصدر أو بجانبك. هذه وضعية البداية.","اعصر الأرداف وخلفي الفخذ بقوة، خذ نفسًا ثم اصعد ببطء (3–6 ثوانٍ) وأنت تزفر. عصر الأرداف يقلل عمل عضلات ثني الورك فيشتغل البطن أكثر.","اشهق وعد ببطء وتحكّم إلى البداية."]],"Jefferson_Squats":["سكوات جيفرسون",["ضع بارًا على الأرض وقف في منتصفه بحيث يكون البار بين رجليك بالطول.","انزل بثني الركبتين مع ظهر مستقيم، وأمسك مقدمة البار باليد اليمنى ومؤخرته باليد اليسرى، على مسافتين متساويتين من جسمك.","قف باستقامة بالوزن، والقدمان بعرض الكتفين وأصابعهما للخارج قليلًا.","انزل في سكوات بظهر مستقيم ورأس مرفوع حتى يصبح الفخذان موازيين للأرض، وأنت تشهق.","ادفع بقدميك لتصعد إلى البداية. الذراعان مجرد خطّافين، والرفع بالفخذين."]],"Jerk_Balance":["توازن الجيرك",["تمرين يعلّمك النزول بما يكفي في الجيرك ويصحّح الرجوع للخلف. ابدأ والبار على مقدمة الكتفين، والجذع مستقيم والقدمان مفتوحتان قليلًا.","انزل بالركبتين والجذع عمودي، ثم ادفع بقوة للأعلى باستخدام الاندفاع لا الذراعين.","ثبّت القدم الخلفية واستخدمها لتدفع جسمك للأمام إلى وضعية مفتوحة كاملة أثناء رفع الوزن. ثم قف والوزن فوق رأسك."]],"Jerk_Dip_Squat":["نزول الجيرك",["يقوّي هذا التمرين مرحلة النزول في الجيرك. ابدأ والبار على مقدمة الكتفين ملامسًا الرقبة برفق، والقدمان تحت الحوض.","والجذع عمودي، انزل بثني الركبتين للأمام دون دفع الحوض للخلف، نزولًا غير مبالغ فيه. ثم ادفع بقوة بالقدمين لتعود إلى البداية."]],"Jogging_Treadmill":["هرولة على جهاز المشي",["اصعد على جهاز المشي واختر البرنامج: يدوي أو جاهز. يمكنك إدخال عمرك ووزنك لتقدير السعرات، وتغيير الميل لتغيير الشدة.","جهاز المشي مريح ومفيد للقلب وأخف على المفاصل من الهرولة في الخارج. حافظ على وضعية جيدة، وأمسك المقابض فقط عند الحاجة كالنزول أو قياس النبض."]],"Keg_Load":["رفع البرميل",["ضع البراميل على مسافة من منصة التحميل (عادةً 10–15 مترًا).","أمسك المقبض القريب للبرميل الأول وأمِله على جنبه لتمسك حافة قاعدته المقابلة، وارفعه إلى صدرك.","كلما رفعته أعلى تحركت أسرع. لا يُسمح عادةً بوضعه على الكتف. امشِ بسرعة إلى المنصة وحمّله عليها بفرد الحوض والركبتين والكاحلين لرفعه لأعلى ما يمكن.","عد لأخذ البرميل التالي وكرّر حتى النهاية."]],"Kettlebell_Arnold_Press":["ضغط أرنولد بالكيتلبل",["ارفع الكيتلبل إلى كتفك (كلين) بفرد الرجلين والحوض، والكف للداخل.","والنظر للأمام، اضغط الكيتلبل للأعلى فوق رأسك مع لفّ الرسغ لتصبح الكف للأمام في الأعلى.","أعده إلى البداية والكف للداخل."]],"Kettlebell_Dead_Clean":["كلين ميت بالكيتلبل",["ضع الكيتلبل بين قدميك. ادفع مؤخرتك للخلف وانظر للأمام.","ارفع الكيتلبل من الأرض إلى كتفك (كلين) بفرد الرجلين والحوض مع لفّ الرسغ.","أنزله إلى الأرض مع ظهر مستقيم ومؤخرة للخلف."]],"Kettlebell_Figure_8":["الرقم 8 بالكيتلبل",["ضع كيتلبلًا بين رجليك بوقفة أعرض من الكتفين. انحنِ بدفع مؤخرتك للخلف مع ظهر مستقيم.","التقط الكيتلبل ومرّره إلى يدك الأخرى بين رجليك، واليد المستقبلة تأتي من خلف الرجل، على شكل الرقم 8. تابع ذهابًا وإيابًا."]],"Kettlebell_Hang_Clean":["كلين بالكيتلبل من التعليق",["ضع الكيتلبل بين قدميك. ادفع مؤخرتك للخلف وانظر للأمام.","ارفع الكيتلبل إلى كتفك (كلين) بفرد الرجلين والحوض مع لفّ الرسغ.","أنزله إلى وضع التعليق بين رجليك مع إبقاء الشد على خلفي الفخذ، والرأس مرفوع دائمًا."]],"Kettlebell_One-Legged_Deadlift":["ديدلفت برجل واحدة بالكيتلبل",["أمسك كيتلبلًا بيد واحدة، وقف على الرجل من الجهة نفسها.","مع ثني بسيط في تلك الركبة، انحنِ من الحوض كديدلفت بأرجل مستقيمة، ومدّ رجلك الحرة للخلف للتوازن.","انزل حتى يصبح جذعك موازيًا للأرض، ثم عد إلى الوقوف. أكمل التكرارات ثم بدّل الجهة."]],"Kettlebell_Pass_Between_The_Legs":["تمرير الكيتلبل بين الرجلين",["ضع كيتلبلًا بين رجليك بوقفة مريحة. انحنِ بدفع مؤخرتك للخلف مع ظهر مستقيم.","التقط الكيتلبل ومرّره إلى يدك الأخرى بين رجليك على شكل حرف W. تابع ذهابًا وإيابًا."]],"Kettlebell_Pirate_Ships":["سفينة القراصنة بالكيتلبل",["بوقفة واسعة، أمسك كيتلبلًا بيديك متدليًا أمام الخصر والذراعان ممدودتان. هذه وضعية البداية.","التفت إلى جهة وأرجح الكيتلبل حتى مستوى الرأس، وتوقف لحظة.","دعه ينزل وأنت تلتفت إلى الجهة الأخرى، وارفعه مجددًا حتى مستوى الرأس. تابع بالتبادل."]],"Kettlebell_Pistol_Squat":["سكوات المسدس بالكيتلبل (برجل واحدة)",["أمسك كيتلبلًا بيديك من قرنيه. ارفع رجلًا عن الأرض وانزل على الأخرى.","انزل بثني الركبة والجلوس بالحوض للخلف، والكيتلبل مرفوع أمامك.","اثبت ثانية في الأسفل، ثم اصعد بالدفع بالكعب والرأس والصدر مرفوعان.","انزل مجددًا وكرّر."]],"Kettlebell_Seated_Press":["ضغط أكتاف بالكيتلبل جلوسًا",["اجلس على الأرض وباعد رجليك براحة.","ارفع كيتلبلًا إلى كتفك.","اضغطه للأعلى حتى تنقفل ذراعك فوق رأسك، ثم عد إلى البداية."]],"Kettlebell_Seesaw_Press":["ضغط أرجوحي بالكيتلبل",["ارفع كيتلبلين إلى كتفيك.","اضغط واحدًا فوق رأسك.","أنزله واضغط الآخر فورًا. كرّر العدد نفسه للجهتين."]],"Kettlebell_Sumo_High_Pull":["سحب عالٍ سومو بالكيتلبل",["ضع كيتلبلًا على الأرض بين قدميك بوقفة واسعة وأمسكه بيديك. ادفع حوضك للخلف لأقصى حد والركبتان مثنيتان، والصدر والرأس مرفوعان. هذه وضعية البداية.","افرد الحوض والركبتين وفي الوقت نفسه اسحب الكيتلبل حتى كتفيك مع رفع المرفقين. اعكس الحركة لتعود إلى البداية."]],"Kettlebell_Thruster":["ثرستر بالكيتلبل",["ارفع كيتلبلين إلى كتفيك (كلين) بفرد الرجلين والحوض مع لفّ الرسغين. هذه وضعية البداية.","انزل في سكوات بثني الحوض والركبتين، والظهر مستقيم، لأعمق ما تستطيع.","في الأسفل اصعد بقوة بالدفع بكعبيك، وفي الوقت نفسه اضغط الكيتلبلين فوق رأسك مستفيدًا من اندفاع السكوات.","أعد الوزن إلى كتفيك مع بداية التكرار التالي."]],"Kettlebell_Turkish_Get-Up_Lunge_style":["النهوض التركي بالكيتلبل (أسلوب اللانج)",["استلقِ على ظهرك واضغط كيتلبلًا للأعلى بفرد المرفق، واثنِ الركبة في جهة الكيتلبل.","والكيتلبل مقفل فوقك دائمًا، دُر نحو الجهة المعاكسة واستعن باليد الحرة لتجلس، ثم انتقل إلى ركبة واحدة (وضعية اللانج).","وعيناك على الكيتلبل، قف ببطء. ثم اعكس الحركة إلى البداية وكرّر."]],"Kettlebell_Turkish_Get-Up_Squat_style":["النهوض التركي بالكيتلبل (أسلوب السكوات)",["استلقِ على ظهرك واضغط كيتلبلًا للأعلى بفرد المرفق، واثنِ الركبة في جهة الكيتلبل.","والكيتلبل مقفل فوقك دائمًا، دُر نحو الجهة المعاكسة واستعن باليد الحرة لتجلس.","انتقل إلى قدميك في وضعية سكوات، ثم قف ببطء وعيناك على الكيتلبل. اعكس الحركة إلى البداية وكرّر."]],"Kettlebell_Windmill":["طاحونة الهواء بالكيتلبل",["ضع كيتلبلًا أمام قدمك الأمامية، وارفعه فوق رأسك باليد المعاكسة: كلين إلى الكتف بفرد الرجلين والحوض مع لفّ الرسغ، ثم ضغط بفرد المرفق.","والكيتلبل مقفل فوقك دائمًا، ادفع مؤخرتك باتجاهه، والقدمان بزاوية 45° بعيدًا عن جهته. انحنِ من الحوض إلى الجانب ببطء حتى تلمس الأرض باليد الحرة، وعيناك على الكيتلبل دائمًا.","توقف ثانية، ثم عد إلى البداية."]],"Kipping_Muscle_Up":["مسل أب بالتأرجح (كيبينغ)",["أمسك الحلقات بقبضة كاذبة (قاعدة الكف فوق الحلقة).","ابدأ بأرجحة رجليك للخلف قليلًا.","ثم أرجحهما للأمام وللأعلى بقوة مع سحب الذقن والصدر للخلف، واسحب نفسك بالذراعين. في أعلى العقلة اسحب الحلقات إلى إبطيك وأدِر كتفيك للأمام والمرفقان للخلف، لتنتقل إلى وضعية المتوازي.","بتحكّم وثبات، افرد المرفقين لتكمل الحركة.","انزل إلى الأرض بحذر."]],"Knee_Across_The_Body":["الركبة عبر الجسم",["استلقِ على الأرض والرجل اليمنى ممدودة. اثنِ اليسرى وأنزلها عبر جسمك، واضغط الركبة نحو الأرض بيدك اليمنى (لا يلزم أن تلمس الأرض إذا كنت مشدودًا).","ضع ذراعك اليسرى بجانبك براحة وأدر رأسك إلى اليسار. دع عصعصك ينزل نحو الأرض وصدرك يتجه بالاتجاه المعاكس لإطالة أسفل الظهر. بدّل الجهة."]],"Knee_Circles":["دوائر الركبتين",["قف والرجلان معًا واليدان على الخصر.","حرّك ركبتيك في دائرة وتنفّس بشكل طبيعي.","كرّر العدد المطلوب، ثم بالاتجاه المعاكس."]],"Knee_Hip_Raise_On_Parallel_Bars":["رفع الركبتين على المتوازي",["ضع ساعديك على مساند جهاز رفع الرجلين (كابتن تشير) وأمسك المقابض، والذراعان مثنيتان 90°.","الجذع مستقيم وأسفل الظهر ملتصق بالمسند، والرجلان ممدودتان نحو الأرض. هذه وضعية البداية.","ازفر وارفع رجليك (ممدودتين أو مثنيتين للأسهل) حتى تصبحا موازيتين للأرض تقريبًا، واثبت ثانية. لا تؤرجح جسمك.","انزل ببطء وأنت تشهق."]],"Knee_Tuck_Jump":["قفز مع ضم الركبتين",["قف بوضعية مرتاحة والركبتان مثنيتان قليلًا، واليدان أمامك بمستوى الصدر والكفّان للأسفل. هذه وضعية البداية.","انزل بسرعة في ربع سكوات ثم انطلق للأعلى فورًا، وارفع ركبتيك نحو صدرك محاولًا لمس كفّيك.","اقفز لأعلى ما تستطيع، ثم اهبط بفرد رجليك وامتص الصدمة بثني الركبتين."]],"Kneeling_Arm_Drill":["تمرين الذراعين على الركبتين",["تمرين يحسّن حركة الذراعين أثناء الركض. اركع والقدم اليسرى أمامك والركبة اليمنى على الأرض، واضغط بالكعب الأمامي لتنشيط الأرداف وخلفي الفخذ.","حرّك ذراعيك بأرجحات طويلة كالبندول، ثم ضيّق الزاوية كما في الهرولة، ثم الركض، ثم العدو السريع.","عندما تتجاوز يداك الحوض، سرّعهما للأمام بأقصى سرعة.","بدّل الركبة وكرّر."]],"Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists":["كرنش بالكيبل على الركبتين مع التفاف للجانبين",["ركّب حبلًا على الكيبل العلوي وضع حصيرة أمامه.","أمسك الحبل بيديك واركع على بعد 60 سم تقريبًا من الجهاز.","ضع الحبل خلف رأسك ويداك بجانب أذنيك.","ثبّت يديك، واعصر البطن لتسحب الحبل للأسفل في حركة كرنش حتى يصل مرفقاك إلى ركبتيك. توقف لحظة، ثم اصعد ببطء.","في التكرار التالي، عند منتصف النزول لفّ أحد مرفقيك نحو الركبة المعاكسة، ثم اصعد ببطء.","تابع بالتبادل بين الجهتين."]],"Kneeling_Cable_Triceps_Extension":["تراي بالكيبل على الركبتين",["ضع بنشًا بالعرض أمام الكيبل العلوي.","أمسك البار المستقيم فوق رأسك بقبضة علوية والمسافة بين اليدين نحو 15 سم.","اركع وظهرك للجهاز، وضع رأسك وخلف عضديك على البنش، والمرفقان مثنيان والساعدان نحو الكيبل. هذه وضعية البداية.","مع إبقاء العضدين قريبين من رأسك، ادفع البار للأمام في نصف دائرة حتى تستقيم ذراعاك موازيتين للأرض. اعصر التراي ثانية وأنت تزفر.","عد ببطء وأنت تشهق."]],"Kneeling_Forearm_Stretch":["إطالة الساعد على الركبتين",["اركع على حصيرة والكفّان على الأرض والأصابع تشير للخلف نحو ركبتيك.","مِل ببطء للخلف والكفّان على الأرض حتى تشعر بإطالة في الرسغين والساعدين. اثبت 20–30 ثانية."]],"Kneeling_High_Pulley_Row":["تجديف بالكيبل العلوي على الركبتين",["اختر الوزن على كيبل أعلى من رأسك وركّب عليه حبلًا. اركع على بعد خطوة وأمسك الحبل أمامك والذراعان ممدودتان. هذه وضعية البداية.","اثنِ المرفقين واسحب لوحي الكتف للخلف بالكامل، ساحبًا الحبل نحو أعلى صدرك والمرفقان للخارج.","توقف لحظة، ثم عد ببطء إلى البداية."]],"Kneeling_Hip_Flexor":["إطالة ثانيات الورك على الركبتين",["اركع على حصيرة، ثم ضع قدمك اليمنى أمامك على الأرض، ومدّ الرجل اليسرى خلفك وظهر قدمها على الأرض.","انقل وزنك للأمام حتى تشعر بإطالة في الورك. اثبت 15 ثانية ثم بدّل الجهة."]],"Kneeling_Jump_Squat":["سكوات بالقفز من الركبتين",["اركع على الأرض والبار على أعلى ظهرك (أو بوزن الجسم فقط). يمكن أداؤه داخل القفص لتسهيل أخذ البار.","اجلس بحوضك للخلف حتى تلمس مؤخرتك قدميك، والرأس والصدر مرفوعان.","انطلق بقوة بحوضك لتهبط بقدميك مسطحتين على الأرض.","أكمل السكوات بالدفع بكعبيك وفرد الركبتين حتى تقف."]],"Kneeling_Single-Arm_High_Pulley_Row":["تجديف بالكيبل العلوي بيد واحدة على الركبتين",["ركّب مقبضًا واحدًا على الكيبل العلوي واختر الوزن.","اركع أمام الجهاز وأمسك المقبض بيد واحدة والذراع ممدودة. هذه وضعية البداية.","ابدأ والكف للأمام، واسحب الوزن نحو جذعك بثني المرفق وسحب لوح الكتف للخلف، مع لفّ الرسغ بحيث تصبح الكف نحوك في النهاية.","توقف لحظة، ثم عد إلى البداية."]],"Kneeling_Squat":["سكوات على الركبتين",["اضبط البار على الارتفاع المناسب في القفص. اركع خلفه (يمكن وضع حصيرة تحت ركبتيك)، وادخل تحته وضعه على أعلى ظهرك مع ضمّ لوحي الكتف، ثم أخرجه من الحامل.","والنظر للأمام، اجلس بمؤخرتك للخلف حتى تلمس سمانتيك.","اعكس الحركة لتعود بجذعك إلى الوضع المستقيم."]],"Landmine_180s":["لاندماين 180 درجة",["ثبّت طرف البار في قاعدة لاندماين أو في زاوية بشكل آمن، وحمّله بالوزن المناسب.","ارفع الطرف الآخر من الأرض إلى مستوى الكتفين بيديك والذراعان ممدودتان أمامك، بوقفة واسعة. هذه وضعية البداية.","لفّ جذعك وحوضك وأنت تؤرجح الوزن نزولًا إلى جهة واحدة، والذراعان ممدودتان طوال الوقت.","اعكس الحركة لتؤرجح الوزن إلى الجهة الأخرى، وتابع بالتبادل."]],"Landmine_Linear_Jammer":["دفع اللاندماين (جامر)",["ثبّت طرف البار في قاعدة لاندماين أو في زاوية بشكل آمن، حمّله بالوزن المناسب وركّب المقبض.","ارفع البار من الأرض حتى تصبح المقابض عند كتفيك. هذه وضعية البداية.","بوقفة رياضية، انزل في سكوات بدفع حوضك للخلف والذراعان مثنيتان.","اعكس الحركة بقوة بفرد الحوض والركبتين والكاحلين، مع مدّ المرفقين حتى تستقيم ذراعاك، بشكل انفجاري.","عد إلى البداية."]],"Lateral_Bound":["وثب جانبي",["اتخذ وضعية نصف سكوات وجانبك لاتجاه الحركة. هذه وضعية البداية.","حرّك الرجل الأمامية للداخل قليلًا وأنت تنقل وزنك إلى الرجل الخارجية.","ادفع فورًا وافرد جسمك لتثب إلى الجانب لأبعد مسافة.","عند الهبوط ادفع فورًا في الاتجاه المعاكس لتعود. تابع ذهابًا وإيابًا."]],"Lateral_Box_Jump":["قفز جانبي على الصندوق",["قف براحة وبجانبك صندوق منخفض. هذه وضعية البداية.","انزل بسرعة في ربع سكوات ثم اعكس الاتجاه فورًا لتقفز للأعلى وللجانب.","ارفع ركبتيك بما يكفي لتتجاوز قدماك الصندوق.","اهبط في منتصف الصندوق وامتص الصدمة برجليك.","اقفز بحذر إلى الجهة الأخرى، وتابع ذهابًا وإيابًا."]],"Lateral_Cone_Hops":["نطّ جانبي فوق الأقماع",["ضع عدة أقماع في صف على مسافات قصيرة.","قف عند طرف الصف وجانبك لاتجاه الحركة. هذه وضعية البداية.","انزل قليلًا بالركبتين ثم انطلق فورًا لتقفز للأعلى وللجانب فوق القمع.","امتص الصدمة برجليك وارتد فورًا إلى القفزة التالية حتى نهاية الصف."]],"Lateral_Raise_-_With_Bands":["رفرفة جانبية بالمطاط",["قف على مطاط التمارين بحيث يبدأ الشد والذراعان ممدودتان. أمسك المقبضين بجانب فخذيك، والذراعان ممدودتان مع ثني بسيط والظهر مستقيم.","ارفع المقبضين جانبيًا بالكتف الجانبي وأنت تزفر، حتى أعلى من الموازاة قليلًا. مِل يدك قليلًا كأنك تصبّ الماء، والجذع ثابت، واثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Latissimus_Dorsi-SMR":["تدليك الظهر (لاتس) بالفوم رولر",["استلقِ على الأرض وضع الفوم رولر تحت ظهرك على جانب واحد خلف الإبط مباشرة. هذه وضعية البداية.","أبقِ ذراع الجهة المستهدفة خلفك وللجانب، وانقل وزنك على عضلة الظهر (اللاتس) والجزء العلوي مرفوع عن الأرض. اثبت 10–30 ثانية ثم بدّل الجهة."]],"Leg-Over_Floor_Press":["ضغط على الأرض والرجل فوق الأخرى",["استلقِ على الأرض والكيتلبل على صدرك ممسوكًا من المقبض. ضع رجل جهة العمل فوق الرجل الأخرى، ومدّ ذراعك الحرة جانبًا للثبات.","اضغط الكيتلبل للأعلى حتى تنقفل ذراعك.","أنزله حتى يلمس المرفق الأرض والكيتلبل فوق المرفق. أكمل التكرارات ثم بدّل الجهة."]],"Leg-Up_Hamstring_Stretch":["إطالة خلفي الفخذ والرجل مرفوعة",["استلقِ على ظهرك، اثنِ ركبة وضع القدم على الأرض لتثبيت الظهر.","ارفع الرجل الأخرى للأعلى. إن كنت مشدودًا لن تستطيع فردها بالكامل، وهذا طبيعي. افرد الركبة بحيث يتجه باطن القدم نحو السقف قدر الإمكان.","افرد الرجل ببطء قدر الإمكان واسحبها نحو أنفك. بدّل الجهة."]],"Leg_Extensions":["أمامي جهاز (مد الرجلين)",["اختر الوزن واجلس على الجهاز ورجلاك تحت المسند (عند أسفل الساق فوق القدم مباشرة)، وأمسك المقابض الجانبية. الزاوية بين الفخذ والساق 90°، ولا تنزل أقل منها حفاظًا على الركبة.","مدّ رجليك لأقصى حد بأمامي الفخذ وأنت تزفر، وباقي الجسم ثابت على المقعد. اثبت ثانية.","أنزل الوزن ببطء وأنت تشهق، دون تجاوز زاوية 90°."]],"Leg_Lift":["رفع الرجل",["قف باستقامة والقدمان متجاورتان، وأمسك شيئًا ثابتًا كقفص السكوات أو كرسي للتوازن.","بوزن على الكاحل أو بدونه، ارفع رجلًا واحدة خلفك بثني الركبة، والرجل الأخرى مستقيمة، وأنت تزفر.","أنزلها ببطء وأنت تشهق.","أكمل التكرارات ثم بدّل الرجل."]],"Leg_Press":["مكبس الأرجل (ليغ بريس)",["اجلس على مكبس الأرجل وضع قدميك على المنصة بعرض الكتفين.","حرّر أذرع الأمان وادفع المنصة حتى تمتد رجلاك دون قفل الركبتين. هذه وضعية البداية.","اشهق وأنزل المنصة ببطء حتى تصبح الزاوية بين الفخذ والساق 90°.","ادفع بكعبيك وبأمامي الفخذ لتعود إلى البداية وأنت تزفر.","عند الانتهاء أعد أذرع الأمان إلى مكانها جيدًا قبل أن تنزل عن الجهاز."]],"Leg_Pull-In":["سحب الركبتين",["استلقِ على حصيرة والرجلان ممدودتان، ويداك بجانبك والكفّان للأسفل أو تحت مؤخرتك. هذه وضعية البداية.","اثنِ ركبتيك واسحب فخذيك نحو بطنك وأنت تزفر، حتى تصل ركبتاك إلى مستوى الصدر تقريبًا. اعصر البطن واثبت ثانية. الساقان موازيتان للأرض دائمًا.","عد إلى البداية وأنت تشهق."]],"Leverage_Chest_Press":["جهاز ضغط الصدر",["ضع الوزن المناسب واضبط المقعد على طولك، بحيث تكون المقابض عند أسفل أو منتصف الصدر في البداية.","الصدر والرأس مرفوعان ولوحا الكتف مسحوبان للخلف. هذه وضعية البداية.","اضغط المقابض للأمام بفرد المرفقين.","توقف لحظة، ثم أعد الوزن حتى فوق نقطة البداية بقليل، دون إنزاله إلى المكدّس حتى نهاية المجموعة لتبقى العضلة تحت الشد."]],"Leverage_Deadlift":["جهاز الديدلفت",["ضع الوزن المناسب وقف بين المقابض مباشرة. أمسك المقابض السفلية، وأنزل حوضك وأنت تأخذ نفسًا. انظر للأمام وارفع صدرك. هذه وضعية البداية.","ادفع الأرض بكعبيك وافرد حوضك وركبتيك حتى تقف باستقامة، والذراعان مستقيمتان.","أنزل الوزن بتحكّم إلى البداية."]],"Leverage_Decline_Chest_Press":["جهاز ضغط الصدر المقلوب",["ضع الوزن المناسب واضبط المقعد بحيث تكون المقابض عند أسفل الصدر في البداية. الصدر والرأس مرفوعان ولوحا الكتف مسحوبان للخلف.","اضغط المقابض للأمام بفرد المرفقين.","توقف لحظة، ثم أعد الوزن حتى فوق نقطة البداية بقليل، دون إنزاله إلى المكدّس حتى نهاية المجموعة."]],"Leverage_High_Row":["جهاز التجديف العالي",["ضع الوزن المناسب واضبط المقعد بحيث تصل إلى المقابض فوقك بالكاد، واضبط مسند الركبتين ليثبّتك. أمسك المقابض بقبضة علوية. هذه وضعية البداية.","اسحب المقابض نحو جذعك مع سحب لوحي الكتف للخلف وثني المرفقين.","توقف في الأسفل، ثم أعد المقابض ببطء. لا تُرجع الوزن إلى المكدّس بين التكرارات لتبقى العضلة تحت الشد."]],"Leverage_Incline_Chest_Press":["جهاز ضغط الصدر المائل",["ضع الوزن المناسب واضبط المقعد بحيث تكون المقابض عند أعلى الصدر في البداية. الصدر والرأس مرفوعان ولوحا الكتف مسحوبان للخلف.","اضغط المقابض للأمام بفرد المرفقين.","توقف لحظة، ثم أعد الوزن حتى فوق نقطة البداية بقليل، دون إنزاله إلى المكدّس حتى نهاية المجموعة."]],"Leverage_Iso_Row":["جهاز التجديف (آيزو رو)",["ضع الوزن المناسب واضبط المقعد بحيث تكون المقابض على مستوى الصدر. أمسكها بقبضة محايدة أو علوية. هذه وضعية البداية.","اسحب المقابض نحو جذعك مع سحب لوحي الكتف للخلف وثني المرفقين.","توقف في نهاية السحب، ثم أعد المقابض ببطء. لا تُرجع الوزن إلى المكدّس بين التكرارات."]],"Leverage_Shoulder_Press":["جهاز ضغط الأكتاف",["ضع الوزن المناسب واضبط المقعد بحيث تكون المقابض عند أعلى الكتفين في البداية. الصدر والرأس مرفوعان، والقبضة علوية. هذه وضعية البداية.","اضغط المقابض للأعلى بفرد المرفقين.","توقف لحظة في الأعلى، ثم أعد الوزن حتى فوق نقطة البداية بقليل، دون إنزاله إلى المكدّس حتى نهاية المجموعة."]],"Leverage_Shrug":["جهاز الترابيس (شراغ)",["ضع الوزن المناسب وقف بين المقابض مباشرة.","أمسك المقابض العلوية، وأنزل حوضك وأنت تأخذ نفسًا. انظر للأمام وارفع صدرك.","ادفع الأرض بكعبيك وافرد حوضك وركبتيك حتى تقف، والذراعان مستقيمتان والكتفان للخلف. هذه وضعية البداية.","ارفع الوزن برفع كتفيك نحو أذنيك، للأعلى وللأسفل بخط مستقيم.","توقف في الأعلى، ثم أنزل الوزن إلى البداية."]],"Linear_3-Part_Start_Technique":["تقنية الانطلاق بثلاث مراحل",["تمرين يساعدك على الانطلاق السريع من الثبات. قف على خط، وضع أصابع قدمك اليسرى بجانب كاحلك الأيمن، والقدم اليمنى خلف اليسرى بنحو 10–15 سم.","ضع يدك اليمنى على الخط، وقرّب أنفك من ركبتك اليسرى.","انزل وأنت تميل للأمام، والرأس أخفض من الحوض والوزن على الرجل اليسرى. هذه وضعية البداية.","ارفع يدك اليسرى موازية للأرض للخلف، وانطلق بقوة عندما تكون جاهزًا."]],"Linear_Acceleration_Wall_Drill":["تمرين التسارع على الحائط",["مِل على حائط بزاوية نحو 45°، والقدمان معًا والأرداف مشدودة.","ارفع ركبتك اليمنى بسرعة، توقف، ثم اضرب بها الأرض مستقيمًا للأسفل.","بدّل الرجل: ارفع الركبة الأخرى ثم اضرب الأرض.","كرّر مرة أخرى باليمنى، وفور ملامستها الأرض بدّل بين الرجلين بأسرع ما يمكن."]],"Linear_Depth_Jump":["قفز عميق مستقيم",["تحتاج صندوقين أو بنشين على مسافة قصيرة من بعض. قف على صندوق مقابل الآخر.","انزل برفق إلى الأرض بين الصندوقين مع ثني الركبتين والحوض.","انطلق فورًا بفرد الحوض والركبتين والكاحلين لتقفز على الصندوق الآخر.","اهبط بنعومة وامتص الصدمة برجليك."]],"Log_Lift":["رفع جذع الشجرة (لوغ)",["قف وجذع الشجرة (اللوغ) أمامك. أمسك المقابض واسحبه لأعلى ما يمكن نحو صدرك وأنت منحنٍ، ثم افرد الحوض والركبتين لتكمل رفعه إلى صدرك.","أرجع رأسك وانظر للأعلى ليصنع صدرك رفًا للوغ. انزل قليلًا بالركبتين ثم اعكس لتدفعه للأعلى، وافرد مرفقيك لتضغطه فوق رأسك. أدخل رأسك للأمام تحته في كل تكرار.","كرّر بأكبر عدد ممكن، وأنزله إلى الأرض بتحكّم."]],"London_Bridges":["جسور لندن (حبال)",["علّق حبل تسلق على عارضة عالية، وتحته بار سميث مثبت بالأمان لا يتحرك (أو صندوق ثابت).","قف على البار مستعينًا بالحبل للتوازن. هذه وضعية البداية.","والجسم مستقيم، مِل للخلف وانزل بتحريك يديك على الحبل واحدة بعد الأخرى حتى يصبح جسمك موازيًا للأرض.","والجسم مستقيم، عد بتحريك يديك للأعلى بالطريقة نفسها."]],"Looking_At_Ceiling":["النظر إلى السقف (إطالة الرقبة)",["اركع على الأرض وأمسك كعبيك بيديك.","ارفع حوضك للأمام وأرجع رأسك لتنظر إلى السقف، فيتقوّس ظهرك."]],"Low_Cable_Crossover":["تقاطع الكيبل من الأسفل",["اضبط البكرتين في الأسفل، اختر الوزن وأمسك مقبضًا بكل يد.","تقدّم خطوة حتى يشتد الكيبل. الكفّان للأمام واليدان تحت مستوى الخصر والذراعان مستقيمتان. هذه وضعية البداية.","مع ثني بسيط في الذراعين، اسحب يديك للأعلى ونحو منتصف جسمك حتى تلتقيا أمام صدرك والكفّان للأعلى.","توقف لحظة، ثم أعد ذراعيك إلى البداية."]],"Low_Cable_Triceps_Extension":["تراي بالكيبل السفلي",["اختر الوزن واستلقِ على ظهرك على مقعد جهاز التجديف المركّب عليه حبل، ورأسك نحو الحبل.","أمسك طرفي الحبل من الخارج بقبضة محايدة.","المرفقان مثنيان 90° والعضدان عموديان على جذعك ويشيران نحو السقف، والمرفقان للداخل. هذه وضعية البداية.","ازفر ومدّ ساعديك حتى تستقيم ذراعاك عموديًا. العضدان ثابتان. اعصر التراي ثانية.","اشهق وعد ببطء إلى البداية."]],"Low_Pulley_Row_To_Neck":["سحب بالكيبل السفلي إلى الرقبة",["اجلس على جهاز التجديف بالكيبل السفلي المركّب عليه حبل.","أمسك طرفي الحبل بقبضة علوية، والظهر مستقيم شبه عمودي والركبتان مثنيتان قليلًا، والذراعان ممدودتان أمامك.","ثبّت جذعك، وارفع مرفقيك واسحب الحبل نحو رقبتك وأنت تزفر، والعضدان موازيان للأرض، حتى تقترب يداك من أذنيك والمرفقان للخارج.","اثبت ثانية، ثم عد ببطء وأنت تشهق. الجذع لا يتحرك أبدًا."]],"Lower_Back-SMR":["تدليك أسفل الظهر بالفوم رولر",["اجلس وضع الفوم رولر تحت أسفل ظهرك، واعقد ذراعيك أمامك. هذه وضعية البداية.","ارفع حوضك عن الأرض ومِل للخلف والوزن على أسفل الظهر، ثم انقل وزنك قليلًا إلى جانب واحد بعيدًا عن العمود الفقري. تدحرج وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالجهة الأخرى."]],"Lower_Back_Curl":["ثني أسفل الظهر",["انبطح على بطنك والذراعان ممدودتان للجانبين. هذه وضعية البداية.","بعضلات أسفل الظهر، افرد ظهرك وارفع صدرك عن الأرض، دون الدفع بالذراعين. الرأس مرفوع. كرّر 10–20 مرة."]],"Lunge_Pass_Through":["لانج مع تمرير الكيتلبل",["قف باستقامة وكيتلبل في يدك اليمنى. هذه وضعية البداية.","اخطُ بقدمك اليسرى للأمام وانزل بثني الحوض والركبة، والجذع مستقيم، حتى تكاد الركبة الخلفية تلمس الأرض.","أثناء النزول مرّر الكيتلبل من تحت رجلك الأمامية إلى يدك الأخرى.","ادفع بكعب القدم الأمامية لتعود إلى البداية. كرّر بالتبادل بين الرجلين."]],"Lunge_Sprint":["لانج مع عدو",["اضبط البار على جهاز السميث على الارتفاع المناسب وضعه على أعلى ظهرك. حرّره وباعد بين قدميك: واحدة للأمام وأخرى للخلف. هذه وضعية البداية.","انزل حتى تكاد ركبتك الخلفية تلمس الأرض.","في الأسفل اعكس الاتجاه فورًا: ادفع بقوة بكعب القدم الأمامية مع ضغط خفيف من الخلفية، واقفز لتبدّل وضع الرجلين."]],"Lying_Bent_Leg_Groin":["إطالة الفخذ الداخلي مستلقيًا والرجلان مثنيتان",["استلقِ على ظهرك والركبتان مثنيتان وباطنا القدمين متلاصقان، ويمسك زميلك ركبتيك. هذه وضعية البداية.","حاول ضم ركبتيك بينما يمنع زميلك أي حركة.","بعد 10–20 ثانية أرخِ عضلاتك بينما يدفع زميلك ركبتيك برفق نحو الأرض. أخبره عندما تكفي الإطالة."]],"Lying_Cable_Curl":["باي بالكيبل مستلقيًا",["أمسك البار المستقيم أو بار EZ المركّب على الكيبل السفلي بقبضة سفلية بعرض الكتفين.","استلقِ على ظهرك على حصيرة أمام الجهاز، وقدماك على إطار الجهاز ورجلاك مستقيمتان.","الذراعان ممدودتان والمرفقان قريبان من الجسم مع ثني بسيط. هذه وضعية البداية.","ثبّت العضدين واثنِ البار ببطء نحو صدرك وأنت تزفر وتعصر الباي.","اعصر ثانية في الأعلى، ثم عد ببطء."]],"Lying_Cambered_Barbell_Row":["تجديف بالبار المقوّس منبطحًا",["ضع بارًا مقوّسًا تحت بنش التمارين.","انبطح على البنش وأمسك البار بقبضة علوية أعرض من الكتفين. هذه وضعية البداية.","ازفر واسحب البار والمرفقان قريبان من الجسم: نحو صدرك للتركيز على منتصف الظهر، أو نحو بطنك للتركيز على اللاتس.","اثبت ثانية في الأعلى، ثم انزل ببطء وأنت تشهق."]],"Lying_Close-Grip_Bar_Curl_On_High_Pulley":["باي بقبضة ضيقة بالكيبل العلوي مستلقيًا",["ضع بنشًا مستويًا أمام الكيبل العلوي أو جهاز السحب الأمامي.","أمسك البار المستقيم بقبضة سفلية بعرض الكتفين.","استلقِ على ظهرك ورأسك عند طرف البنش.","مدّ ذراعيك فوق كتفيك مباشرة، عموديتين على الجذع، والمرفقان للداخل. هذه وضعية البداية.","ازفر واثنِ البار في نصف دائرة حتى يلمس ذقنك، واعصر الباي ثانية. الساعدان فقط يتحركان.","عد ببطء إلى البداية."]],"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head":["تراي بالبار خلف الرأس مستلقيًا بقبضة ضيقة",["أمسك بارًا أو بار EZ بقبضة علوية (بعرض الكتفين للبار، أو من المقبض الداخلي لبار EZ)، واستلقِ على بنش مستوٍ ورأسك قرب طرفه.","مدّ ذراعيك أمامك وحرّك البار في نصف دائرة والذراعان ممدودتان حتى يصبح فوق رأسك والذراعان موازيتان للأرض. المرفقان للداخل دائمًا.","اشهق وأنزل البار بثني المرفقين مع ثبات العضدين حتى يصبح الساعدان عموديين على الأرض.","ازفر وادفع البار في نصف دائرة إلى البداية، واعصر التراي ثانية. الساعدان فقط يتحركان."]],"Lying_Close-Grip_Barbell_Triceps_Press_To_Chin":["تراي بالبار إلى الذقن مستلقيًا بقبضة ضيقة",["أمسك بارًا أو بار EZ بقبضة علوية، واستلقِ على بنش مستوٍ ورأسك خارج طرفه.","مدّ ذراعيك فوق صدرك عموديتين على جذعك. هذه وضعية البداية.","اشهق وأنزل البار في نصف دائرة بثني المرفقين، مع ثبات العضدين والمرفقين للداخل، حتى يلامس ذقنك برفق.","ازفر وادفعه في نصف دائرة إلى البداية، واعصر التراي ثانية."]],"Lying_Crossover":["تقاطع مستلقيًا (إطالة)",["استلقِ على ظهرك والرجلان ممدودتان.","اعبر برجل مثنية فوق جسمك محاولًا لمس الأرض بالركبة. يجلس زميلك بجانبك ويثبّت كتفك بيد ويتحكّم بالرجل باليد الأخرى. هذه وضعية البداية.","حاول رفع الركبة عن الأرض بينما يمنع زميلك أي حركة.","بعد 10–20 ثانية أرخِ الرجل بينما يضغط زميلك الركبة برفق نحو الأرض. كرّر بالجهة الأخرى."]],"Lying_Dumbbell_Tricep_Extension":["تراي بالدمبل مستلقيًا",["استلقِ على بنش مستوٍ ودمبلان فوقك، والذراعان ممدودتان عموديتان على الجذع، والكفّان متقابلتان والمرفقان للداخل.","اشهق وأنزل الدمبلين ببطء حتى يقتربا من أذنيك، مع ثبات العضدين والمرفقين للداخل.","ازفر وأعدهما إلى البداية بالتراي."]],"Lying_Face_Down_Plate_Neck_Resistance":["مقاومة الرقبة بالقرص منبطحًا",["انبطح على بنش مستوٍ وجسمك مستقيم، والكتفان خارج طرف البنش قليلًا بحيث يكون الرأس والرقبة خارجه. أمسك قرصًا خلف رأسك. هذه وضعية البداية.","مع تثبيت القرص، أنزل رأسك ببطء (كأنك تقول نعم) وأنت تشهق.","ارفع رأسك إلى البداية في نصف دائرة وأنت تزفر، واثبت ثانية. ابدأ بوزن خفيف جدًا."]],"Lying_Face_Up_Plate_Neck_Resistance":["مقاومة الرقبة بالقرص مستلقيًا على الظهر",["استلقِ على ظهرك على بنش مستوٍ، والكتفان خارج طرفه قليلًا بحيث يكون الرأس والرقبة خارجه. أمسك قرصًا على جبهتك. هذه وضعية البداية.","مع تثبيت القرص، أنزل رأسك للخلف ببطء في نصف دائرة وأنت تشهق.","ارفع رأسك إلى البداية وأنت تزفر، واثبت ثانية. ابدأ بوزن خفيف جدًا."]],"Lying_Glute":["إطالة الأرداف مستلقيًا",["استلقِ على ظهرك وزميلك راكع بجانبك.","اثنِ ورك رجل واحدة وارفعها، ثم أدِرها بحيث تصبح القدم فوق الورك المعاكس والساق عمودية على جسمك. يثبّت زميلك الركبة والكاحل. هذه وضعية البداية.","حاول دفع رجلك نحو زميلك بينما يمنع أي حركة.","بعد 10–20 ثانية أرخِ تمامًا بينما يدفع زميلك الكاحل والركبة برفق نحو صدرك. أخبره عندما تكفي الإطالة."]],"Lying_Hamstring":["إطالة خلفي الفخذ مستلقيًا",["استلقِ على ظهرك والرجلان ممدودتان وزميلك راكع بجانبك. ارفع رجلًا نحو السقف ويمسك زميلك كاحلها (ويمكنه سندها بكتفه). هذه وضعية البداية.","وزميلك يثبّت رجلك، حاول ثني الركبة بعصر خلفي الفخذ 10–20 ثانية.","أرخِ رجلك ودع زميلك يدفعها برفق نحو رأسك. أخبره عندما تكفي الإطالة. بدّل الجهة."]],"Lying_High_Bench_Barbell_Curl":["باي بالبار منبطحًا على بنش عالٍ",["انبطح على بنش مستوٍ عالٍ وأمسك البار بقبضة سفلية (بعرض الكتفين للبار، أو من المقبض الداخلي لبار EZ). أعلى صدرك عند طرف البنش، والبار متدلٍّ أمامك والذراعان عموديتان على الأرض.","ثبّت العضدين والمرفقين للداخل، واثنِ البار في نصف دائرة وأنت تعصر الباي وتزفر. اثبت ثانية.","اشهق وعد ببطء إلى البداية، بتحكّم كامل ودون تأرجح."]],"Lying_Leg_Curls":["خلفي نائم (ثني الرجلين منبطحًا)",["اضبط ذراع الجهاز على طولك، وانبطح على جهاز الخلفي والمسند على أسفل السمانة بقليل. الجهاز المائل أفضل لتشغيل خلفي الفخذ من المستوي.","الجذع ملتصق بالبنش والرجلان ممدودتان بالكامل، وأمسك المقابض الجانبية. هذه وضعية البداية.","ازفر واثنِ رجليك لأقصى حد دون أن ترفع فخذيك عن المسند. اثبت ثانية.","اشهق وأعد رجليك إلى البداية."]],"Lying_Machine_Squat":["جهاز السكوات المستلقي",["اضبط الجهاز بحيث تدخل فيه والركبتان مثنيتان والفخذان أقل من الموازاة بقليل.","اختر الوزن وادخل الجهاز على ظهرك، والكتفان تحت المساند، والظهر والرأس مستندان على الجهاز. لا تتجاوز الركبتان أصابع القدمين.","أمسك المقابض، والقدمان بعرض الكتفين وأصابعهما للخارج قليلًا. هذه وضعية البداية.","ادفع بمقدمة القدمين وأنت تزفر حتى يستقيم جسمك، واعصر أمامي الفخذ ثانية. في التكرار الأول فقط يمكنك المساعدة بيديك على فخذيك.","انزل ببطء وأنت تشهق، وتوقف عندما يصبح الفخذان موازيين للمنصة (زاوية 90°)."]],"Lying_One-Arm_Lateral_Raise":["رفرفة جانبية مستلقيًا بيد واحدة",["أمسك دمبلًا بيد واحدة وانبطح بصدرك على بنش مستوٍ. يمكنك الإمساك بالبنش باليد الأخرى للثبات.","الكف نحو جسمك والذراع ممدودة مع ثني بسيط في المرفق. هذه وضعية البداية.","ارفع الذراع جانبيًا حتى يصبح المرفق على مستوى الكتف والذراع موازية للأرض، وأنت تزفر. اثبت ثانية.","أنزل الدمبل ببطء وأنت تشهق."]],"Lying_Prone_Quadriceps":["إطالة أمامي الفخذ منبطحًا",["انبطح على الأرض وزميلك راكع بجانبك. اثنِ ركبتك وارفع رجلك محاولًا لمس مؤخرتك بقدمك. يمسك زميلك الركبة والكاحل. هذه وضعية البداية.","حاول فرد ركبتك بينما يمنع زميلك أي حركة.","بعد 10–20 ثانية أرخِ عضلاتك بينما يدفع زميلك القدم برفق نحو مؤخرتك لإطالة أمامي الفخذ وثانيات الورك.","بعد 10–20 ثانية بدّل الجهة."]],"Lying_Rear_Delt_Raise":["كتف خلفي مستلقيًا",["أمسك دمبلًا في كل يد وانبطح بصدرك على بنش مستوٍ.","الكفّان نحو جسمك والذراعان ممدودتان مع ثني بسيط في المرفقين. هذه وضعية البداية.","ارفع ذراعيك جانبيًا حتى يصبح المرفقان على مستوى الكتفين والذراعان موازيتان للأرض، وأنت تزفر. اثبت ثانية.","أنزل الدمبلين ببطء وأنت تشهق."]],"Lying_Supine_Dumbbell_Curl":["باي دمبل مستلقيًا على الظهر",["استلقِ على ظهرك على بنش مستوٍ والدمبلان على فخذيك.","أنزل الدمبلين إلى جانبيك والذراعان ممدودتان والكفّان نحو الفخذين.","مع إبقاء الذراعين قريبتين من الجسم، أنزلهما ببطء نحو الأرض لأقصى حد مع ثني بسيط في المرفقين، ثم ثبّت العضدين في هذا الوضع. هذه وضعية البداية.","ازفر واثنِ الدمبلين ببطء مع لفّ الرسغين لتصبح الكفّان للأعلى، حتى ينقبض الباي بالكامل، واعصر ثانية. الساعدان فقط يتحركان.","عد ببطء شديد إلى البداية."]],"Lying_T-Bar_Row":["تجديف تي بار منبطحًا",["حمّل جهاز تجديف تي بار بالوزن واضبط ارتفاع الرجلين بحيث يكون أعلى صدرك عند أعلى المسند.","انبطح على المسند وأمسك المقابض: قبضة علوية أو سفلية أو محايدة حسب الجزء الذي تريد التركيز عليه من الظهر.","ارفع البار عن الحامل ومدّ ذراعيك أمامك. هذه وضعية البداية.","ازفر واسحب الوزن ببطء واعصر ظهرك في الأعلى. العضدان قريبان من الجذع، ولا ترفع جسمك عن المسند ولا تسحب بالباي.","اثبت ثانية، ثم انزل ببطء وأنت تشهق."]],"Lying_Triceps_Press":["ضغط تراي مستلقيًا",["استلقِ على بنش مستوٍ، وبار EZ أو بار مستقيم على الأرض خلف رأسك، والقدمان على الأرض.","أمسك البار خلفك بقبضة علوية متوسطة وارفعه أمامك والذراعان ممدودتان عموديتان على الجذع، والمرفقان للداخل. هذه وضعية البداية.","اشهق وأنزل الوزن ببطء حتى يلامس البار جبهتك برفق، مع ثبات العضدين والمرفقين.","ازفر وأعد البار إلى البداية بالتراي."]],"Machine_Bench_Press":["جهاز ضغط الصدر",["اجلس على جهاز ضغط الصدر واختر الوزن.","اضغط على دوّاسة الجهاز (إن وُجدت) لتقريب المقابض حتى تمسكها وتمدّ ذراعيك.","أمسك المقابض بقبضة علوية وارفع مرفقيك بحيث يكون العضدان موازيين للأرض بجانب جذعك. هذه وضعية البداية بعد مدّ الذراعين.","أعد المقابض نحوك وأنت تشهق.","ادفعها بعيدًا عنك بعصر الصدر وأنت تزفر، واثبت ثانية.","عند الانتهاء اضغط الدوّاسة مرة أخرى وأعد المقابض ببطء إلى مكانها."]],"Machine_Bicep_Curl":["جهاز الباي",["اضبط المقعد واختر الوزن. ضع عضديك على المسند وأمسك المقابض. هذه وضعية البداية.","اثنِ المرفقين لتسحب ساعديك نحو عضديك.","توقف في الأعلى، ثم أعد الوزن ببطء. لا تُرجعه إلى المكدّس حتى نهاية المجموعة لتبقى العضلة تحت الشد."]],"Machine_Preacher_Curls":["باي على جهاز المسند (بريتشر)",["اجلس على جهاز المسند (بريتشر) واختر الوزن.","ضع خلف عضديك على المسند وأمسك المقابض بقبضة سفلية، والمرفقان للداخل. هذه وضعية البداية.","ارفع المقابض بعصر الباي وأنت تزفر، واثبت ثانية في الأعلى. العضدان ثابتان على المسند دائمًا.","أنزل المقابض ببطء وأنت تشهق."]],"Machine_Shoulder_Military_Press":["جهاز ضغط الأكتاف (العسكري)",["اجلس على جهاز ضغط الأكتاف واختر الوزن.","أمسك المقابض بجانبك والمرفقان مثنيان على خط الجذع. هذه وضعية البداية.","ارفع المقابض حتى تمتد ذراعاك بالكامل وأنت تزفر، واثبت ثانية.","أنزلها ببطء وأنت تشهق."]],"Machine_Triceps_Extension":["جهاز التراي",["اضبط المقعد واختر الوزن. ضع عضديك على المسند وأمسك المقابض. هذه وضعية البداية.","افرد المرفقين لتدفع ساعديك بعيدًا عن عضديك.","توقف عند نهاية الحركة، ثم أعد الوزن ببطء. لا تُرجعه إلى المكدّس حتى نهاية المجموعة."]],"Medicine_Ball_Chest_Pass":["تمرير الكرة الطبية من الصدر",["تحتاج زميلًا، أو استخدم حائطًا.","قف مقابل زميلك وأمسك الكرة الطبية أمام جذعك بيديك.","اسحب الكرة إلى صدرك ثم ادفعها بفرد المرفقين. يمكنك التقدّم خطوة أثناء الرمي.","يلتقط زميلك الكرة ويرميها إليك.","استقبلها بيديك بمستوى الصدر."]],"Medicine_Ball_Full_Twist":["لفّ كامل بالكرة الطبية",["تحتاج كرة طبية وزميلًا. قفا ظهرًا لظهر على بعد 60–90 سم. هذه وضعية البداية.","أمسك الكرة أمام جذعك، وافتح حوضك ولفّ كتفيك مع زميلك في الوقت نفسه.","للدوران الكامل، يلتف كلاكما بالاتجاه نفسه.","مرّر الكرة لزميلك، ثم التفّا بالاتجاه المعاكس وكرّرا."]],"Medicine_Ball_Scoop_Throw":["رمي الكرة الطبية بالمغرفة",["قف في نصف سكوات والكرة الطبية بين يديك متدلية قرب قدميك.","ادفع حوضك للأمام وافرد رجليك قافزًا للأعلى.","أثناء ذلك أرجح ذراعيك الممدودتين فوق رأسك، وأفلت الكرة في أعلى الحركة لترميها لأبعد مسافة خلفك."]],"Middle_Back_Shrug":["ترابيس لمنتصف الظهر",["انبطح على بنش مائل ودمبل في كل يد، والذراعان ممدودتان متدليتان نحو الأرض والكفّان متقابلتان.","ازفر واضغط لوحي الكتف معًا، واثبت ثانية كاملة. الحركة عكس العناق، كأنك تفتح ذراعيك دون أن تحركهما.","اشهق وعد إلى البداية."]],"Middle_Back_Stretch":["إطالة منتصف الظهر",["قف والقدمان بعرض الكتفين واليدان على الخصر.","لفّ جذعك من الخصر حتى تشعر بإطالة. اثبت 10–15 ثانية، ثم لفّ إلى الجهة الأخرى."]],"Mixed_Grip_Chin":["عقلة بقبضة مختلطة",["أمسك بار العقلة بعرض أوسع من الكتفين بقليل، يد كفّها للأمام والأخرى كفّها نحوك. هذه وضعية البداية.","اسحب نفسك للأعلى وأنت تزفر. مرفق اليد ذات القبضة السفلية قريب من الجسم، ومرفق الأخرى بعيد لكن على خط الجذع. ركّز على عضلات الظهر.","اثبت ثانية، ثم انزل ببطء وأنت تشهق.","في المجموعة التالية بدّل القبضتين بين اليدين."]],"Monster_Walk":["مشية الوحش بالمطاط",["ضع مطاطًا حول الكاحلين وآخر حول الركبتين، بحيث يكونان مشدودين والقدمان بعرض الكتفين.","امشِ للأمام بخطوات قصيرة بالتبادل بين القدمين.","بعد عدة خطوات امشِ للخلف حتى نقطة البداية."]],"Mountain_Climbers":["متسلق الجبل",["ابدأ بوضعية الضغط على يديك وأطراف قدميك. اثنِ ركبة وورك رجل واحدة حتى تصبح الركبة تحت الحوض تقريبًا. هذه وضعية البداية.","بدّل وضع الرجلين بسرعة: افرد المثنية واجلب الأخرى للأمام. تابع بالتبادل 20–30 ثانية."]],"Moving_Claw_Series":["سلسلة المخلب المتحرك",["حركة تهيّئ أسلوب الركض للعدو السريع. أثناء الركض اثنِ الركبة محاولًا ركل مؤخرتك بكعبك مع امتداد الورك.","أعد شحن الرجل وهي تتقدّم للأمام لتضرب الأرض في الخطوة التالية.","أثناء الركض حرّك ذراعيك بقوة وبسرعة."]],"Muscle_Snatch":["خطف عضلي (مسل سناتش)",["أمسك بارًا محمّلًا بقبضة واسعة عند منتصف الفخذ، والقدمان تحت الحوض. أنزل حوضك قليلًا والصدر مرفوع والنظر للأمام، والكتفان أمام البار. هذه وضعية البداية.","ادفع بمقدمة الكعبين لترفع البار، ثم افرد الحوض والركبتين والكاحلين بقوة لتدفعه للأعلى بسرعة، قريبًا من جسمك.","تابع رفع البار حتى فوق رأسك دون أن تثني ركبتيك مرة أخرى."]],"Muscle_Up":["مسل أب",["أمسك الحلقات بقبضة كاذبة (قاعدة الكف فوق الحلقة). ابدأ عقلة بسحب المرفقين إلى جانبيك.","في أعلى العقلة اسحب الحلقات إلى إبطيك وأدِر كتفيك للأمام والمرفقان للخلف، لتنتقل إلى وضعية المتوازي.","بتحكّم وثبات، افرد المرفقين لتكمل الحركة.","انزل إلى الأرض بحذر."]],"Narrow_Stance_Hack_Squats":["هاك سكوات بوقفة ضيقة",["أسند ظهرك على مسند جهاز الهاك وضع كتفيك تحت المساند.","ضع قدميك على المنصة بوقفة ضيقة (المسافة بينهما نحو 8 سم أو أقل) وأصابعهما للخارج قليلًا. الرأس مرفوع والظهر على المسند دائمًا.","أمسك المقابض الجانبية وحرّر أذرع الأمان.","افرد رجليك دون قفل الركبتين. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق.","ادفع بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Narrow_Stance_Leg_Press":["مكبس الأرجل بوقفة ضيقة",["اجلس على مكبس الأرجل وضع قدميك على المنصة بوقفة ضيقة (المسافة بينهما نحو 8 سم أو أقل) وأصابعهما للخارج قليلًا.","حرّر أذرع الأمان وادفع المنصة حتى تمتد رجلاك دون قفل الركبتين. هذه وضعية البداية.","اشهق وأنزل المنصة ببطء حتى تصبح الزاوية بين الفخذ والساق 90°.","ادفع بكعبيك لتعود إلى البداية وأنت تزفر.","عند الانتهاء أعد أذرع الأمان إلى مكانها جيدًا."]],"Narrow_Stance_Squats":["سكوات بوقفة ضيقة",["يُفضّل أداء التمرين داخل قفص السكوات للأمان. اضبط البار على ارتفاع مناسب وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسك البار وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة وضع قدميك بوقفة ضيقة (8–15 سم بينهما) وأصابعهما للخارج قليلًا. الرأس مرفوع والظهر مستقيم.","انزل ببطء بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Natural_Glute_Ham_Raise":["رفع خلفي الفخذ الطبيعي (نورديك)",["باستخدام مسند ركبتي جهاز السحب الأمامي أو بنش البريتشر، ضع كاحليك تحت المساند وركبتيك على المقعد وظهرك للجهاز. قف على ركبتيك باستقامة. هذه وضعية البداية.","انزل بجسمك للأمام بتحكّم حتى تستقيم ركبتاك تقريبًا.","اصعد بتحكّم إلى البداية بخلفي الفخذ.","إذا لم تستطع إكمال التكرار، استعن بمطاط أو زميل أو ادفع بيديك عن صندوق."]],"Neck-SMR":["تدليك الرقبة بالفوم رولر",["ضع رولر العضلات أو شوبك العجين خلف رأسك على رقبتك، لا على العمود الفقري مباشرة بل على العضلات بجانبه. هذه وضعية البداية.","ابدأ من أعلى الرقبة وتدحرج ببطء للأسفل، وتوقف 10–30 ثانية عند نقاط الشد."]],"Neck_Press":["ضغط صدر بالبار إلى الرقبة",["استلقِ على بنش مستوٍ وأمسك البار بقبضة متوسطة، ارفعه من الحامل وثبّته فوق رقبتك والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى تشعر به قرب رقبتك. استخدم وزنًا خفيفًا ومُساعدًا، فالتمرين خطِر.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد البار إلى الحامل."]],"Oblique_Crunches":["كرنش الخواصر",["استلقِ على الأرض وأسفل ظهرك ملتصق بها، يد بجانب رأسك والأخرى على الأرض بجانبك.","ارفع قدميك وضعهما على سطح مستوٍ.","ارفع الكتف الذي يدك بجانب رأسه، واصعد بجسمك حتى يلمس مرفقك الركبة المعاكسة. مثلًا: المرفق الأيمن إلى الركبة اليسرى.","انزل إلى البداية. ازفر أثناء الصعود واشهق أثناء النزول.","أكمل التكرارات ثم بدّل الجهة."]],"Oblique_Crunches_-_On_The_Floor":["كرنش الخواصر على الأرض",["استلقِ على جنبك الأيمن والرجلان فوق بعضهما والركبتان مثنيتان قليلًا.","ضع يدك اليسرى خلف رأسك.","ارفع مرفقك الأيسر للأعلى كأنه كرنش عادي لكن بالتركيز على الخاصرة.","اصعد لأعلى ما تستطيع واثبت ثانية، ثم انزل ببطء. ازفر أثناء الصعود واشهق أثناء النزول. أكمل التكرارات ثم بدّل الجهة."]],"Olympic_Squat":["سكوات أولمبي",["ابدأ والبار على أعلى الترابيس، والصدر مرفوع والنظر للأمام، والقدمان بعرض الحوض وأصابعهما للخارج.","انزل بثني الركبتين مع أقل دفع ممكن للحوض للخلف، فتتقدم الركبتان للأمام على خط القدمين، والجذع مستقيم قدر الإمكان. انزل حتى النهاية والوزن على مقدمة الكعب.","عندما يلامس الفخذ الساق، اعكس الحركة وادفع الوزن للأعلى."]],"On-Your-Back_Quad_Stretch":["إطالة أمامي الفخذ على الظهر",["استلقِ على بنش مستوٍ أو درجة، ودع رجلًا وذراعًا تتدليان من الجانب.","اثنِ الركبة وأمسك ظهر القدم، دون أن تقوّس أسفل ظهرك.","اسحب سرّتك نحو العمود الفقري. اضغط قدمك في يدك. لإضافة إطالة الورك ارفع ورك تلك الرجل نحو السقف.","بدّل الجهة."]],"On_Your_Side_Quad_Stretch":["إطالة أمامي الفخذ على الجنب",["استلقِ على جنبك الأيمن والركبة اليمنى مثنية 90° أمامك على الأرض لتثبيت الجذع.","اثنِ ركبتك اليسرى خلفك وأمسك القدم بيدك اليسرى. لإطالة ثانيات الورك ادفع وركك الأيسر للأمام وقدمك للخلف في يدك. بدّل الجهة."]],"One-Arm_Dumbbell_Row":["تجديف دمبل بيد واحدة",["ضع دمبلًا بجانب بنش مستوٍ.","ضع ركبتك اليمنى على طرف البنش، وانحنِ من الخصر حتى يصبح جذعك موازيًا للأرض، واستند بيدك اليمنى على البنش.","أمسك الدمبل باليد اليسرى والكف نحو جسمك، مع ظهر مستقيم. هذه وضعية البداية.","اسحب الدمبل للأعلى إلى جانب صدرك والعضد قريب من جسمك، وأنت تزفر. اعصر الظهر في الأعلى. اسحب بالظهر لا بالذراع، والجذع ثابت.","أنزل الدمبل بشكل مستقيم إلى البداية وأنت تشهق.","أكمل التكرارات ثم بدّل الجهة."]],"One-Arm_Flat_Bench_Dumbbell_Flye":["تفتيح دمبل بيد واحدة على بنش مستوٍ",["استلقِ على بنش مستوٍ ودمبل في يد واحدة على فخذك، بقبضة محايدة.","بمساعدة فخذك، ارفع الدمبل أمامك والذراع ممدودة بالكامل. أمسك البنش باليد الأخرى للثبات. هذه وضعية البداية.","مع ثني بسيط في المرفق، أنزل ذراعك للجانب في قوس واسع حتى تشعر بإطالة في الصدر، وأنت تشهق. الحركة من الكتف فقط.","أعدها في القوس نفسه وأنت تعصر الصدر وتزفر، واثبت ثانية.","أكمل التكرارات ثم بدّل الذراع."]],"One-Arm_High-Pulley_Cable_Side_Bends":["ميلان جانبي بالكيبل العلوي بيد واحدة",["ركّب مقبضًا على الكيبل في أعلى وضع.","قف وجانبك للجهاز، وأمسك المقبض بيد واحدة بقبضة سفلية.","اسحب الكيبل حتى يلمس مرفقك جانبك والمقبض عند كتفك.","القدمان بعرض الحوض، واليد الأخرى على خصرك.","ثبّت ذراعك، واعصر الخاصرة لتنزل الوزن في كرنش جانبي.","بعد أقصى انقباض، عد ببطء دون أن يرتاح الوزن على المكدّس. أكمل التكرارات ثم بدّل الجهة."]],"One-Arm_Incline_Lateral_Raise":["رفرفة جانبية بيد واحدة على بنش مائل",["استلقِ على جنبك على بنش مائل ودمبل في يدك العليا، وكتفك مستند على البنش.","أمسك الدمبل والذراع ممدودة أمامك موازية للأرض. هذه وضعية البداية.","ارفع الذراع جانبيًا حتى تشير نحو السقف، وأنت تزفر. اثبت ثانية واشعر بانقباض الكتف.","اشهق وأنزل الوزن عبر جسمك إلى البداية.","أكمل التكرارات ثم بدّل الذراع."]],"One-Arm_Kettlebell_Clean":["كلين بالكيتلبل بيد واحدة",["ضع الكيتلبل بين قدميك. انحنِ لتمسكه بدفع مؤخرتك للخلف والنظر للأمام.","ارفعه إلى كتفك (كلين) بفرد الرجلين والحوض مع لفّ الرسغ.","أعده إلى البداية. أكمل التكرارات ثم بدّل اليد."]],"One-Arm_Kettlebell_Clean_and_Jerk":["كلين وجيرك بالكيتلبل بيد واحدة",["أمسك كيتلبلًا من مقبضه.","ارفعه إلى كتفك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغ لتصبح الكف للأمام.","انزل قليلًا بثني الركبتين والجذع مستقيم.","اعكس الاتجاه فورًا بالدفع بالكعبين كأنك تقفز، واضغط الكيتلبل فوق رأسك مستفيدًا من الاندفاع.","استقبل الوزن فوق رأسك بالنزول تحته في سكوات.","والوزن فوق رأسك، قف باستقامة. أنزله إلى الأرض للتكرار التالي."]],"One-Arm_Kettlebell_Floor_Press":["ضغط بالكيتلبل على الأرض بيد واحدة",["استلقِ على الأرض وأمسك كيتلبلًا بيد واحدة، والعضد مستند على الأرض والكف للداخل.","اضغط الكيتلبل للأعلى نحو السقف مع لفّ الرسغ.","أنزله إلى البداية وكرّر. ثم بدّل اليد."]],"One-Arm_Kettlebell_Jerk":["جيرك بالكيتلبل بيد واحدة",["أمسك كيتلبلًا من مقبضه وارفعه إلى كتفك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغ لتصبح الكف للأمام. هذه وضعية البداية.","انزل قليلًا بثني الركبتين والجذع مستقيم.","اعكس الاتجاه فورًا بالدفع بالكعبين، واضغط الكيتلبل فوق رأسك مستفيدًا من الاندفاع. استقبله بالنزول في سكوات تحته، ثم قف والوزن فوق رأسك.","أنزل الوزن للتكرار التالي."]],"One-Arm_Kettlebell_Military_Press_To_The_Side":["ضغط عسكري بالكيتلبل بيد واحدة مع الميلان للجانب",["ارفع الكيتلبل إلى كتفك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغ لتصبح الكف للداخل. هذه وضعية البداية.","انظر إلى الكيتلبل واضغطه للأعلى وللخارج حتى تنقفل ذراعك فوق رأسك.","أنزله إلى كتفك بتحكّم وكرّر. اعصر الظهر والأرداف والبطن بقوة للثبات."]],"One-Arm_Kettlebell_Para_Press":["ضغط بارا بالكيتلبل بيد واحدة",["ارفع الكيتلبل إلى كتفك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغ لتصبح الكف للأمام. هذه وضعية البداية.","والمرفق للخارج جانبيًا، اضغط الكيتلبل للأعلى وللخارج حتى تنقفل ذراعك فوق رأسك.","أنزله إلى كتفك بتحكّم وكرّر. اعصر الظهر والأرداف والبطن بقوة للثبات."]],"One-Arm_Kettlebell_Push_Press":["ضغط دفعي بالكيتلبل بيد واحدة",["أمسك كيتلبلًا وارفعه إلى كتفك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغ لتصبح الكف للأمام. هذه وضعية البداية.","انزل قليلًا بثني الركبتين والجذع مستقيم.","اعكس الاتجاه فورًا بالدفع بالكعبين، واضغط الكيتلبل فوق رأسك مستفيدًا من الاندفاع. أنزله للتكرار التالي."]],"One-Arm_Kettlebell_Row":["تجديف بالكيتلبل بيد واحدة",["ضع كيتلبلًا أمام قدميك. اثنِ ركبتيك قليلًا وادفع مؤخرتك للخلف قدر الإمكان وانحنِ. أمسك الكيتلبل واسحبه نحو بطنك بضم لوح الكتف وثني المرفق، والظهر مستقيم. أنزله وكرّر، ثم بدّل اليد."]],"One-Arm_Kettlebell_Snatch":["خطف بالكيتلبل بيد واحدة (سناتش)",["ضع الكيتلبل بين قدميك. اثنِ ركبتيك وادفع مؤخرتك للخلف.","انظر للأمام وأرجح الكيتلبل للخلف بين رجليك.","اعكس الاتجاه فورًا وادفع بالحوض والركبتين لتسرّع الكيتلبل للأعلى. عندما يصل إلى كتفك لفّ يدك واضرب للأعلى مستقيمًا، لتستقبله مقفلًا فوق رأسك."]],"One-Arm_Kettlebell_Split_Jerk":["جيرك مفتوح بالكيتلبل بيد واحدة",["أمسك كيتلبلًا وارفعه إلى كتفك (كلين) بفرد الرجلين والحوض، مع لفّ الرسغ لتصبح الكف للأمام. هذه وضعية البداية.","انزل قليلًا بثني الركبتين والجذع مستقيم.","اعكس الاتجاه فورًا بالدفع بالكعبين، واضغط الكيتلبل فوق رأسك مستفيدًا من الاندفاع.","استقبل الوزن بالنزول تحته بقدمين مفتوحتين: واحدة للأمام وأخرى للخلف.","والوزن فوق رأسك، قف واجمع قدميك. أنزله للتكرار التالي."]],"One-Arm_Kettlebell_Split_Snatch":["خطف مفتوح بالكيتلبل بيد واحدة",["أمسك كيتلبلًا من مقبضه بيد واحدة.","انزل نحو الأرض ثم اعكس الحركة بفرد الحوض والركبتين ثم الكاحلين لترفع الكيتلبل فوق رأسك.","بعد الامتداد الكامل انزل في وضعية لانج (رجل للأمام وأخرى للخلف) لتستقبل الوزن مقفلًا فوق رأسك، بحركة واحدة متصلة.","قف والوزن فوق رأسك واجمع قدميك. أنزل الوزن إلى البداية."]],"One-Arm_Kettlebell_Swings":["أرجحة الكيتلبل بيد واحدة (سوينغ)"],"One-Arm_Long_Bar_Row":["تجديف بطرف البار بيد واحدة",["ثبّت طرف البار في قاعدة لاندماين أو في زاوية، وحمّل الطرف الآخر بالوزن المناسب.","قف بجانب البار وأمسكه بيد واحدة قرب الأقراص، وقف باستخدام حوضك ورجليك.","اثنِ ركبتيك وادفع حوضك للخلف وارفع صدرك، والذراع ممدودة. هذه وضعية البداية.","اسحب الوزن إلى جانبك بسحب الكتف للخلف وثني المرفق، دون رجّ أو غش.","توقف لحظة، ثم عد إلى البداية. أكمل التكرارات ثم بدّل اليد."]],"One-Arm_Medicine_Ball_Slam":["ضرب الكرة الطبية بيد واحدة",["قف بوقفة رياضية والقدمان متباعدتان للأمام والخلف، والكرة الطبية في اليد التي في جهة الرجل الخلفية. هذه وضعية البداية.","ارفع الكرة فوق رأسك وافرد الحوض والركبتين والكاحلين استعدادًا للضرب.","في أقصى امتداد، اثنِ الكتفين والجذع والحوض لترمي الكرة بقوة في الأرض أمامك مباشرة.","التقطها بعد الارتداد وتابع."]],"One-Arm_Open_Palm_Kettlebell_Clean":["كلين بالكيتلبل بيد واحدة وكف مفتوح",["ضع كيتلبلًا بين قدميك.","أمسك المقبض بيد واحدة وارفعه بسرعة، ودعه ينقلب حتى تستقر كرة الكيتلبل في كفك المفتوحة.","ارمه أمامك والتقط المقبض بيد واحدة.","أعده إلى الأرض وكرّر. اشتغل باليدين."]],"One-Arm_Overhead_Kettlebell_Squats":["سكوات بالكيتلبل فوق الرأس بيد واحدة",["ارفع كيتلبلًا بيد واحدة إلى كتفك (كلين) ثم اضغطه فوق رأسك بفرد المرفق. هذه وضعية البداية.","والنظر للأمام والكيتلبل مقفل فوقك، اثنِ الركبتين والحوض وانزل بجذعك بين رجليك، والرأس والصدر مرفوعان.","اثبت ثانية في الأسفل، ثم اصعد بالدفع بكعبيك."]],"One-Arm_Side_Deadlift":["ديدلفت جانبي بيد واحدة",["قف بجانب البار عند منتصفه. اثنِ ركبتيك وانزل حتى تصل إليه.","أمسك البار كأنك تحمل حقيبة (الكف نحوك). قد تحتاج حزام الرسغ مع الأوزان الثقيلة. هذه وضعية البداية.","ارفع البار باستخدام رجليك وأنت تزفر، حتى تقف باستقامة والذراع ممدودة.","أنزله ببطء وأنت تشهق، مع ثني الركبتين.","أكمل التكرارات ثم بدّل اليد."]],"One-Arm_Side_Laterals":["رفرفة جانبية بيد واحدة",["أمسك دمبلًا بيد واحدة، وأمسك شيئًا ثابتًا باليد الأخرى، ومِل قليلًا نحو جهة الدمبل للتوازن.","قف باستقامة والدمبل بجانبك والكف نحوك. هذه وضعية البداية.","مع ثبات الجذع ودون تأرجح، ارفع الدمبل جانبيًا مع ثني بسيط في المرفق ويدك مائلة قليلًا للأمام كأنك تصبّ الماء، حتى تصبح ذراعك موازية للأرض. ازفر واثبت ثانية.","أنزله ببطء وأنت تشهق.","أكمل التكرارات ثم بدّل الذراع."]],"One-Legged_Cable_Kickback":["ركلة الأرداف بالكيبل برجل واحدة",["اربط حزام الكاحل بالكيبل السفلي ثم بكاحلك.","قف مقابل الجهاز على بعد 60 سم تقريبًا وأمسك الإطار للثبات.","مع ثني بسيط في الركبتين والحوض وشدّ البطن، اعصر الأرداف لتركل الرجل للخلف في قوس لأعلى ما يمكن براحة، وأنت تزفر. اعصر الأرداف ثانية في الأعلى.","أعد الرجل ببطء مقاومًا سحب الكيبل حتى البداية.","أكمل التكرارات ثم بدّل الرجل."]],"One_Arm_Against_Wall":["إطالة الصدر بذراع على الحائط",["قف وضع ذراعًا مثنية على حائط أو إطار باب.","مِل ببطء نحو ذراعك حتى تشعر بإطالة في الظهر (اللاتس)."]],"One_Arm_Chin-Up":["عقلة بيد واحدة",["ضع منشفة حول بار العقلة.","أمسك البار بيد واحدة والكف نحوك، واليد الأخرى تمسك المنشفة.","مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","اسحب جسمك حتى يقترب البار من أعلى صدرك، بسحب الكتف والعضد للأسفل وللخلف، وأنت تزفر. اعصر الظهر.","بعد ثانية، اشهق وانزل ببطء حتى تمتد ذراعك. أكمل التكرارات ثم بدّل الذراع."]],"One_Arm_Dumbbell_Bench_Press":["ضغط صدر بالدمبل بيد واحدة",["استلقِ على بنش مستوٍ ودمبل في يد واحدة على فخذك.","بمساعدة فخذك، ارفع الدمبل وأمسكه أمامك بعرض الكتف. يمكنك ضبط وضعه باليد الأخرى.","لفّ رسغك لتصبح الكف للأمام. هذه وضعية البداية.","أنزل الدمبل ببطء إلى جانبك وأنت تشهق، بتحكّم كامل. استخدم اليد الأخرى للتوازن فقط عند الحاجة.","ادفعه للأعلى بعضلات الصدر وأنت تزفر، واعصر ثانية. النزول يأخذ ضعف وقت الصعود.","أكمل التكرارات ثم بدّل الذراع."]],"One_Arm_Dumbbell_Preacher_Curl":["باي دمبل على المسند بيد واحدة",["أمسك دمبلًا باليد اليمنى وضع العضد على مسند البريتشر أو بنش مائل، والدمبل عند مستوى الكتف. هذه وضعية البداية.","اشهق وأنزل الدمبل ببطء حتى تمتد ذراعك ويتمدد الباي بالكامل.","ازفر واثنِ الدمبل بالباي حتى مستوى الكتف. في الأعلى اجعل الإصبع الصغير أعلى من الإبهام لانقباض كامل.","اعصر الباي بقوة ثانية. أكمل التكرارات ثم بدّل الذراع."]],"One_Arm_Floor_Press":["ضغط على الأرض بيد واحدة",["استلقِ على الأرض أو على حصيرة والركبتان مثنيتان.","اطلب من زميل أن يناولك البار بيد واحدة، والذراع شبه ممدودة كما في بداية ضغط الصدر، لكن بقبضة محايدة (الكف نحو جسمك).","اليد الأخرى بجانبك.","أنزل البار حتى يلمس مرفقك الأرض وأنت تشهق.","ارفعه إلى البداية وأنت تزفر. أكمل التكرارات ثم بدّل الذراع."]],"One_Arm_Lat_Pulldown":["سحب أمامي بيد واحدة (لات بول داون)",["اختر الوزن واضبط مسند الركبتين ليثبّتك. أمسك المقبض بقبضة علوية. هذه وضعية البداية.","اسحب المقبض للأسفل مع ثني المرفق وجلبه إلى جانبك.","توقف في الأسفل، ثم أعد المقبض ببطء. لا تُرجع الوزن بالكامل بين التكرارات. أكمل التكرارات ثم بدّل الذراع."]],"One_Arm_Pronated_Dumbbell_Triceps_Extension":["تراي بالدمبل بيد واحدة بقبضة علوية",["استلقِ على بنش مستوٍ وأمسك دمبلًا والذراع ممدودة عموديًا على جسمك، والكف نحو قدميك (قبضة علوية).","ضع يدك الأخرى على الباي للسند.","أنزل الدمبل ببطء بثني المرفق وأنت تشهق.","ارفعه بعصر التراي وأنت تزفر. أكمل التكرارات ثم بدّل الذراع."]],"One_Arm_Supinated_Dumbbell_Triceps_Extension":["تراي بالدمبل بيد واحدة بقبضة سفلية",["استلقِ على بنش مستوٍ وأمسك دمبلًا والذراع ممدودة عموديًا على جسمك، والكف نحو وجهك (قبضة سفلية).","ضع يدك الأخرى على الباي للسند.","أنزل الدمبل ببطء بثني المرفق وأنت تشهق.","ارفعه بعصر التراي وأنت تزفر. أكمل التكرارات ثم بدّل الذراع."]],"One_Half_Locust":["نصف الجرادة (إطالة)",["انبطح على الأرض.","ضع يدك اليسرى تحت عظمة وركك الأيسر لحمايته.","اثنِ ركبتك اليمنى وأمسك القدم بيدك اليمنى.","ارفع القدم وفي الوقت نفسه ارفع كتفيك عن الأرض. هذا يطيل أيضًا ثانيات الورك والصدر والكتفين. بدّل الجهة. إن لم يزعج ظهرك يمكنك تجربته بالذراعين والرجلين معًا."]],"One_Handed_Hang":["تعلّق بيد واحدة",["أمسك بار العقلة بيد واحدة بقبضة علوية، والقدمان على الأرض أو على درجة. دع معظم وزنك يتعلّق بتلك اليد والقدمان على الأرض. اثبت 10–20 ثانية ثم بدّل اليد."]],"One_Knee_To_Chest":["ركبة واحدة إلى الصدر",["استلقِ على الأرض.","مدّ رجلًا واسحب ركبة الأخرى إلى صدرك، وأمسك تحت مفصل الركبة لحمايتها.","اسحب الركبة برفق نحو أنفك.","بدّل الجهة. يطيل هذا الأرداف وأسفل الظهر للرجل المثنية وثانيات الورك للممدودة."]],"One_Leg_Barbell_Squat":["سكوات برجل واحدة بالبار",["قف على بعد 60–90 سم أمام بنش مستوٍ وظهرك له، والبار على الأرض أمامك. القدمان بعرض الكتفين.","اثنِ ركبتيك وأمسك البار بقبضة علوية أعرض من الكتفين، وارفعه إلى صدرك.","ارفعه فوق رأسك وضعه على أسفل رقبتك خلفك. أرجع قدمًا للخلف وضع أصابعها على البنش، والقدم الأخرى ثابتة أمامك. الرأس مرفوع والظهر مستقيم والصدر للأمام.","اشهق وانزل ببطء حتى يصبح الفخذ الأمامي موازيًا للأرض، والصدر فوق منتصف الفخذ.","اصعد إلى البداية بعصر أمامي الفخذ وأنت تزفر، والصدر والحوض يقودان الحركة. أكمل التكرارات ثم بدّل الرجل."]],"Open_Palm_Kettlebell_Clean":["كلين بالكيتلبل بكف مفتوح",["ضع كيتلبلًا بين قدميك. ارفعه بفرد الرجلين والحوض نحو كتفيك.","أفلته أثناء الصعود ودعه ينقلب حتى تستقر كرته في كفّيك المفتوحتين.","ارمه أمامك والتقط المقبض بيديك. أنزله إلى البداية وكرّر."]],"Otis-Up":["أوتيس أب (سيت أب بالقرص)",["ثبّت قدميك واستلقِ على ظهرك والركبتان مثنيتان، وأمسك وزنًا بيديك على صدرك. هذه وضعية البداية.","اثنِ الحوض والعمود الفقري لترفع جذعك عن الأرض.","أثناء الصعود اضغط الوزن للأعلى حتى يصبح فوق رأسك في أعلى الحركة.","أعد الوزن إلى صدرك وأنت تنزل، دون أن تصل إلى الأرض بالكامل."]],"Overhead_Cable_Curl":["باي بالكيبل العلوي فوق الرأس",["اختر الوزن نفسه على البكرتين.","اضبط البكرتين على ارتفاع أعلى من كتفيك.","قف في المنتصف وأمسك كل مقبض بقبضة سفلية، والذراعان ممدودتان موازيتان للأرض والقدمان بعرض الكتفين. هذه وضعية البداية.","ازفر واعصر الباي من الجهتين ببطء حتى يلامس الساعدان الباي.","اشهق وأعد الساعدين إلى البداية. الجسم كله ثابت إلا الساعدين."]],"Overhead_Lat":["إطالة الظهر (لاتس) فوق الرأس",["اجلس باستقامة على الأرض وزميلك خلفك. ارفع ذراعًا للأعلى واثنِ المرفق محاولًا لمس ظهرك بيدك. يمسك زميلك عضدك ورسغك. هذه وضعية البداية.","حاول سحب عضدك إلى جانبك بينما يمنعك زميلك.","بعد 10–20 ثانية أرخِ الذراع ودع زميلك يزيد إطالة الظهر بضغط خفيف على العضد. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Overhead_Slam":["ضرب الكرة من فوق الرأس",["أمسك الكرة الطبية بيديك والقدمان بعرض الكتفين. هذه وضعية البداية.","ارفع الكرة فوق رأسك وافرد جسمك بالكامل.","اعكس الحركة واضرب الكرة في الأرض أمامك مباشرة بأقوى ما يمكن.","التقطها بيديك بعد الارتداد وكرّر."]],"Overhead_Squat":["سكوات والبار فوق الرأس",["البار على الأرض أمامك والقدمان أعرض من الكتفين.","اثنِ ركبتيك وأمسك البار بقبضة علوية أعرض من الكتفين، وارفعه إلى صدرك.","ارفعه فوق رأسك وخلفه قليلًا والذراعان ممدودتان، والرأس مرفوع والظهر مستقيم ولوحا الكتف مضمومان. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى يصبح الفخذان موازيين للأرض وأنت تشهق، والظهر مستقيم والذراعان فوق رأسك دائمًا.","اصعد إلى البداية وأنت تزفر."]],"Overhead_Stretch":["إطالة فوق الرأس",["قف باستقامة، شبّك أصابعك وافتح كفّيك نحو السقف. أبقِ كتفيك للأسفل وأنت تمدّ ذراعيك للأعلى.","لإطالة الجذع كاملًا، اسحب عصعصك للأسفل وثبّت جذعك، لتشعر بالإطالة في مقدمة الجذع وخلفه."]],"Overhead_Triceps":["إطالة التراي فوق الرأس",["اجلس باستقامة على الأرض وزميلك خلفك. ارفع ذراعًا للأعلى واثنِ المرفق محاولًا لمس ظهرك بيدك. يمسك زميلك المرفق والرسغ. هذه وضعية البداية.","حاول مدّ الذراع للأعلى بينما يمنعك زميلك.","بعد 10–20 ثانية أرخِ الذراع ودع زميلك يزيد إطالة التراي بضغط خفيف على الرسغ. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Pallof_Press":["ضغط بالوف (مقاومة الالتفاف)",["ركّب مقبضًا على الكيبل واضبطه بمستوى الكتفين إن أمكن (أو في الأسفل).","قف وجانبك للجهاز وأمسك المقبض بيديك، وابتعد حتى يصبح الكيبل مشدودًا على بعد طول ذراع تقريبًا.","القدمان بعرض الحوض والركبتان مثنيتان قليلًا، والمقبض على منتصف صدرك. هذه وضعية البداية.","ادفع المقبض بعيدًا عن صدرك حتى تمتد ذراعاك، مع شدّ البطن ومقاومة الالتفاف.","اثبت عدة ثوانٍ، ثم عد إلى البداية.","في نهاية المجموعة كرّر والجهة الأخرى نحو الجهاز."]],"Pallof_Press_With_Rotation":["ضغط بالوف مع الالتفاف",["ركّب مقبضًا على الكيبل بمستوى الكتفين.","قف وجانبك للجهاز وأمسك المقبض بيد واحدة، وابتعد حتى يصبح الكيبل مشدودًا على بعد طول ذراع تقريبًا.","القدمان بعرض الحوض، اسحب المقبض إلى صدرك وأمسكه بيديك الاثنتين.","ووجهك للأمام، ادفع المقبض بعيدًا عن صدرك مع شدّ البطن.","مع ثبات الحوض، لفّ جذعك بعيدًا عن الجهاز ربع دورة، ثم عد ببطء إلى الأمام والذراعان ممدودتان.","أعد يديك إلى صدرك، ثم ادفع للأمام مجددًا. هذا تكرار واحد. أكمل ثم بدّل الجهة."]],"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench":["ثني الرسغ بالدمبل والكف للأسفل على البنش",["ضع دمبلين على أحد جانبي بنش مستوٍ.","اركع على ركبتيك ووجهك نحو البنش.","أمسك الدمبلين بقبضة علوية (الكفّان للأسفل)، واسند ساعديك على البنش والرسغان خارج حافته.","اثنِ رسغيك للأعلى وأنت تزفر.","أنزلهما ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك."]],"Palms-Down_Wrist_Curl_Over_A_Bench":["ثني الرسغ بالبار والكف للأسفل على البنش",["ضع بارًا على أحد جانبي بنش مستوٍ.","اركع على ركبتيك ووجهك نحو البنش.","أمسك البار بقبضة علوية (الكفّان للأسفل)، واسند ساعديك على البنش والرسغان خارج حافته.","اثنِ رسغيك للأعلى وأنت تزفر.","أنزلهما ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك."]],"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench":["ثني الرسغ بالبار والكف للأعلى على البنش",["ضع بارًا على أحد جانبي بنش مستوٍ.","اركع على ركبتيك ووجهك نحو البنش.","أمسك البار بقبضة سفلية (الكفّان للأعلى)، واسند ساعديك على البنش والرسغان خارج حافته.","اثنِ رسغيك للأعلى وأنت تزفر.","أنزلهما ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك."]],"Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench":["ثني الرسغ بالدمبل والكف للأعلى على البنش",["ضع دمبلين على أحد جانبي بنش مستوٍ.","اركع على ركبتيك ووجهك نحو البنش.","أمسك الدمبلين بقبضة سفلية (الكفّان للأعلى)، واسند ساعديك على البنش والرسغان خارج حافته.","اثنِ رسغيك للأعلى وأنت تزفر.","أنزلهما ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك."]],"Parallel_Bar_Dip":["متوازي",["قف بين بارات المتوازي وضع يدًا على كل بار، ثم اقفز قليلًا لترتفع والذراعان مقفلتان.","اثنِ المرفقين وانزل حتى تصبح الزاوية في الذراعين أقل من 90°، دون تأرجح ومع وضعية جيدة.","افرد المرفقين لتعود إلى البداية."]],"Pelvic_Tilt_Into_Bridge":["إمالة الحوض ثم جسر",["استلقِ والقدمان على الأرض والكعبان تحت الركبتين.","ارفع عصعصك فقط نحو السقف لإطالة أسفل الظهر (لا ترفع الظهر كله بعد)، واسحب بطنك للداخل.","للانتقال إلى الجسر، ارفع العمود الفقري كله ما عدا الرقبة."]],"Peroneals-SMR":["تدليك الساق الجانبية بالفوم رولر",["استلقِ على جنبك واستند على ساعدك وعلى فوم رولر تحت الجهة الخارجية من ساقك. الرجل العليا فوق السفلية أو أمامك. هذه وضعية البداية.","ارفع حوضك وتدحرج من تحت الركبة حتى فوق الكاحل على جانب الساق، وتوقف 10–30 ثانية عند نقاط الشد. كرّر بالرجل الأخرى."]],"Peroneals_Stretch":["إطالة الساق الجانبية",["اجلس ولفّ حزامًا أو حبلًا حول قدم واحدة. هذه وضعية البداية.","والرجل ممدودة والكعب مرفوع عن الأرض، اسحب الحزام بحيث يتجه باطن القدم للداخل نحوك. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Physioball_Hip_Bridge":["جسر الحوض على كرة التمارين",["استلقِ على كرة التمارين بحيث يستند أعلى ظهرك عليها والحوض غير مسنود، والقدمان على الأرض بعرض الحوض أو أوسع. هذه وضعية البداية.","افرد حوضك بالأرداف وخلفي الفخذ وارفعه للأعلى كالجسر.","توقف في الأعلى، ثم عد إلى البداية."]],"Pin_Presses":["ضغط من المساند (بن برس)",["يلغي هذا التمرين مرحلة النزول في ضغط الصدر، فيبني قوة البداية ويسمح بتدريب جزء محدد من الحركة.","ضع البنش داخل القفص، واضبط المساند على النقطة المطلوبة (قرب القفل أو فوق الصدر ببضعة سنتيمترات)، والبار عليها.","استلقِ والبار فوق نقطة ملامسته المعتادة لصدرك. اسحب قدميك للخلف وقوّس ظهرك، واضغط لوحي الكتف معًا، وحافظ على هذا الشد.","أمسك البار بقبضتك المعتادة أو بعرض الكتفين للتركيز على التراي. البار والرسغ والمرفق على خط واحد، واعصر البار.","ادفع البار للأعلى بأقصى قوة والمرفقان قريبان من الجسم حتى القفل.","أعد البار إلى المساند، وتوقف قبل التكرار التالي."]],"Piriformis-SMR":["تدليك عضلة الكمثري بالفوم رولر",["اجلس بمؤخرتك على الفوم رولر والركبتان مثنيتان، وضع كاحل رجل فوق الركبة الأخرى. هذه وضعية البداية.","انقل وزنك إلى جهة الرجل المتقاطعة وتدحرج على الأرداف حتى تشعر بشد في أعلى الأرداف. يمكنك سحب الركبة المثنية نحو صدرك بيد واحدة. اثبت 10–30 ثانية ثم بدّل الجهة."]],"Plank":["بلانك",["انبطح على الأرض واستند على أطراف قدميك وساعديك، والذراعان مثنيتان تحت الكتفين مباشرة.","حافظ على جسم مستقيم تمامًا واثبت أطول وقت ممكن. لزيادة الصعوبة ارفع ذراعًا أو رجلًا."]],"Plate_Pinch":["قرص الأصابع (مسك الأقراص)",["خذ قرصين بحافة عريضة وضعهما معًا والجهتان الملساوان للخارج.","أمسكهما بأصابعك من جهة وإبهامك من الجهة الأخرى. هذه وضعية البداية.","اضغط القرصين بأصابعك وإبهامك واثبت أطول وقت ممكن.","بدّل اليد وكرّر."]],"Plate_Twist":["لفّ بالقرص",["اجلس على الأرض والرجلان ممدودتان والجذع مرفوع، وأمسك قرصًا من جانبيه أمام بطنك والذراعان مثنيتان قليلًا.","شبّك رجليك عند الكاحلين وارفعهما عن الأرض مع ثني بسيط في الركبتين. مِل بجذعك للخلف قليلًا للتوازن. هذه وضعية البداية.","حرّك القرص إلى اليسار حتى يلمس الأرض وأنت تزفر.","عد إلى المنتصف وأنت تشهق، ثم إلى اليمين. تحرّك ببطء، فالحركات المفاجئة قد تؤذي الظهر."]],"Platform_Hamstring_Slides":["انزلاق خلفي الفخذ على المنصة",["تحتاج أرضية ملساء. استلقِ على ظهرك والرجلان ممدودتان، وضع منشفة أو قرصًا خفيفًا تحت كعبك. هذه وضعية البداية.","اثنِ ركبة واحدة والرجل الأخرى مستقيمة.","اسحب الكعب نحوك منزلقًا على الأرض.","عند الثني الكامل، اعكس الحركة لتعود إلى البداية."]],"Plie_Dumbbell_Squat":["سكوات بليه بالدمبل",["أمسك دمبلًا من طرفه بيديك وقف باستقامة. باعد قدميك أوسع من الكتفين والركبتان مثنيتان قليلًا.","أصابع القدمين للخارج، والذراعان ثابتتان طوال التمرين. هذه وضعية البداية.","اثنِ ركبتيك ببطء وانزل حتى يصبح الفخذان موازيين للأرض، وأنت تشهق.","ادفع بكعبيك لتعود إلى البداية وأنت تزفر."]],"Plyo_Kettlebell_Pushups":["ضغط بالقفز على الكيتلبل",["ضع كيتلبلًا على الأرض. اتخذ وضعية الضغط على أطراف قدميك، يد على الأرض ويد على الكيتلبل، والمرفقان ممدودان. هذه وضعية البداية.","انزل لأدنى ما تستطيع والظهر مستقيم.","ادفع بسرعة وقوة لتنتقل إلى الجهة الأخرى من الكيتلبل مع تبديل اليدين. انزل وكرّر ذهابًا وإيابًا."]],"Plyo_Push-up":["ضغط بالقفز (بلايو بوش أب)",["اتخذ وضعية الضغط على يديك وأطراف قدميك.","الذراعان ممدودتان واليدان بعرض الكتفين، والجسم مستقيم طوال الحركة. هذه وضعية البداية.","انزل بثني المرفقين بصدرك نحو الأرض.","في الأسفل ادفع بأسرع ما يمكن حتى ترتفع يداك عن الأرض.","عد إلى البداية وكرّر. لزيادة الصعوبة صفّق بيديك وأنت في الهواء."]],"Posterior_Tibialis_Stretch":["إطالة عضلة الساق الخلفية العميقة",["اجلس ولفّ حزامًا أو حبلًا حول قدم واحدة. هذه وضعية البداية.","والرجل ممدودة والكعب مرفوع عن الأرض، اسحب الحزام بحيث يتجه باطن القدم للخارج والجهة الخارجية نحوك. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Power_Clean":["باور كلين",["قف والقدمان أعرض قليلًا من الكتفين وأصابعهما للخارج قليلًا.","انزل وأمسك البار بقبضة علوية أعرض قليلًا من الكتفين خارج الركبتين، والمرفقان ممدودان، والبار على بعد 2–3 سم أمام الساقين فوق مقدمة القدمين. الظهر مستقيم أو مقوّس قليلًا، الصدر مرفوع ولوحا الكتف للخلف، والنظر للأمام.","ارفع البار عن الأرض بفرد الحوض والركبتين بقوة، مع ثبات زاوية الجذع وعدم ارتفاع الحوض قبل الكتفين. البار قريب من الساقين والكتفان فوقه.","عندما يتجاوز البار الركبتين، ادفع حوضك للأمام ثم افرد الحوض والركبتين بسرعة وقوة وارتفع على أصابع قدميك، والبار قريب من جسمك.","عند الامتداد الكامل ارفع كتفيك بسرعة (شراغ) قبل ثني المرفقين، ثم اثنِ المرفقين لتسحب جسمك تحت البار.","لفّ ذراعيك تحت البار وانزل في ربع سكوات، واستقبل البار على مقدمة الكتفين والترقوة والمرفقان مرفوعان، والجذع مشدود والقدمان مسطحتان.","قف باستقامة، ثم أنزل البار بتحكّم إلى فخذيك مع ثني الحوض والركبتين لامتصاص الوزن، ثم إلى الأرض."]],"Power_Clean_from_Blocks":["باور كلين من المكعبات",["البار على صناديق بالارتفاع المطلوب، أمسكه خارج الرجلين مباشرة. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع.","ادفع بالكعبين وافرد الركبتين، مع ثبات زاوية الظهر والذراعان مستقيمتان. عند منتصف الفخذ ابدأ بفرد الحوض.","افرد الحوض والركبتين والكاحلين بقوة كأنك تقفز، دون السحب بالذراعين.","عند الامتداد الكامل ارفع كتفيك واثنِ ذراعيك والمرفقان للأعلى وللخارج، واسحب نفسك تحت البار بما يكفي لاستقباله على مقدمة الكتفين.","اصعد فورًا بالدفع بالكعبين حتى تقف، ثم أعد البار إلى الصناديق."]],"Power_Jerk":["باور جيرك",["قف والبار على مقدمة الكتفين والقدمان تحت الحوض. انزل قليلًا بالركبتين دون دفع الحوض للخلف، ثم اعكس الاتجاه بأقصى قوة.","ادفع بالكعبين بأقصى سرعة وقوة، وأبعد رأسك عن مسار البار.","عندما ترتفع قدماك انقلهما بسرعة إلى وقفة أعرض قليلًا والركبتان مثنيتان جزئيًا.","استقبل البار والذراعان مقفلتان فوق رأسك.","قف باستقامة."]],"Power_Partials":["حركات جزئية قوية",["قف باستقامة ودمبل في كل يد بجانبك، والمرفقان قريبان من الجسم والكفّان نحوه، والقدمان بعرض الكتفين.","مع إبقاء الذراعين مستقيمتين والجذع ثابتًا، ارفع الدمبلين جانبيًا حتى مستوى الكتفين وأنت تزفر.","اثبت ثانية ثم أنزلهما ببطء وأنت تشهق. أبقِ الكفّين للأسفل والإصبع الصغير أعلى قليلًا للتركيز على الكتف."]],"Power_Snatch":["باور سناتش",["البار المحمّل على الأرض قريب من ساقيك، أمسكه بقبضة واسعة. القدمان تحت الحوض، أنزل حوضك والصدر مرفوع والنظر للأمام، والكتفان أمام البار. هذه وضعية البداية.","السحبة الأولى: ادفع بمقدمة الكعبين لترفع البار، مع ثبات زاوية الظهر حتى يتجاوز الركبتين.","السحبة الثانية: افرد الحوض والركبتين والكاحلين بقوة لتدفع البار للأعلى بسرعة قريبًا من جسمك. في أقصى امتداد ارفع كتفيك ودع المرفقين ينثنيان للجانبين.","انقل قدميك إلى وقفة أعرض قليلًا واسحب نفسك تحت البار وأنت ترفعه، واستقبله مقفلًا فوق رأسك في سكوات جزئي.","قف والوزن فوق رأسك."]],"Power_Snatch_from_Blocks":["باور سناتش من المكعبات",["البار المحمّل على صناديق بالارتفاع المطلوب، أمسكه بقبضة واسعة. القدمان تحت الحوض، أنزل حوضك والصدر مرفوع والنظر للأمام، والكتفان أمام البار والمرفقان للخارج. هذه وضعية البداية.","ادفع بمقدمة الكعبين لترفع البار عن الصناديق.","افرد الحوض والركبتين والكاحلين بقوة لتدفع البار للأعلى بسرعة قريبًا من جسمك. في أقصى امتداد ارفع كتفيك ودع المرفقين ينثنيان للجانبين.","انقل قدميك إلى وضعية الاستقبال خارج الحوض قليلًا، واسحب نفسك تحت البار وأنت ترفعه فوق رأسك. استقبله فوق السكوات الكامل والذراعان ممدودتان.","والبار فوق مقدمة الكعبين، قف بالدفع بالكعبين. أعد الوزن إلى الصناديق بحذر."]],"Power_Stairs":["درج القوة",["في درج القوة تُنقل أوزان على درجات. للتدريب يمكن استخدام إطار أو صندوق.","أمسك الأداة بيديك، والقدمان متباعدتان والرأس والصدر مرفوعان. ادفع الأرض بكعبيك وافرد الركبتين والحوض لترفع الوزن.","وأنت تميل للخلف، أرجح الوزن على الدرجة (عادةً 40–45 سم). يمكنك الدفع برجليك للمساعدة.","كرّر 3–5 مرات ثم زِد الوزن، بأسرع ما يمكن."]],"Preacher_Curl":["باي على المسند (بريتشر)",["تحتاج إلى بنش المسند (بريتشر) وبار EZ. أمسك البار من المقبض الداخلي الضيق، والكفّان للأمام مائلتان للداخل قليلًا.","العضدان على المسند والصدر ملاصق له، والبار عند مستوى الكتفين. هذه وضعية البداية.","اشهق وأنزل البار ببطء حتى تمتد ذراعاك ويتمدد الباي بالكامل.","ازفر واثنِ البار بالباي حتى مستوى الكتفين، واعصر بقوة ثانية."]],"Preacher_Hammer_Dumbbell_Curl":["باي مطرقة بالدمبل على المسند",["ضع عضديك على مسند البريتشر ودمبل في كل يد بقبضة محايدة (الكفّان متقابلتان).","اشهق وأنزل الدمبلين ببطء حتى تمتد ذراعاك ويتمدد الباي.","ازفر واثنِ الدمبلين بالباي حتى مستوى الكتفين.","اعصر الباي بقوة ثانية في الأعلى."]],"Press_Sit-Up":["سيت أب مع ضغط",["استلقِ على بنش البطن والبار على صدرك، والرجلان مثبتتان. هذه وضعية البداية.","اشهق وشدّ البطن والأرداف، ثم اثنِ جذعك كما في السيت أب وفي الوقت نفسه اضغط البار فوق رأسك وأنت تزفر، مع التركيز على البطن.","انزل بجذعك إلى البداية وأعد البار إلى صدرك وأنت تشهق."]],"Prone_Manual_Hamstring":["إطالة خلفي الفخذ منبطحًا بمساعدة",["تحتاج زميلًا. انبطح والرجلان مستقيمتان، ويضع زميلك يده على كعبك.","اثنِ ركبتك لترفع رجلك، ويقاوم زميلك بقوة خفيفة تزيد تدريجيًا. تواصلا لضبط المقاومة.","توقف في الأعلى، ثم أعد الرجل بينما يقاوم زميلك في الاتجاه المعاكس."]],"Prowler_Sprint":["عدو بزلاجة البراولر",["ضع الزلاجة (البراولر) على سطح مناسب وحمّلها بوزن يتطلب جهدًا دون أن يبطئك كثيرًا.","أمسك المقابض العالية أو المنخفضة والذراعان ممدودتان، ومِل نحو الزلاجة.","بوضعية جيدة، ادفع الأرض بخطوات قصيرة متبادلة، بأسرع ما يمكن لمسافة قصيرة."]],"Pull_Through":["سحب بين الرجلين بالكيبل (بول ثرو)",["قف على بعد خطوات أمام الكيبل السفلي المركّب عليه حبل، وظهرك للجهاز والكيبل بين رجليك المتباعدتين.","انحنِ من الحوض ومدّ يديك بين رجليك لأبعد حد، والركبتان مثنيتان قليلًا.","والذراعان مستقيمتان، افرد حوضك لتقف باستقامة. لا تسحب بالكتفين، فالحركة كلها من الحوض والأرداف."]],"Pullups":["عقلة",["أمسك بار العقلة والكفّان للأمام بالقبضة المطلوبة (واسعة: أعرض من الكتفين، متوسطة: بعرضهما، ضيقة: أضيق).","والذراعان ممدودتان، مِل بجذعك للخلف قليلًا مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","اسحب جسمك للأعلى حتى يقترب البار من أعلى صدرك، بسحب الكتفين والعضدين للأسفل وللخلف، وأنت تزفر. اعصر عضلات الظهر في الأعلى. الساعدان يمسكان فقط.","بعد ثانية، اشهق وانزل ببطء حتى تمتد ذراعاك بالكامل."]],"Push-Up_Wide":["ضغط بقبضة واسعة (بوش أب)",["اتخذ وضعية البلانك على أطراف القدمين واليدين، واليدان متباعدتان كثيرًا، والمرفقان ممدودان والجسم مستقيم دون هبوط الحوض. هذه وضعية البداية.","اشهق وانزل بصدرك نحو الأرض بثني المرفقين.","ادفع جسمك للأعلى بعضلات الصدر حتى تمتد ذراعاك، وأنت تزفر.","توقف لحظة في الأعلى، ثم كرّر."]],"Push-Ups_-_Close_Triceps_Position":["ضغط بقبضة ضيقة للتراي (بوش أب)",["انبطح على الأرض وضع يديك أضيق من الكتفين، وارفع جسمك والذراعان ممدودتان.","انزل حتى يكاد صدرك يلمس الأرض وأنت تشهق.","ادفع للأعلى بالتراي وبعض عضلات الصدر، واعصر صدرك، وأنت تزفر.","توقف ثانية في الأعلى، ثم كرّر."]],"Push-Ups_With_Feet_Elevated":["ضغط والرجلان مرفوعتان",["انبطح على الأرض وضع يديك متباعدتين بعرض أوسع من الكتفين، وارفع جسمك والذراعان ممدودتان.","ضع أطراف قدميك على بنش مستوٍ. كلما ارتفع البنش زادت الصعوبة.","انزل حتى يكاد صدرك يلمس الأرض وأنت تشهق.","ادفع للأعلى بعضلات الصدر واعصرها وأنت تزفر.","توقف ثانية في الأعلى، ثم كرّر."]],"Push-Ups_With_Feet_On_An_Exercise_Ball":["ضغط والرجلان على كرة التمارين",["انبطح على الأرض واليدان أعرض من الكتفين، وارفع جسمك والذراعان ممدودتان.","ضع أطراف قدميك على كرة التمارين.","انزل حتى يكاد صدرك يلمس الأرض وأنت تشهق.","ادفع للأعلى بعضلات الصدر واعصرها وأنت تزفر.","توقف ثانية في الأعلى، ثم كرّر."]],"Push_Press":["ضغط دفعي (بوش برس)"],"Push_Press_-_Behind_the_Neck":["ضغط دفعي خلف الرقبة",["قف والبار على أعلى ظهرك، والقدمان تحت الحوض. انزل قليلًا بالركبتين دون دفع الحوض للخلف، ثم اعكس الاتجاه بأقصى قوة بالدفع بالكعبين، والبار في مسار عمودي.","استخدم هذا الاندفاع لتكمل ضغط البار فوق رأسك بفرد الذراعين.","عد إلى البداية واستخدم رجليك لامتصاص الوزن."]],"Push_Up_to_Side_Plank":["ضغط ثم بلانك جانبي",["اتخذ وضعية الضغط على أطراف القدمين، واليدان أعرض قليلًا من الكتفين.","انزل بثني المرفقين والجسم مستقيم، ثم اصعد.","أثناء الصعود انقل وزنك إلى الجانب الأيسر، ولفّ جسمك وارفع ذراعك اليمنى نحو السقف في بلانك جانبي.","أنزل الذراع للأرض وقم بضغطة أخرى، ثم لفّ إلى الجهة الأخرى. تابع بالتبادل."]],"Pushups":["ضغط (بوش أب)",["انبطح على الأرض وضع يديك أعرض قليلًا من الكتفين، وارفع جسمك والذراعان ممدودتان.","اشهق وانزل حتى يكاد صدرك يلمس الأرض.","ازفر وادفع للأعلى إلى البداية مع عصر الصدر.","توقف لحظة في الأعلى، ثم كرّر."]],"Pushups_Close_and_Wide_Hand_Positions":["ضغط بقبضة ضيقة وواسعة",["انبطح على الأرض والجسم مستقيم على أطراف القدمين، واليدان أعرض من الكتفين (واسعة) أو أضيق منهما (ضيقة)، والذراعان ممدودتان.","انزل حتى يكاد صدرك يلمس الأرض وأنت تشهق.","ادفع للأعلى بعضلات الصدر واعصرها وأنت تزفر.","توقف ثانية في الأعلى، ثم كرّر."]],"Pyramid":["الهرم (إطالة)",["دحرج جذعك للأمام على كرة التمارين حتى يستقر حوضك فوقها ويصبح أعلى نقطة في جسمك.","ضع يديك وقدميك على الأرض. الذراعان والرجلان مثنية قليلًا أو مستقيمة حسب حجم الكرة ومرونتك. هذا يقوّي ثبات الجذع والكتفين أيضًا."]],"Quad_Stretch":["إطالة أمامي الفخذ",["استلقِ على جنبك ولفّ حزامًا أو حبلًا حول قدمك العليا. اثنِ الركبة وافرد الورك محاولًا لمس مؤخرتك بقدمك، والحزام في يديك. هذه وضعية البداية.","والحزام فوق كتفك أو رأسك، اسحبه برفق لزيادة إطالة أمامي الفخذ. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Quadriceps-SMR":["تدليك أمامي الفخذ بالفوم رولر",["انبطح على الأرض واستند على يديك أو ساعديك. ضع الفوم رولر تحت أمامي فخذ رجل واحدة والقدم مرفوعة عن الأرض، وأرخِ الرجل. هذه وضعية البداية.","ضع على الرجل ما تتحمّله من وزنك، وتدحرج من فوق الركبة حتى تحت الورك، وتوقف 10–30 ثانية عند نقاط الشد. بدّل الجهة."]],"Quick_Leap":["وثبة سريعة",["تحتاج صندوقًا.","قف مقابله على بعد 30–60 سم من حافته.","بقوة الحوض، اقفز على الصندوق واهبط على القدمين، والرجلان مثنيتان والقدمان مسطحتان.","فور الهبوط افرد جسمك بالكامل وأرجح ذراعيك فوق رأسك لتنطلق عن الصندوق، وامتص الصدمة برجليك عند الهبوط."]],"Rack_Delivery":["استلام البار من الحامل",["تمرين يعلّم إيصال البار إلى وضعية الاستقبال على الكتفين. أمسك البار بوضعية الفزّاعة: العضدان موازيان للأرض والساعدان متدليان، بقبضة الخطّاف.","دوّر مرفقيك حول البار لتوصله إلى كتفيك، وأرخِ قبضتك مع تقدّم المرفقين. الكتفان للأمام ليصنعا رفًا للبار الملامس للرقبة برفق.","أبقِ البار قريبًا من جسمك دائمًا. مع تحسّن الحركة يمكن زيادة السرعة والوزن."]],"Rack_Pull_with_Bands":["سحب من الحامل بالمطاط",["ضع البار على مساند القفص عند النقطة المطلوبة (تحت الركبتين أو فوقهما أو منتصف الفخذ). اربط المطاط بقاعدة القفص من طرف وبالبار من الطرف الآخر.","قف أمام البار بوضعية الديدلفت: القدمان تحت الحوض، القبضة بعرض الكتفين، الظهر مقوّس والحوض للخلف. يمكنك استخدام قبضة مختلطة أو أحزمة الرسغ.","والنظر للأمام، افرد الحوض والركبتين واسحب الوزن للأعلى وللخلف حتى القفل، مع إرجاع الكتفين. أعد الوزن إلى المساند وكرّر."]],"Rack_Pulls":["سحب من الحامل (راك بول)",["ضع البار على مساند القفص عند النقطة المطلوبة (تحت الركبتين أو فوقهما أو منتصف الفخذ). قف أمامه بوضعية الديدلفت: القدمان تحت الحوض، القبضة بعرض الكتفين، الظهر مقوّس والحوض للخلف. يمكنك استخدام قبضة مختلطة أو أحزمة الرسغ.","والنظر للأمام، افرد الحوض والركبتين واسحب الوزن للأعلى وللخلف حتى القفل، مع إرجاع الكتفين.","أعد الوزن إلى المساند وكرّر."]],"Rear_Leg_Raises":["رفع الرجل للخلف",["ابدأ على يديك وركبتيك على حصيرة، والنظر للأمام والركبتان مثنيتان 90°. هذه وضعية البداية.","مدّ رجلًا للأعلى وللخلف بفرد الركبة والورك. كرّر 5–10 مرات ثم بدّل الجهة."]],"Recumbent_Bike":["دراجة بمسند للظهر",["اجلس على الدراجة واضبط المقعد على طولك.","اختر البرنامج من القائمة (قد تحتاج للبدء بالتبديل لتشغيلها). يمكنك إدخال عمرك ووزنك لتقدير السعرات، وتغيير المقاومة، واستخدام المقابض لقياس النبض.","الدراجة بمسند للظهر مريحة ومفيدة للقلب وخفيفة على المفاصل."]],"Return_Push_from_Stance":["دفع عكسي من الوقفة",["تحتاج زميلًا.","ابدأ بوضعية رياضية بنقطتين أو ثلاث نقاط.","عند الإشارة تحرّك إلى وضعية استقبال التمريرة من زميلك.","التقط الكرة الطبية بيديك وارمها إليه فورًا.","يمكنك تنويع التمرين بمسارات ركض مختلفة."]],"Reverse_Band_Bench_Press":["ضغط صدر بمطاط عكسي",["ضع البنش داخل القفص والبار على الارتفاع المناسب. ثبّت المطاط في أعلى القفص واربط طرفه الآخر بالبار، بحيث يخفف الوزن في الأسفل.","استلقِ، اسحب قدميك للخلف وقوّس ظهرك، واضغط لوحي الكتف معًا، وحافظ على هذا الشد.","أخرج البار دون دفع الكتفين للأمام واعصره. أنزله إلى أسفل صدرك أو أعلى بطنك، والبار والرسغ والمرفق على خط واحد.","توقف عند ملامسة جسمك، ثم ادفع البار بأقصى قوة والمرفقان قريبان من الجسم حتى القفل."]],"Reverse_Band_Box_Squat":["بوكس سكوات بمطاط عكسي",["ضع صندوقًا خلفك داخل القفص، وثبّت المطاط في أعلى القفص فوق البار مباشرة واربطه بالبار.","ضع البار على أعلى ظهرك، اضغط لوحي الكتف معًا، وأخرجه مع تقويس أسفل الظهر. باعد القدمين للتركيز على الأرداف وخلفي الفخذ، أو قرّبهما لأمامي الفخذ.","مع شدّ الظهر والبطن، ادفع ركبتيك ومؤخرتك للخارج واجلس للخلف حتى تجلس على الصندوق. توقف ولا ترتد أبدًا.","والوزن على الكعبين، اصعد بقوة عن الصندوق والرأس يقود الحركة، ثم أعد البار إلى الحامل بحذر."]],"Reverse_Band_Deadlift":["ديدلفت بمطاط عكسي",["ضع البار داخل القفص. ثبّت المطاط في أعلى القفص واربط طرفه الآخر بالبار.","قف والبار فوق منتصف قدميك، والقدمان بعرض الحوض. انحنِ وأمسك البار بعرض الكتفين بقبضة علوية أو مختلطة.","خذ نفسًا عميقًا وأنزل حوضك حتى تلامس ساقاك البار. انظر للأمام وارفع صدرك وقوّس ظهرك، وادفع بكعبيك لترفع الوزن.","بعد تجاوز الركبتين اسحب البار للخلف وادفع حوضك نحوه واضغط لوحي الكتف معًا.","أنزل البار بثني الحوض وتوجيهه إلى الأرض."]],"Reverse_Band_Power_Squat":["سكوات قوة بمطاط عكسي",["اضبط المساند والبار داخل القفص على الارتفاع المناسب. بعد تحميل البار، ثبّت المطاط في أعلى القفص واربطه بالبار.","ضع البار على أعلى ظهرك، اضغط لوحي الكتف معًا، وأخرجه مع تقويس أسفل الظهر. باعد القدمين للتركيز على الأرداف وخلفي الفخذ.","النظر للأمام، ومع شدّ الظهر والبطن ادفع ركبتيك ومؤخرتك للخارج واجلس للخلف قدر الإمكان، حتى يصبح مفصل الورك أسفل مستوى الركبة.","والوزن على الكعبين وركبتاك للخارج، اصعد بقوة والرأس يقود الحركة حتى تعود إلى البداية."]],"Reverse_Band_Sumo_Deadlift":["ديدلفت سومو بمطاط عكسي",["البار المحمّل على الأرض داخل القفص. ثبّت المطاط في أعلى القفص واربطه بالبار.","اقترب من البار بحيث يكون فوق منتصف قدميك، والقدمان متباعدتان كثيرًا. انحنِ من الحوض وأمسك البار والذراعان تحت الكتفين بين الرجلين، وأرخِ كتفيك.","خذ نفسًا، أنزل حوضك والنظر للأمام والصدر مرفوع. ادفع الأرض كأنك تباعد قدميك، وافرد الحوض والركبتين.","عندما يتجاوز البار الركبتين، مِل للخلف وادفع حوضك نحو البار واضغط لوحي الكتف معًا.","أعد الوزن إلى الأرض بثني الحوض والتحكّم بالنزول."]],"Reverse_Barbell_Curl":["باي بالبار بقبضة علوية",["قف باستقامة وأمسك البار بعرض الكتفين بقبضة علوية (الكفّان للأسفل)، والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ البار وأنت تزفر حتى مستوى الكتفين، واعصر ثانية. الساعدان فقط يتحركان.","أنزل البار ببطء وأنت تشهق."]],"Reverse_Barbell_Preacher_Curls":["باي بالبار على المسند بقبضة علوية",["أمسك بار EZ بعرض الكتفين بقبضة علوية (الكفّان للأسفل).","ضع عضديك على مسند البريتشر والذراعان ممدودتان. هذه وضعية البداية.","ازفر واثنِ البار حتى مستوى الكتفين، واعصر ثانية.","اشهق وأنزله ببطء حتى تمتد ذراعاك بالكامل."]],"Reverse_Cable_Curl":["باي بالكيبل بقبضة علوية",["قف باستقامة وأمسك البار المركّب على الكيبل السفلي بعرض الكتفين بقبضة علوية، والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ البار وأنت تزفر حتى مستوى الكتفين، واعصر ثانية. الساعدان فقط يتحركان.","أنزله ببطء وأنت تشهق."]],"Reverse_Crunch":["كرنش عكسي",["استلقِ على الأرض والرجلان ممدودتان والذراعان بجانبك والكفّان على الأرض. الذراعان ثابتتان طوال التمرين.","ارفع رجليك بحيث يكون الفخذان عموديين على الأرض والقدمان معًا موازيتين لها. هذه وضعية البداية.","حرّك رجليك نحو جذعك مع لفّ الحوض للخلف ورفعه عن الأرض، حتى تلمس ركبتاك صدرك.","اثبت ثانية، ثم أعد رجليك إلى البداية. ازفر عند الرفع واشهق عند النزول."]],"Reverse_Flyes":["تفتيح عكسي (كتف خلفي)",["انبطح على بنش مائل والصدر والبطن على المسند، ودمبل في كل يد بقبضة محايدة.","مدّ ذراعيك أمامك عموديتين على البنش، والرجلان ثابتتان على مقدمة القدمين. هذه وضعية البداية.","مع ثني بسيط في المرفقين، افتح الدمبلين للجانبين في قوس وأنت تزفر، واضغط لوحي الكتف معًا.","ارفع ذراعيك حتى تصبحا موازيتين للأرض.","اشعر بالانقباض ثم أنزلهما ببطء وأنت تشهق."]],"Reverse_Flyes_With_External_Rotation":["تفتيح عكسي مع تدوير الكتف للخارج",["انبطح على بنش مائل بزاوية 30° والصدر والبطن على المسند.","دمبل في كل يد والكفّان للأسفل، والذراعان أمامك عموديتان على البنش مع ثني بسيط في المرفقين. الرجلان ثابتتان على مقدمة القدمين. هذه وضعية البداية.","افتح الدمبلين للجانبين في قوس وأنت تزفر.","أثناء الرفع دوّر رسغيك 90° للخارج لتنتقل من قبضة علوية إلى محايدة، واضغط لوحي الكتف معًا.","ارفع ذراعيك حتى مستوى رأسك، ثم أنزلهما ببطء وأنت تشهق."]],"Reverse_Grip_Bent-Over_Rows":["تجديف بالبار منحنيًا بقبضة سفلية",["قف باستقامة وأمسك البار بقبضة سفلية (الكفّان للأعلى).","اثنِ ركبتيك قليلًا وانحنِ من الخصر بظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. الرأس مرفوع والبار متدلٍّ أمامك.","ثبّت جذعك واسحب البار وأنت تزفر، والمرفقان قريبان من الجسم. اعصر الظهر ثانية في الأعلى.","أنزل البار ببطء وأنت تشهق."]],"Reverse_Grip_Triceps_Pushdown":["تراي للأسفل بقبضة سفلية",["ركّب بارًا (مستقيمًا أو EZ) على الكيبل العلوي.","قف مقابله وأمسكه بقبضة سفلية بعرض الكتفين، واسحبه للأسفل حتى تمتد ذراعاك بجانبك. المرفقان ملتصقان بجانبيك. هذه وضعية البداية.","اشهق ودع البار يرتفع ببطء حتى مستوى صدرك. الساعدان فقط يتحركان.","ازفر وأنزل البار إلى البداية بعصر التراي بقوة."]],"Reverse_Hyperextension":["تمديد الظهر العكسي (ريفرس هايبر)",["ضع الوزن المناسب وثبّت قدميك بين المساند، وانبطح على المسند العلوي والحوض متدلٍّ خلفه، وأمسك المقابض.","اثنِ حوضك لتسحب رجليك للأمام.","افرد حوضك لتركل رجليك للخلف، دون أن تبالغ في مدّ الحوض. توقف قبل أقصى مدى.","عد بثني الحوض مرة أخرى."]],"Reverse_Machine_Flyes":["فراشة عكسية (كتف خلفي)",["اضبط المقابض في أقصى الخلف، اختر الوزن واضبط المقعد بحيث تكون المقابض بمستوى الكتفين. أمسكها والكفّان للداخل. هذه وضعية البداية.","اسحب يديك للجانبين وللخلف في نصف دائرة، وأنت تعصر الكتف الخلفي.","الذراعان مثنيتان قليلًا طوال الحركة، والحركة من مفصل الكتف فقط.","توقف في الخلف، ثم أعد الوزن ببطء."]],"Reverse_Plate_Curls":["باي بالقرص بقبضة علوية",["قف باستقامة وأمسك قرصًا بيديك والذراعان ممدودتان، بقبضة علوية عند الساعة 11 والساعة 1، والأصابع على الجهة الخشنة والإبهام على الملساء.","القدمان بعرض الكتفين والقرص أمام أسفل البطن. هذه وضعية البداية.","ارفع القرص ببطء مع إبقاء المرفقين للداخل والعضدين ثابتين، حتى يلامس الساعدان الباي، وأنت تزفر.","اثبت ثانية، ثم أنزله ببطء وأنت تشهق."]],"Reverse_Triceps_Bench_Press":["ضغط صدر للتراي بقبضة معكوسة",["استلقِ على بنش مستوٍ وأمسك البار بقبضة سفلية ضيقة (بعرض الكتفين تقريبًا)، ارفعه من الحامل والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى يلمس منتصف صدرك، والمرفقان قريبان من الجسم دائمًا للتركيز على التراي.","توقف ثانية، ثم ادفعه بالتراي إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد البار إلى الحامل."]],"Rhomboids-SMR":["تدليك المعينيات بالفوم رولر",["استلقِ على ظهرك وضع الفوم رولر تحت أعلى ظهرك، واعقد ذراعيك أمامك. هذه وضعية البداية.","ارفع حوضك عن الأرض والوزن على الرولر. انقل وزنك إلى جانب واحد كل مرة وتدحرج على منتصف وأعلى الظهر، وتوقف 10–30 ثانية عند نقاط الشد."]],"Rickshaw_Carry":["حمل الريكشا",["ضع إطار الريكشا عند نقطة البداية وحمّله بالوزن المناسب. قف في منتصفه وأمسك المقابض وارفعه بالدفع بكعبيك، والصدر والرأس مرفوعان والظهر مستقيم.","امشِ فورًا بخطوات سريعة ومتحكّم بها، والصدر مرفوع والنظر للأمام، وتنفّس باستمرار. أنزل الإطار عند نقطة النهاية."]],"Rickshaw_Deadlift":["ديدلفت الريكشا",["حمّل إطار الريكشا بالوزن المطلوب وقف في منتصف المقابض، والقدمان بعرض الحوض. انحنِ وأمسك المقابض.","خذ نفسًا عميقًا، أنزل حوضك واثنِ ركبتيك. انظر للأمام وارفع صدرك وقوّس ظهرك، وادفع بكعبيك لترفع الوزن، مع ضم لوحي الكتف ودفع الحوض للأمام.","أنزل الوزن بثني الحوض وتوجيهه إلى الأرض."]],"Ring_Dips":["متوازي على الحلقات",["أمسك حلقة بكل يد، واقفز قليلًا لترتفع والذراعان مقفلتان.","اثنِ المرفقين وانزل حتى تصبح الزاوية في الذراعين أقل من 90°، دون تأرجح ومع وضعية جيدة.","افرد المرفقين لتعود إلى البداية."]],"Rocket_Jump":["قفزة الصاروخ",["قف بوضعية مرتاحة والقدمان بعرض الكتفين والذراعان قريبتان من الجسم.","انزل إلى نصف سكوات ثم انطلق للأعلى لأقصى ارتفاع.","افرد جسمك كله ومدّ ذراعيك فوق رأسك لأبعد حد. عند الهبوط امتص الصدمة برجليك."]],"Rocking_Standing_Calf_Raise":["سمانة وقوف مع التأرجح",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار على ارتفاع مناسب وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسك البار وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، الرأس مرفوع والظهر مستقيم والركبتان مثنيتان قليلًا.","ارفع كعبيك لأعلى ما يمكن وأنت تزفر وتعصر السمانة، والركبتان ثابتتان. اثبت ثانية.","انزل ببطء حتى تتمدد السمانة وأنت تشهق.","ارفع مقدمة قدميك بعصر عضلة الساق الأمامية وأنت تزفر، اثبت ثانية ثم أنزلهما."]],"Rocky_Pull-Ups_Pulldowns":["عقلة وسحب روكي",["أمسك بار العقلة بقبضة علوية واسعة.","والذراعان ممدودتان، مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","اسحب جسمك حتى يلمس البار أعلى صدرك، بسحب الكتفين والعضدين للأسفل وللخلف، وأنت تزفر. اعصر الظهر.","بعد ثانية، اشهق وانزل ببطء حتى تمتد ذراعاك.","في التكرار التالي اصعد والجذع مستقيم بحيث يلمس البار خلف رقبتك، مع إمالة الرأس للأمام قليلًا.","انزل إلى البداية، وتابع بالتبادل."]],"Romanian_Deadlift":["ديدلفت روماني",["ضع البار أمامك على الأرض وأمسكه بقبضة علوية أعرض قليلًا من الكتفين. قد تحتاج أحزمة الرسغ مع الأوزان الثقيلة.","اثنِ ركبتيك قليلًا، الساقان عموديتان والحوض للخلف والظهر مستقيم.","مع ظهر وذراعين مستقيمتين دائمًا، ارفع البار بالحوض وأنت تزفر، بحركة ثابتة ومتحكّم بها.","بعد الوقوف الكامل، أنزل البار بدفع الحوض للخلف مع ثني بسيط فقط في الركبتين، لا كالسكوات. خذ نفسًا عميقًا في البداية وارفع صدرك."]],"Romanian_Deadlift_from_Deficit":["ديدلفت روماني من منصة مرتفعة",["قف وأمسك البار أمامك والذراعان ممدودتان. يمكنك الوقوف على منصة مرتفعة لزيادة المدى.","اثنِ ركبتيك قليلًا، ثم انحنِ من الحوض بدفع مؤخرتك للخلف لأقصى حد، وأنزل جذعك بقدر ما تسمح مرونتك. الظهر مستقيم تمامًا والبار ملامس لرجليك. يجب أن تشعر بشد قوي في خلفي الفخذ.","اعكس الحركة لتعود إلى البداية."]],"Rope_Climb":["تسلق الحبل",["أمسك الحبل بيديك فوق رأسك، واسحبه وأنت تقفز قليلًا.","لفّ الحبل حول رجل واحدة واضغطه بقدميك. مدّ ذراعيك لأعلى ما يمكن وأمسك الحبل بقوة.","حرّر قدميك واسحب نفسك بذراعيك مع رفع ركبتيك نحو صدرك.","ثبّت قدميك على الحبل مجددًا، ثم قف لتمسك أعلى. تابع حتى أعلى الحبل.","للنزول، أرخِ قبضة قدميك وانزل بتحريك يديك واحدة بعد الأخرى."]],"Rope_Crunch":["كرنش بالحبل",["اركع على بعد 30–60 سم أمام الكيبل المركّب عليه حبل.","اختر الوزن وأمسك الحبل بيديك فوق رأسك، والجذع مستقيم. هذه وضعية البداية.","اثنِ عمودك الفقري محاولًا تقريب قفصك الصدري من رجليك وأنت تسحب الكيبل للأسفل.","توقف في الأسفل، ثم عد ببطء. يمكنك إضافة لفّ أو ميلان جانبي لتشغيل الخواصر."]],"Rope_Jumping":["نطّ الحبل",["أمسك طرف الحبل بكل يد والحبل خلفك على الأرض. ارفع ذراعيك وأدِر الحبل فوق رأسك إلى الأمام، واقفز فوقه عندما يصل إلى الأرض. حافظ على إيقاع مناسب، ونوّع السرعات والأساليب.","نطّ الحبل ممتع ويتحدى التوافق ويحتاج طاقة كبيرة."]],"Rope_Straight-Arm_Pulldown":["سحب للأسفل بذراعين مستقيمتين بالحبل",["ركّب حبلًا على الكيبل العلوي واختر الوزن. قف على بعد خطوة بقدمين متباعدتين للأمام والخلف، وأمسك الحبل بيديك. انحنِ من الحوض بظهر مستقيم، والذراعان ممدودتان للأعلى أمامك. هذه وضعية البداية.","مع إبقاء الذراعين مستقيمتين، اسحب الحبل للأسفل حتى فخذيك.","توقف في الأسفل واعصر عضلات الظهر (اللاتس).","عد إلى البداية دون أن يرتاح الوزن على المكدّس."]],"Round_The_World_Shoulder_Stretch":["إطالة الكتف حول العالم",["قف باستقامة والرجلان معًا وأمسك عصا أو بارًا خفيفًا.","أمسكه خلف حوضك بقبضة أعرض من الكتفين، والكفّان للأسفل والإبهامان للخارج.","ارفع ذراعيك ببطء خلف رأسك. لا تجبر الحركة إذا صعبت."]],"Rowing_Stationary":["جهاز التجديف",["اجلس على جهاز التجديف، والكعبان على قاعدة المساند والأحزمة مثبتة. اختر البرنامج إن وُجد. اجلس باستقامة ومِل من الحوض للأمام.","المرحلة الأولى: تقدّم للأمام والركبتان مثنيتان قريبتان من صدرك، والجذع مائل للأمام قليلًا. ثم ادفع بقدميك وافرد رجليك وأنت تسحب المقبض إلى أعلى بطنك وتضم لوحي الكتف. اعتمد على الرجلين والحوض لحماية الظهر.","مرحلة العودة: افرد ذراعيك، اثنِ ركبتيك، وتقدّم بجسمك للأمام لتبدأ من جديد."]],"Runners_Stretch":["إطالة العدّاء",["الأسهل أن تبدأ واقفًا، ثم ترجع رجلًا للخلف وتنزل بجذعك ببطء نحو الأرض.","أبقِ الكعب الأمامي على الأرض (إذا ارتفع أرجع الرجل الخلفية أكثر).","ضع يديك على جانبي الرجل الأمامية. لإطالة أكبر ارفع مؤخرتك نحو السقف ثم أنزلها تدريجيًا. تطيل ثانيات الورك للرجل الخلفية وخلفي الفخذ والأرداف للأمامية."]],"Running_Treadmill":["ركض على جهاز المشي",["اصعد على جهاز المشي واختر البرنامج: يدوي أو جاهز. يمكنك إدخال عمرك ووزنك لتقدير السعرات، وتغيير الميل لتغيير الشدة.","جهاز المشي مريح ومفيد للقلب وأخف على المفاصل من الركض في الخارج. حافظ على وضعية جيدة، وأمسك المقابض فقط عند الحاجة كالنزول أو قياس النبض."]],"Russian_Twist":["الالتفاف الروسي",["اجلس على الأرض وثبّت قدميك تحت شيء ثابت أو اطلب من زميل إمساكهما، والركبتان مثنيتان.","ارفع جذعك بحيث يشكّل مع فخذيك حرف V، والذراعان ممدودتان أمامك واليدان متشابكتان. هذه وضعية البداية.","لفّ جذعك إلى اليمين حتى تصبح ذراعاك موازيتين للأرض، وأنت تزفر.","اثبت ثانية ثم عد إلى المنتصف، وكرّر إلى اليسار."]],"Sandbag_Load":["رفع كيس الرمل",["ضع أكياس الرمل على مسافة من منصة التحميل (عادةً 15 مترًا).","ارفع الكيس، وهو غير متوازن عادةً. لفّ ذراعيك حوله قدر الإمكان وافرد الحوض والركبتين لترفعه عاليًا. لا يُسمح عادةً بوضعه على الكتف.","امشِ بسرعة إلى المنصة وحمّله عليها بفرد الحوض والركبتين والكاحلين، وتأكد أنه لن يسقط.","عد لأخذ الكيس التالي وكرّر حتى النهاية."]],"Scapular_Pull-Up":["عقلة لوحي الكتف",["أمسك بار العقلة بقبضة علوية.","من وضع التعلّق، ارفع جسمك بضعة سنتيمترات دون ثني الذراعين، بإنزال لوحي الكتف للأسفل (عكس الشراغ).","توقف في النهاية، ثم عد ببطء إلى البداية."]],"Scissor_Kick":["ركلة المقص",["استلقِ على ظهرك والذراعان ممدودتان للجانبين والكفّان للأسفل. الذراعان ثابتتان طوال الوقت.","مع ثني بسيط في الركبتين، ارفع رجليك حتى يصبح الكعبان على بعد 15 سم عن الأرض. هذه وضعية البداية.","ارفع الرجل اليسرى إلى نحو 45° وأنزل اليمنى حتى يصبح كعبها على بعد 5–8 سم من الأرض.","بدّل: ارفع اليمنى وأنزل اليسرى. تنفّس بانتظام وتابع."]],"Scissors_Jump":["قفزة المقص",["اتخذ وضعية اللانج: قدم للأمام والركبة مثنية، والركبة الخلفية تكاد تلمس الأرض.","الركبة الأمامية فوق منتصف القدم. افرد الرجلين واقفز لأعلى ما تستطيع مع أرجحة الذراعين.","في الهواء بدّل وضع الرجلين: الأمامية للخلف والخلفية للأمام.","اهبط في وضعية اللانج وامتص الصدمة، وكرّر."]],"Seated_Band_Hamstring_Curl":["خلفي جالس بالمطاط",["ثبّت مطاطًا قريبًا من الأرض، وضع بنشًا على بعد خطوة منه.","اجلس على البنش وثبّت المطاط خلف كاحليك، والرجلان مستقيمتان. هذه وضعية البداية.","اثنِ ركبتيك لتسحب قدميك نحو البنش. قد تحتاج للميلان للخلف قليلًا حتى لا تلمس قدماك الأرض.","توقف في النهاية، ثم عد ببطء."]],"Seated_Barbell_Military_Press":["ضغط عسكري بالبار جلوسًا",["اجلس على بنش الضغط العسكري والبار خلف رأسك. اطلب من أحد أن يناولك البار (أفضل للكتف) أو ارفعه بحذر بقبضة علوية أعرض من الكتفين.","ارفع البار فوق رأسك حتى تمتد ذراعاك، أمام رأسك بقليل. هذه وضعية البداية.","أنزل البار ببطء إلى مستوى الترقوة وأنت تشهق.","ارفعه إلى البداية وأنت تزفر."]],"Seated_Barbell_Twist":["لفّ الجذع بالبار جلوسًا",["اجلس على طرف بنش مستوٍ والبار على فخذيك، والقدمان بعرض الكتفين.","أمسك البار بقبضة علوية أعرض من الكتفين، وارفعه فوق رأسك حتى تمتد ذراعاك.","أنزله خلف رأسك حتى يستقر على أسفل الرقبة. هذه وضعية البداية.","مع ثبات القدمين والرأس، لفّ خصرك من جانب إلى آخر بقدر ما يسمح به جسمك فقط، ببطء وتحكّم. المبالغة قد تسبب إصابة.","ازفر أثناء اللفّ واشهق أثناء العودة."]],"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":["تراي بالدمبل بيد واحدة جالسًا ومنحنيًا",["اجلس على طرف بنش مستوٍ ودمبل في يد واحدة بقبضة محايدة.","اثنِ ركبتيك قليلًا وانحنِ من الخصر بظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض، والرأس مرفوع.","ارفع العضد حتى يصبح موازيًا للأرض بجانب جذعك، والساعد متدلٍّ للأسفل بزاوية 90°. هذه وضعية البداية.","ثبّت العضد وارفع الدمبل بالتراي حتى تمتد ذراعك موازية للأرض، وأنت تزفر. الساعد فقط يتحرك.","اعصر ثانية ثم أنزله ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الذراع."]],"Seated_Bent-Over_Rear_Delt_Raise":["كتف خلفي جالسًا ومنحنيًا",["ضع دمبلين أمام بنش مستوٍ.","اجلس على طرف البنش والرجلان معًا، والدمبلان خلف سمانتيك.","انحنِ من الخصر بظهر مستقيم والتقط الدمبلين والكفّان متقابلتان. هذه وضعية البداية.","ثبّت جذعك منحنيًا، ومع ثني بسيط في المرفقين ارفع الدمبلين جانبيًا حتى تصبح ذراعاك موازيتين للأرض، وأنت تزفر. لا تؤرجح جسمك ولا ترجع ذراعيك للخلف.","اثبت ثانية ثم أنزلهما ببطء."]],"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":["تراي بدمبلين جالسًا ومنحنيًا",["اجلس على طرف بنش مستوٍ ودمبل في كل يد بقبضة محايدة.","اثنِ ركبتيك قليلًا وانحنِ من الخصر بظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض، والرأس مرفوع.","ارفع العضدين حتى يصبحا موازيين للأرض بجانب جذعك، والساعدان متدليان بزاوية 90°. هذه وضعية البداية.","ثبّت العضدين وارفع الدمبلين بالتراي حتى تمتد ذراعاك موازيتين للأرض، وأنت تزفر.","اعصر ثانية ثم أنزلهما ببطء وأنت تشهق."]],"Seated_Biceps":["إطالة الباي جلوسًا",["اجلس على الأرض والركبتان مثنيتان وزميلك واقف خلفك. مدّ ذراعيك مستقيمتين خلفك والكفّان متقابلتان، ويمسك زميلك رسغيك. هذه وضعية البداية.","حاول ثني مرفقيك بينما يمنع زميلك أي حركة.","بعد 10–20 ثانية أرخِ ذراعيك بينما يرفع زميلك رسغيك برفق لإطالة الباي. أخبره عندما تكفي الإطالة."]],"Seated_Cable_Rows":["تجديف بالكيبل جلوسًا (سيتد رو)",["اجلس على جهاز التجديف بالكيبل السفلي المركّب عليه مقبض V (قبضة محايدة)، وضع قدميك على المسند الأمامي مع ثني بسيط في الركبتين.","مِل للأمام مع ظهر مستقيم وأمسك المقبض.","اسحب للخلف والذراعان ممدودتان حتى يصبح جذعك عموديًا على رجليك، الظهر مقوّس قليلًا والصدر للأمام، وتشعر بإطالة في الظهر. هذه وضعية البداية.","ثبّت جذعك واسحب المقبض نحو بطنك والذراعان قريبتان من الجسم، وأنت تزفر. اعصر الظهر بقوة ثانية، ثم عد ببطء وأنت تشهق."]],"Seated_Cable_Shoulder_Press":["ضغط أكتاف بالكيبل جلوسًا",["اختر الوزن واجلس وأمسك المقابض. العضدان بزاوية 90° عن الجسم والمرفقان مثنيان نحو 90°، والرأس والصدر مرفوعان.","مدّ مرفقيك واضغط المقابض فوق رأسك نحو بعضها.","توقف في الأعلى، ثم عد إلى البداية مع إبقاء الشد على الكيبل.","يمكنك أداؤه دون الاستناد إلى المسند، أو بيد واحدة بالتبادل."]],"Seated_Calf_Raise":["سمانة جلوس",["اجلس على الجهاز وضع مقدمة قدميك على الطرف السفلي للمنصة والكعبان خارجها.","ضع أسفل فخذيك تحت المسند (اضبطه على طولك)، ويداك فوقه حتى لا ينزلق.","ارفع المسند قليلًا بدفع كعبيك وحرّر ذراع الأمان. هذه وضعية البداية.","أنزل كعبيك ببطء حتى تتمدد السمانة بالكامل، وأنت تشهق.","ارفع كعبيك لأعلى ما يمكن وأنت تعصر السمانة وتزفر، واثبت ثانية."]],"Seated_Calf_Stretch":["إطالة السمانة جلوسًا",["اجلس باستقامة على حصيرة.","اثنِ ركبة وضع القدم على الأرض لتثبيت الجذع.","افرد الرجل الأخرى واثنِ الكاحل نحوك.","بمطاط أو منشفة أو بيدك إن وصلت، اسحب أصابع القدم نحوك. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Seated_Close-Grip_Concentration_Barbell_Curl":["باي تركيز بالبار جالسًا بقبضة ضيقة",["اجلس على بنش مستوٍ والبار أو بار EZ أمامك بين رجليك المتباعدتين، والقدمان على الأرض.","ارفع البار وضع خلف عضديك على الجزء الداخلي من فخذيك قرب الركبتين، بقبضة سفلية أضيق من الكتفين والذراعان ممدودتان.","ثبّت العضدين واثنِ البار وأنت تزفر حتى مستوى الكتفين، واعصر الباي ثانية.","أنزله ببطء وأنت تشهق، دون تأرجح."]],"Seated_Dumbbell_Curl":["باي دمبل جلوسًا",["اجلس على بنش مستوٍ ودمبل في كل يد والذراعان ممدودتان، والمرفقان قريبان من الجسم.","الكفّان نحو جسمك. هذه وضعية البداية.","ثبّت العضدين واثنِ الدمبلين، وبعد تجاوزهما الفخذين لفّ الرسغين لتصبح الكفّان للأمام في النهاية. ازفر واعصر الباي ثانية في مستوى الكتفين.","أنزلهما ببطء وأنت تشهق، مع إعادة الرسغين إلى القبضة المحايدة."]],"Seated_Dumbbell_Inner_Biceps_Curl":["باي داخلي بالدمبل جلوسًا",["اجلس على طرف بنش مستوٍ ودمبل في كل يد والذراعان ممدودتان، والمرفقان قريبان من الجسم.","الكفّان للداخل (قبضة محايدة). هذه وضعية البداية.","ثبّت العضدين واثنِ الدمبلين للخارج وللأعلى، مع لفّ الكفّين للخارج، والساعدان على خط الكتفين الجانبيين، حتى مستوى الكتفين. اعصر ثانية.","أنزلهما ببطء وأنت تشهق، مع العودة إلى القبضة المحايدة."]],"Seated_Dumbbell_Palms-Down_Wrist_Curl":["ثني الرسغ بالدمبل والكف للأسفل جلوسًا",["ضع دمبلين على الأرض أمام بنش مستوٍ.","اجلس على طرف البنش والرجلان بعرض الكتفين والقدمان على الأرض.","أمسك الدمبلين واسند ساعديك على فخذيك والكفّان للأسفل، والرسغان خارج حافة الفخذين.","اثنِ رسغيك للأعلى وأنت تزفر.","أنزلهما ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك. عند الانتهاء أنزل الدمبلين إلى الأرض."]],"Seated_Dumbbell_Palms-Up_Wrist_Curl":["ثني الرسغ بالدمبل والكف للأعلى جلوسًا",["ضع دمبلين على الأرض أمام بنش مستوٍ.","اجلس على طرف البنش والرجلان بعرض الكتفين والقدمان على الأرض.","أمسك الدمبلين واسند ساعديك على فخذيك والكفّان للأعلى، والرسغان خارج حافة الفخذين.","اثنِ رسغيك للأعلى وأنت تزفر.","أنزلهما ببطء وأنت تشهق. الساعدان ثابتان والرسغ فقط يتحرك. عند الانتهاء أنزل الدمبلين إلى الأرض."]],"Seated_Dumbbell_Press":["ضغط أكتاف بالدمبل جلوسًا",["خذ دمبلين واجلس على بنش بمسند للظهر، والدمبلان واقفان على فخذيك.","ارفعهما إلى مستوى الكتفين واحدًا تلو الآخر بمساعدة فخذيك.","لفّ رسغيك لتصبح الكفّان للأمام. هذه وضعية البداية.","ازفر وادفع الدمبلين للأعلى حتى يتلامسا.","توقف ثانية، ثم أنزلهما ببطء وأنت تشهق."]],"Seated_Flat_Bench_Leg_Pull-In":["سحب الركبتين جالسًا على بنش مستوٍ",["اجلس على بنش والرجلان ممدودتان أمامك أسفل الموازاة بقليل، وأمسك جانبي البنش، والجذع مائل للخلف نحو 45°. هذه وضعية البداية.","قرّب ركبتيك منك وفي الوقت نفسه قرّب جذعك منهما، وأنت تزفر.","توقف ثانية، ثم عد إلى البداية وأنت تشهق."]],"Seated_Floor_Hamstring_Stretch":["إطالة خلفي الفخذ جالسًا على الأرض",["اجلس على حصيرة والرجل اليمنى ممدودة أمامك، واليسرى مثنية وقدمها على الفخذ الداخلي الأيمن.","مِل للأمام من الحوض ومدّ يدك نحو كاحلك حتى تشعر بإطالة في خلفي الفخذ. اثبت 15 ثانية ثم بدّل الجهة."]],"Seated_Front_Deltoid":["إطالة الكتف الأمامي جلوسًا",["اجلس باستقامة على الأرض والرجلان مثنيتان، وزميلك واقف خلفك. افتح ذراعيك للجانبين والكفّان للأسفل، وحرّكهما للخلف قدر الإمكان بينما يمسك زميلك رسغيك. هذه وضعية البداية.","والمرفقان مستقيمان، حاول تحريك ذراعيك للأمام بينما يمنعك زميلك برفق لمدة 10–20 ثانية.","أرخِ عضلاتك ودع زميلك يزيد إطالة الكتفين والصدر برفق. اثبت 10–20 ثانية."]],"Seated_Glute":["إطالة الأرداف جلوسًا",["اجلس والركبتان مثنيتان، وضع كاحلًا فوق الركبة المعاكسة. يقف زميلك خلفك. مِل للأمام بينما يسند كتفيك بيديه. هذه وضعية البداية.","حاول دفع جذعك للخلف 10–20 ثانية بينما يمنع زميلك أي حركة.","أرخِ عضلاتك بينما يزيد زميلك الإطالة بدفع جذعك برفق للأمام 10–20 ثانية."]],"Seated_Good_Mornings":["غود مورنينغ جلوسًا",["ضع صندوقًا داخل القفص والمساند على ارتفاع مناسب. ادخل تحت البار وضعه على أعلى ظهرك خلف الكتفين، واضغط لوحي الكتف معًا.","أخرج البار مع تقويس أسفل الظهر، والنظر للأمام، ثم اجلس على الصندوق مع شدّ الظهر والبطن. هذه وضعية البداية.","مع شدّ البار، انحنِ للأمام من الحوض قدر الإمكان. ضبط المساند على مستوى الموازاة يعطيك أمانًا ويحدد لك متى تتوقف.","توقف فوق المساند بقليل، ثم عد حتى يستقيم جذعك."]],"Seated_Hamstring":["إطالة خلفي الفخذ جلوسًا",["اجلس والرجلان ممدودتان وزميلك واقف خلفك. مِل للأمام بينما يسند كتفيك بيديه. هذه وضعية البداية.","حاول دفع جذعك للخلف 10–20 ثانية بينما يمنع زميلك أي حركة.","أرخِ عضلاتك بينما يزيد زميلك الإطالة بدفع جذعك برفق للأمام 10–20 ثانية."]],"Seated_Hamstring_and_Calf_Stretch":["إطالة خلفي الفخذ والسمانة جلوسًا",["لفّ حزامًا أو حبلًا حول قدم واحدة، واجلس والرجلان ممدودتان. هذه وضعية البداية.","مِل للأمام قليلًا واسحب الحزام لتسحب أصابع القدم للخلف. اثبت 10–20 ثانية ثم بدّل الرجل."]],"Seated_Head_Harness_Neck_Resistance":["مقاومة الرقبة بحزام الرأس جلوسًا",["ضع حزام الرقبة على الأرض عند طرف بنش مستوٍ مع الأوزان. اجلس على الطرف والقدمان أوسع من الكتفين والأصابع للخارج.","انحنِ للأمام وثبّت الحزام حول رأسك والأوزان ما زالت على الأرض، ثم أمسك الوزن بيديك وارفع جذعك حتى يصبح شبه عمودي، مع ميلان بسيط للأمام.","ضع يديك على ركبتيك. هذه وضعية البداية.","أنزل رأسك ببطء حتى يلمس ذقنك أعلى صدرك وأنت تشهق.","ارفع رأسك إلى البداية وأنت تزفر. ابدأ بوزن خفيف جدًا."]],"Seated_Leg_Curl":["خلفي جالس (ثني الرجلين جلوسًا)",["اضبط ذراع الجهاز على طولك واجلس وظهرك على المسند.","ضع خلف أسفل ساقيك على المسند المتحرك (تحت السمانة ببضعة سنتيمترات)، وثبّت مسند الفخذين فوق الركبتين. أمسك المقابض الجانبية والرجلان ممدودتان أمامك. هذه وضعية البداية.","ازفر واسحب المسند للخلف لأقصى حد بثني الركبتين، والجذع ثابت. اثبت ثانية.","عد ببطء وأنت تشهق."]],"Seated_Leg_Tucks":["ضم الركبتين جالسًا",["اجلس على بنش والرجلان ممدودتان أمامك أسفل الموازاة بقليل، وأمسك جانبي البنش، والجذع مائل للخلف نحو 45°. هذه وضعية البداية.","قرّب ركبتيك منك وفي الوقت نفسه قرّب جذعك منهما، وأنت تزفر.","توقف ثانية، ثم عد إلى البداية وأنت تشهق."]],"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl":["ثني الرسغ بالدمبل بيد واحدة والكف للأسفل جلوسًا",["اجلس على بنش مستوٍ ودمبل في يدك اليمنى.","القدمان على الأرض بعرض أوسع قليلًا من الكتفين.","مِل للأمام واسند ساعدك الأيمن على فخذك والكف للأسفل، والرسغ فوق الركبة. هذه وضعية البداية.","أنزل الدمبل لأقصى حد مع قبضة محكمة، وأنت تشهق.","اثنِ الرسغ لأعلى ما يمكن وأنت تزفر، واثبت ثانية. الحركة من الرسغ فقط. أكمل التكرارات ثم بدّل اليد."]],"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl":["ثني الرسغ بالدمبل بيد واحدة والكف للأعلى جلوسًا",["اجلس على بنش مستوٍ ودمبل في يدك اليمنى.","القدمان على الأرض بعرض أوسع قليلًا من الكتفين.","مِل للأمام واسند ساعدك الأيمن على فخذك والكف للأعلى، والرسغ فوق الركبة. هذه وضعية البداية.","أنزل الدمبل لأقصى حد مع قبضة محكمة، وأنت تشهق.","اثنِ الرسغ لأعلى ما يمكن وأنت تزفر، واثبت ثانية. الحركة من الرسغ فقط. أكمل التكرارات ثم بدّل اليد."]],"Seated_One-arm_Cable_Pulley_Rows":["تجديف بالكيبل بيد واحدة جلوسًا",["اجلس على جهاز التجديف بالكيبل وضع قدميك على المسند الأمامي مع ثني بسيط في الركبتين.","مِل للأمام بظهر مستقيم وأمسك المقبض الواحد بيدك اليسرى بقبضة علوية.","اسحب للخلف والذراع ممدودة حتى يصبح جذعك عموديًا على رجليك، الظهر مقوّس قليلًا والصدر للأمام. اليد الأخرى على خصرك. هذه وضعية البداية.","ثبّت جذعك واسحب المقبض نحو بطنك والذراع قريبة من الجسم، مع لفّ الرسغ ليصبح محايدًا في النهاية، وأنت تزفر. اعصر الظهر بقوة.","اثبت ثانية، ثم عد ببطء وأنت تشهق مع إعادة الرسغ. أكمل التكرارات ثم بدّل اليد."]],"Seated_Overhead_Stretch":["إطالة فوق الرأس جلوسًا",["اجلس باستقامة على حصيرة.","ألصق باطني قدميك معًا على بعد 15–20 سم أمام حوضك.","ضع يدًا على الأرض بجانبك والأخرى خلف رأسك.","ارفع المرفق نحو السقف وأنت تميل بجذعك إلى الجهة الأخرى. اثبت 10–20 ثانية ثم بدّل الجهة."]],"Seated_Palm-Up_Barbell_Wrist_Curl":["ثني الرسغ بالبار والكف للأعلى جلوسًا",["أمسك البار بيديك والكفّان للأعلى بعرض الكتفين.","القدمان على الأرض بعرض أوسع قليلًا من الكتفين.","مِل للأمام واسند ساعديك على فخذيك والكفّان للأعلى، والرسغان فوق الركبتين. هذه وضعية البداية.","أنزل البار لأقصى حد وأنت تشهق، مع قبضة محكمة.","اثنِ البار لأعلى ما يمكن وأنت تزفر، واثبت ثانية. الرسغ فقط يتحرك."]],"Seated_Palms-Down_Barbell_Wrist_Curl":["ثني الرسغ بالبار والكف للأسفل جلوسًا",["أمسك البار بيديك والكفّان للأسفل بعرض الكتفين.","القدمان على الأرض بعرض أوسع قليلًا من الكتفين.","مِل للأمام واسند ساعديك على فخذيك والكفّان للأسفل، والرسغان فوق الركبتين. هذه وضعية البداية.","أنزل البار لأقصى حد وأنت تشهق، مع قبضة محكمة.","ارفع البار لأعلى ما يمكن بالرسغين وأنت تزفر، واثبت ثانية. الرسغ فقط يتحرك."]],"Seated_Side_Lateral_Raise":["رفرفة جانبية جلوسًا",["خذ دمبلين واجلس على طرف بنش مستوٍ والقدمان ثابتتان على الأرض. أمسكهما بجانبك والكفّان للداخل والذراعان ممدودتان.","مع ثبات الجذع ودون تأرجح، ارفع الدمبلين جانبيًا مع ثني بسيط في المرفقين ويداك مائلتان قليلًا للأمام كأنك تصبّ الماء، حتى تصبح ذراعاك موازيتين للأرض. ازفر واثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Seated_Triceps_Press":["ضغط تراي جلوسًا (خلف الرأس)",["اجلس على بنش بمسند للظهر وأمسك دمبلًا بيديك فوق رأسك والذراعان ممدودتان (الأفضل أن يناولك أحد الدمبل إذا كان ثقيلًا). الدمبل مستقر في كفّيك والإبهامان حوله.","العضدان قريبان من رأسك وعموديان على الأرض، أنزل الدمبل في نصف دائرة خلف رأسك حتى يلمس الساعدان الباي، وأنت تشهق. العضدان ثابتان.","ارفعه إلى البداية بالتراي وأنت تزفر."]],"Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl":["ثني الرسغ بالكيبل السفلي بيدين والكف للأعلى جلوسًا",["ضع بنشًا أمام الكيبل السفلي المركّب عليه بار أو بار EZ.","أبعد البنش بحيث يبقى الكيبل مشدودًا عندما تضع البار على فخذيك.","أمسك البار بيديك بقبضة سفلية بعرض الكتفين.","اجلس على البنش والقدمان بعرض الكتفين على الأرض.","مِل للأمام واسند ساعديك على فخذيك والرسغان فوق الركبتين. هذه وضعية البداية.","أنزل البار لأقصى حد وأنت تشهق، ثم اثنِ رسغيك لأعلى ما يمكن. الرسغ فقط يتحرك.","اثبت ثانية، ثم عد إلى البداية."]],"See-Saw_Press_Alternating_Side_Press":["ضغط أرجوحي (ضغط جانبي بالتبادل)",["قف باستقامة ودمبل في كل يد.","ارفع الدمبلين إلى مستوى الصدر والكتفين والكفّان نحوك، كبداية ضغط أرنولد. هذه وضعية البداية.","اضغط الذراع اليسرى فوق رأسك مع لفّ الكف للأمام، وفي الوقت نفسه مِل من الحوض إلى الجهة المعاكسة، كأنك تمدّ يدك اليسرى لتلتقط شيئًا فوق جانبك الأيمن. ازفر أثناء ذلك.","في الأعلى اشهق، ثم ابدأ الحركة نفسها إلى الجهة الأخرى. تابع بالتبادل."]],"Shotgun_Row":["تجديف شوت غن بالكيبل",["ركّب مقبضًا واحدًا على الكيبل السفلي.","اختر الوزن وقف على بعد خطوة بوقفة مفتوحة واسعة، والذراع ممدودة والكتف للأمام. هذه وضعية البداية.","اسحب بسحب الكتف للخلف وثني المرفق، مع لفّ الرسغ لتصبح الكف للأعلى أثناء السحب.","توقف لحظة، ثم عد إلى البداية."]],"Shoulder_Circles":["دوائر الكتفين",["والكتفان مرتخيان والذراعان بجانبك (أو في حضنك إن كنت جالسًا)، دوّر كتفيك برفق للأمام ثم للأعلى ثم للخلف ثم للأسفل.","اعكس الاتجاه. يمكنك أداؤه بالتبادل أو بالكتفين معًا."]],"Shoulder_Press_-_With_Bands":["ضغط أكتاف بالمطاط",["قف على مطاط التمارين بحيث يبدأ الشد والذراعان ممدودتان. أمسك المقبضين وارفعهما إلى مستوى الكتفين بجانبيك.","لفّ رسغيك لتصبح الكفّان للأمام، والمرفقان مثنيان. هذه وضعية البداية.","ازفر وارفع المقبضين حتى تمتد ذراعاك فوق رأسك، ثم أنزلهما بتحكّم."]],"Shoulder_Raise":["رفع الكتفين",["أرخِ ذراعيك بجانبك وارفع كتفيك نحو أذنيك، ثم أنزلهما."]],"Shoulder_Stretch":["إطالة الكتف",["مدّ ذراعك اليسرى عبر جسمك مستقيمة، واسحبها برفق باليد الأخرى. ثم بدّل الذراع."]],"Side-Lying_Floor_Stretch":["إطالة جانبية مستلقيًا على الأرض",["استلقِ على جنبك الأيسر واثنِ ركبتك اليسرى أمامك لتثبيت الجذع (واستعن ببطنك أيضًا).","افرد رجلك اليمنى وضع قدمها على الأرض خلف اليسرى. مدّ ذراعك اليمنى فوق رأسك واسحب رسغها برفق لإطالة الجانب الأيمن كله. بدّل الجهة."]],"Side_Bridge":["بلانك جانبي (جسر جانبي)"],"Side_Hop-Sprint":["نطّ جانبي ثم عدو",["قف بجانب قمع أو حاجز.","انطّ جانبيًا فوقه، ثم ارتد فورًا لتعود إلى مكانك.","انطّ العدد المحدد بأسرع ما يمكن، ثم اركض مسافة قصيرة بعد آخر نطّة."]],"Side_Jackknife":["جاك نايف جانبي"],"Side_Lateral_Raise":["رفرفة جانبية",["خذ دمبلين وقف باستقامة والدمبلان بجانبك والكفّان نحوك.","مع ثبات الجذع ودون تأرجح، ارفع الدمبلين جانبيًا مع ثني بسيط في المرفقين ويداك مائلتان قليلًا للأمام كأنك تصبّ الماء، حتى تصبح ذراعاك موازيتين للأرض. ازفر واثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Side_Laterals_to_Front_Raise":["رفرفة جانبية ثم أمامية",["قف ودمبل في كل يد بجانبك.","مع ثني بسيط في المرفقين، ارفع الدمبلين جانبيًا حتى مستوى الكتفين دون تأرجح.","في الأعلى حرّكهما أمامك والذراعان ممدودتان، ثم أنزلهما بتحكّم.","في التكرار التالي ارفعهما أمامك حتى مستوى الكتفين، ثم حرّكهما إلى الجانبين، ثم أنزلهما."]],"Side_Leg_Raises":["رفع الرجل جانبيًا",["قف بجانب كرسي وأمسكه للسند، وقف على رجل واحدة. هذه وضعية البداية.","والرجل مستقيمة، ارفعها إلى الجانب لأبعد حد، ثم أرجحها للأسفل لتعبر أمام الرجل الأخرى.","كرّر 5–10 مرات مع زيادة المدى تدريجيًا، ثم بدّل الرجل."]],"Side_Lying_Groin_Stretch":["إطالة الفخذ الداخلي على الجنب",["استلقِ على جنبك الأيمن واثنِ ركبتك اليمنى أمامك لتثبيت الجذع.","أسند رأسك على يدك اليمنى أو كتفك. ارفع رجلك اليسرى وأمسكها من خلف الركبة (أسهل) أو من القدم (أصعب).","اسحب ركبتك اليسرى نحو كتفك الأيسر واضغط القدم أو الركبة نحو الأرض في الوقت نفسه. لزيادة الإطالة افرد الرجل اليسرى. بدّل الجهة."]],"Side_Neck_Stretch":["إطالة الرقبة الجانبية",["والكتفان مرتخيان، أمِل رأسك برفق نحو كتفك.","ساعد الإطالة بسحب خفيف على جانب الرأس. ثم بدّل الجهة."]],"Side_Standing_Long_Jump":["وثب طويل جانبي",["قف والقدمان بعرض الحوض بوضعية رياضية، والرأس والصدر مرفوعان، والركبتان والحوض مثنية قليلًا. هذه وضعية البداية.","مِل إلى اليمين وافرد الحوض والركبتين والكاحلين لتقفز، مستعينًا بذراعيك، لأبعد مسافة إلى اليمين.","اهبط بالاتجاه نفسه والقدمان بعرض الحوض، وامتص الصدمة."]],"Side_To_Side_Chins":["عقلة من جانب إلى جانب",["أمسك بار العقلة بقبضة علوية واسعة.","والذراعان ممدودتان، مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","اسحب جسمك مائلًا نحو اليسار حتى يكاد البار يلمس أعلى صدرك، وأنت تزفر. اعصر الظهر دون تأرجح.","اثبت ثانية ثم انزل وأنت تشهق.","كرّر مائلًا نحو اليمين، ثم انزل. تابع بالتبادل."]],"Side_Wrist_Pull":["سحب الرسغ الجانبي",["يُفضّل واقفًا. اعبر بذراعك اليسرى أمام جسمك وأمسك رسغها بيدك اليمنى بمستوى الحوض، والذراع اليسرى مثنية.","افردها واسحبها وارفعها ببطء حتى مستوى الكتف. اشعر بالإطالة في الظهر لا في الكتف، ولا تسحب بقوة. بدّل الجهة."]],"Side_to_Side_Box_Shuffle":["تنقل جانبي على الصندوق",["قف بجانب الصندوق وقدمك اليسرى على منتصفه.","اقفز للأعلى وإلى الجهة الأخرى، لتهبط بقدمك اليمنى على الصندوق واليسرى على الأرض. أرجح ذراعيك للمساعدة.","تابع التنقل ذهابًا وإيابًا فوق الصندوق."]],"Single-Arm_Cable_Crossover":["تقاطع الكيبل بيد واحدة",["اضبط البكرتين في الأعلى، اختر الوزن وأمسك مقبضًا بكل يد.","تقدّم أمام البكرتين والذراعان ممدودتان أمامك واليدان معًا، والرأس والصدر مرفوعان مع ميلان للأمام والقدمان متباعدتان للأمام والخلف. هذه وضعية البداية.","ثبّت الذراع اليسرى، ودع اليمنى تنفتح للجانب مع ثني بسيط في المرفق حتى مستوى الكتف تقريبًا.","أعدها إلى منتصف الجسم.","اثبت ثانية، ثم كرّر بالجهة الأخرى، وتابع بالتبادل."]],"Single-Arm_Linear_Jammer":["دفع اللاندماين بيد واحدة (جامر)",["ثبّت طرف البار في قاعدة لاندماين أو في زاوية بشكل آمن، وحمّله بالوزن المناسب.","ارفع البار إلى كتفك بيد واحدة أو باليدين، بوقفة واسعة. هذه وضعية البداية.","اضغط الوزن للأعلى بفرد المرفق، بحركة انفجارية مع فرد الحوض والركبتين بالكامل لإنتاج أقصى قوة.","عد إلى البداية."]],"Single-Arm_Push-Up":["ضغط بيد واحدة (بوش أب)",["انبطح على الأرض، ثم ارتفع على أطراف قدميك ويد واحدة تحت الكتف مباشرة والذراع ممدودة. باعد قدميك أكثر من الضغط العادي للتوازن.","حافظ على وضعية جيدة وضع اليد الأخرى خلف ظهرك. هذه وضعية البداية.","انزل بثني المرفق حتى تقترب من الأرض.","انزل ببطء، ثم افرد الذراع لتعود إلى البداية."]],"Single-Cone_Sprint_Drill":["تمرين العدو حول قمع واحد",["تمرين لسرعة القدمين، يحتاج قمعًا واحدًا. قف بجانب القمع وذراع للخلف وأخرى للأمام.","حرّك قدميك بأسرع ما يمكن مع تحريك الذراعين، ودُر حول القمع والركبتان مرفوعتان.","استرح بعد ثلاث دورات حول القمع."]],"Single-Leg_High_Box_Squat":["سكوات برجل واحدة على صندوق عالٍ",["ضع صندوقًا داخل القفص، وثبّت حبلًا أو مطاطًا فوقه للتوازن.","قف أمامه واصعد عليه برجل واحدة حتى تقف بالكامل، والرجل الأخرى معلّقة دون سند. أمسك الحبل للتوازن.","تابع الصعود والنزول بالرجل نفسها، ثم بدّل."]],"Single-Leg_Hop_Progression":["تدرّج النطّ برجل واحدة",["رتّب صفًّا من الأقماع أمامك. قف براحة على رجل واحدة وارفع ركبة الأخرى. هذه وضعية البداية.","انطّ للأمام فوق القمع واهبط على الرجل نفسها.","انطّ من قمع إلى قمع.","في النهاية استدر وعد على الرجل الأخرى."]],"Single-Leg_Lateral_Hop":["نطّ جانبي برجل واحدة",["قف بجانب قمع أو حاجز على رجل واحدة والركبة مثنية قليلًا.","انطّ جانبيًا فوق القمع.","اهبط على الرجل نفسها وارتد فورًا لتعود إلى البداية.","تابع ذهابًا وإيابًا."]],"Single-Leg_Leg_Extension":["أمامي جهاز برجل واحدة",["اجلس على الجهاز واضبطه: المسند على أسفل الساق دون أن يلامس الكاحل، ومحور الجهاز على خط الركبة. اختر وزنًا مناسبًا.","بوضعية جيدة، مدّ رجلًا واحدة بالكامل وتوقف في الأعلى.","عد إلى البداية دون أن يتوقف الوزن، لتبقى العضلة تحت الشد.","أكمل التكرارات ثم بدّل الرجل."]],"Single-Leg_Stride_Jump":["قفزة الخطوة برجل واحدة",["قف بجانب صندوق وقدمك الداخلية عليه قرب الحافة.","أرجح ذراعيك للأعلى وادفع بالرجل التي على الصندوق لتقفز لأعلى ما يمكن، مع رفع الركبة المعاكسة.","اهبط في وضعية البداية نفسها، والرجل الداخلية تخفف الصدمة."]],"Single_Dumbbell_Raise":["رفرفة بدمبل واحد",["بوقفة واسعة، أمسك دمبلًا بيديك من رأسه لا من المقبض، والذراعان ممدودتان متدليتان أمام الخصر. هذه وضعية البداية.","ارفع الدمبل حتى أعلى من مستوى الكتفين والذراعان ممدودتان. الجذع والحوض ثابتان.","عد إلى البداية وكرّر."]],"Single_Leg_Butt_Kick":["ركل المؤخرة برجل واحدة",["قف على رجل واحدة والركبة الأخرى مرفوعة مثنية. هذه وضعية البداية.","انزل قليلًا ثم اقفز للأعلى بفرد ورك وركبة وكاحل الرجل الأرضية.","اثنِ ركبة الرجل القافزة فورًا محاولًا لمس مؤخرتك بكعبها.","أعد الرجل مثنية جزئيًا تحت الحوض واهبط. الرجل الأخرى تبقى في وضعها تقريبًا."]],"Single_Leg_Glute_Bridge":["جسر الأرداف برجل واحدة",["استلقِ على ظهرك والقدمان على الأرض والركبتان مثنيتان.","ارفع رجلًا واحدة واسحب ركبتها نحو صدرك. هذه وضعية البداية.","ادفع بكعب القدم الأخرى وارفع حوضك ومؤخرتك عن الأرض.","ارتفع لأقصى حد، توقف، ثم انزل. أكمل التكرارات ثم بدّل الرجل."]],"Single_Leg_Push-off":["دفع برجل واحدة",["قف على الأرض وقدم واحدة على الصندوق والكعب قرب الحافة.","ادفع بالقدم التي على الصندوق لأعلى ما يمكن بفرد الورك والركبة.","اهبط بالقدم نفسها على الصندوق وأعد الأخرى إلى الأرض. أكمل التكرارات ثم بدّل."]],"Sit-Up":["سيت أب",["استلقِ وثبّت قدميك تحت شيء ثابت أو اطلب من زميل إمساكهما، والركبتان مثنيتان.","شبّك يديك خلف رأسك. هذه وضعية البداية.","ارفع جذعك حتى يشكّل مع فخذيك حرف V، وأنت تزفر. لا تشدّ رأسك بيديك.","اثبت ثانية، ثم انزل ببطء وأنت تشهق."]],"Sit_Squats":["سكوات الجلوس",["قف والقدمان بعرض الكتفين. هذه وضعية البداية.","اثنِ ركبتيك وحوضك واجلس بحوضك للخلف.","انزل جزءًا من المسافة (فوق الموازاة) ثم اعكس الحركة بسرعة. كرّر 5–10 مرات."]],"Skating":["حركة التزلج",["التزلج نشاط ممتع يحسّن اللياقة القلبية وتحمّل العضلات، ويحتاج توازنًا وتوافقًا جيدين. تعلّم أساسيات الدوران والتوقف والبس معدات الحماية.","تزلّج بسرعة مريحة 30 دقيقة متواصلة، أو بتدريب متقطع: دقيقتان سريعتان من كل خمس دقائق والباقي للاستشفاء."]],"Sled_Drag_-_Harness":["سحب الزلاجة بالحزام",["حمّل الزلاجة بالوزن المطلوب واربط حزام السحب. يمكنك السحب بالمقابض أو بحزام على الجسم أو بحزام الوزن.","سواء سحبت للأمام أو للخلف، مِل باتجاه الحركة وتقدّم بفرد الحوض والركبتين."]],"Sled_Overhead_Backward_Walk":["مشي للخلف بالزلاجة والذراعان فوق الرأس",["اربط مقبضين بالزلاجة بحبل أو سلسلة، وحمّلها بوزن خفيف.","قف مقابل الزلاجة وارجع حتى يشتد الحبل. ارفع يديك فوق رأسك والمرفقان ممدودان. هذه وضعية البداية.","امشِ للخلف والذراعان مرفوعتان فوق رأسك، دون حركات مفاجئة."]],"Sled_Overhead_Triceps_Extension":["تراي فوق الرأس بالزلاجة",["اربط مقبضين بالزلاجة بحبل أو سلسلة، وحمّلها بالوزن المناسب.","قف وظهرك للزلاجة وابتعد حتى يشتد الحبل. ارفع يديك معًا فوق رأسك والكفّان متقابلتان، والمرفقان يشيران للأعلى ومثنيان. هذه وضعية البداية.","افرد مرفقيك لتستقيم ذراعاك، مع ثبات العضدين.","بعد الامتداد الكامل، تقدّم خطوة ليشتد الحبل مجددًا. يمكنك المباعدة بين قدميك للأمام والخلف للثبات."]],"Sled_Push":["دفع الزلاجة",["حمّل زلاجة الدفع بالوزن المطلوب.","اتخذ وضعية رياضية ومِل نحو الزلاجة والذراعان ممدودتان على المقابض. ادفعها بأسرع ما يمكن مع التركيز على فرد الحوض والركبتين."]],"Sled_Reverse_Flye":["تفتيح عكسي بالزلاجة",["اربط مقبضين بالزلاجة بحبل أو سلسلة، وحمّلها بوزن خفيف.","قف مقابل الزلاجة وارجع حتى يشتد الحبل. أمسك المقبضين والذراعان ممدودتان عند مستوى الخصر، والركبتان مثنيتان قليلًا والصدر والرأس مرفوعان. هذه وضعية البداية.","دون ثني المرفقين، اسحب المقبضين للأعلى وللجانبين في تفتيح عكسي مع تدوير الكتف للخارج، والكفّان للأمام.","عد إلى البداية وارجع خطوة أو اثنتين ليشتد الحبل."]],"Sled_Row":["تجديف بالزلاجة",["اربط مقبضين بالزلاجة بحبل أو سلسلة وحمّلها بالوزن المناسب. قف مقابلها وارجع حتى يشتد الحبل.","مقبض في كل يد، الركبتان مثنيتان قليلًا، والرأس والصدر مرفوعان، والذراعان ممدودتان.","اثنِ المرفقين واضمم لوحي الكتف لتسحب الزلاجة نحوك.","ارجع خطوة أو اثنتين ليشتد الحبل وكرّر."]],"Sledgehammer_Swings":["ضرب المطرقة الثقيلة",["تحتاج إطارًا ومطرقة ثقيلة. قف أمام الإطار على بعد 60 سم تقريبًا بقدمين متباعدتين للأمام والخلف، وأمسك المطرقة.","إذا كنت تستخدم اليمنى، تكون يدك اليسرى أسفل المقبض واليمنى أقرب إلى الرأس.","عند رفع المطرقة تنزلق يدك اليمنى نحو الرأس، وعند الضرب تنزلق للأسفل لتلحق باليسرى. اضرب الإطار بأقوى ما يمكن وتحكّم بارتداد المطرقة.","كرّر من الجهة الأخرى."]],"Smith_Incline_Shoulder_Raise":["رفع الكتفين على السميث على بنش مائل",["ضع بنشًا مائلًا تحت جهاز السميث، واضبط البار على ارتفاع تصله وذراعاك شبه ممدودتين. استلقِ بحيث يكون كتفاك تحت البار مباشرة.","أمسك البار بقبضة علوية بعرض الكتفين، حرّره وثبّته فوقك مع ثني بسيط في المرفقين. هذه وضعية البداية.","ازفر وارفع البار حتى تمتد ذراعاك، بدفع الكتفين. يجب أن تشعر بالانقباض حول الكتفين.","توقف ثانية، ثم عد إلى البداية وأنت تشهق.","عند الانتهاء أعد البار إلى الحامل."]],"Smith_Machine_Behind_the_Back_Shrug":["ترابيس على السميث خلف الظهر",["اضبط البار على مستوى الفخذين وحمّله بالوزن المناسب.","قف والبار خلفك، أمسكه بقبضة علوية بعرض الكتفين وحرّره. قف باستقامة والرأس والصدر مرفوعان والذراعان ممدودتان. هذه وضعية البداية.","ارفع كتفيك للأعلى بشكل مستقيم، دون ثني الذراعين أو الرسغين.","توقف لحظة، ثم أعد الوزن إلى البداية.","بعد إكمال التكرارات أعد قفل البار."]],"Smith_Machine_Bench_Press":["ضغط صدر على السميث",["ضع بنشًا مستويًا تحت جهاز السميث، واضبط البار على ارتفاع تصله وذراعاك شبه ممدودتين. استلقِ، وأمسك البار بقبضة علوية أعرض من الكتفين، حرّره وثبّته فوقك والذراعان ممدودتان.","اشهق وأنزل البار ببطء حتى يلمس منتصف صدرك.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد قفل البار."]],"Smith_Machine_Bent_Over_Row":["تجديف منحنيًا على السميث",["اضبط بار السميث على ارتفاع تحت الركبتين بنحو 5 سم.","اثنِ ركبتيك قليلًا وانحنِ من الخصر بظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. الرأس مرفوع.","أمسك البار بقبضة علوية وحرّره، ودعه يتدلى أمامك والذراعان ممدودتان. هذه وضعية البداية.","ثبّت جذعك واسحب البار وأنت تزفر، والمرفقان قريبان من الجسم. اعصر الظهر ثانية في الأعلى.","أنزله ببطء وأنت تشهق."]],"Smith_Machine_Calf_Raise":["سمانة على السميث",["ضع مكعبًا أو قرصًا تحت بار السميث، واضبط البار على ارتفاعك. قف بمقدمة قدميك على القرص وضع البار على أعلى ظهرك.","أمسك البار والكفّان للأمام، ولفّه لتحرّره. هذه وضعية البداية.","ارفع كعبيك لأعلى ما يمكن بالدفع بمقدمة القدمين، واعصر السمانة. الركبتان ممدودتان. اثبت ثانية.","انزل ببطء بإنزال كعبيك وأنت تشهق."]],"Smith_Machine_Close-Grip_Bench_Press":["ضغط صدر على السميث بقبضة ضيقة",["ضع بنشًا مستويًا تحت جهاز السميث، واضبط البار على ارتفاع تصله وذراعاك شبه ممدودتين. استلقِ وأمسك البار بقبضة علوية ضيقة (بعرض الكتفين تقريبًا)، حرّره وثبّته فوقك.","اشهق وأنزل البار ببطء حتى يلمس منتصف صدرك، والمرفقان قريبان من الجسم دائمًا للتركيز على التراي.","توقف ثانية، ثم ادفعه بالتراي إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد قفل البار."]],"Smith_Machine_Decline_Press":["ضغط صدر على السميث على بنش مقلوب",["ضع بنشًا مقلوبًا تحت السميث بحيث يكون البار فوق صدرك، حمّل الوزن المناسب واستلقِ.","لفّ البار لتحرّره ومدّ ذراعيك بالكامل، والظهر مقوّس قليلًا ولوحا الكتف مسحوبان للخلف. هذه وضعية البداية.","اثنِ ذراعيك وأنزل البار إلى صدرك.","توقف لحظة، ثم مدّ ذراعيك لتدفع الوزن إلى البداية.","بعد إكمال التكرارات لفّ البار لتقفله."]],"Smith_Machine_Hang_Power_Clean":["باور كلين من التعليق على السميث",["اضبط البار على مستوى الركبتين وحمّله بالوزن المناسب.","أمسكه بقبضة علوية أعرض من الكتفين وحرّره. الذراعان ممدودتان، الرأس والصدر مرفوعان، المرفقان للخارج والكتفان للخلف وللأسفل، والحوض للخلف ليشدّ خلفي الفخذ. هذه وضعية البداية.","افرد الحوض والركبتين بقوة لتسرّع البار، والذراعان مستقيمتان في هذه المرحلة.","عند الامتداد الكامل، اثنِ الحوض والركبتين مجددًا لتنزل تحت البار.","اثنِ ذراعيك ولفّ المرفقين حول البار لتستقبله على كتفيك.","افرد الحوض والركبتين لتقف والبار على كتفيك."]],"Smith_Machine_Hip_Raise":["رفع الحوض على السميث",["ضع بنشًا داخل جهاز السميث وحمّل البار بالوزن المناسب. استلقِ وضع باطن قدميك تحت البار، حرّره ومدّ رجليك (قد تحتاج لمساعدة يديك). أمسك جانبي الجهاز للثبات. هذه وضعية البداية.","دوّر حوضك واثنِ عمودك الفقري لترفع حوضك عن البنش، مع ثني بسيط ثابت في الركبتين.","توقف لحظة، ثم أعد الحوض إلى البنش."]],"Smith_Machine_Incline_Bench_Press":["ضغط صدر على السميث على بنش مائل",["ضع بنشًا مائلًا تحت جهاز السميث، واضبط البار على ارتفاع تصله وذراعاك شبه ممدودتين. استلقِ بحيث يكون أعلى صدرك على خط البار. أمسكه بقبضة علوية أعرض من الكتفين، حرّره وثبّته فوقك.","اشهق وأنزل البار ببطء حتى يلمس أعلى صدرك.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر. النزول يأخذ ضعف وقت الصعود.","عند الانتهاء أعد قفل البار."]],"Smith_Machine_Leg_Press":["مكبس الأرجل على السميث",["اضبط بار السميث على ارتفاع نحو 60 سم عن الأرض على مساند الأمان، وحمّله بالوزن المناسب. استلقِ تحته وضع منتصف قدميك على البار، والركبتان نحو صدرك. هذه وضعية البداية.","ادفع بقدميك لترفع البار بفرد الحوض والركبتين، دون قفل الركبتين.","توقف لحظة في الأعلى، ثم عد إلى البداية."]],"Smith_Machine_One-Arm_Upright_Row":["سحب عمودي على السميث بيد واحدة",["اضبط البار على مستوى الفخذين وحمّله بالوزن المناسب.","أمسك البار بيد واحدة بقبضة واسعة وحرّره، ثم أبعد اليد الأخرى. الذراع ممدودة، والرأس والصدر مرفوعان. هذه وضعية البداية.","اثنِ المرفق لترفع العضد والمرفق يشير للخارج، حتى يصبح العضد موازيًا للأرض.","توقف لحظة، ثم أعد الوزن إلى البداية.","بعد إكمال التكرارات أعد قفل البار، ثم بدّل اليد."]],"Smith_Machine_Overhead_Shoulder_Press":["ضغط أكتاف على السميث",["ضع بنشًا (يُفضّل بمسند للظهر) تحت السميث، واضبط البار بحيث تصله جالسًا وذراعاك شبه ممدودتين.","اجلس خلف البار قليلًا بحيث يكون على خط أنفك تقريبًا، والقدمان ثابتتان. أمسكه والكفّان للأمام، حرّره وارفعه حتى تمتد ذراعاك. هذه وضعية البداية.","أنزل البار ببطء حتى مستوى ذقنك وأنت تشهق.","ارفعه إلى البداية بالكتفين وأنت تزفر."]],"Smith_Machine_Pistol_Squat":["سكوات المسدس على السميث",["اضبط البار على ارتفاعك وضعه على أعلى ظهرك.","أمسكه والكفّان للأمام، حرّره وارفعه عن الحامل بفرد رجليك.","قدّم قدمًا واحدة نحو 30 سم أمام البار، ومدّ الرجل الأخرى أمامك مرفوعة عن الأرض. انظر للأمام وظهرك مستقيم. هذه وضعية البداية.","بوضعية جيدة، انزل بثني الركبة والحوض بقدر ما تسمح مرونتك.","توقف لحظة، ثم اصعد بالدفع بكعب القدم. أكمل التكرارات ثم بدّل الرجل."]],"Smith_Machine_Reverse_Calf_Raises":["سمانة عكسية على السميث (رفع مقدمة القدم)",["اضبط بار السميث على ارتفاعك وضع تحته منصة مرتفعة.","قف على المنصة بكعبيك ومقدمة القدمين خارجها، والقدمان بعرض الكتفين.","ضع البار على كتفيك وقف باستقامة والركبتان مثنيتان قليلًا. البار هنا للتوازن فقط.","ارفع مقدمة قدميك لأعلى ما يمكن وأنت تزفر، والركبتان ثابتتان. اثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Smith_Machine_Squat":["سكوات على السميث",["اضبط البار على ارتفاع يناسب طولك، ثم ادخل تحته وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسكه والكفّان للأمام، حرّره وارفعه بالدفع برجليك وفرد جذعك.","القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Smith_Machine_Stiff-Legged_Deadlift":["ديدلفت بأرجل مستقيمة على السميث",["اضبط بار السميث عند منتصف الفخذين تقريبًا وحمّله. أمسكه بقبضة علوية بعرض الكتفين (قد تحتاج أحزمة الرسغ).","ارفع البار والذراعان ممدودتان والظهر مستقيم، والقدمان بعرض الكتفين أو أضيق، والركبتان مثنيتان قليلًا. هذه وضعية البداية.","مع ثبات الركبتين، أنزل البار نحو قدميك بالانحناء من الخصر بظهر مستقيم، حتى تشعر بإطالة في خلفي الفخذ.","عند الشعور بالإطالة، افرد حوضك لتعود إلى البداية."]],"Smith_Machine_Upright_Row":["سحب عمودي على السميث (أبرايت رو)",["اضبط بار السميث عند منتصف الفخذين تقريبًا وحمّله. أمسكه بقبضة علوية بعرض الكتفين.","ارفع البار والذراعان ممدودتان مع ثني بسيط في المرفقين، والظهر مستقيم. هذه وضعية البداية.","ارفع البار بالكتف الجانبي وأنت تزفر، قريبًا من جسمك، حتى يكاد يلمس ذقنك. المرفقان يقودان الحركة ويبقيان أعلى من الساعدين. الجذع ثابت، واثبت ثانية.","أنزله ببطء وأنت تشهق."]],"Smith_Single-Leg_Split_Squat":["سكوات مفتوح برجل واحدة على السميث",["ضع بنشًا مستويًا على بعد 60–90 سم خلف جهاز السميث. اضبط البار على ارتفاعك وضعه على أعلى ظهرك.","أمسكه والكفّان للأمام، حرّره وارفعه بالدفع برجليك.","ضع قدمًا أمامك تحت البار تقريبًا، ومدّ الرجل الأخرى للخلف وضع ظهر قدمها على البنش. هذه وضعية البداية.","انزل ببطء بثني الركبة الأمامية مع ظهر مستقيم ورأس مرفوع، حتى تصبح الزاوية أقل قليلًا من 90°، وأنت تشهق.","ادفع بكعب القدم الأمامية لتصعد وأنت تزفر. أكمل التكرارات ثم بدّل الرجل."]],"Snatch":["خطف (سناتش)",["قف والقدمان بعرض الكتفين، والبار فوق مفصل أصابع القدمين.","اثنِ ركبتيك مع ظهر مستقيم وأمسك البار بقبضة علوية أعرض من الكتفين. أنزل حوضك كأنك ستجلس على كرسي. هذه وضعية البداية.","ادفع الأرض بقدميك وارفع البار قريبًا من رجليك.","عندما يصل البار إلى منتصف الفخذين، ادفع الأرض برجليك وافرد جسمك بالكامل بحركة انفجارية.","ارفع كتفيك (شراغ) والمرفقان للخارج وفوق البار أطول وقت ممكن.","بحركة سريعة وقوية، انزل تحت البار عندما يصل إلى ارتفاع كافٍ، واقفل ذراعيك والبار فوق رأسك في وضعية سكوات.","قف من السكوات لتنهي الرفعة، والقدمان على خط واحد والذراعان ممدودتان فوق رأسك."]],"Snatch_Balance":["توازن الخطف",["ابدأ والقدمان في وضعية السحب، والبار على أعلى ظهرك، واليدان بقبضة الخطف الواسعة.","انزل قليلًا بسرعة وادفع بالركبتين لترفع البار عن كتفيك، واندفع تحته بقوة مع نقل القدمين إلى وضعية الاستقبال.","استقبل البار مقفلًا فوق رأسك قرب أسفل السكوات، والجذع عمودي والحوض بين الرجلين.","انزل حتى العمق الكامل، ثم قف. أنزل الوزن بحذر."]],"Snatch_Deadlift":["ديدلفت الخطف",["يقوّي ديدلفت الخطف السحبة الأولى في الخطف. أمسك البار بقبضة الخطف الواسعة، والقدمان تحت الحوض وأصابعهما للخارج. انزل إلى البار والظهر مستقيم تمامًا والنظر للأمام.","ادفع بالكعبين وارفع الحوض، مع ثبات زاوية الظهر حتى يتجاوز البار الركبتين.","ثم ادفع حوضك نحو البار وأنت تميل للخلف. أعد البار إلى الأرض بعكس الحركة."]],"Snatch_Pull":["سحب الخطف",["البار على الأرض قريب من ساقيك، أمسكه بقبضة الخطف الواسعة. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع، والكتفان أمام البار قليلًا.","ابدأ السحبة الأولى بالدفع بالكعبين وفرد الركبتين، مع ثبات زاوية الظهر والذراعان مستقيمتان، حتى يتجاوز البار الركبتين.","في السحبة الثانية، عندما يقترب البار من منتصف الفخذ، افرد الحوض والركبتين والكاحلين بقوة كأنك تقفز لتسرّع البار للأعلى.","لا تسحب بالذراعين. في النهاية يكون الجسم ممدودًا بالكامل ومائلًا قليلًا للخلف، بامتداد سريع وحاد."]],"Snatch_Shrug":["ترابيس الخطف",["أمسك البار بقبضة واسعة (علوية أو خطّاف)، والبار متدلٍّ عند منتصف الفخذ، والظهر مستقيم ومائل للأمام قليلًا.","ارفع كتفيك نحو أذنيك. يمكن استخدام وزن أثقل من الخطف، لكن لا تثقل لدرجة تبطئ الحركة."]],"Snatch_from_Blocks":["خطف من المكعبات",["البار المحمّل على صناديق بالارتفاع المطلوب، أمسكه بقبضة واسعة. القدمان تحت الحوض، أنزل حوضك والصدر مرفوع والنظر للأمام، والكتفان أمام البار. هذه وضعية البداية.","ادفع بمقدمة الكعبين لترفع البار عن الصناديق.","افرد الحوض والركبتين والكاحلين بقوة لتدفع البار للأعلى بسرعة قريبًا من جسمك. في أقصى امتداد ارفع كتفيك ودع المرفقين ينثنيان للجانبين.","انقل قدميك خارج الحوض قليلًا واسحب نفسك بقوة تحت البار وأنت ترفعه، واستقبله بأدنى وضعية والذراعان ممدودتان.","والبار فوق مقدمة الكعبين، قف بالدفع بالكعبين. أعد الوزن إلى الصناديق بحذر."]],"Speed_Band_Overhead_Triceps":["تراي فوق الرأس بالمطاط بسرعة",["ثبّت مطاطًا في الأرض (مثلًا في قاعدة بنش مائل وأنت واقف فوقه، أو قف على المطاط).","اسحب المطاط خلف رأسك بقبضة علوية والمرفقان للأعلى. هذه وضعية البداية.","افرد المرفقين بسرعة لتستقيم ذراعاك، مع ثبات العضدين.","توقف، ثم عد إلى البداية."]],"Speed_Box_Squat":["بوكس سكوات سريع",["اربط مطاطًا بالبار وثبّته قرب الأرض بشد مناسب.","استخدم صندوقًا بارتفاع مناسب، ووزنًا بين 50 و70% من أقصى وزن لك، بحيث لا تخسر السرعة.","ضع البار على أعلى ظهرك، ولوحا الكتف مضمومان والظهر مقوّس والجسم مشدود. هذه وضعية البداية.","أخرج البار وقف أمام الصندوق. اجلس بحوضك للخلف حتى تجلس على الصندوق بنزول متحكّم به دون ارتطام.","توقف لحظة، ثم انطلق عن الصندوق بقوة بفرد الحوض والركبتين."]],"Speed_Squats":["سكوات سريع",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار على ارتفاعك وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسكه وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق.","اصعد بأسرع ما يمكن دون ارتداد، بالدفع بكعبيك وأنت تزفر. السرعة مطلوبة لكن دون خسارة التقنية."]],"Spell_Caster":["الساحر (تمرين الخواصر بالدمبل)",["أمسك دمبلًا في كل يد بقبضة علوية، والقدمان متباعدتان والحوض والركبتان ممدودة. هذه وضعية البداية.","اسحب الدمبلين معًا إلى جانب واحد بجانب حوضك مع لفّ جذعك.","والذراعان مستقيمتان والدمبلان موازيان للأرض، لفّ جذعك لتؤرجح الوزن إلى الجهة الأخرى.","تابع بالتبادل من جهة إلى أخرى."]],"Spider_Crawl":["زحف العنكبوت",["انبطح على الأرض واستند على يديك وأطراف قدميك، والقدمان معًا والجسم مستقيم، والذراعان مثنيتان 90°. هذه وضعية البداية.","ارفع قدمًا عن الأرض وأدرها للخارج، وقرّب ركبتك نحو مرفقك لأبعد ما تستطيع.","أعد الرجل إلى البداية وكرّر بالجهة الأخرى."]],"Spider_Curl":["باي العنكبوت (سبايدر كيرل)",["ضع البار على مقعد بنش البريتشر بشكل متوازن حتى لا يسقط.","انتقل إلى الجهة الأمامية من البنش وانبطح عليها بزاوية 45° وصدرك وبطنك على المسند.","ثبّت قدميك على الأرض، وضع عضديك على الجهة الأخرى من المسند متدليتين.","أمسك البار بقبضة سفلية بعرض الكتفين أو أضيق قليلًا.","ارفع البار ببطء وأنت تزفر، واعصر الباي ثانية في الأعلى.","أنزله ببطء وأنت تشهق."]],"Spinal_Stretch":["إطالة العمود الفقري",["اجلس على كرسي والظهر مستقيم والقدمان ثابتتان على الأرض.","شبّك أصابعك خلف رأسك والمرفقان للخارج والذقن للأسفل.","لفّ جذعك إلى جهة واحدة نحو 3 مرات لأبعد حد، ثم مِل للأمام ولفّ لتقرّب مرفقك من الأرض داخل ركبتك.","عد إلى الوضع المستقيم وكرّر للجهة الأخرى."]],"Split_Clean":["كلين مفتوح",["البار على الأرض قريب من ساقيك، أمسكه بقبضة علوية خارج الرجلين. أنزل حوضك والوزن على الكعبين، الظهر مستقيم والنظر للأمام والصدر مرفوع.","السحبة الأولى: ادفع بالكعبين وافرد الركبتين، مع ثبات زاوية الظهر والذراعان مستقيمتان، حتى يتجاوز البار الركبتين.","السحبة الثانية: عند منتصف الفخذ افرد الحوض والركبتين والكاحلين بقوة كأنك تقفز، دون السحب بالذراعين.","السحبة الثالثة: ارفع كتفيك واثنِ ذراعيك والمرفقان للأعلى وللخارج، واسحب نفسك تحت البار مع لفّ المرفقين.","استقبل البار بقدمين مفتوحتين (واحدة للأمام وأخرى للخلف) على مقدمة الكتفين.","قف فورًا بالدفع بالكعبين والجذع مستقيم والمرفقان مرفوعان، واجمع قدميك."]],"Split_Jerk":["جيرك مفتوح",["قف والبار على مقدمة الكتفين والقدمان تحت الحوض. انزل بثني الركبتين دون دفع الحوض للخلف.","انزل قليلًا فقط ثم اعكس الاتجاه بأقصى قوة بالدفع بالكعبين، وأبعد رأسك عن مسار البار. عندما ترتفع قدماك انقلهما بسرعة إلى وضعية الاستقبال.","افتح قدميك: واحدة للأمام وأخرى للخلف والركبتان مثنيتان جزئيًا، واستقبل البار والذراعان مقفلتان فوق رأسك.","قف واجمع قدميك."]],"Split_Jump":["قفزة مفتوحة (لانج بالقفز)",["اتخذ وضعية اللانج: قدم للأمام والركبة مثنية، والركبة الخلفية تكاد تلمس الأرض.","الركبة الأمامية فوق منتصف القدم.","افرد الرجلين واقفز لأعلى ما تستطيع مع أرجحة الذراعين.","في الهواء اجمع قدميك ثم أعدهما إلى وضعهما الأول قبل الهبوط.","امتص الصدمة بالعودة إلى وضعية البداية."]],"Split_Snatch":["خطف مفتوح",["البار المحمّل على الأرض قريب من ساقيك، أمسكه بقبضة واسعة. القدمان تحت الحوض، أنزل حوضك والصدر مرفوع والنظر للأمام. هذه وضعية البداية.","السحبة الأولى: ادفع بمقدمة الكعبين لترفع البار، مع ثبات زاوية الظهر حتى يتجاوز الركبتين.","السحبة الثانية: افرد الحوض والركبتين والكاحلين بقوة لتدفع البار للأعلى بسرعة. في أقصى امتداد ارفع كتفيك ودع المرفقين ينثنيان للجانبين.","افتح قدميك بقوة (واحدة للأمام وأخرى للخلف) واسحب نفسك تحت البار، واستقبله بأدنى وضعية والذراعان ممدودتان فوق رأسك.","قف بالدفع بالكعبين واجمع قدميك.","أعد الوزن إلى الأرض بحذر."]],"Split_Squat_with_Dumbbells":["سكوات مفتوح بالدمبل",["قف بوقفة مفتوحة: القدم الخلفية مرفوعة على بنش والأمامية للأمام.","أمسك دمبلًا في كل يد بجانبك. هذه وضعية البداية.","انزل بثني الركبة والحوض، مع وضعية جيدة والركبة الأمامية على خط القدم.","في الأسفل ادفع بالكعب لتفرد الركبة والحوض وتعود إلى البداية. أكمل التكرارات ثم بدّل الرجل."]],"Split_Squats":["سكوات مفتوح (سبليت سكوات)",["ابدأ واقفًا، ثم اقفز إلى وضعية مفتوحة (رجل للأمام وأخرى للخلف) مع ثني الركبتين وإنزال الحوض قليلًا.","أثناء النزول اعكس الاتجاه فورًا واقفز مبدّلًا وضع الرجلين. كرّر 5–10 مرات لكل رجل."]],"Squat_Jerk":["جيرك بالسكوات",["قف والبار على مقدمة كتفيك والقدمان تحت الحوض. انزل قليلًا بثني الركبتين دون دفع الحوض للخلف، ثم اعكس الاتجاه بأقصى قوة بالدفع بالكعبين، وأبعد رأسك عن مسار البار.","عندما ترتفع قدماك عن الأرض، انقلهما بسرعة إلى خارج الحوض قليلًا، واستقبل البار في سكوات كامل والذراعان ممدودتان فوق رأسك.","والبار فوق مقدمة الكعبين والرأس والصدر مرفوعان، ادفع بكعبيك لتقف. أعد الوزن إلى الأرض بحذر."]],"Squat_with_Bands":["سكوات بالمطاط",["ثبّت المطاط على طرفي البار وعلى أوتاد القفص أو دمبلات بشد مناسب.","ادخل تحت البار وضعه على أعلى ظهرك، اضغط لوحي الكتف معًا وأخرجه مع تقويس أسفل الظهر. باعد القدمين للتركيز على الظهر والأرداف وخلفي الفخذ، والنظر للأمام.","مع شدّ الظهر والبطن، ادفع ركبتيك ومؤخرتك للخارج واجلس للخلف قدر الإمكان، حتى يصبح مفصل الورك أسفل مستوى الركبة.","والوزن على الكعبين وركبتاك للخارج، اصعد بقوة والرأس يقود الحركة حتى تعود إلى البداية."]],"Squat_with_Chains":["سكوات بالسلاسل",["علّق السلسلة الخفيفة على طرفي البار، واربط بها السلسلة الثقيلة، بحيث تبقى بضع حلقات على الأرض في أعلى الحركة.","ادخل تحت البار وضعه على أعلى ظهرك، اضغط لوحي الكتف معًا وأخرجه مع تقويس أسفل الظهر. باعد القدمين، والنظر للأمام.","مع شدّ الظهر والبطن، ادفع ركبتيك ومؤخرتك للخارج واجلس للخلف قدر الإمكان، حتى يصبح مفصل الورك أسفل مستوى الركبة.","والوزن على الكعبين وركبتاك للخارج، اصعد بقوة والرأس يقود الحركة حتى تعود إلى البداية."]],"Squat_with_Plate_Movers":["سكوات مع تحريك الأقراص",["اضبط البار تحت مستوى الكتفين بقليل، وضع قرصًا على الأرض على بعد خطوة خلف الحامل. ضع البار على أعلى ظهرك.","ارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد عن الحامل بوقفة واسعة وأصابع القدمين للخارج، وقدم واحدة على القرص. الرأس مرفوع. هذه وضعية البداية.","انزل ببطء بثني الركبتين والحوض حتى تصبح الزاوية أقل قليلًا من 90°.","اصعد بالدفع بكعبيك وأنت تزفر.","في الأعلى اخطُ جانبيًا واجمع قدميك على الجهة الأخرى من القرص، ثم ادفع القرص بقدمك الداخلية لينزلق إلى حيث كنت.","ضع قدمك الداخلية على القرص بوقفة واسعة للتكرار التالي."]],"Squats_-_With_Bands":["سكوات بالمطاط",["قف على منتصف المطاط والقدمان بعرض الكتفين، بحيث يتساوى طوله على الجانبين.","أمسك المقبضين بجانب وجهك بقبضة علوية، والمطاط بالارتفاع نفسه من الجهتين. هذه وضعية البداية.","اثنِ ركبتيك ببطء وانزل حتى يصبح الفخذان موازيين للأرض.","ادفع بكعبيك لتصعد إلى البداية."]],"Stairmaster":["جهاز الدرج (ستير ماستر)",["اصعد على جهاز الدرج (ستير ماستر) واختر البرنامج: يدوي أو جاهز. يمكنك إدخال عمرك ووزنك لتقدير السعرات.","حرّك رجليك للأعلى وللأسفل بإيقاع ثابت، واضغط الدوّاسات دون أن تصل إلى الأرض. أمسك المقابض حتى لا تقع، ويمكنك قياس النبض منها.","الجهاز مفيد جدًا للقلب وأصعب عادةً من أجهزة الكارديو الأخرى."]],"Standing_Alternating_Dumbbell_Press":["ضغط أكتاف بالدمبل وقوفًا بالتبادل",["قف ودمبل في كل يد عند كتفيك، الكفّان للأمام والمرفقان للخارج. هذه وضعية البداية.","مدّ ذراعًا واحدة لتضغط الدمبل للأعلى مباشرة، واليد الأخرى ثابتة. لا تمِل ولا تدفع بجسمك.","توقف لحظة، ثم أعده إلى البداية.","كرّر بالذراع الأخرى، وتابع بالتبادل."]],"Standing_Barbell_Calf_Raise":["سمانة وقوف بالبار",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار على ارتفاعك وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسك البار وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم والركبتان مثنيتان قليلًا. لمدى أكبر يمكنك الوقوف بمقدمة القدمين على لوح ثابت.","ارفع كعبيك لأعلى ما يمكن وأنت تزفر وتعصر السمانة، والركبتان ثابتتان. اثبت ثانية.","انزل ببطء حتى تتمدد السمانة وأنت تشهق."]],"Standing_Barbell_Press_Behind_Neck":["ضغط بالبار خلف الرقبة وقوفًا",["يُفضّل البدء من قفص السكوات. اضبط البار على ارتفاعك وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسكه وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين، والظهر مستقيم. هذه وضعية البداية.","ارفع البار فوق رأسك حتى تمتد ذراعاك وأنت تزفر.","اثبت ثانية ثم أنزله إلى البداية وأنت تشهق. استخدم وزنًا خفيفًا إذا كان كتفك حساسًا."]],"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension":["تراي بالدمبل بيد واحدة وقوفًا ومنحنيًا",["دمبل في يد واحدة والكف نحو جسمك، اثنِ ركبتيك قليلًا وانحنِ من الخصر بظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. الرأس مرفوع.","العضد قريب من الجذع وموازٍ للأرض، والساعد متدلٍّ للأسفل بزاوية 90°. هذه وضعية البداية.","ثبّت العضد وارفع الدمبل بالتراي حتى تمتد الذراع موازية للأرض، وأنت تزفر. الساعد فقط يتحرك.","اعصر ثانية ثم أنزله ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الذراع."]],"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension":["تراي بدمبلين وقوفًا ومنحنيًا",["دمبل في كل يد والكفّان نحو جسمك، اثنِ ركبتيك قليلًا وانحنِ من الخصر بظهر مستقيم حتى يصبح جذعك شبه موازٍ للأرض. العضدان قريبان من الجذع وموازيان للأرض، والساعدان متدليان بزاوية 90°.","ثبّت العضدين وارفع الدمبلين بالتراي حتى تمتد ذراعاك موازيتين للأرض، وأنت تزفر.","اعصر ثانية ثم أنزلهما ببطء وأنت تشهق."]],"Standing_Biceps_Cable_Curl":["باي بالكيبل وقوفًا",["قف باستقامة وأمسك بار الكيبل السفلي بعرض الكتفين بقبضة سفلية، والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ البار وأنت تزفر حتى مستوى الكتفين، واعصر ثانية. الساعدان فقط يتحركان.","أنزله ببطء وأنت تشهق."]],"Standing_Biceps_Stretch":["إطالة الباي وقوفًا",["شبّك يديك خلف ظهرك والكفّان معًا، افرد ذراعيك ثم لفّهما بحيث تتجه الكفّان للأسفل.","ارفع ذراعيك واثبت حتى تشعر بإطالة في الباي."]],"Standing_Bradford_Press":["ضغط برادفورد وقوفًا",["ضع بارًا محمّلًا على الحامل بمستوى الكتفين. أمسكه بقبضة علوية بعرض الكتفين، وابدأ والبار على مقدمة كتفيك.","ادفع البار فوق رأسك بفرد المرفقين، دون قفلهما بالكامل وأنت تنقله خلف رأسك.","أنزل البار خلف رأسك حتى يصبح المرفق بزاوية قائمة.","ارفعه فوق رأسك مجددًا، ثم أنزله إلى الأمام. تابع بالتبادل. استخدم وزنًا خفيفًا."]],"Standing_Cable_Chest_Press":["ضغط صدر بالكيبل وقوفًا",["اضبط البكرتين بمستوى الصدر واختر الوزن. قف على بعد 30–60 سم أمام الكيبلين وأمسك مقبضًا بكل يد، والقدمان متباعدتان للأمام والخلف للثبات.","العضدان بزاوية 90° ولوحا الكتف مضمومان. هذه وضعية البداية.","مع ثبات باقي الجسم، مدّ مرفقيك لتضغط المقبضين للأمام وتجمعهما أمامك.","توقف في نهاية الحركة، ثم عد إلى البداية."]],"Standing_Cable_Lift":["رفع بالكيبل وقوفًا (لفّ قطري للأعلى)",["ركّب مقبضًا على الكيبل في أدنى وضع.","قف وجانبك للجهاز وأمسك المقبض بيد واحدة، وابتعد حتى يصبح الكيبل مشدودًا والذراع على خطه.","القدمان بعرض الكتفين، انزل في سكوات وأمسك المقبض باليدين والذراعان ممدودتان.","بحركة واحدة، اسحب المقبض للأعلى وعبر جسمك حتى تصبح ذراعاك ممدودتين فوق رأسك من الجهة الأخرى.","الظهر مستقيم والذراعان قريبتان، ودوّر قدمك الخلفية وافرد رجليك لمدى كامل.","عد ببطء وتحكّم إلى البداية. أكمل التكرارات ثم بدّل الجهة."]],"Standing_Cable_Wood_Chop":["تقطيع الخشب بالكيبل وقوفًا (وود تشوب)",["ركّب مقبضًا على الكيبل في أعلى وضع.","قف وجانبك للجهاز وأمسك المقبض بيد واحدة، وابتعد حتى يصبح الكيبل مشدودًا والذراع على خطه.","القدمان بعرض الكتفين، أمسك المقبض باليدين والذراعان ممدودتان للأعلى.","بحركة واحدة، اسحب المقبض للأسفل وعبر جسمك نحو ركبتك الأمامية مع لفّ جذعك.","الظهر والذراعان مستقيمة والبطن مشدود، ودوّر قدمك الخلفية واثنِ ركبتيك لمدى كامل.","عد ببطء وتحكّم إلى البداية. أكمل التكرارات ثم بدّل الجهة."]],"Standing_Calf_Raises":["سمانة وقوف",["اضبط مسند جهاز السمانة على طولك.","ضع كتفيك تحت المساند ومقدمة قدميك على المكعب والكعبان خارجه. ادفع المسند بفرد الحوض والركبتين حتى تقف، والركبتان مثنيتان قليلًا. هذه وضعية البداية.","ارفع كعبيك لأعلى ما يمكن وأنت تزفر وتعصر السمانة، والركبتان ثابتتان. اثبت ثانية.","انزل ببطء حتى تتمدد السمانة وأنت تشهق."]],"Standing_Concentration_Curl":["باي تركيز وقوفًا",["أمسك دمبلًا بيدك العاملة وانحنِ للأمام. دع ذراعك تتدلى عمودية على الأرض والمرفق للخارج. هذه وضعية البداية.","ثبّت العضد واثنِ المرفق لترفع الوزن. في الأعلى اعصر الباي وتوقف.","أنزل الدمبل إلى البداية. أكمل التكرارات ثم بدّل الذراع."]],"Standing_Dumbbell_Calf_Raise":["سمانة وقوف بالدمبل",["قف باستقامة ودمبل في كل يد بجانبك، ومقدمة قدميك على لوح ثابت بارتفاع 5–8 سم والكعبان على الأرض.","الأصابع للأمام (لكل السمانة)، أو للداخل (للرأس الخارجي)، أو للخارج (للرأس الداخلي). ارفع كعبيك وأنت تزفر وتعصر السمانة، واثبت ثانية.","أنزل كعبيك ببطء وأنت تشهق."]],"Standing_Dumbbell_Press":["ضغط أكتاف بالدمبل وقوفًا",["قف والقدمان بعرض الكتفين ودمبل في كل يد. ارفع الدمبلين إلى مستوى الرأس والمرفقان للخارج بزاوية 90°. هذه وضعية البداية.","بتقنية صارمة دون دفع بالرجلين أو ميلان للخلف، مدّ مرفقيك لترفع الدمبلين معًا فوق رأسك مباشرة.","توقف، ثم أعدهما ببطء إلى البداية."]],"Standing_Dumbbell_Reverse_Curl":["باي دمبل بقبضة علوية وقوفًا",["قف باستقامة ودمبل في كل يد بقبضة علوية (الكفّان للأسفل)، والذراعان ممدودتان والقدمان بعرض الكتفين.","ثبّت العضدين واثنِ الدمبلين وأنت تزفر حتى مستوى الكتفين، واعصر ثانية. الساعدان فقط يتحركان.","أنزلهما ببطء وأنت تشهق."]],"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head":["رفرفة أمامية بالدمبل بذراع مستقيمة فوق الرأس وقوفًا",["أمسك الدمبلين أمام فخذيك والكفّان نحوهما.","الذراعان مستقيمتان مع ثني بسيط ثابت في المرفقين. هذه وضعية البداية.","ارفع الدمبلين في نصف دائرة حتى فوق رأسك والذراعان ممدودتان، وأنت تزفر.","عد ببطء في المسار نفسه وأنت تشهق."]],"Standing_Dumbbell_Triceps_Extension":["تراي بالدمبل وقوفًا",["قف والقدمان بعرض الكتفين، وأمسك دمبلًا بيديك وارفعه فوق رأسك حتى تمتد ذراعاك.","الدمبل مستقر في كفّيك والإبهامان حوله، والكفّان نحو السقف. هذه وضعية البداية.","العضدان قريبان من رأسك وعموديان على الأرض، أنزل الدمبل في نصف دائرة خلف رأسك حتى يلمس الساعدان الباي، وأنت تشهق. العضدان ثابتان.","ارفعه إلى البداية بالتراي وأنت تزفر."]],"Standing_Dumbbell_Upright_Row":["سحب عمودي بالدمبل وقوفًا",["أمسك دمبلًا في كل يد بقبضة علوية أضيق قليلًا من الكتفين، والدمبلان على فخذيك، والذراعان ممدودتان مع ثني بسيط والظهر مستقيم.","ارفع الدمبلين بالكتف الجانبي وأنت تزفر، قريبين من جسمك، حتى يكادا يلمسان ذقنك. المرفقان يقودان الحركة ويبقيان أعلى من الساعدين. الجذع ثابت، واثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Standing_Elevated_Quad_Stretch":["إطالة أمامي الفخذ والرجل مرفوعة وقوفًا",["قف وظهرك على بعد 60–90 سم من بنش أو درجة.","ارفع رجلًا خلفك وضع قدمها على الدرجة (على ظهر القدم أو مقدمتها، حسب الراحة).","أبقِ الركبة الأمامية مثنية قليلًا ولا تدعها تتجاوز أصابع القدم. بدّل الجهة."]],"Standing_Front_Barbell_Raise_Over_Head":["رفرفة أمامية بالبار فوق الرأس وقوفًا",["قف باستقامة وأمسك البار بقبضة علوية أضيق من الكتفين.","القدمان بعرض الكتفين، والمرفقان مثنيان قليلًا. هذه وضعية البداية.","ارفع البار أمامك حتى يصبح فوق رأسك مباشرة وأنت تزفر، مع ثني بسيط في المرفقين.","بعد الشعور بالانقباض، أنزله ببطء إلى البداية وأنت تشهق."]],"Standing_Gastrocnemius_Calf_Stretch":["إطالة السمانة وقوفًا",["ضع كعبك الأيمن على درجة والركبة ممدودة، ومِل للأمام لتمسك أصابع قدمك اليمنى بيدك اليمنى. الركبة اليسرى مثنية قليلًا والظهر مستقيم.","الوزن على الرجل اليسرى ويدك اليسرى على فخذك الأيسر.","اسحب أصابع قدمك اليمنى نحو الركبة حتى تشعر بإطالة في السمانة. بدّل الجهة."]],"Standing_Hamstring_and_Calf_Stretch":["إطالة خلفي الفخذ والسمانة وقوفًا",["لفّ حزامًا أو حبلًا حول قدم واحدة، وقف وتلك القدم للأمام.","اثنِ الرجل الخلفية والأمامية مستقيمة، وارفع أصابع القدم الأمامية عن الأرض ومِل للأمام.","اسحب ظهر القدم بالحزام لزيادة إطالة السمانة. اثبت 10–20 ثانية ثم بدّل القدم."]],"Standing_Hip_Circles":["دوائر الورك وقوفًا",["قف على رجل واحدة وأمسك عمودًا للسند.","ارفع الركبة الحرة إلى 90°. هذه وضعية البداية.","افتح الورك لأقصى حد وارسم بركبتك دائرة كبيرة.","أدِّها ببطء عدة مرات ثم بدّل الجهة."]],"Standing_Hip_Flexors":["إطالة ثانيات الورك وقوفًا",["قف باستقامة والعمود الفقري عمودي، والقدم اليسرى أمام اليمنى قليلًا.","اثنِ الركبتين وارفع الكعب الخلفي وأنت تدفع الورك الأيمن للأمام. بدّل الجهة."]],"Standing_Inner-Biceps_Curl":["باي داخلي وقوفًا",["قف ودمبل في كل يد والذراعان ممدودتان، المرفقان قريبان من الجسم والقدمان بعرض الكتفين.","الكفّان للداخل (قبضة محايدة). هذه وضعية البداية.","ثبّت العضدين واثنِ الدمبلين للخارج وأنت تزفر، مع لفّ الرسغين لتصبح الكفّان للأعلى في النهاية. الساعدان على خط الكتفين الجانبيين.","تابع حتى مستوى الكتفين واعصر الباي ثانية.","أنزلهما ببطء وأنت تشهق، مع العودة إلى القبضة المحايدة."]],"Standing_Lateral_Stretch":["إطالة جانبية وقوفًا",["قف بوقفة أعرض قليلًا من الحوض والركبتان مثنيتان قليلًا.","ضع يدك اليمنى على وركك الأيمن لسند الظهر.","ارفع ذراعك اليسرى عموديًا ثم ضع يدك خلف رأسك، ومِل بجذعك إلى اليمين.","وزّع وزنك بالتساوي على الرجلين. بدّل الجهة."]],"Standing_Leg_Curl":["خلفي وقوف (ثني الرجل وقوفًا)",["اضبط ذراع الجهاز على طولك، وقف منحنيًا للأمام بزاوية 30–45°، ومسند الجهاز خلف ساقك اليمنى تحت السمانة ببضعة سنتيمترات، ومقدمة الرجل على مسند الجهاز.","والجذع منحنٍ، مدّ رجلك بالكامل وأمسك المقابض الجانبية. هذه وضعية البداية.","ازفر واثنِ رجلك اليمنى لأقصى حد دون أن ترفع الفخذ عن المسند. اثبت ثانية.","اشهق وأعد الرجل إلى البداية. أكمل التكرارات ثم بدّل إلى اليسرى."]],"Standing_Long_Jump":["وثب طويل من الثبات",["يُفضّل على الرمل أو سطح هبوط ناعم، مع إمكانية قياس المسافة. قف في نصف سكوات والقدمان بعرض الكتفين.","بأرجحة قوية للذراعين ونزول سريع بالرجلين، اقفز للأمام لأبعد مسافة.","حاول الهبوط وقدماك ممدودتان أمامك لأبعد حد.","قس المسافة من نقطة الهبوط إلى البداية وسجّل النتيجة."]],"Standing_Low-Pulley_Deltoid_Raise":["رفرفة جانبية بالكيبل السفلي وقوفًا",["قف إلى يمين الكيبل السفلي، ومدّ يدك اليسرى عبر جسمك لتمسك المقبض بقبضة علوية، والذراع أمامك. أمسك الجهاز باليد اليمنى للتوازن.","الظهر مستقيم والقدمان بعرض الكتفين. هذه وضعية البداية.","ارفع ذراعك اليسرى عبر جسمك وللخارج حتى مستوى الكتف وأنت تزفر.","اثبت ثانية ثم أنزلها ببطء وأنت تشهق.","أكمل التكرارات ثم بدّل الجهة."]],"Standing_Low-Pulley_One-Arm_Triceps_Extension":["تراي بالكيبل السفلي بيد واحدة وقوفًا",["أمسك مقبضًا واحدًا بيدك اليسرى بجانب الكيبل السفلي، واستدر بعيدًا عن الجهاز. ارفع المقبض باليدين فوق رأسك والكف للأمام، والعضد عمودي تمامًا، وضع يدك اليمنى على مرفقك الأيسر لتثبيته. هذه وضعية البداية.","العضد قريب من رأسك وعمودي، أنزل المقبض في نصف دائرة خلف رأسك حتى يلمس الساعد الباي، وأنت تشهق. العضد ثابت.","ارفعه إلى البداية بالتراي وأنت تزفر.","أكمل التكرارات ثم بدّل الذراع."]],"Standing_Military_Press":["ضغط عسكري وقوفًا",["ضع البار على الحامل بمستوى الصدر تقريبًا، وأمسكه بقبضة علوية أعرض من الكتفين.","اثنِ ركبتيك قليلًا وضع البار على الترقوة، ارفعه وارجع خطوة، والقدمان بعرض الكتفين.","ارفع البار فوق رأسك حتى تمتد ذراعاك، أمام رأسك بقليل. هذه وضعية البداية.","أنزل البار ببطء إلى الترقوة وأنت تشهق.","ارفعه إلى البداية وأنت تزفر."]],"Standing_Olympic_Plate_Hand_Squeeze":["ضغط القرص الأولمبي باليدين وقوفًا",["قف باستقامة وأمسك قرصًا من حافته بكل يد والذراعان ممدودتان، بقبضة محايدة، والقدمان بعرض الكتفين. هذه وضعية البداية.","أنزل القرصين حتى تكاد أصابعك تنفتح لكن ما زالت تمسك الوزن، وأنت تشهق.","أغلق يديك لترفع القرصين إلى البداية وأنت تزفر."]],"Standing_One-Arm_Cable_Curl":["باي بالكيبل بيد واحدة وقوفًا",["أمسك مقبضًا واحدًا بجانب الكيبل السفلي، وابتعد بحيث تحمل ذراعك الوزن.","العضد ثابت وعمودي على الأرض، والمرفق للداخل والكف للأمام. اليد الأخرى على خصرك للتوازن.","اثنِ المقبض للأعلى ببطء حتى يلمس الساعد الباي، وأنت تزفر. الساعد فقط يتحرك.","اعصر الباي ثم أنزل المقبض إلى البداية وأنت تشهق.","أكمل التكرارات ثم بدّل الذراع."]],"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench":["باي دمبل بيد واحدة على بنش مائل وقوفًا",["قف خلف بنش مائل كأنك مساعد لشخص عليه، ودمبل في يد واحدة بقبضة سفلية والذراع ممدودة فوق المسند.","ضع يدك الأخرى على طرف البنش، والصدر ملاصق لأعلى المسند والقدمان متباعدتان على الأرض. هذه وضعية البداية.","ثبّت العضد واثنِ الدمبل وأنت تزفر حتى مستوى الكتف، واثبت ثانية. الساعد فقط يتحرك.","أنزله ببطء وأنت تشهق.","أكمل التكرارات ثم بدّل الذراع."]],"Standing_One-Arm_Dumbbell_Triceps_Extension":["تراي بالدمبل بيد واحدة وقوفًا",["قف والقدمان بعرض الكتفين ودمبل في يد واحدة، ومدّ الذراع فوق رأسك بالكامل، والإصبع الصغير نحو السقف والكف للأمام. هذه وضعية البداية.","العضد قريب من رأسك وعمودي على الأرض، أنزل الدمبل في نصف دائرة خلف رأسك حتى يلمس الساعد الباي، وأنت تشهق. العضد ثابت.","ارفعه إلى البداية بالتراي وأنت تزفر.","أكمل التكرارات ثم بدّل الذراع."]],"Standing_Overhead_Barbell_Triceps_Extension":["تراي بالبار فوق الرأس وقوفًا",["قف والقدمان بعرض الكتفين، وأمسك بارًا أو بار EZ بقبضة علوية أضيق من الكتفين.","ارفع البار فوق رأسك حتى تمتد ذراعاك والمرفقان للداخل. هذه وضعية البداية.","العضدان قريبان من رأسك وعموديان، أنزل البار في نصف دائرة خلف رأسك حتى يلمس الساعدان الباي، وأنت تشهق. العضدان ثابتان.","ارفعه إلى البداية بالتراي وأنت تزفر."]],"Standing_Palm-In_One-Arm_Dumbbell_Press":["ضغط أكتاف بالدمبل بيد واحدة بقبضة محايدة وقوفًا",["أمسك دمبلًا بيد واحدة بقبضة محايدة والذراع ممدودة بجانبك، وأمسك بنشًا مائلًا باليد الأخرى للتوازن.","القدمان بعرض الكتفين. ارفع الدمبل حتى تتكون زاوية 90° في ذراعك والساعد عمودي على الأرض، مع إبقاء القبضة محايدة.","ارفع الدمبل حتى تمتد ذراعك بالكامل. هذه وضعية البداية.","اشهق وأنزل الوزن حتى تعود الذراع إلى 90°.","اثبت ثانية ثم ارفعه وأنت تزفر. أكمل التكرارات ثم بدّل الذراع."]],"Standing_Palms-In_Dumbbell_Press":["ضغط أكتاف بالدمبل بقبضة محايدة وقوفًا",["أمسك دمبلًا في كل يد بقبضة محايدة والذراعان بجانبك، والقدمان بعرض الكتفين. ارفع الدمبلين حتى تتكون زاوية 90° في الذراعين والساعدان عموديان. هذه وضعية البداية.","مع إبقاء القبضة محايدة، ارفع الدمبلين ببطء حتى تمتد ذراعاك بالكامل.","اشهق وأنزلهما حتى تعود الذراعان إلى 90°."]],"Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl":["ثني الرسغ بالبار خلف الظهر والكف للأعلى وقوفًا",["قف باستقامة وأمسك البار خلف مؤخرتك والذراعان ممدودتان، والكفّان للخلف بعرض الكتفين. (الأسهل أن تأخذه من الحامل أو يناولك أحد.)","النظر للأمام والقدمان بعرض الكتفين. هذه وضعية البداية.","ازفر وارفع البار بثني رسغيك للأعلى في نصف دائرة. الرسغ فقط يتحرك.","اثبت ثانية ثم أنزله ببطء وأنت تشهق.","عند الانتهاء أنزل البار إلى الحامل أو الأرض بثني الركبتين."]],"Standing_Pelvic_Tilt":["إمالة الحوض وقوفًا",["قف والقدمان بعرض الحوض.","اثنِ ركبتيك قليلًا لتبقيا مرنتين.","حرّك حوضك للأمام والخلف عدة مرات، ثم اثبت والعصعص للأمام."]],"Standing_Rope_Crunch":["كرنش بالحبل وقوفًا",["ركّب حبلًا على الكيبل العلوي واختر الوزن.","قف وظهرك للجهاز، وأمسك الحبل بيديك فوق كتفيك على أعلى صدرك. هذه وضعية البداية.","اثنِ عمودك الفقري وانزل بالوزن في كرنش لأقصى حد.","اثبت لحظة في الانقباض، ثم عد إلى البداية."]],"Standing_Soleus_And_Achilles_Stretch":["إطالة السمانة العميقة ووتر أخيل وقوفًا",["قف والقدمان بعرض الحوض، وقدم أمام الأخرى قليلًا.","اثنِ الركبتين مع إبقاء الكعب الخلفي على الأرض لإطالة السمانة العميقة ووتر أخيل. بدّل الجهة."]],"Standing_Toe_Touches":["لمس أصابع القدمين وقوفًا",["قف ولديك مساحة أمامك وخلفك.","انحنِ من الخصر والرجلان مستقيمتان، ودع الجزء العلوي يتدلى أمامك مسترخيًا والذراعان متدليتان. اثبت 10–20 ثانية."]],"Standing_Towel_Triceps_Extension":["تراي بالمنشفة وقوفًا",["قف والقدمان بعرض الكتفين، والذراعان ممدودتان فوق رأسك تمسكان طرف منشفة، والمرفقان للداخل والكفّان متقابلتان. هذه وضعية البداية.","يمسك زميلك الطرف الآخر للمنشفة ليقاوم. العضدان قريبان من رأسك وعموديان، أنزل يديك في نصف دائرة خلف رأسك حتى يلمس الساعدان الباي، وأنت تشهق.","ارفع المنشفة بالتراي إلى البداية وأنت تزفر."]],"Standing_Two-Arm_Overhead_Throw":["رمي بيدين من فوق الرأس وقوفًا",["قف والقدمان بعرض الكتفين وأمسك الكرة الطبية بيديك. أرجعها خلف رأسك لأبعد حد مع ثني الركبتين قليلًا والميلان للخلف.","ارمِ الكرة للأمام بقوة مع ثني الحوض واستخدام الجسم كله.","ارمها إلى زميل أو حائط واستقبلها عند ارتدادها."]],"Star_Jump":["قفزة النجمة",["قف بوضعية مرتاحة والقدمان بعرض الكتفين والذراعان قريبتان من الجسم.","انزل إلى نصف سكوات ثم انطلق للأعلى لأقصى ارتفاع، وافرد جسمك كله مع فتح الرجلين والذراعين كالنجمة.","عند الهبوط أعد الذراعين والرجلين وامتص الصدمة برجليك."]],"Step-up_with_Knee_Raise":["صعود على الصندوق مع رفع الركبة",["قف أمام صندوق أو بنش بارتفاع مناسب والقدمان معًا. هذه وضعية البداية.","اصعد بوضع قدمك اليسرى على الصندوق وافرد ورك وركبة الرجل الأمامية لتقف عليه، وفي الوقت نفسه ارفع ركبتك اليمنى لأعلى ما تستطيع.","انزل بعكس الحركة، ثم كرّر بالرجل الأخرى."]],"Step_Mill":["جهاز الدرج المتحرك",["اصعد على جهاز الدرج المتحرك واختر البرنامج: يدوي أو جاهز. انتبه حتى لا تتعثر، وأمسك المقابض حتى لا تقع.","الجهاز مفيد جدًا للقلب وأخف على المفاصل من الركض، وأصعب عادةً من أجهزة الكارديو الأخرى."]],"Stiff-Legged_Barbell_Deadlift":["ديدلفت بالبار بأرجل مستقيمة",["أمسك البار بقبضة علوية (قد تحتاج أحزمة الرسغ مع الأوزان الثقيلة).","قف باستقامة والقدمان بعرض الكتفين أو أضيق، والركبتان مثنيتان قليلًا. هذه وضعية البداية.","مع ثبات الركبتين، أنزل البار نحو قدميك بالانحناء من الحوض بظهر مستقيم، حتى تشعر بإطالة في خلفي الفخذ. اشهق أثناء النزول.","افرد حوضك لتعود إلى البداية وأنت تزفر."]],"Stiff-Legged_Dumbbell_Deadlift":["ديدلفت بالدمبل بأرجل مستقيمة",["أمسك دمبلين بجانبك والذراعان ممدودتان.","قف باستقامة والقدمان بعرض الكتفين أو أضيق، والركبتان مثنيتان قليلًا. هذه وضعية البداية.","مع ثبات الركبتين، أنزل الدمبلين نحو قدميك بالانحناء من الخصر بظهر مستقيم، حتى تشعر بإطالة في خلفي الفخذ.","افرد حوضك لتعود إلى البداية."]],"Stiff_Leg_Barbell_Good_Morning":["غود مورنينغ بالبار بأرجل مستقيمة",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار على ارتفاعك وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسكه وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان بعرض الكتفين، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","مع ثبات الرجلين، انحنِ بجذعك للأمام من الحوض وأنت تشهق، حتى يصبح موازيًا للأرض.","ارفع جذعك إلى البداية وأنت تزفر. استخدم وزنًا خفيفًا، والتمرين يضغط أسفل الظهر."]],"Stomach_Vacuum":["شفط البطن (فاكيوم)",["قف باستقامة والقدمان بعرض الكتفين واليدان على الخصر. هذه وضعية البداية.","خذ نفسًا عميقًا ببطء، ثم أخرج كل الهواء وأنت تسحب بطنك للداخل لأقصى حد واثبت، كأن سرّتك تلمس عمودك الفقري.","اثبت نحو 20 ثانية مع تنفّس طبيعي، ثم تنفّس وأرخِ بطنك.","مع التمرين زِد المدة تدريجيًا إلى 40–60 ثانية."]],"Straight-Arm_Dumbbell_Pullover":["بول أوفر بالدمبل بذراعين مستقيمتين",["ضع دمبلًا واقفًا على بنش مستوٍ.","استلقِ بالعرض على البنش بحيث يستند كتفاك فقط، والحوض أسفل مستوى البنش والقدمان ثابتتان على الأرض.","أمسك الدمبل بيديك من أحد طرفيه فوق صدرك والذراعان ممدودتان. تأكد أن أقراص الدمبل مثبتة جيدًا.","والذراعان مستقيمتان، أنزل الدمبل ببطء في قوس خلف رأسك وأنت تشهق، حتى تشعر بإطالة في الصدر.","أعده في القوس نفسه إلى فوق صدرك وأنت تزفر، واثبت ثانية."]],"Straight-Arm_Pulldown":["سحب للأسفل بذراعين مستقيمتين",["أمسك البار العريض للكيبل العلوي بقبضة علوية أعرض من الكتفين، وارجع للخلف نحو 60 سم.","انحنِ بجذعك للأمام نحو 30° والذراعان ممدودتان أمامك مع ثني بسيط في المرفقين. إذا لم تمتد ذراعاك بالكامل، ارجع للخلف أكثر. شدّ عضلات الظهر.","والذراعان مستقيمتان، اسحب البار للأسفل بعضلات الظهر (اللاتس) حتى تصل يداك بجانب فخذيك، وأنت تزفر.","والذراعان مستقيمتان، عد إلى البداية وأنت تشهق."]],"Straight_Bar_Bench_Mid_Rows":["تجديف بالبار المستقيم منبطحًا على البنش",["ضع بارًا محمّلًا عند طرف بنش. قف على البنش خلف البار وأمسكه بقبضة علوية متوسطة. ادفع حوضك للخلف وارفع صدرك مع ظهر مستقيم. هذه وضعية البداية.","اسحب البار إلى جذعك بضم لوحي الكتف وثني المرفقين، بحركة متحكّم بها دون رجّ.","توقف لحظة، ثم أعد البار ببطء حتى الأسفل تمامًا."]],"Straight_Raises_on_Incline_Bench":["رفرفة بذراعين مستقيمتين على بنش مائل",["ضع بارًا على الأرض خلف رأس بنش مائل.","انبطح على البنش والتقط البار بقبضة علوية والذراعان مستقيمتان، ودعه يتدلى للأسفل. هذه وضعية البداية.","ارفع البار أمام رأسك والذراعان ممدودتان.","عد إلى البداية."]],"Stride_Jump_Crossover":["قفزة الخطوة المتقاطعة",["قف بجانب صندوق وقدمك الداخلية عليه قرب الحافة.","أرجح ذراعيك للأعلى وادفع بالرجل التي على الصندوق لتقفز لأعلى ما يمكن، مع رفع الركبة المعاكسة.","اهبط في الجهة الأخرى من الصندوق: القدم التي كانت عليه تصبح على الأرض، والأخرى على الصندوق.","كرّر عائدًا إلى الجهة الأولى."]],"Sumo_Deadlift":["ديدلفت سومو",["البار المحمّل على الأرض. اقترب منه بحيث يكون فوق منتصف قدميك، والقدمان متباعدتان كثيرًا قرب الأقراص. انحنِ من الحوض وأمسك البار والذراعان تحت الكتفين مباشرة بين الرجلين، بقبضة علوية أو مختلطة. أرخِ كتفيك.","خذ نفسًا، أنزل حوضك والنظر للأمام والصدر مرفوع. ادفع الأرض كأنك تباعد قدميك، والوزن على النصف الخلفي من القدم، وافرد الحوض والركبتين.","عندما يتجاوز البار الركبتين، مِل للخلف وادفع حوضك نحو البار واضغط لوحي الكتف معًا.","أعد الوزن إلى الأرض بثني الحوض والتحكّم بالنزول."]],"Sumo_Deadlift_with_Bands":["ديدلفت سومو بالمطاط",["لفّ المطاط القصير على البار وادخل قدميك فيه، بحيث يكون تحت النصف الخلفي من قدميك.","اقترب من البار بحيث يكون فوق منتصف قدميك، والقدمان متباعدتان كثيرًا. انحنِ من الحوض وأمسك البار والذراعان تحت الكتفين بين الرجلين.","خذ نفسًا، أنزل حوضك والنظر للأمام والصدر مرفوع. ادفع الأرض كأنك تباعد قدميك، وافرد الحوض والركبتين.","عندما يتجاوز البار الركبتين، مِل للخلف وادفع حوضك نحو البار واضغط لوحي الكتف معًا.","أعد الوزن إلى الأرض بثني الحوض والتحكّم بالنزول."]],"Sumo_Deadlift_with_Chains":["ديدلفت سومو بالسلاسل",["علّق السلاسل على طرفي البار أو ضع منتصفها فوق البار، بعيدًا عن الأقراص.","اقترب من البار بحيث يكون فوق منتصف قدميك، والقدمان متباعدتان كثيرًا. انحنِ من الحوض وأمسك البار والذراعان تحت الكتفين بين الرجلين، وأرخِ كتفيك.","خذ نفسًا، أنزل حوضك والنظر للأمام والصدر مرفوع. ادفع الأرض كأنك تباعد قدميك، وافرد الحوض والركبتين.","عندما يتجاوز البار الركبتين، مِل للخلف وادفع حوضك نحو البار واضغط لوحي الكتف معًا.","أعد الوزن إلى الأرض بثني الحوض والتحكّم بالنزول."]],"Superman":["سوبرمان",["انبطح على الأرض والجسم مستقيم والذراعان ممدودتان أمامك. هذه وضعية البداية.","ارفع ذراعيك ورجليك وصدرك عن الأرض معًا واثبت ثانيتين، كأنك سوبرمان يطير. اعصر أسفل ظهرك وازفر.","أنزلها ببطء وأنت تشهق."]],"Supine_Chest_Throw":["رمي الكرة من الصدر مستلقيًا",["استلقِ على ظهرك والركبتان مثنيتان.","أمسك الكرة على صدرك بيديك من الأسفل.","ادفعها بقوة بفرد المرفقين لترميها مستقيمة للأعلى لأعلى ما يمكن.","التقطها بيديك عند نزولها."]],"Supine_One-Arm_Overhead_Throw":["رمي من فوق الرأس بيد واحدة مستلقيًا",["استلقِ على ظهرك والركبتان مثنيتان، وأمسك الكرة بيد واحدة والذراع ممدودة خلف رأسك. هذه وضعية البداية.","ابدأ الحركة من الكتف وارمِ الكرة للأمام وأنت ترفع جذعك، لأبعد مسافة.","ارمها إلى زميل أو اضربها على حائط."]],"Supine_Two-Arm_Overhead_Throw":["رمي من فوق الرأس بيدين مستلقيًا",["استلقِ على ظهرك والركبتان مثنيتان.","أمسك الكرة بيديك والذراعان ممدودتان خلف رأسك. هذه وضعية البداية.","ابدأ الحركة من الكتفين وارمِ الكرة للأمام وأنت ترفع جذعك، لأبعد مسافة.","ارمها إلى زميل أو اضربها على حائط."]],"Suspended_Fallout":["السقوط للأمام بالأحزمة المعلّقة",["اضبط الأحزمة المعلّقة بحيث تكون المقابض تحت مستوى الخصر.","قف وأمسك المقابض، ومِل نحو الأحزمة إلى وضعية ضغط مائل. هذه وضعية البداية.","والذراعان مستقيمتان، مِل أكثر نحو الأرض ودع ذراعيك ترتفعان فوق رأسك.","الظهر مستقيم والجسم كله مشدود، والحركة من الكتفين فقط.","توقف عند أقصى نقطة، ثم عد إلى البداية."]],"Suspended_Push-Up":["ضغط بالأحزمة المعلّقة",["ثبّت الأحزمة المعلّقة جيدًا في أعلى القفص أو شيء ثابت.","أمسك مقبضًا بكل يد ومِل نحو الأحزمة إلى وضعية بلانك، أقرب ما يمكن إلى الموازاة مع الأرض والذراعان ممدودتان.","والجذع مستقيم ومشدود، انزل ببطء بثني المرفقين.","تابع حتى تصبح الزاوية أقل من 90°، توقف ثم افرد ذراعيك لتعود."]],"Suspended_Reverse_Crunch":["كرنش عكسي بالأحزمة المعلّقة",["علّق الأحزمة بحيث تكون المقابض على ارتفاع 30 سم تقريبًا عن الأرض. اتخذ وضعية البلانك وظهرك للقفص.","ضع قدميك في المقابض، والجسم مستقيم دون هبوط الحوض. هذه وضعية البداية.","اثنِ ركبتيك وحوضك لتسحب ركبتيك نحو جذعك، مع لفّ الحوض وانثناء الظهر.","في أعلى الحركة المتحكّم بها، عد إلى البداية."]],"Suspended_Row":["تجديف بالأحزمة المعلّقة",["علّق الأحزمة بمستوى الصدر تقريبًا. أمسك مقبضًا بكل يد ومِل للخلف، والجسم مستقيم والرأس والصدر مرفوعان والذراعان ممدودتان. هذه وضعية البداية.","اثنِ المرفقين واسحب صدرك نحو المقبضين مع ضم لوحي الكتف.","توقف في النهاية، ثم عد إلى البداية."]],"Suspended_Split_Squat":["سكوات مفتوح بالأحزمة المعلّقة",["علّق الأحزمة بحيث تكون المقابض على ارتفاع 45–75 سم عن الأرض.","وظهرك للأحزمة، ضع قدمك الخلفية في المقبض خلفك. النظر للأمام والصدر مرفوع والركبة مثنية قليلًا. هذه وضعية البداية.","انزل بثني الركبة والحوض، والوزن على كعب القدم الأمامية مع وضعية جيدة.","في الأسفل افرد الحوض والركبة لتعود إلى البداية. أكمل التكرارات ثم بدّل الرجل."]],"Svend_Press":["ضغط سفيند (ضغط القرص)",["قف باستقامة.","اضغط قرصين خفيفين بين كفّيك أمام صدرك، والأصابع للأمام، لتنقبض عضلات الصدر. هذه وضعية البداية.","واصل ضغط القرصين ومدّ ذراعيك أمامك مباشرة بتحكّم.","توقف في النهاية، ثم عد ببطء إلى صدرك."]],"T-Bar_Row_with_Handle":["تجديف تي بار بالمقبض",["ثبّت طرف البار في قاعدة لاندماين أو في زاوية، وحمّل الطرف الآخر بالوزن المناسب.","قف فوق البار وركّب مقبض التجديف المزدوج حوله قرب الأقراص، ثم قف باستخدام حوضك ورجليك.","بوقفة واسعة، ادفع حوضك للخلف وارفع صدرك والذراعان ممدودتان. هذه وضعية البداية.","اسحب الوزن نحو أعلى بطنك بضم لوحي الكتف وثني المرفقين، دون رجّ أو غش.","توقف لحظة، ثم عد إلى البداية."]],"Tate_Press":["ضغط تيت (تراي بالدمبل)",["استلقِ على بنش مستوٍ والدمبلان على فخذيك والكفّان متقابلتان.","بمساعدة فخذيك، ارفع الدمبلين أمامك أعرض قليلًا من الكتفين بقبضة علوية، والمرفقان للخارج. هذه وضعية البداية.","ثبّت العضدين وأنزل الدمبلين نحو الداخل وللأسفل في نصف دائرة حتى يلمسا أعلى صدرك، وأنت تشهق. لا تُرحهما على الصدر.","ازفر وارفعهما بالتراي في المسار نفسه معكوسًا، مع محاولة إبقائهما متلاصقين. اثبت ثانية. النزول يأخذ ضعف وقت الصعود."]],"The_Straddle":["إطالة فتح الرجلين",["اجلس باستقامة وافتح رجليك أمامك على شكل V.","ويداك على الأرض، مِل للأمام لأبعد حد. اثبت 10–20 ثانية."]],"Thigh_Abductor":["جهاز الفخذ الخارجي (فتح الرجلين)",["اجلس على جهاز الفخذ الخارجي واختر وزنًا مريحًا. ضع رجليك جيدًا وأمسك المقابض الجانبية. الجزء العلوي من الجسم ثابت. هذه وضعية البداية.","ادفع المساند برجليك ببطء لتباعدهما وأنت تزفر.","اثبت ثانية، ثم أعد رجليك إلى البداية وأنت تشهق، مع ثبات الجزء العلوي."]],"Thigh_Adductor":["جهاز الفخذ الداخلي (ضم الرجلين)",["اجلس على جهاز الفخذ الداخلي واختر وزنًا مريحًا. ضع رجليك على المساند وأمسك المقابض الجانبية. الجزء العلوي من الجسم ثابت. هذه وضعية البداية.","اضغط المساند برجليك ببطء لتقرّبهما من بعض وأنت تزفر.","اثبت ثانية، ثم أعد رجليك إلى البداية وأنت تشهق. تجنّب الحركات السريعة المفاجئة."]],"Tire_Flip":["قلب الإطار",["أمسك أسفل الإطار من النقوش، وأرجع قدميك قليلًا، وصدرك مضغوط على الإطار.","لرفع الإطار، افرد الحوض والركبتين والكاحلين واندفع فيه للأعلى.","عندما يصل إلى زاوية 45° تقدّم خطوة وادفعه بركبتك، ثم انقل يديك إلى أعلاه وادفعه للأمام بأقوى ما يمكن ليكمل الانقلاب. كرّر."]],"Toe_Touchers":["لمس أصابع القدمين مستلقيًا",["استلقِ على ظهرك والذراعان بجانبك والكفّان للأسفل.","الرجلان متلاصقتان، ارفعهما ببطء حتى تقاربا العمودي مع ثني بسيط في الركبتين.","ارفع ذراعيك ممدودتين بزاوية 45° عن الأرض. هذه وضعية البداية.","مع إبقاء أسفل الظهر على الأرض، ارفع جذعك ببطء وحاول لمس أصابع قدميك بيديك، وأنت تزفر.","انزل ببطء وأنت تشهق، والذراعان ممدودتان نحو القدمين."]],"Torso_Rotation":["لفّ الجذع",["قف باستقامة وأمسك كرة التمارين بيديك والذراعان ممدودتان أمامك. هذه وضعية البداية.","لفّ جذعك إلى جهة وعيناك على الكرة، ثم إلى الجهة الأخرى. كرّر 10–20 مرة."]],"Trail_Running_Walking":["ركض أو مشي في الطبيعة",["الركض أو المشي في المسارات الطبيعية يرفع النبض بسرعة. البس حذاءً جيدًا. الصعود يشغّل السمانة والأرداف، والنزول يضغط الركبتين والكاحلين، فخذ خطوات أقصر في النزول والركبتان مثنيتان وتمهّل حتى لا تقع.","المشي صعودًا يحرق سعرات أكثر من المشي على أرض مستوية، والركض أكثر بكثير."]],"Trap_Bar_Deadlift":["ديدلفت بالبار السداسي (تراب بار)",["حمّل البار السداسي (تراب بار) بالوزن المناسب على الأرض. قف في وسطه وأمسك المقبضين.","أنزل حوضك وانظر للأمام والصدر مرفوع.","ادفع بكعبيك وافرد الحوض والركبتين لتقف. لا تقوّس ظهرك أبدًا.","عند الوقوف الكامل، أنزل الوزن إلى الأرض بتحكّم. هذا ديدلفت لطيف على الظهر مقارنة بالبار العادي."]],"Tricep_Dumbbell_Kickback":["تراي كيك باك بالدمبل",["دمبل في كل يد والكفّان نحو جسمك. ظهر مستقيم وركبتان مثنيتان قليلًا، وانحنِ من الخصر حتى يصبح جذعك شبه موازٍ للأرض والرأس مرفوع. العضدان قريبان من الجذع وموازيان للأرض، والساعدان متدليان بزاوية 90°. هذه وضعية البداية.","ثبّت العضدين، ازفر وارفع الدمبلين بالتراي حتى تمتد ذراعاك بالكامل. الساعد فقط يتحرك.","توقف لحظة، ثم اشهق وأنزلهما ببطء."]],"Tricep_Side_Stretch":["إطالة التراي الجانبية",["اعبر بذراعك اليمنى أمام جسمك وفوق كتفك الأيسر، وأمسك مرفقها بيدك اليسرى حتى تشعر بإطالة في التراي. ثم كرّر بالذراع الأخرى."]],"Triceps_Overhead_Extension_with_Rope":["تراي خلف الرأس بالحبل",["ركّب حبلًا على الكيبل السفلي، اختر الوزن وأمسك الحبل بيديك وظهرك للجهاز.","ضع يديك خلف رأسك والمرفقان يشيران للأعلى ومثنيان. قف بقدمين متباعدتين للأمام والخلف ومِل قليلًا بعيدًا عن الجهاز للثبات. هذه وضعية البداية.","افرد مرفقيك مع ثبات العضدين لترفع يديك فوق رأسك.","اعصر التراي في الأعلى، ثم أنزل الوزن ببطء."]],"Triceps_Pushdown":["تراي للأسفل (بوش داون)",["ركّب بارًا مستقيمًا أو مائلًا على الكيبل العلوي وأمسكه بقبضة علوية بعرض الكتفين.","قف باستقامة مع ميلان بسيط جدًا للأمام، والعضدان ملتصقان بجسمك وعموديان على الأرض، والساعدان للأعلى نحو الكيبل. هذه وضعية البداية.","أنزل البار بالتراي حتى يلمس مقدمة فخذيك وتمتد ذراعاك بالكامل، وأنت تزفر. العضدان ثابتان والساعدان فقط يتحركان.","اثبت ثانية، ثم ارفع البار ببطء إلى البداية وأنت تشهق."]],"Triceps_Pushdown_-_Rope_Attachment":["تراي حبل للأسفل",["ركّب حبلًا على الكيبل العلوي وأمسكه بقبضة محايدة (الكفّان متقابلتان).","قف باستقامة مع ميلان بسيط جدًا للأمام، والعضدان ملتصقان بجسمك وعموديان على الأرض، والساعدان للأعلى نحو الكيبل. هذه وضعية البداية.","أنزل الحبل بالتراي وافتح طرفيه إلى جانبي فخذيك حتى تمتد ذراعاك بالكامل، وأنت تزفر. العضدان ثابتان.","اثبت ثانية، ثم ارفع الحبل ببطء وأنت تشهق."]],"Triceps_Pushdown_-_V-Bar_Attachment":["تراي للأسفل بمقبض V",["ركّب مقبض V على الكيبل العلوي وأمسكه بقبضة علوية.","قف باستقامة مع ميلان بسيط جدًا للأمام، والعضدان ملتصقان بجسمك وعموديان، والإبهامان أعلى من الأصابع الصغيرة. هذه وضعية البداية.","أنزل المقبض بالتراي حتى يلمس مقدمة فخذيك وتمتد ذراعاك، وأنت تزفر. العضدان ثابتان.","اثبت ثانية، ثم ارفعه ببطء وأنت تشهق."]],"Triceps_Stretch":["إطالة التراي",["مدّ يدك خلف رأسك، وأمسك مرفقها باليد الأخرى واسحبه برفق. اثبت 10–20 ثانية ثم بدّل."]],"Tuck_Crunch":["كرنش مع ضم الركبتين",["استلقِ على الأرض وظهرك ملتصق بها، والذراعان بجانبك والكفّان للأسفل.","شبّك كاحليك، وارفع رجليك حتى يصبح الفخذان عموديين على الأرض مع ثني بسيط في الركبتين.","اعقد ذراعيك على صدرك. هذه وضعية البداية.","مع إبقاء أسفل الظهر ملتصقًا بالأرض، ارفع جذعك ببطء وأنت تزفر.","انزل ببطء وأنت تشهق."]],"Two-Arm_Dumbbell_Preacher_Curl":["باي دمبل على المسند باليدين",["أمسك دمبلًا في كل يد وضع عضديك على مسند البريتشر أو بنش مائل، والدمبلان عند مستوى الكتفين. هذه وضعية البداية.","اشهق وأنزل الدمبلين ببطء حتى تمتد ذراعاك ويتمدد الباي.","ازفر واثنِ الدمبلين بالباي حتى مستوى الكتفين.","اعصر الباي بقوة ثانية في الأعلى."]],"Two-Arm_Kettlebell_Clean":["كلين بالكيتلبل بيدين",["ضع كيتلبلين بين قدميك. ادفع مؤخرتك للخلف وانظر للأمام.","ارفعهما إلى كتفيك (كلين) بفرد الرجلين والحوض مع لفّ الرسغين.","أنزلهما إلى البداية وكرّر."]],"Two-Arm_Kettlebell_Jerk":["جيرك بالكيتلبل بيدين",["ارفع كيتلبلين إلى كتفيك (كلين) بفرد الرجلين والحوض مع لفّ الرسغين لتصبح الكفّان للأمام. انزل بضعة سنتيمترات ثم اعكس الحركة بسرعة لتدفع الكيتلبلين فوق رأسك. بعد الدفع مباشرة انزل مجددًا تحتهما، وعندما تنقفل ذراعاك قف باستقامة."]],"Two-Arm_Kettlebell_Military_Press":["ضغط عسكري بكيتلبلين",["ارفع كيتلبلين إلى كتفيك (كلين) بفرد الرجلين والحوض مع لفّ الرسغين لتصبح الكفّان للأمام.","اضغطهما للأعلى وللخارج. عندما يتجاوزان رأسك مِل قليلًا نحو الوزن بحيث يستقران فوق رأسك وخلفه قليلًا. اعصر الظهر والأرداف والبطن للثبات."]],"Two-Arm_Kettlebell_Row":["تجديف بكيتلبلين",["ضع كيتلبلين أمام قدميك. اثنِ ركبتيك قليلًا وادفع مؤخرتك للخلف قدر الإمكان وانحنِ.","أمسك الكيتلبلين واسحبهما نحو بطنك بضم لوحي الكتف وثني المرفقين، والظهر مستقيم. أنزلهما وكرّر."]],"Underhand_Cable_Pulldowns":["سحب للأسفل بالكيبل بقبضة سفلية",["اجلس على جهاز السحب الأمامي واضبط مسند الركبتين ليثبّتك.","أمسك البار بقبضة سفلية (الكفّان نحوك) أضيق من الكتفين.","والذراعان ممدودتان، مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","ازفر واسحب البار حتى يلمس أعلى صدرك، بسحب الكتفين والعضدين للأسفل وللخلف والمرفقان قريبان من الجسم. اعصر الظهر.","بعد ثانية، أعد البار ببطء حتى تمتد ذراعاك وتشعر بإطالة الظهر، وأنت تشهق."]],"Upper_Back-Leg_Grab":["إطالة أعلى الظهر بمسك الرجلين",["اجلس وانحنِ للأمام لتحتضن فخذيك من الأسفل بذراعيك.","الركبتان معًا والرجلان ممدودتان، وأنزل صدرك نحو ركبتيك. يمكنك أيضًا إطالة منتصف الظهر بدفع ظهرك بعيدًا عن ركبتيك وأنت تحتضنهما."]],"Upper_Back_Stretch":["إطالة أعلى الظهر",["شبّك أصابعك والإبهامان للأسفل، ودوّر كتفيك للأمام وأنت تمدّ يديك أمامك."]],"Upright_Barbell_Row":["سحب عمودي بالبار (أبرايت رو)",["أمسك البار بقبضة علوية أضيق قليلًا من الكتفين، والبار على فخذيك والذراعان ممدودتان مع ثني بسيط، والظهر مستقيم.","ازفر وارفع البار بالكتف الجانبي، والمرفقان يرتفعان للأعلى وللجانبين، والبار قريب من جسمك حتى يكاد يلمس ذقنك. المرفقان أعلى من الساعدين دائمًا، والجذع ثابت. اثبت ثانية.","أنزله ببطء وأنت تشهق."]],"Upright_Cable_Row":["سحب عمودي بالكيبل",["أمسك البار المستقيم للكيبل السفلي بقبضة علوية أضيق قليلًا من الكتفين، والبار على فخذيك والذراعان ممدودتان مع ثني بسيط، والظهر مستقيم.","ارفع البار بالكتف الجانبي وأنت تزفر، قريبًا من جسمك، حتى يكاد يلمس ذقنك. المرفقان يقودان الحركة ويبقيان أعلى من الساعدين، والجذع ثابت. اثبت ثانية.","أنزله ببطء وأنت تشهق."]],"Upright_Row_-_With_Bands":["سحب عمودي بالمطاط",["قف على مطاط التمارين بحيث يبدأ الشد والذراعان ممدودتان. أمسك المقبضين بقبضة علوية أضيق قليلًا من الكتفين على فخذيك، والذراعان ممدودتان مع ثني بسيط والظهر مستقيم.","ارفع المقبضين بالكتف الجانبي وأنت تزفر، قريبين من جسمك، حتى يكادا يلمسان ذقنك. المرفقان يقودان الحركة ويبقيان أعلى من الساعدين، والجذع ثابت. اثبت ثانية.","أنزلهما ببطء وأنت تشهق."]],"Upward_Stretch":["إطالة للأعلى",["مدّ يديك مستقيمتين فوق رأسك والكفّان متلامستان.","ادفع يديك ببطء للأعلى وللخلف والظهر مستقيم."]],"V-Bar_Pulldown":["سحب أمامي بمقبض V",["اجلس على جهاز السحب الأمامي المركّب عليه مقبض V.","اضبط مسند الركبتين ليثبّتك.","أمسك المقبض بقبضة محايدة، أخرج صدرك ومِل للخلف نحو 30°. هذه وضعية البداية.","اسحب المقبض بعضلات الظهر وأنت تضم لوحي الكتف، حتى يكاد صدرك يلمس المقبض، وأنت تزفر. الجذع ثابت.","اثبت ثانية، ثم أعده ببطء وأنت تشهق."]],"V-Bar_Pullup":["عقلة بمقبض V",["ضع منتصف مقبض V على منتصف بار العقلة، والمقابض للأسفل لتتعلّق بها (إن لم يكن في العقلة مقابض محايدة).","بعد تثبيته، أمسك المقبضين وتعلّق. أخرج صدرك ومِل للخلف قليلًا. هذه وضعية البداية.","اسحب جسمك بعضلات الظهر مع إمالة رأسك للخلف قليلًا حتى لا يصطدم بالبار، حتى يكاد صدرك يلمس المقبض، وأنت تزفر.","اثبت ثانية، ثم انزل ببطء وأنت تشهق."]],"Vertical_Swing":["أرجحة عمودية بالدمبل",["أمسك دمبلًا بيديك متدليًا بين رجليك والذراعان ممدودتان، والظهر مستقيم والرأس مرفوع.","أرجح الدمبل بين رجليك مع ثني الحوض والركبتين قليلًا.","اعكس الحركة بقوة بفرد الحوض والركبتين والكاحلين لتنطلق للأعلى، وأرجح الدمبل فوق رأسك.","عند الهبوط امتص الصدمة برجليك واسحب الدمبل نحو جذعك قبل التكرار التالي."]],"Walking_Treadmill":["مشي على جهاز المشي",["اصعد على جهاز المشي واختر البرنامج: يدوي أو جاهز. يمكنك إدخال عمرك ووزنك لتقدير السعرات، وتغيير الميل لتغيير الشدة.","امشِ بسرعة متوسطة إلى سريعة لا ببطء. المشي أقل حرقًا للسعرات من الركض لكنه مفيد جدًا. حافظ على وضعية جيدة، وأمسك المقابض فقط عند الحاجة."]],"Weighted_Ball_Hyperextension":["تمديد الظهر مع كرة وزن",["انبطح على كرة التمارين والجذع عليها موازٍ للأرض، ومقدمة القدمين على الأرض للتوازن. أمسك قرصًا تحت ذقنك أو خلف رقبتك. هذه وضعية البداية.","ارفع جذعك ببطء بفرد الخصر وأسفل الظهر وأنت تزفر.","اثبت ثانية، ثم أنزل جذعك ببطء وأنت تشهق."]],"Weighted_Ball_Side_Bend":["ميلان جانبي مع كرة وزن",["استلقِ على جنبك الأيسر على كرة التمارين (الخصر والحوض والكتف على الكرة).","القدمان على الأرض والرجلان متقاطعتان. أمسك قرصًا بيدك اليمنى بجانب رأسك.","ضع ذراعك اليسرى عبر جذعك والكف على الخاصرة. هذه وضعية البداية.","ارفع جانب جذعك بالميلان الجانبي من الخصر وأنت تزفر.","اثبت ثانية، ثم انزل ببطء وأنت تشهق. أكمل التكرارات ثم بدّل الجهة."]],"Weighted_Bench_Dip":["متوازي على البنش بوزن إضافي",["ضع بنشًا خلفك وآخر أمامك. أمسك حافة البنش الخلفي بيديك بعرض الكتفين قريبتين من جسمك، والذراعان ممدودتان.","ضع رجليك ممدودتين على البنش الأمامي موازيتين للأرض، والجذع عمودي. يضع زميلك الدمبل على فخذيك (أفضل بمساعدة). هذه وضعية البداية.","انزل ببطء بثني المرفقين حتى تصبح الزاوية بين العضد والساعد أقل قليلًا من 90°، وأنت تشهق. المرفقان قريبان من الجسم.","اصعد بالتراي إلى البداية وأنت تزفر."]],"Weighted_Crunches":["كرنش بوزن إضافي",["استلقِ على ظهرك والقدمان على الأرض، أو على بنش والركبتان مثنيتان 90°.","أمسك وزنًا على صدرك أو ممدودًا فوق جذعك. هذه وضعية البداية.","ازفر وارفع كتفيك عن الأرض نحو 10 سم، وأسفل الظهر على الأرض.","اعصر البطن لحظة في الأعلى.","اشهق وانزل ببطء."]],"Weighted_Jump_Squat":["سكوات بالقفز مع وزن",["ضع بارًا خفيفًا على أعلى ظهرك (أو استخدم سترة وزن أو كيس رمل).","الوزن خفيف بحيث لا يبطئك كثيرًا. القدمان أعرض قليلًا من الكتفين، والرأس والصدر مرفوعان. هذه وضعية البداية.","انزل جزئيًا في سكوات ثم اعكس الاتجاه فورًا وانطلق عن الأرض بقوة بفرد الحوض والركبتين والكاحلين، مع وضعية جيدة.","عند الهبوط امتص الصدمة بثني رجليك."]],"Weighted_Pull_Ups":["عقلة بوزن إضافي",["اربط وزنًا بحزام المتوازي حول خصرك. أمسك بار العقلة والكفّان للأمام بعرض الكتفين، والذراعان ممدودتان.","مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","ازفر واسحب جسمك حتى يصبح رأسك فوق يديك، مع سحب لوحي الكتف للخلف وللأسفل في الأعلى.","توقف لحظة، ثم اشهق وانزل ببطء حتى تمتد ذراعاك."]],"Weighted_Sissy_Squat":["سيسي سكوات بوزن إضافي",["قف باستقامة والقدمان بعرض الكتفين على أطراف أصابعك، وأمسك قفص السكوات بيد واحدة، واليد الأخرى تمسك قرصًا على صدرك. هذه وضعية البداية.","اثنِ ركبتيك وانزل بجذعك ببطء نحو الأرض مع دفع الحوض والركبتين للأمام، وأنت تشهق، حتى تقارب الزاوية بين الفخذ والساق 90°. اثبت ثانية.","اصعد إلى البداية بعضلات الفخذ وأنت تزفر."]],"Weighted_Sit-Ups_-_With_Bands":["سيت أب بالمطاط",["اربط المطاط بقاعدة البنش المقلوب، والمقبضان للداخل بحيث تصلهما وأنت مستلقٍ.","ثبّت رجليك في البنش وأمسك المقبضين قرب الترقوة بقبضة محايدة. الذراعان ثابتتان طوال التمرين. هذه وضعية البداية.","ارفع جذعك حتى يصبح عموديًا على الأرض وأنت تزفر. اثبت ثانية، ثم انزل وأنت تشهق."]],"Weighted_Squat":["سكوات بحزام الوزن",["ضع بنشين مستويين متباعدين بعرض الكتفين وقف عليهما. اربط حزام الوزن حول خصرك بوزن مريح، والأصابع للخارج.","قف باستقامة والوزن متدلٍّ بين رجليك، والذراعان بجانبك. هذه وضعية البداية.","انزل بثني الركبتين مع ظهر مستقيم ورأس مرفوع حتى تصبح الزاوية أقل قليلًا من 90°، وأنت تشهق.","اصعد بالدفع بمقدمة القدمين وأنت تزفر."]],"Wide-Grip_Barbell_Bench_Press":["ضغط صدر بالبار بقبضة واسعة",["استلقِ على بنش مستوٍ والقدمان ثابتتان على الأرض. أمسك البار بقبضة علوية واسعة (أعرض من الكتفين بنحو 8 سم لكل يد)، ارفعه من الحامل وثبّته فوقك.","اشهق وأنزل البار ببطء حتى يلمس منتصف صدرك.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر، واعصر صدرك. النزول يأخذ ضعف وقت الصعود."]],"Wide-Grip_Decline_Barbell_Bench_Press":["ضغط صدر بالبار على بنش مقلوب بقبضة واسعة",["استلقِ على بنش مقلوب والقدمان مثبتتان. أمسك البار بقبضة علوية واسعة، ارفعه من الحامل وثبّته فوقك.","اشهق وأنزل البار ببطء حتى يلمس أسفل صدرك.","توقف ثانية، ثم ادفعه بعضلات الصدر إلى البداية وأنت تزفر، واعصر صدرك. النزول يأخذ ضعف وقت الصعود."]],"Wide-Grip_Decline_Barbell_Pullover":["بول أوفر بالبار على بنش مقلوب بقبضة واسعة",["استلقِ على بنش مقلوب والرجلان مثبتتان. التقط البار من خلف رأسك بقبضة علوية أعرض من الكتفين وارفعه.","الذراعان ممدودتان وعموديتان على الأرض. هذه وضعية البداية.","أنزل البار في نصف دائرة خلف رأسك كأنك ستضعه على الأرض، وتوقف عندما تصبح ذراعاك موازيتين للأرض، وأنت تشهق. الذراعان ممدودتان والحركة من الكتف فقط.","ارفعه إلى البداية وأنت تزفر، بتحكّم كامل.","عند الانتهاء أنزل البار ببطء إلى مستوى رأسك واتركه."]],"Wide-Grip_Lat_Pulldown":["سحب أمامي بقبضة واسعة (لات بول داون)",["اجلس على جهاز السحب الأمامي المركّب عليه بار عريض، واضبط مسند الركبتين ليثبّتك.","أمسك البار بقبضة علوية واسعة (أعرض من الكتفين) والكفّان للأمام.","والذراعان ممدودتان، مِل بجذعك للخلف نحو 30° مع تقويس أسفل الظهر وإخراج الصدر. هذه وضعية البداية.","ازفر واسحب البار حتى يلمس أعلى صدرك، بسحب الكتفين والعضدين للأسفل وللخلف. اعصر الظهر في الأسفل. الجذع ثابت والساعدان يمسكان فقط.","بعد ثانية مع ضم لوحي الكتف، ارفع البار ببطء حتى تمتد ذراعاك وتشعر بإطالة الظهر، وأنت تشهق."]],"Wide-Grip_Pulldown_Behind_The_Neck":["سحب خلف الرقبة بقبضة واسعة",["اجلس على جهاز السحب الأمامي المركّب عليه بار عريض، واضبط مسند الركبتين ليثبّتك.","أمسك البار بقبضة علوية واسعة والكفّان للأمام.","والذراعان ممدودتان، مِل بجذعك ورأسك للأمام بحيث يكون البار فوق خلف رقبتك. هذه وضعية البداية.","ازفر واسحب البار حتى يلمس خلف رقبتك، بسحب الكتفين والعضدين للأسفل وللخلف. اعصر الظهر. هذا التمرين يضغط الكتف، فاستخدم وزنًا خفيفًا.","بعد ثانية، ارفع البار ببطء حتى تمتد ذراعاك، وأنت تشهق."]],"Wide-Grip_Rear_Pull-Up":["عقلة خلف الرقبة بقبضة واسعة",["أمسك بار العقلة بقبضة علوية واسعة.","والذراعان ممدودتان، مِل بجذعك ورأسك للأمام بحيث يكون البار فوق خلف رقبتك. هذه وضعية البداية.","اسحب جسمك حتى يقترب البار من خلف رقبتك، بسحب الكتفين والعضدين للأسفل وللخلف مع إمالة الرأس للأمام قليلًا، وأنت تزفر. اعصر الظهر. هذا التمرين يضغط الكتف، فلا تبالغ.","بعد ثانية، اشهق وانزل ببطء حتى تمتد ذراعاك."]],"Wide-Grip_Standing_Barbell_Curl":["باي بالبار وقوفًا بقبضة واسعة",["قف باستقامة وأمسك البار بقبضة واسعة والكفّان للأمام، والمرفقان قريبان من الجسم.","ثبّت العضدين واثنِ البار وأنت تزفر. الساعدان فقط يتحركان.","تابع حتى مستوى الكتفين واعصر الباي بقوة ثانية.","أنزله ببطء وأنت تشهق."]],"Wide_Stance_Barbell_Squat":["سكوات بالبار بوقفة واسعة",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار على ارتفاعك وضعه على أعلى ظهرك تحت الرقبة بقليل.","أمسكه وارفعه عن الحامل بالدفع برجليك وفرد جذعك.","ابتعد خطوة، القدمان أعرض من الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل ببطء بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق. الركبتان على خط أصابع القدمين.","ادفع الأرض بكعبيك لتصعد إلى البداية وأنت تزفر."]],"Wide_Stance_Stiff_Legs":["إطالة خلفي الفخذ بوقفة واسعة",["البار المحمّل على الأرض. قف بوقفة واسعة وانحنِ من الحوض لتمسك البار، والحوض للخلف قدر الإمكان والرجلان شبه مستقيمتين. الظهر مستقيم والرأس والصدر مرفوعان. هذه وضعية البداية.","ادفع حوضك للأمام والذراعان متدليتان مستقيمتان حتى تقف باستقامة، ثم أعد الوزن ببطء. في التكرارات التالية لا يلزم أن يلمس الوزن الأرض."]],"Wind_Sprints":["عدو سريع متقطع",["تعلّق على بار العقلة بقبضة علوية، والذراعان والرجلان ممدودة. هذه وضعية البداية.","ارفع ركبة واحدة بسرعة لأعلى ما تستطيع دون تأرجح.","أنزلها فورًا وارفع الركبة الأخرى في الوقت نفسه.","تابع بالتبادل حتى نهاية المجموعة."]],"Windmills":["طواحين الهواء",["استلقِ على ظهرك والذراعان ممدودتان للجانبين والرجلان مستقيمتان. هذه وضعية البداية.","ارفع رجلًا واعبر بها بسرعة فوق جسمك محاولًا لمس الأرض قرب اليد المعاكسة.","عد إلى البداية وكرّر بالرجل الأخرى. تابع بالتبادل 10–20 مرة."]],"Worlds_Greatest_Stretch":["أعظم إطالة في العالم",["إطالة من ثلاثة أجزاء. ابدأ بلانج أمامي: القدم الأمامية على الأرض والخلفية على أطراف أصابعها، وانزل حتى تكاد الركبة الخلفية تلمس الأرض. الجذع مستقيم، واثبت 10–20 ثانية.","ضع الذراع من جهة الرجل الأمامية على الأرض والمرفق بجانب القدم، واليد الأخرى على الأرض موازية للرجل الأمامية للسند.","بعد 10–20 ثانية ضع يديك على جانبي القدم الأمامية، ارفع أصابعها عن الأرض وافرد الرجل (قد تحتاج لتعديل الرجل الخلفية). اثبت 10–20 ثانية ثم كرّر كل شيء للجهة الأخرى."]],"Wrist_Circles":["دوائر الرسغ",["قف باستقامة والقدمان بعرض الكتفين، وارفع ذراعيك جانبيًا موازيتين للأرض بمستوى الكتفين على شكل حرف T، والكفّان للأسفل. هذه وضعية البداية.","والجسم ثابت إلا الرسغين، دوّر رسغيك للأمام في دوائر كأن يديك فرشاة ترسم دائرة. تنفّس بشكل طبيعي.","كرّر العدد المطلوب، ثم بالاتجاه المعاكس."]],"Wrist_Roller":["لفّ حبل الرسغ (ريست رولر)",["قف باستقامة والقدمان بعرض الكتفين، وأمسك عصا لفّ الرسغ بقبضة علوية.","ارفع ذراعيك ممدودتين أمامك موازيتين للأرض، والحبل غير ملفوف. الجسم كله ثابت إلا الساعدين. هذه وضعية البداية.","لفّ رسغًا واحدًا كل مرة للأعلى لتلفّ الحبل وترفع الوزن حتى العصا.","بعد وصول الوزن، أنزله ببطء بلفّ الرسغين في الاتجاه المعاكس."]],"Wrist_Rotations_with_Straight_Bar":["تدوير الرسغ بالبار المستقيم",["أمسك البار بيديك والكفّان للأسفل بعرض الكتفين. هذه وضعية البداية.","بالتبادل بين اليدين، افرد الرسغ كأنك تلفّ جريدة. تابع حتى التعب.","اعكس الحركة بثني الرسغ لتلفّ بالاتجاه المعاكس، وتابع حتى التعب."]],"Yoke_Walk":["مشي النير (يوك)",["يُؤدّى عادةً بأداة النير (يوك)، وأحيانًا بثلاجات أو أوزان ثقيلة.","ضع الأداة على أعلى ظهرك، والنظر للأمام والظهر مقوّس، وارفعها بالدفع بكعبيك.","امشِ بأسرع ما يمكن بخطوات قصيرة وسريعة. يمكنك الإمساك بالأعمدة الجانبية لتثبيتها. تابع للمسافة المحددة (عادةً 20–30 مترًا)."]],"Zercher_Squats":["سكوات زيرشر",["يُفضّل أداؤه داخل قفص السكوات. اضبط البار بين مستوى الخصر والصدر. شبّك يديك وضع البار في ثنية مرفقيك بين الساعد والعضد.","ارفع البار حتى يستقر على ساعديك، كأن ذراعيك متقاطعتان والبار عليهما.","ابتعد خطوة، القدمان بعرض الكتفين وأصابعهما للخارج قليلًا، والرأس مرفوع والظهر مستقيم. هذه وضعية البداية.","انزل بثني الركبتين حتى تصبح الزاوية بين الفخذ والساق أقل قليلًا من 90°، وأنت تشهق.","ادفع الأرض بمقدمة قدميك لتصعد وأنت تزفر."]],"Zottman_Curl":["باي زوتمان",["قف باستقامة ودمبل في كل يد والذراعان ممدودتان، والمرفقان قريبان من الجسم.","الكفّان متقابلتان. هذه وضعية البداية.","ثبّت العضدين واثنِ الدمبلين وأنت تزفر، مع لفّ الرسغين لتصبح الكفّان للأعلى، حتى مستوى الكتفين.","اعصر الباي ثانية.","في الأعلى لفّ رسغيك لتصبح الكفّان للأسفل.","أنزل الدمبلين ببطء بهذه القبضة العلوية.","عندما يقتربان من فخذيك، أعد الرسغين إلى القبضة المحايدة."]],"Zottman_Preacher_Curl":["باي زوتمان على المسند",["أمسك دمبلًا في كل يد وضع عضديك على مسند البريتشر، والدمبلان عند مستوى الكتفين والمرفقان مثنيان والكفّان للأسفل. هذه وضعية البداية.","اشهق وأنزل الدمبلين ببطء والكفّان للأسفل حتى تمتد ذراعاك ويتمدد الباي.","في الأسفل لفّ رسغيك لتصبح الكفّان للأعلى.","ازفر واثنِ الدمبلين بالباي حتى مستوى الكتفين، والإصبع الصغير أعلى من الإبهام.","اعصر الباي ثانية، ثم لفّ رسغيك لتصبح الكفّان للأسفل مجددًا."]]};
